public boolean implicitlyCloseParentTagOnNewTag(String parentNodeName, String nodeName) {
		if (parentNodeName == null) {
			return false;
		}
		parentNodeName = parentNodeName.toLowerCase();
		nodeName = nodeName.toLowerCase();

		for (int i = 0; i < IMPLIED_ON_START.length; i+=2) {
			if (StringUtil.equalsOne(parentNodeName, IMPLIED_ON_START[i]) != -1) {
				if (StringUtil.equalsOne(nodeName, IMPLIED_ON_START[i + 1]) != -1) {
					return true;
				}
			}
		}

		return false;
	}

public boolean implicitlyCloseParentTagOnTagEnd(String parentNodeName, String nodeName) {
		if (parentNodeName == null) {
			return false;
		}

		parentNodeName = parentNodeName.toLowerCase();
		nodeName = nodeName.toLowerCase();

		for (int i = 0; i < IMPLIED_ON_END.length; i += 2) {
			if (StringUtil.equalsOne(nodeName, IMPLIED_ON_END[i]) != -1) {
				if (StringUtil.equalsOne(parentNodeName, IMPLIED_ON_END[i + 1]) != -1) {
					return true;
				}
			}
		}

		return false;
	}

public boolean implicitlyCloseTagOnEOF(String nodeName) {
		if (nodeName == null) {
			return false;
		}

		nodeName = nodeName.toLowerCase();

		return StringUtil.equalsOne(nodeName, CLOSED_ON_EOF) != -1;
	}

@Override
	public void clear() {
		entries = null;
		Iterator<String> keys = getAttributeNames();
		while (keys.hasNext()) {
			removeAttribute(keys.next());
		}
	}

@Override
	public Set<Entry<String, Object>> entrySet() {
		if (entries == null) {
			entries = new HashSet<>();
			Iterator<String> iterator = getAttributeNames();
			while (iterator.hasNext()) {
				final String key = iterator.next();
				final Object value = getAttribute(key);
				entries.add(new Entry<String, Object>() {
					@Override
					public boolean equals(final Object obj) {
						if (obj == null) {
							return false;
						}

						if (this.getClass() != obj.getClass()) {
							return false;
						}

						Entry entry = (Entry) obj;
						return ((key == null) ? (entry.getKey() == null) : key.equals(entry.getKey())) && ((value == null) ? (entry.getValue() == null) : value.equals(entry.getValue()));
					}

					@Override
					public int hashCode() {
						return ((key == null) ? 0 : key.hashCode()) ^ ((value == null) ? 0 : value.hashCode());
					}

					@Override
					public String getKey() {
						return key;
					}

					@Override
					public Object getValue() {
						return value;
					}

					@Override
					public Object setValue(final Object obj) {
						setAttribute(key, obj);
						return value;
					}
				});
			}
		}

		return entries;
	}

@Override
	public Object put(final String key, final Object value) {
		entries = null;
		Object previous = get(key);
		setAttribute(key, value);
		return previous;
	}

@Override
	public Object remove(final Object key) {
		entries = null;
		Object value = get(key);
		removeAttribute(key.toString());
		return value;
	}

@SuppressWarnings({"ThrowCaughtLocally"})
	public static StackTraceElement[] getCurrentStackTrace() {
		StackTraceElement[] ste = new Exception().getStackTrace();
		if (ste.length > 1) {
			StackTraceElement[] result = new StackTraceElement[ste.length - 1];
			System.arraycopy(ste, 1, result, 0, ste.length - 1);
			return result;
		} else {
			return ste;
		}
	}

public static StackTraceElement[] getStackTrace(final Throwable t, final String[] allow, final String[] deny) {
		StackTraceElement[] st = t.getStackTrace();
		ArrayList<StackTraceElement> result = new ArrayList<>(st.length);

		elementLoop:
		for (StackTraceElement element : st) {
			String className = element.getClassName();
			if (allow != null) {
				boolean validElemenet = false;
				for (String filter : allow) {
					if (className.contains(filter)) {
						validElemenet = true;
						break;
					}
				}
				if (!validElemenet) {
					continue;
				}
			}
			if (deny != null) {
				for (String filter : deny) {
					if (className.contains(filter)) {
						continue elementLoop;
					}
				}
			}
			result.add(element);
		}
		st = new StackTraceElement[result.size()];
		return result.toArray(st);
	}

public static StackTraceElement[][] getStackTraceChain(Throwable t, final String[] allow, final String[] deny) {
		ArrayList<StackTraceElement[]> result = new ArrayList<>();
		while (t != null) {
			StackTraceElement[] stack = getStackTrace(t, allow, deny);
			result.add(stack);
			t = t.getCause();
		}
		StackTraceElement[][] allStacks = new StackTraceElement[result.size()][];
		for (int i = 0; i < allStacks.length; i++) {
			allStacks[i] = result.get(i);
		}
		return allStacks;
	}

public static Throwable[] getExceptionChain(Throwable throwable) {
		ArrayList<Throwable> list = new ArrayList<>();
		list.add(throwable);
		while ((throwable = throwable.getCause()) != null) {
			list.add(throwable);
		}
		Throwable[] result = new Throwable[list.size()];
		return list.toArray(result);
	}

