public void injectContext(final Object targetObject) {
		final Class targetType = targetObject.getClass();

		final ScopeData scopeData = scopeDataInspector.inspectClassScopesWithCache(targetType);

		final Targets targets = new Targets(targetObject, scopeData);

		// inject no context
		scopeResolver.forEachScope(madvocScope -> madvocScope.inject(targets));

		// inject special case
		scopeResolver.forScope(ParamsScope.class, scope -> scope.inject(targets));

		// inject servlet context
		final ServletContext servletContext = madvocController.getApplicationContext();
		if (servletContext != null) {
			scopeResolver.forEachScope(madvocScope -> madvocScope.inject(servletContext, targets));
		}
	}

public List<CssSelector> parse() {
		try {
			lexer.yylex();
			if (lexer.selectors.isEmpty()) {
				return null;
			}

			// fixes last combinator
			CssSelector last = lexer.selectors.get(lexer.selectors.size() - 1);
			if (last.getCombinator() == Combinator.DESCENDANT) {
				last.setCombinator(null);
			}

			// set previous css selector
			CssSelector prevCssSelector = null;
			for (CssSelector cssSelector : lexer.selectors) {
				if (prevCssSelector != null) {
					cssSelector.setPrevCssSelector(prevCssSelector);
				}
				prevCssSelector = cssSelector;
			}

			return lexer.selectors;
		} catch (IOException ioex) {
			throw new CSSellyException(ioex);
		}
	}

public static List<List<CssSelector>> parse(final String query) {
		String[] singleQueries = StringUtil.splitc(query, ',');
		List<List<CssSelector>> selectors = new ArrayList<>(singleQueries.length);

		for (String singleQuery: singleQueries) {
			selectors.add(new CSSelly(singleQuery).parse());
		}

		return selectors;
	}

