public static String createViolationsJsonString(final HttpServletRequest request, final List<Violation> violations) {
		if (violations == null) {
			return StringPool.EMPTY;
		}
		StringBuilder sb = new StringBuilder().append('[');
		for (int i = 0, violationsSize = violations.size(); i < violationsSize; i++) {
			Violation violation = violations.get(i);
			if (i != 0) {
				sb.append(',');
			}
			sb.append('{');
			sb.append("\"name\":\"").append(violation.getName()).append('"').append(',');
			sb.append("\"msg\":\"").append(resolveValidationMessage(request, violation)).append('"');
			sb.append('}');
		}
		sb.append(']');
		return sb.toString();
	}

public static String resolveValidationMessage(final HttpServletRequest request, final Violation violation) {
		ValidationConstraint vc = violation.getConstraint();
		String key = vc != null ? vc.getClass().getName() : violation.getName();
		String msg = LocalizationUtil.findMessage(request, key);
		if (msg != null) {
			return beanTemplateParser.parseWithBean(msg, violation);
		}
		return null;
	}

public BeanReferences removeDuplicateNames() {
		if (names.length < 2) {
			return this;
		}

		int nullCount = 0;

		for (int i = 1; i < names.length; i++) {
			String thisRef = names[i];

			if (thisRef == null) {
				nullCount++;
				continue;
			}

			for (int j = 0; j < i; j++) {
				if (names[j] == null) {
					continue;
				}
				if (thisRef.equals(names[j])) {
					names[i] = null;
					break;
				}
			}
		}

		if (nullCount == 0) {
			return this;
		}

		String[] newRefs = new String[names.length - nullCount];
		int ndx = 0;

		for (String name : names) {
			if (name == null) {
				continue;
			}
			newRefs[ndx] = name;
			ndx++;
		}

		return new BeanReferences(newRefs);
	}

