@Override
	public void doFilter(final ServletRequest servletRequest, final ServletResponse servletResponse, final FilterChain filterChain) throws IOException, ServletException {
		HttpServletRequest request = (HttpServletRequest) servletRequest;
		HttpServletResponse response = (HttpServletResponse) servletResponse;
		String actionPath = DispatcherUtil.getServletPath(request);

		if (processActionPath(request, response, actionPath)) {
			return;
		}

		if (!acceptActionPath(request, actionPath)) {
			filterChain.doFilter(servletRequest, servletResponse);
			return;
		}

		BufferResponseWrapper wrapper = new BufferResponseWrapper(response);
		filterChain.doFilter(servletRequest, wrapper);

		// reset servlet response content length AFTER the chain, since
		// servlet container may set it and we are changing the content.
		servletResponse.setContentLength(-1);

		char[] content = wrapper.getBufferContentAsChars();

		if ((content != null) && (content.length != 0)) {
			if (log.isDebugEnabled()) {
				log.debug("Lagarto is about to parse: " + actionPath);
			}
			try {
				content = parse(content, request);
			} catch (Exception ex) {
				log.error("Error parsing", ex);
				throw new ServletException(ex);
			}

			wrapper.writeContentToResponse(content);
		}
	}

protected boolean acceptActionPath(final HttpServletRequest request, final String actionPath) {
		String extension = FileNameUtil.getExtension(actionPath);
		if (extension.length() == 0) {
			return true;
		}
		if (extension.equals("html") || extension.equals("htm")) {
			return true;
		}
		return false;
	}

@Override
	public void render(final ActionRequest actionRequest, final Object resultValue) {
		final Chain chainResult;

		if (resultValue == null) {
			chainResult = Chain.to(StringPool.EMPTY);
		} else {
			if (resultValue instanceof String) {
				chainResult = Chain.to((String)resultValue);
			}
			else {
				chainResult = (Chain) resultValue;
			}
		}

		final String resultBasePath = actionRequest.getActionRuntime().getResultBasePath();

		final String resultPath = resultMapper.resolveResultPathString(resultBasePath, chainResult.path());

		actionRequest.setNextActionPath(resultPath);
	}

@Override
	public Object intercept(final ActionRequest actionRequest) throws Exception {
		HttpServletRequest servletRequest = actionRequest.getHttpServletRequest();

		// detect multipart request
		if (ServletUtil.isMultipartRequest(servletRequest)) {
			servletRequest = new MultipartRequestWrapper(servletRequest, fileUploader.get(), madvocEncoding.getEncoding());
			actionRequest.bind(servletRequest);
		}

		// do it
		inject(actionRequest);

		final Object result = actionRequest.invoke();

		outject(actionRequest);

		return result;
	}

protected void inject(final ActionRequest actionRequest) {
		final Targets targets = actionRequest.getTargets();
		final ServletContext servletContext = actionRequest.getHttpServletRequest().getServletContext();

		scopeResolver.forEachScope(madvocScope -> madvocScope.inject(servletContext, targets));
		scopeResolver.forEachScope(madvocScope -> madvocScope.inject(actionRequest, targets));

	}

protected void outject(final ActionRequest actionRequest) {
		final Targets targets = actionRequest.getTargets();

		scopeResolver.forEachScope(madvocScope -> madvocScope.outject(actionRequest, targets));
	}

