private boolean isConfigurationActive(ConfigDef configDef, Map<String, Object> configuration) {
    String dependsOn = configDef.dependsOn();
    if (!dependsOn.isEmpty()) {
      Object dependsOnValue = configuration.get(dependsOn);
      if (dependsOnValue != null) {
        String valueStr = dependsOnValue.toString();
        for (String trigger : configDef.triggeredByValue()) {
          if (valueStr.equals(trigger)) {
            return true;
          }
        }
        return false;
      }
      return false;
    }
    return true;
  }

public static void resolveStageAlias(
    StageLibraryTask stageLibrary,
    StageConfiguration stageConf
  ) {
    String aliasKey = Joiner.on(",").join(stageConf.getLibrary(), stageConf.getStageName());
    String aliasValue = Strings.nullToEmpty(stageLibrary.getStageNameAliases().get(aliasKey));
    if (LOG.isTraceEnabled()) {
      for (String key : stageLibrary.getStageNameAliases().keySet()) {
        LOG.trace("Stage Lib Alias: {} => {}", key, stageLibrary.getStageNameAliases().get(key));
      }
      LOG.trace("Looking for '{}' and found '{}'", aliasKey, aliasValue);
    }
    if (!aliasValue.isEmpty()) {
      List<String> alias = Splitter.on(",").splitToList(aliasValue);
      if (alias.size() == 2) {
        LOG.debug("Converting '{}' to '{}'", aliasKey, aliasValue);
        stageConf.setLibrary(alias.get(0));
        stageConf.setStageName(alias.get(1));
      } else {
        LOG.error("Malformed stage alias: '{}'", aliasValue);
      }
    }
  }

public static boolean resolveLibraryAliases(
    StageLibraryTask stageLibrary,
    List<StageConfiguration> stageConfigurations
  ) {
    for (StageConfiguration stageConf : stageConfigurations) {
      String name = stageConf.getLibrary();
      if (stageLibrary.getLibraryNameAliases().containsKey(name)) {
        stageConf.setLibrary(stageLibrary.getLibraryNameAliases().get(name));
      }
      resolveStageAlias(stageLibrary, stageConf);
    }
    return true;
  }

public static void addMissingConfigsToStage(
    StageLibraryTask stageLibrary,
    StageConfiguration stageConf
  ) {
    StageDefinition stageDef = stageLibrary.getStage(stageConf.getLibrary(), stageConf.getStageName(), false);
    if (stageDef != null) {
      for (ConfigDefinition configDef : stageDef.getConfigDefinitions()) {
        String configName = configDef.getName();
        Config config = stageConf.getConfig(configName);
        if (config == null) {
          Object defaultValue = configDef.getDefaultValue();
          LOG.warn(
              "Stage '{}' missing configuration '{}', adding with '{}' as default",
              stageConf.getInstanceName(),
              configName,
              defaultValue
          );
          config = new Config(configName, defaultValue);
          stageConf.addConfig(config);
        }
      }
    }
  }

public static boolean validateStageConfiguration(
    StageLibraryTask stageLibrary,
    boolean shouldBeSource,
    StageConfiguration stageConf,
    boolean notOnMainCanvas,
    IssueCreator issueCreator,
    boolean isPipelineFragment,
    Map<String, Object> constants,
    List<Issue> issues
  ) {
    boolean preview = true;
    StageDefinition stageDef = stageLibrary.getStage(
        stageConf.getLibrary(),
        stageConf.getStageName(),
        false
    );
    if (stageDef == null) {
      // stage configuration refers to an undefined stage definition
      issues.add(
          issueCreator.create(
              stageConf.getInstanceName(),
              ValidationError.VALIDATION_0006,
              stageConf.getLibrary(),
              stageConf.getStageName(),
              stageConf.getStageVersion()
          )
      );
      preview = false;
    } else {
      if (shouldBeSource) {
        if (stageDef.getType() != StageType.SOURCE && !isPipelineFragment) {
          // first stage must be a Source
          issues.add(issueCreator.create(stageConf.getInstanceName(), ValidationError.VALIDATION_0003));
          preview = false;
        }
      } else {
        if (!stageLibrary.isMultipleOriginSupported() && stageDef.getType() == StageType.SOURCE) {
          // no stage other than first stage can be a Source
          issues.add(issueCreator.create(stageConf.getInstanceName(), ValidationError.VALIDATION_0004));
          preview = false;
        }
      }
      if (!stageConf.isSystemGenerated() && !TextUtils.isValidName(stageConf.getInstanceName())) {
        // stage instance name has an invalid name (it must match '[0-9A-Za-z_]+')
        issues.add(
            issueCreator.create(
                stageConf.getInstanceName(),
                ValidationError.VALIDATION_0016,
                stageConf.getInstanceName(),
                TextUtils.VALID_NAME
            )
        );
        preview = false;
      }

      // Hidden stages can't appear on the main canvas
      if(!notOnMainCanvas && !stageDef.getHideStage().isEmpty()) {
        issues.add(issueCreator.create(stageConf.getInstanceName(), ValidationError.VALIDATION_0037));
        preview = false;
      }

      for (String lane : stageConf.getInputLanes()) {
        if (!TextUtils.isValidName(lane)) {
          // stage instance input lane has an invalid name (it must match '[0-9A-Za-z_]+')
          issues.add(
              issueCreator.create(
                  stageConf.getInstanceName(),
                  ValidationError.VALIDATION_0017,
                  lane,
                  TextUtils.VALID_NAME
              )
          );
          preview = false;
        }
      }
      for (String lane : stageConf.getOutputLanes()) {
        if (!TextUtils.isValidName(lane)) {
          // stage instance output lane has an invalid name (it must match '[0-9A-Za-z_]+')
          issues.add(
              issueCreator.create(
                  stageConf.getInstanceName(),
                  ValidationError.VALIDATION_0018,
                  lane,
                  TextUtils.VALID_NAME
              )
          );
          preview = false;
        }
      }
      for (String lane : stageConf.getEventLanes()) {
        if (!TextUtils.isValidName(lane)) {
          // stage instance output lane has an invalid name (it must match '[0-9A-Za-z_]+')
          issues.add(
              issueCreator.create(
                  stageConf.getInstanceName(),
                  ValidationError.VALIDATION_0100,
                  lane,
                  TextUtils.VALID_NAME
              )
          );
          preview = false;
        }
      }

      // Special validation for stage exposed limit of input lanes
      // -1: Means that framework is fully in control on how many input lanes should be present
      //  0: Means that the stage supports unlimited number of input lanes
      // >0: Means that stage needs exactly that amount of lanes which we will validate here
      if(stageDef.getInputStreams() > 0) {
        if(stageDef.getInputStreams() != stageConf.getInputLanes().size()) {
           issues.add(
              issueCreator.create(
                  stageConf.getInstanceName(),
                  ValidationError.VALIDATION_0094,
                  stageDef.getInputStreams(),
                  stageConf.getInputLanes().size()
              )
          );
        }
      }

      // Validate proper input/output lane configuration
      switch (stageDef.getType()) {
        case SOURCE:
          if (!stageConf.getInputLanes().isEmpty()) {
            // source stage cannot have input lanes
            issues.add(
                issueCreator.create(
                    stageConf.getInstanceName(),
                    ValidationError.VALIDATION_0012,
                    stageDef.getType(),
                    stageConf.getInputLanes()
                )
            );
            preview = false;
          }
          if (!notOnMainCanvas && !stageDef.isVariableOutputStreams()) {
            // source stage must match the output stream defined in StageDef
            if (stageDef.getOutputStreams() != stageConf.getOutputLanes().size()) {
              issues.add(
                  issueCreator.create(
                      stageConf.getInstanceName(),
                      ValidationError.VALIDATION_0015,
                      stageDef.getOutputStreams(),
                      stageConf.getOutputLanes().size()
                  )
              );
            }
          } else if (!notOnMainCanvas && stageConf.getOutputLanes().isEmpty()) {
            // source stage must have at least one output lane
            issues.add(issueCreator.create(stageConf.getInstanceName(), ValidationError.VALIDATION_0032));
          }
          break;
        case PROCESSOR:
          if (!notOnMainCanvas && stageConf.getInputLanes().isEmpty() && !isPipelineFragment) {
            // processor stage must have at least one input lane
            issues.add(
                issueCreator.create(
                    stageConf.getInstanceName(),
                    ValidationError.VALIDATION_0014,
                    "Processor"
                )
            );
            preview = false;
          }
          if(!notOnMainCanvas) {
            if (!stageDef.isVariableOutputStreams()) {
              // processor stage must match the output stream defined in StageDef
              if (stageDef.getOutputStreams() != stageConf.getOutputLanes().size()) {
                issues.add(
                  issueCreator.create(
                    stageConf.getInstanceName(),
                    ValidationError.VALIDATION_0015,
                    stageDef.getOutputStreams(),
                    stageConf.getOutputLanes().size()
                  )
                );
              }
            } else if (stageConf.getOutputLanes().isEmpty()) {
              // processor stage must have at least one output lane
              issues.add(issueCreator.create(stageConf.getInstanceName(), ValidationError.VALIDATION_0032));
            }
          }
          break;
        case EXECUTOR:
        case TARGET:
          // Normal target stage must have at least one input lane
          if (!notOnMainCanvas && stageConf.getInputLanes().isEmpty() && !isPipelineFragment) {
            issues.add(
                issueCreator.create(
                    stageConf.getInstanceName(),
                    ValidationError.VALIDATION_0014,
                    "Target"
                )
            );
            preview = false;
          }
          // Error/Stats/Pipeline lifecycle must not have an input lane
          if (notOnMainCanvas && !stageConf.getInputLanes().isEmpty()) {
            issues.add(
                issueCreator.create(
                    stageConf.getInstanceName(),
                    ValidationError.VALIDATION_0012,
                    "Error/Stats/Lifecycle",
                    stageConf.getInputLanes()
                )
            );
            preview = false;
          }
          if (!stageConf.getOutputLanes().isEmpty()) {
            // target stage cannot have output lanes
            issues.add(
                issueCreator.create(
                    stageConf.getInstanceName(),
                    ValidationError.VALIDATION_0013,
                    stageDef.getType(),
                    stageConf.getOutputLanes()
                )
            );
            preview = false;
          }
          if (notOnMainCanvas && !stageConf.getEventLanes().isEmpty()) {
            issues.add(
                issueCreator.create(
                    stageConf.getInstanceName(),
                    ValidationError.VALIDATION_0036,
                    stageDef.getType(),
                    stageConf.getEventLanes()
                )
            );
            preview = false;
          }
          break;
        default:
          throw new IllegalStateException("Unexpected stage type " + stageDef.getType());
      }

      // Validate proper event configuration
      if(!notOnMainCanvas && stageConf.getEventLanes().size() > 1) {
        issues.add(
          issueCreator.create(
            stageConf.getInstanceName(),
            ValidationError.VALIDATION_0101
          )
        );
        preview = false;
      }
      if(!notOnMainCanvas && !stageDef.isProducingEvents() && stageConf.getEventLanes().size() > 0) {
        issues.add(
          issueCreator.create(
            stageConf.getInstanceName(),
            ValidationError.VALIDATION_0102
          )
        );
        preview = false;
      }

      // Validate stage owns configuration
      preview &= validateComponentConfigs(
        stageConf,
        stageDef.getConfigDefinitions(),
        stageDef.getConfigDefinitionsMap(),
        stageDef.getHideConfigs(),
        stageDef.hasPreconditions(),
        constants,
        issueCreator,
        issues
      );

      // Validate service definitions
      Set<String> expectedServices = stageDef.getServices().stream()
        .map(service -> service.getService().getName())
        .collect(Collectors.toSet());
      Set<String> configuredServices = stageConf.getServices().stream()
        .map(service -> service.getService().getName())
        .collect(Collectors.toSet());
      if(!expectedServices.equals(configuredServices)) {
        issues.add(issueCreator.create(
            stageConf.getInstanceName(),
            ValidationError.VALIDATION_0200,
            StringUtils.join(expectedServices, ","),
            StringUtils.join(configuredServices, ",")
        ));
        preview = false;
      } else {
        // Validate all services
        for (ServiceConfiguration serviceConf: stageConf.getServices()) {
          ServiceDefinition serviceDef = stageLibrary.getServiceDefinition(serviceConf.getService(), false);
          preview &= validateComponentConfigs(
            serviceConf,
            serviceDef.getConfigDefinitions(),
            serviceDef.getConfigDefinitionsMap(),
            Collections.emptySet(),
            false,
            constants,
            issueCreator.forService(serviceConf.getService().getName()),
            issues
          );
        }
      }
    }
    return preview;
  }

@Override
  protected List<ConfigIssue> init() {
    List<ConfigIssue> issues = super.init();
    errorRecordHandler = new DefaultErrorRecordHandler(getContext()); // NOSONAR

    double rateLimit = conf.rateLimit > 0 ? (1000.0 / conf.rateLimit) : Double.MAX_VALUE;
    rateLimiter = RateLimiter.create(rateLimit);

    httpClientCommon.init(issues, getContext());

    conf.dataFormatConfig.init(
        getContext(),
        conf.dataFormat,
        Groups.HTTP.name(),
        HttpClientCommon.DATA_FORMAT_CONFIG_PREFIX,
        issues
    );

    bodyVars = getContext().createELVars();
    bodyEval = getContext().createELEval(REQUEST_BODY_CONFIG_NAME);

    if (issues.isEmpty()) {
      parserFactory = conf.dataFormatConfig.getParserFactory();
    }

    return issues;
  }

@Override
  public void process(Batch batch, SingleLaneBatchMaker batchMaker) throws StageException {
    List<Future<Response>> responses = new ArrayList<>();
    resolvedRecords.clear();

    Iterator<Record> records = batch.getRecords();
    while (records.hasNext()) {

      Record record = records.next();
      String resolvedUrl = httpClientCommon.getResolvedUrl(conf.resourceUrl, record);
      WebTarget target = httpClientCommon.getClient().target(resolvedUrl);

      LOG.debug("Resolved HTTP Client URL: '{}'",resolvedUrl);

      // If the request (headers or body) contain a known sensitive EL and we're not using https then fail the request.
      if (httpClientCommon.requestContainsSensitiveInfo(conf.headers, conf.requestBody) &&
          !target.getUri().getScheme().toLowerCase().startsWith("https")) {
        throw new StageException(Errors.HTTP_07);
      }

      // from HttpStreamConsumer
      final MultivaluedMap<String, Object> resolvedHeaders = httpClientCommon.resolveHeaders(conf.headers, record);

      String contentType = HttpStageUtil.getContentTypeWithDefault(resolvedHeaders, conf.defaultRequestContentType);

      final AsyncInvoker asyncInvoker = target.request()
          .property(OAuth1ClientSupport.OAUTH_PROPERTY_ACCESS_TOKEN, httpClientCommon.getAuthToken())
          .headers(resolvedHeaders)
          .async();

      HttpMethod method = httpClientCommon.getHttpMethod(conf.httpMethod, conf.methodExpression, record);

      rateLimiter.acquire();
      if (conf.requestBody != null && !conf.requestBody.isEmpty() && method != HttpMethod.GET) {
        RecordEL.setRecordInContext(bodyVars, record);
        final String requestBody = bodyEval.eval(bodyVars, conf.requestBody, String.class);
        resolvedRecords.put(record, new HeadersAndBody(resolvedHeaders, requestBody, contentType, method, target));
        responses.add(asyncInvoker.method(method.getLabel(), Entity.entity(requestBody, contentType)));
      } else {
        resolvedRecords.put(record, new HeadersAndBody(resolvedHeaders, null, null, method, target));
        responses.add(asyncInvoker.method(method.getLabel()));
      }
    }

    records = batch.getRecords();
    int recordNum = 0;
    while (records.hasNext()) {
      try {
        Record record = processResponse(records.next(), responses.get(recordNum), conf.maxRequestCompletionSecs, false);
        if (record != null) {
          batchMaker.addRecord(record);
        }
      } catch (OnRecordErrorException e) {
        errorRecordHandler.onError(e);
      } finally {
        ++recordNum;
      }
    }
    if (!resolvedRecords.isEmpty()) {
      reprocessIfRequired(batchMaker);
    }
  }

private Record processResponse(
      Record record,
      Future<Response> responseFuture,
      long maxRequestCompletionSecs,
      boolean failOn403
  ) throws StageException {

    Response response = null;
    try {
      response = responseFuture.get(maxRequestCompletionSecs, TimeUnit.SECONDS);
      InputStream responseBody = null;
      if (response.hasEntity()) {
        responseBody = response.readEntity(InputStream.class);
      }
      int responseStatus = response.getStatus();
      if (conf.client.useOAuth2 && response.getStatus() == 403 && !failOn403) {
        HttpStageUtil.getNewOAuth2Token(conf.client.oauth2, httpClientCommon.getClient());
        return null;
      } else if (responseStatus < 200 || responseStatus >= 300) {
        resolvedRecords.remove(record);
        throw new OnRecordErrorException(
            record,
            Errors.HTTP_01,
            response.getStatus(),
            response.getStatusInfo().getReasonPhrase() + " " + responseBody
        );
      }
      resolvedRecords.remove(record);
      Record parsedResponse = parseResponse(responseBody);
      if (parsedResponse != null) {
        record.set(conf.outputField, parsedResponse.get());
        addResponseHeaders(record, response);
      } else if (responseBody == null && responseStatus != 204) {
        throw new OnRecordErrorException(record, Errors.HTTP_34);
      }
      return record;
    } catch (InterruptedException | ExecutionException e) {
      LOG.error(Errors.HTTP_03.getMessage(), e.toString(), e);
      throw new OnRecordErrorException(record, Errors.HTTP_03, e.toString());
    } catch (TimeoutException e) {
      LOG.error("HTTP request future timed out", e.toString(), e);
      throw new OnRecordErrorException(record, Errors.HTTP_03, e.toString());
    } finally {
      if (response != null) {
        response.close();
      }
    }
  }

private Record parseResponse(InputStream response) throws StageException {
    Record record = null;
    if (conf.httpMethod == HttpMethod.HEAD) {
      // Head will have no body so can't be parsed.   Return an empty record.
      record = getContext().createRecord("");
      record.set(Field.create(new HashMap()));

    } else if (response != null) {
      try (DataParser parser = parserFactory.getParser("", response, "0")) {
        // A response may only contain a single record, so we only parse it once.
        record = parser.parse();
        if (conf.dataFormat == DataFormat.TEXT) {
          // Output is placed in a field "/text" so we remove it here.
          record.set(record.get("/text"));
        }
      } catch (IOException | DataParserException e) {
        errorRecordHandler.onError(Errors.HTTP_00, e.toString(), e);
      }
    }
    return record;
  }

private void addResponseHeaders(Record record, Response response) throws StageException {
    if (conf.headerOutputLocation == HeaderOutputLocation.NONE) {
      return;
    }

    Record.Header header = record.getHeader();

    if (conf.headerOutputLocation == HeaderOutputLocation.FIELD) {
      writeResponseHeaderToField(record, response);
    } else if (conf.headerOutputLocation == HeaderOutputLocation.HEADER) {
      writeResponseHeaderToRecordHeader(response, header);
    }
  }

private void writeResponseHeaderToField(Record record, Response response) throws StageException {
    if (record.has(conf.headerOutputField)) {
      throw new StageException(Errors.HTTP_11, conf.headerOutputField);
    }
    Map<String, Field> headers = new HashMap<>(response.getStringHeaders().size());

    for (Map.Entry<String, List<String>> entry : response.getStringHeaders().entrySet()) {
      if (!entry.getValue().isEmpty()) {
        String firstValue = entry.getValue().get(0);
        headers.put(entry.getKey(), Field.create(firstValue));
      }
    }

    record.set(conf.headerOutputField, Field.create(headers));
  }

private void writeResponseHeaderToRecordHeader(Response response, Record.Header header) {
    for (Map.Entry<String, List<String>> entry : response.getStringHeaders().entrySet()) {
      if (!entry.getValue().isEmpty()) {
        String firstValue = entry.getValue().get(0);
        header.setAttribute(conf.headerAttributePrefix + entry.getKey(), firstValue);
      }
    }
  }

synchronized private void saveMetadata() throws StageException {
    // 0) Validate pre-conditions
    if(Files.exists(newMetadataFile))  {
      throw new StageException(BlobStoreError.BLOB_STORE_0010);
    }

    // 1) New content is written into a new temporary file.
    try (
      OutputStream os = Files.newOutputStream(newMetadataFile, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING)
    ) {
      jsonMapper.writeValue(os, metadata);
    } catch (IOException e) {
      throw new StageException(BlobStoreError.BLOB_STORE_0001, e.toString(), e);
    }

    // 2) Old metadata is dropped
    try {
      if(Files.exists(metadataFile)) {
        Files.delete(metadataFile);
      }
    } catch (IOException e) {
      throw new StageException(BlobStoreError.BLOB_STORE_0011, e.toString(), e);
    }

    // 3) Rename from new to old is done
    try {
      Files.move(newMetadataFile, metadataFile);
    } catch (IOException e) {
      throw new StageException(BlobStoreError.BLOB_STORE_0012, e.toString(), e);
    }
  }

@Override
  protected List<ConfigIssue> init() {
    List<ConfigIssue> issues = super.init();
    errorRecordHandler = new DefaultErrorRecordHandler(getContext()); // NOSONAR

    conf.basic.init(getContext(), Groups.HTTP.name(), BASIC_CONFIG_PREFIX, issues);
    conf.dataFormatConfig.init(getContext(), conf.dataFormat, Groups.HTTP.name(), DATA_FORMAT_CONFIG_PREFIX, issues);
    conf.init(getContext(), Groups.HTTP.name(), "conf.", issues);
    if (conf.client.tlsConfig.isEnabled()) {
      conf.client.tlsConfig.init(getContext(), Groups.TLS.name(), TLS_CONFIG_PREFIX, issues);
    }

    resourceVars = getContext().createELVars();
    resourceEval = getContext().createELEval(RESOURCE_CONFIG_NAME);

    bodyVars = getContext().createELVars();
    bodyEval = getContext().createELEval(REQUEST_BODY_CONFIG_NAME);
    Calendar calendar = Calendar.getInstance(TimeZone.getTimeZone(ZoneId.of(conf.timeZoneID)));
    TimeEL.setCalendarInContext(bodyVars, calendar);

    headerVars = getContext().createELVars();
    headerEval = getContext().createELEval(HEADER_CONFIG_NAME);

    stopVars = getContext().createELVars();
    stopEval = getContext().createELEval(STOP_CONFIG_NAME);

    next = null;
    haveMorePages = false;

    if (conf.responseStatusActionConfigs != null) {
      final String cfgName = "conf.responseStatusActionConfigs";
      final EnumSet<ResponseAction> backoffRetries = EnumSet.of(
          ResponseAction.RETRY_EXPONENTIAL_BACKOFF,
          ResponseAction.RETRY_LINEAR_BACKOFF
      );

      for (HttpResponseActionConfigBean actionConfig : conf.responseStatusActionConfigs) {
        final HttpResponseActionConfigBean prevAction = statusToActionConfigs.put(
            actionConfig.getStatusCode(),
            actionConfig
        );

        if (prevAction != null) {
          issues.add(
            getContext().createConfigIssue(
                Groups.HTTP.name(),
                cfgName,
                Errors.HTTP_17,
                actionConfig.getStatusCode()
            )
          );
        }
        if (backoffRetries.contains(actionConfig.getAction()) && actionConfig.getBackoffInterval() <= 0) {
          issues.add(
            getContext().createConfigIssue(
                Groups.HTTP.name(),
                cfgName,
                Errors.HTTP_15
            )
          );
        }
        if (actionConfig.getStatusCode() >= 200 && actionConfig.getStatusCode() < 300) {
          issues.add(
            getContext().createConfigIssue(
                Groups.HTTP.name(),
                cfgName,
                Errors.HTTP_16
            )
          );
        }
      }
    }
    this.timeoutActionConfig = conf.responseTimeoutActionConfig;

    // Validation succeeded so configure the client.
    if (issues.isEmpty()) {
      try {
        configureClient(issues);
      } catch (StageException e) {
        // should not happen on initial connect
        ExceptionUtils.throwUndeclared(e);
      }
    }
    return issues;
  }

private void configureClient(List<ConfigIssue> issues) throws StageException {

    clientCommon.init(issues, getContext());

    if (issues.isEmpty()) {
      client = clientCommon.getClient();
      parserFactory = conf.dataFormatConfig.getParserFactory();
    }

  }

@Override
  public String produce(String lastSourceOffset, int maxBatchSize, BatchMaker batchMaker) throws StageException {
    long start = System.currentTimeMillis();
    int chunksToFetch = Math.min(conf.basic.maxBatchSize, maxBatchSize);
    Optional<String> newSourceOffset = Optional.empty();
    recordCount = 0;

    setPageOffset(lastSourceOffset);

    setResolvedUrl(resolveInitialUrl(lastSourceOffset));
    WebTarget target = client.target(getResolvedUrl());

    // If the request (headers or body) contain a known sensitive EL and we're not using https then fail the request.
    if (requestContainsSensitiveInfo() && !target.getUri().getScheme().toLowerCase().startsWith("https")) {
      LOG.error(Errors.HTTP_07.getMessage());
      throw new StageException(Errors.HTTP_07);
    }

    boolean uninterrupted = true;

    while (!waitTimeExpired(start) && uninterrupted && (recordCount < chunksToFetch)) {
      if (parser != null) {
        // We already have an response that we haven't finished reading.
        newSourceOffset = Optional.of(parseResponse(start, chunksToFetch, batchMaker));
      } else if (shouldMakeRequest()) {

        if (conf.pagination.mode != PaginationMode.NONE) {
          target = client.target(resolveNextPageUrl(newSourceOffset.orElse(null)));
          // Pause between paging requests so we don't get rate limited.
          uninterrupted = ThreadUtil.sleep(conf.pagination.rateLimit);
        }

        makeRequest(target);
        if (lastRequestTimedOut) {
          String actionName = conf.responseTimeoutActionConfig.getAction().name();
          LOG.warn(
              "HTTPClient timed out after waiting {} ms for response from server;" +
              " reconnecting client and proceeding as per configured {} action",
              conf.client.readTimeoutMillis,
              actionName
          );
          reconnectClient();
          return nonTerminating(lastSourceOffset);
        } else {
          newSourceOffset = processResponse(start, chunksToFetch, batchMaker);
        }
      } else if (conf.httpMode == HttpClientMode.BATCH) {
        // We are done.
        return null;
      } else {
        // In polling mode, waiting for the next polling interval.
        uninterrupted = ThreadUtil.sleep(SLEEP_TIME_WAITING_FOR_BATCH_SIZE_MS);
      }
    }

    return newSourceOffset.orElse(lastSourceOffset);
  }

@VisibleForTesting
  String resolveNextPageUrl(String sourceOffset) throws ELEvalException {
    String url;
    if (LINK_PAGINATION.contains(conf.pagination.mode) && next != null) {
      url = next.getUri().toString();
      setResolvedUrl(url);
    } else if (conf.pagination.mode == PaginationMode.BY_OFFSET || conf.pagination.mode == PaginationMode.BY_PAGE) {
      if (sourceOffset != null) {
        setPageOffset(sourceOffset);
      }
      url = resourceEval.eval(resourceVars, conf.resourceUrl, String.class);
    } else {
      url = getResolvedUrl();
    }
    return url;
  }

private void setPageOffset(String sourceOffset) {
    if (conf.pagination.mode == PaginationMode.NONE) {
      return;
    }

    int startAt = conf.pagination.startAt;
    if (StringUtils.isNotEmpty(sourceOffset)) {
      startAt = HttpSourceOffset.fromString(sourceOffset).getStartAt();
    }
    resourceVars.addVariable(START_AT, startAt);
    bodyVars.addVariable(START_AT, startAt);
  }

private void makeRequest(WebTarget target) throws StageException {
    hasher = HF.newHasher();

    MultivaluedMap<String, Object> resolvedHeaders = resolveHeaders();
    final Invocation.Builder invocationBuilder = target
        .request()
        .property(OAuth1ClientSupport.OAUTH_PROPERTY_ACCESS_TOKEN, authToken)
        .headers(resolvedHeaders);

    boolean keepRequesting = !getContext().isStopped();
    boolean gotNewToken = false;
    while (keepRequesting) {
      long startTime = System.currentTimeMillis();
      try {
        if (conf.requestBody != null && !conf.requestBody.isEmpty() && conf.httpMethod != HttpMethod.GET) {
          final String requestBody = bodyEval.eval(bodyVars, conf.requestBody, String.class);
          final String contentType = HttpStageUtil.getContentTypeWithDefault(
              resolvedHeaders, conf.defaultRequestContentType);
          hasher.putString(requestBody, Charset.forName(conf.dataFormatConfig.charset));
          setResponse(invocationBuilder.method(conf.httpMethod.getLabel(), Entity.entity(requestBody, contentType)));
        } else {
          setResponse(invocationBuilder.method(conf.httpMethod.getLabel()));
        }
        LOG.debug("Retrieved response in {} ms", System.currentTimeMillis() - startTime);

        lastRequestTimedOut = false;
        final int status = response.getStatus();
        final boolean statusOk = status >= 200 && status < 300;
        if (conf.client.useOAuth2 && status == 403) { // Token may have expired
          if (gotNewToken) {
            LOG.error(HTTP_21.getMessage());
            throw new StageException(HTTP_21);
          }
          gotNewToken = HttpStageUtil.getNewOAuth2Token(conf.client.oauth2, client);
        } else if (!statusOk && this.statusToActionConfigs.containsKey(status)) {
          final HttpResponseActionConfigBean actionConf = this.statusToActionConfigs.get(status);
          final boolean statusChanged = lastStatus != status || lastRequestTimedOut;

          keepRequesting = applyResponseAction(
              actionConf,
              statusChanged,
              input -> {
                final StageException stageException = new StageException(
                    Errors.HTTP_14,
                    status,
                    response.readEntity(String.class)
                );
                LOG.error(stageException.getMessage());
                return stageException;
              }
          );

        } else {
          keepRequesting = false;
          retryCount = 0;
        }
        lastStatus = status;
      } catch (Exception e) {
        LOG.debug("Request failed after {} ms", System.currentTimeMillis() - startTime);
        final Throwable cause = e.getCause();
        if (cause != null && (cause instanceof TimeoutException || cause instanceof SocketTimeoutException)) {
          LOG.warn(
              "{} attempting to read response in HttpClientSource: {}",
              cause.getClass().getSimpleName(),
              e.getMessage(),
              e
          );
          // read timeout; consult configured action to decide on backoff and retry strategy
          if (this.timeoutActionConfig != null) {
            final HttpResponseActionConfigBean actionConf = this.timeoutActionConfig;

            final boolean firstTimeout = !lastRequestTimedOut;

            applyResponseAction(actionConf, firstTimeout, input -> {
                  LOG.error(Errors.HTTP_18.getMessage());
                  return new StageException(Errors.HTTP_18);
                }
            );

          }

          lastRequestTimedOut = true;
          keepRequesting = false;
        } else if (cause != null && cause instanceof InterruptedException) {
          LOG.error(
            String.format(
                "InterruptedException attempting to make request in HttpClientSource; stopping: %s",
                e.getMessage()
            ),
          e);
          keepRequesting = false;
        } else {
          LOG.error(
            String.format(
                "ProcessingException attempting to make request in HttpClientSource: %s",
                e.getMessage()
            ),
          e);
          Throwable reportEx = cause != null ? cause : e;
          final StageException stageException = new StageException(Errors.HTTP_32, reportEx.toString(), reportEx);
          LOG.error(stageException.getMessage());
          throw stageException;
        }
      }
      keepRequesting &= !getContext().isStopped();
    }

    // Calculate request parameter hash
    currentParameterHash = hasher.hash().toString();
  }

private boolean shouldMakeRequest() {
    final long now = System.currentTimeMillis();

    boolean shouldMakeRequest = lastRequestCompletedTime == -1;
    shouldMakeRequest |= lastRequestTimedOut;
    shouldMakeRequest |= next != null;
    shouldMakeRequest |= (haveMorePages && conf.pagination.mode != PaginationMode.LINK_HEADER);
    shouldMakeRequest |= now > lastRequestCompletedTime + conf.pollingInterval &&
        conf.httpMode == HttpClientMode.POLLING;
    shouldMakeRequest |= now > lastRequestCompletedTime && conf.httpMode == HttpClientMode.STREAMING && conf.httpMethod != HttpMethod.HEAD;

    return shouldMakeRequest;
  }

@VisibleForTesting
  String parseResponse(long start, int maxRecords, BatchMaker batchMaker) throws StageException {
    HttpSourceOffset sourceOffset = new HttpSourceOffset(
        getResolvedUrl(),
        currentParameterHash,
        System.currentTimeMillis(),
        getCurrentPage()
    );
    InputStream in = null;
    if (parser == null) {
      // Only get a new parser if we are done with the old one.
      in = getResponse().readEntity(InputStream.class);
      try {
        parser = parserFactory.getParser(sourceOffset.toString(), in, "0");
      } catch (DataParserException e) {
        if (e.getErrorCode() == JSON_PARSER_00) {
          LOG.warn("No data returned in HTTP response body.", e);
          return sourceOffset.toString();
        }
        LOG.warn("Error parsing response", e);
        throw e;
      }
    }

    Record record = null;
    int subRecordCount = 0;
    try {

      do {
        record = parser.parse();

        if (record == null) {
          break;
        }

        // LINK_FIELD pagination
        if (conf.pagination.mode == PaginationMode.LINK_FIELD) {
          // evaluate stopping condition
          RecordEL.setRecordInContext(stopVars, record);
          haveMorePages = !stopEval.eval(stopVars, conf.pagination.stopCondition, Boolean.class);
          if (haveMorePages) {
            next = Link.fromUri(record.get(conf.pagination.nextPageFieldPath).getValueAsString()).build();
          } else {
            next = null;
          }
        }

        if (conf.pagination.mode != PaginationMode.NONE && record.has(conf.pagination.resultFieldPath)) {
          subRecordCount = parsePaginatedResult(batchMaker, sourceOffset.toString(), record);
          recordCount += subRecordCount;
        } else {
          addResponseHeaders(record.getHeader());
          batchMaker.addRecord(record);
          ++recordCount;
        }

      } while (recordCount < maxRecords && !waitTimeExpired(start));

    } catch (IOException e) {
      LOG.error(Errors.HTTP_00.getMessage(), e.toString(), e);
      errorRecordHandler.onError(Errors.HTTP_00, e.toString(), e);

    } finally {
      try {
        if (record == null) {
          cleanupResponse(in);
        }
        if (subRecordCount != 0) {
          incrementSourceOffset(sourceOffset, subRecordCount);
        }
      } catch(IOException e) {
        LOG.warn(Errors.HTTP_28.getMessage(), e.toString(), e);
        errorRecordHandler.onError(Errors.HTTP_28, e.toString(), e);
      }
    }

    return sourceOffset.toString();
  }

String parseHeadersOnly(BatchMaker batchMaker) throws StageException {
    HttpSourceOffset sourceOffset = new HttpSourceOffset(
            getResolvedUrl(),
            currentParameterHash,
            System.currentTimeMillis(),
            getCurrentPage()
    );

    Record record = getContext().createRecord(sourceOffset + "::0");
    addResponseHeaders(record.getHeader());
    record.set(Field.create(new HashMap()));

    batchMaker.addRecord(record);
    recordCount++;
    incrementSourceOffset(sourceOffset, 1);
    lastRequestCompletedTime = System.currentTimeMillis();
    return sourceOffset.toString();

  }

private void incrementSourceOffset(HttpSourceOffset sourceOffset, int increment) {
    if (conf.pagination.mode == PaginationMode.BY_PAGE) {
      sourceOffset.incrementStartAt(1);
    } else if (conf.pagination.mode == PaginationMode.BY_OFFSET) {
      sourceOffset.incrementStartAt(increment);
    }
  }

private void cleanupResponse(InputStream in) throws IOException {
    IOException ex = null;

    LOG.debug("Cleanup after request processing complete.");
    lastRequestCompletedTime = System.currentTimeMillis();

    if (in != null) {
      try {
        in.close();
      } catch(IOException e) {
        LOG.warn("Error closing input stream", ex);
        ex = e;
      }
    }

    getResponse().close();
    setResponse(null);

    try {
      parser.close();
    } catch(IOException e) {
      LOG.warn("Error closing parser", ex);
      ex = e;
    }
    parser = null;

    if(ex != null) {
      throw ex;
    }
  }

@VisibleForTesting
  int getCurrentPage() {
    // Body params take precedence, but usually only one or the other should be used.
    if (bodyVars.hasVariable(START_AT)) {
      return (int) bodyVars.getVariable(START_AT);
    } else if (resourceVars.hasVariable(START_AT)) {
      return (int) resourceVars.getVariable(START_AT);
    }
    return 0;
  }

private int parsePaginatedResult(BatchMaker batchMaker, String sourceOffset, Record record) throws
      StageException {
    int numSubRecords = 0;

    if (!record.has(conf.pagination.resultFieldPath)) {
      final StageException stageException = new StageException(Errors.HTTP_12, conf.pagination.resultFieldPath);
      LOG.error(stageException.getMessage());
      throw stageException;
    }
    Field resultField = record.get(conf.pagination.resultFieldPath);

    if (resultField.getType() != Field.Type.LIST) {
      final StageException stageException = new StageException(Errors.HTTP_08, resultField.getType());
      LOG.error(stageException.getMessage());
      throw stageException;
    }

    List<Field> results = resultField.getValueAsList();
    int subRecordIdx = 0;
    for (Field result : results) {
      Record r = getContext().createRecord(sourceOffset + "::" + subRecordIdx++);
      if (conf.pagination.keepAllFields) {
        r.set(record.get().clone());
        r.set(conf.pagination.resultFieldPath, result);
      } else {
        r.set(result);
      }
      addResponseHeaders(r.getHeader());
      batchMaker.addRecord(r);
      ++numSubRecords;
    }
    if (conf.pagination.mode != PaginationMode.LINK_FIELD) {
      haveMorePages = numSubRecords > 0;
    }
    return numSubRecords;
  }

private void addResponseHeaders(Record.Header header) {
    final MultivaluedMap<String, String> headers = getResponse().getStringHeaders();
    if (headers == null) {
      return;
    }

    for (Map.Entry<String, List<String>> entry : headers.entrySet()) {
      if (!entry.getValue().isEmpty()) {
        String firstValue = entry.getValue().get(0);
        header.setAttribute(entry.getKey(), firstValue);
      }
    }
  }

private MultivaluedMap<String, Object> resolveHeaders() throws StageException {
    MultivaluedMap<String, Object> requestHeaders = new MultivaluedHashMap<>();
    for (Map.Entry<String, String> entry : conf.headers.entrySet()) {
      List<Object> header = new ArrayList<>(1);
      Object resolvedValue = headerEval.eval(headerVars, entry.getValue(), String.class);
      header.add(resolvedValue);
      requestHeaders.put(entry.getKey(), header);
      hasher.putString(entry.getKey(), Charset.forName(conf.dataFormatConfig.charset));
      hasher.putString(entry.getValue(), Charset.forName(conf.dataFormatConfig.charset));
    }

    return requestHeaders;
  }

private Optional<String> processResponse(long start, int maxRecords, BatchMaker batchMaker) throws
      StageException {
    Optional<String> newSourceOffset = Optional.empty();

    if (getResponse() == null) {
      return newSourceOffset;
    }

    // Response was not in the OK range, so treat as an error
    int status = getResponse().getStatus();
    if (status < 200 || status >= 300) {
      lastRequestCompletedTime = System.currentTimeMillis();
      String reason = getResponse().getStatusInfo().getReasonPhrase();
      String respString = getResponse().readEntity(String.class);
      getResponse().close();
      setResponse(null);


      final String errorMsg = reason + " : " + respString;
      LOG.warn(Errors.HTTP_01.getMessage(), status, errorMsg);
      errorRecordHandler.onError(Errors.HTTP_01, status, errorMsg);

      return newSourceOffset;
    }

    if (conf.pagination.mode == PaginationMode.LINK_HEADER) {
      next = getResponse().getLink("next");
      if (next == null) {
        haveMorePages = false;
      }
    }


    if (getResponse().hasEntity()) {
      newSourceOffset = Optional.of(parseResponse(start, maxRecords, batchMaker));
    } else if (conf.httpMethod.getLabel() == "HEAD") {
      // Handle HEAD only requests, which have no body, by creating a blank record for output with headers.
      newSourceOffset = Optional.of(parseHeadersOnly(batchMaker));

    }
    return newSourceOffset;
  }

