public static long parseRfc5424Date(LoadingCache<String, Long> cache, String tsStr) throws OnRecordErrorException {

    boolean includesTimezone = true;
    long ts;
    int curPos = 0;
    int msgLen = tsStr.length();
    if (msgLen <= RFC5424_PREFIX_LEN) {
      throw new OnRecordErrorException(Errors.SYSLOG_09, tsStr);
    }
    String timestampPrefix = tsStr.substring(curPos, RFC5424_PREFIX_LEN);
    try {
      ts = cache.get(timestampPrefix);
    } catch (ExecutionException ex) {
      Throwable cause = Throwables.getRootCause(ex);
      if (cause instanceof IllegalArgumentException) {
        throw new OnRecordErrorException(Errors.SYSLOG_05, cause, timestampPrefix, cause);
      } else {
        // I don't believe this will ever occur
        throw new IllegalStateException(
            Utils.format(Errors.SYSLOG_05.getMessage(), cause, timestampPrefix),
            cause);
      }
    }
    curPos += RFC5424_PREFIX_LEN;
    // look for the optional fractional seconds
    if (tsStr.charAt(curPos) == '.') {
      // figure out how many numeric digits
      boolean foundEnd = false;
      int endMillisPos = curPos + 1;
      if (msgLen <= endMillisPos) {
        throw new OnRecordErrorException(Errors.SYSLOG_06, tsStr);
      }
      // FIXME: TODO: ensure we handle all bad formatting cases
      while (!foundEnd && endMillisPos < msgLen) {
        char curDigit = tsStr.charAt(endMillisPos);
        if (curDigit >= '0' && curDigit <= '9') {
          endMillisPos++;
        } else {
          foundEnd = true;
        }
      }
      includesTimezone = foundEnd;
      if (!includesTimezone) {
        endMillisPos--;
      }
      // if they had a valid fractional second, append it rounded to millis
      final int fractionalPositions = endMillisPos - (curPos + 1);
      if (fractionalPositions > 0) {
        long milliseconds = Long.parseLong(tsStr.substring(curPos + 1, endMillisPos));
        if (fractionalPositions > 3) {
          milliseconds /= Math.pow(10, (fractionalPositions - 3));
        } else if (fractionalPositions < 3) {
          milliseconds *= Math.pow(10, (3 - fractionalPositions));
        }
        ts += milliseconds;
      } else {
        throw new OnRecordErrorException(Errors.SYSLOG_07, tsStr);
      }
      curPos = endMillisPos;
    }
    // look for timezone
    if (includesTimezone) {
      char tzFirst = tsStr.charAt(curPos);
      // UTC
      if (tzFirst == 'Z') {
        // no-op
      } else if (tzFirst == '+' || tzFirst == '-') {
        if (msgLen <= curPos + 5) {
          throw new OnRecordErrorException(Errors.SYSLOG_08, tsStr);
        }
        int polarity;
        if (tzFirst == '+') {
          polarity = +1;
        } else {
          polarity = -1;
        }

        char[] h = new char[5];
        for (int i = 0; i < 5; i++) {
          h[i] = tsStr.charAt(curPos + 1 + i);
        }

        if (h[0] >= '0' && h[0] <= '9'
            && h[1] >= '0' && h[1] <= '9'
            && h[2] == ':'
            && h[3] >= '0' && h[3] <= '9'
            && h[4] >= '0' && h[4] <= '9') {
          try {
            int hourOffset = Integer.parseInt(tsStr.substring(curPos + 1, curPos + 3));
            int minOffset = Integer.parseInt(tsStr.substring(curPos + 4, curPos + 6));
            ts -= polarity * ((hourOffset * 60L) + minOffset) * 60000L;
          } catch (NumberFormatException nfe) {
            throw new OnRecordErrorException(Errors.SYSLOG_08, tsStr, nfe);
          }
        } else {
          throw new OnRecordErrorException(Errors.SYSLOG_08, tsStr);
        }
      }
    }
    return ts;
  }

public static long parseRfc3164Time(String ts) throws OnRecordErrorException {
    LocalDateTime now = LocalDateTime.now();
    int year = now.getYear();
    ts = TWO_SPACES.matcher(ts).replaceFirst(" ");
    LocalDateTime date;
    try {
      MonthDay monthDay = MonthDay.parse(ts, rfc3164Format);
      LocalTime time = LocalTime.parse(ts, rfc3164Format);
      // this is overly complicated because of the way Java 8 Time API works, as compared to Joda
      // essentially, we just want to pull year out of "now" and set all other fields based on
      // what was parsed
      date = now;
      // zero out millis since we aren't actually parsing those
      date = date.with(ChronoField.MILLI_OF_SECOND, 0);
      // set month and day of month from parsed
      date = date.withMonth(monthDay.getMonthValue()).withDayOfMonth(monthDay.getDayOfMonth());
      // set time fields from parsed
      date = date.withHour(time.getHour()).withMinute(time.getMinute()).withSecond(time.getSecond());
    } catch (DateTimeParseException e) {
      throw new OnRecordErrorException(Errors.SYSLOG_10, ts, e);
    }
    // The RFC3164 is a bit weird date format - it contains day and month, but no year. So we have to somehow guess
    // the year. The current logic is to provide a sliding window - going 11 months to the past and 1 month to the
    // future. If the message is outside of this window, it will have incorrectly guessed year. We go 11 months to the
    // past as we're expecting that more messages will be from the past (syslog usually contains historical data).
    LocalDateTime fixed = date;
    if (fixed.isAfter(now) && fixed.minusMonths(1).isAfter(now)) {
      fixed = date.withYear(year - 1);
    } else if (fixed.isBefore(now) && fixed.plusMonths(11).isBefore(now)) {
      fixed = date.withYear(year + 1);
    }
    date = fixed;
    return date.toInstant(ZoneOffset.UTC).toEpochMilli();
  }

public static boolean sleep(long milliseconds) {
    //checking if we got pre-interrupted.
    boolean interrupted = Thread.interrupted();
    if (!interrupted) {
      try {
        Thread.sleep(milliseconds);
      } catch (InterruptedException ex) {
        interrupted = true;
        // clearing the interrupt flag
        Thread.interrupted();
      }
    }
    return !interrupted;
  }

public static String format(String template, Object... args) {
    String[] templateArr = TEMPLATES.get(template);
    if (templateArr == null) {
      // we may have a race condition here but the end result is idempotent
      templateArr = prepareTemplate(template);
      TEMPLATES.put(template, templateArr);
    }
    StringBuilder sb = new StringBuilder(template.length() * 2);
    for (int i = 0; i < templateArr.length; i++) {
      sb.append(templateArr[i]);
      if (args != null && (i < templateArr.length - 1)) {
        sb.append((i < args.length) ? args[i] : TOKEN);
      }
    }
    return sb.toString();
  }

@SuppressWarnings("unchecked")
  public String serialize() {
    Map map = new LinkedHashMap();
    map.put("path", path.toString());
    map.put("headHash", headHash);
    map.put("headLen", headLen);
    map.put("inode", iNode);
    try {
      JsonMapper objectMapper = DataCollectorServices.instance().get(JsonMapper.SERVICE_KEY);
      return objectMapper.writeValueAsString(map);
    } catch (Exception ex) {
      throw new RuntimeException(Utils.format("Unexpected exception: {}", ex.toString()), ex);
    }
  }

public static LiveFile deserialize(String str) throws IOException {
    Utils.checkNotNull(str, "str");
    try {
      JsonMapper objectMapper = DataCollectorServices.instance().get(JsonMapper.SERVICE_KEY);
      Map map = objectMapper.readValue(str, Map.class);
      Path path = Paths.get((String) map.get("path"));
      String headHash = (map.containsKey("headHash")) ? (String) map.get("headHash") : "";
      int headLen = (map.containsKey("headLen")) ? (int) map.get("headLen") : 0;
      String inode = (String) map.get("inode");
      return new LiveFile(path, inode, headHash, headLen);
    } catch (RuntimeException|IOException ex) {
      throw new IllegalArgumentException(Utils.format("Invalid LiveFile serialized string '{}': {}", str,
                                                      ex.toString()), ex);
    }
  }

public LiveFile refresh() throws IOException {
    LiveFile refresh = this;
    boolean changed;
    try {
      BasicFileAttributes attrs = Files.readAttributes(path, BasicFileAttributes.class);
      String iNodeCurrent = attrs.fileKey().toString();
      int headLenCurrent = (int) Math.min(headLen, attrs.size());
      String headHashCurrent = computeHash(path, headLenCurrent);
      changed = !this.iNode.equals(iNodeCurrent) || !this.headHash.equals(headHashCurrent);
    } catch (NoSuchFileException ex) {
      changed = true;
    }
    if (changed) {
      try (DirectoryStream<Path> directoryStream = Files.newDirectoryStream(path.getParent())) {
        for (Path path : directoryStream) {
          BasicFileAttributes attrs = Files.readAttributes(path, BasicFileAttributes.class);
          String iNode = attrs.fileKey().toString();
          int headLen = (int) Math.min(this.headLen, attrs.size());
          String headHash = computeHash(path, headLen);
          if (iNode.equals(this.iNode) && headHash.equals(this.headHash)) {
            if (headLen == 0) {
              headLen = (int) Math.min(HEAD_LEN, attrs.size());
              headHash = computeHash(path, headLen);
            }
            refresh = new LiveFile(path, iNode, headHash, headLen);
            break;
          }
        }
      }
    }
    return refresh;
  }

@Override
  protected List<ConfigIssue> init() {
    // Validate configuration values and open any required resources.
    List<ConfigIssue> issues = super.init();

    errorRecordHandler = new DefaultErrorRecordHandler(getContext());
    Processor.Context context = getContext();

    issues = hikariConfigBean.validateConfigs(context, issues);

    if (hikariConfigBean.getConnectionString().toLowerCase().startsWith("jdbc:sqlserver") && useMultiRowOp) {
      issues.add(getContext().createConfigIssue(Groups.JDBC.name(), MULTI_ROW_OP, JdbcErrors.JDBC_57));
    }

    if (dynamicTableName) {
      tableNameVars = getContext().createELVars();
      tableNameEval = context.createELEval(JdbcUtil.TABLE_NAME);
      ELUtils.validateExpression(
          tableNameTemplate,
          getContext(),
          Groups.JDBC.getLabel(),
          JdbcUtil.TABLE_NAME,
          JdbcErrors.JDBC_26,
          issues
      );
    }

    if (issues.isEmpty() && null == dataSource) {
      try {
        dataSource = jdbcUtil.createDataSourceForWrite(
            hikariConfigBean, schema,
            tableNameTemplate,
            caseSensitive,
            issues,
            customMappings,
            getContext()
        );
      } catch (RuntimeException | SQLException | StageException e) {
        LOG.debug("Could not connect to data source", e);
        issues.add(getContext().createConfigIssue(Groups.JDBC.name(), CONNECTION_STRING, JdbcErrors.JDBC_00, e.toString()));
      }
    }

    // If issues is not empty, the UI will inform the user of each configuration issue in the list.
    return issues;
  }

@Override
  public void process(Batch batch, SingleLaneBatchMaker batchMaker) throws StageException {
    if (!batch.getRecords().hasNext()) {
      // No records - take the opportunity to clean up the cache so that we don't hold on to memory indefinitely
      cacheCleaner.periodicCleanUp();
    }

    boolean perRecord = false;
    // MS SQL Server does not support returning generateKey after executeBatch
    // Instead of executeBatch, do executeUpdate per record
    if (hikariConfigBean.getConnectionString().toLowerCase().startsWith("jdbc:sqlserver")) {
      perRecord = true;
    }

    if (dynamicTableName) {
      jdbcUtil.write(
          batch,
          tableNameEval,
          tableNameVars,
          tableNameTemplate,
          recordWriters,
          errorRecordHandler,
          perRecord
      );
    } else {
      jdbcUtil.write(batch.getRecords(), tableNameTemplate, recordWriters, errorRecordHandler, perRecord);
    }

    Iterator<Record> it = batch.getRecords();
    while (it.hasNext()) {
      batchMaker.addRecord(it.next());
    }
  }

@Override
  public String getFieldPath(String fieldPath, int operation) {
    if (operation == OperationType.UPDATE_CODE) {
    if (fieldPath.contains(ID_FIELD)){
      // _id is stored in "/o2/column_name for update records. Need to change the fieldpath"
      return fieldPath.replace(OP_FIELD, OP2_FIELD);
    } else {
      // column and values are stored in "/o/$set/column_name". Need to change the fieldpath
      return fieldPath.replaceFirst(OP_FIELD, String.format("%s/%s", OP_FIELD, SET_FIELD));
    }
  }
    return fieldPath;
  }

