private boolean detectCycle(LinkedHashSet<String> dependencyAncestors, Set<String> cycles, final String child) {
    if (dependencyAncestors.contains(child)) {
      // Find index of the child in the ancestors list
      int index = -1;
      for (String s : dependencyAncestors) {
        index++;
        if (s.equals(child)) {
          break;
        }
      }
      // The cycle starts from the first time the child is seen in the ancestors list
      // and continues till the end of the list, followed by the child again.
      cycles.add(Joiner.on(" -> ").join(Iterables.skip(dependencyAncestors, index)) + " -> " + child);
      return true;
    }
    return false;
  }

AWSCredentialsProvider createCredentialsProvider() throws StageException {
    String accessKey = credentialConfigs.getAccessKey().get();
    String secretKey = credentialConfigs.getSecretKey().get();
    if (accessKey != null && !accessKey.isEmpty() && secretKey != null && !secretKey.isEmpty()) {
      return new AWSStaticCredentialsProvider(new BasicAWSCredentials(credentialConfigs.getAccessKey().get(),
          credentialConfigs.getSecretKey().get()
      ));
    }
    return null;
  }

ClientConfiguration createClientConfiguration() throws StageException {
    ClientConfiguration clientConfig = new ClientConfiguration();

    clientConfig.setConnectionTimeout(connectionConfigs.getConnectionTimeoutMillis());
    clientConfig.setSocketTimeout(connectionConfigs.getSocketTimeoutMillis());
    clientConfig.withMaxErrorRetry(connectionConfigs.getMaxErrorRetry());

    if (connectionConfigs.isProxyEnabled()) {
      clientConfig.setProxyHost(connectionConfigs.getProxyHost());
      clientConfig.setProxyPort(connectionConfigs.getProxyPort());
      if (connectionConfigs.isProxyAuthenticationEnabled()) {
        clientConfig.setProxyUsername(connectionConfigs.getProxyUser().get());
        clientConfig.setProxyPassword(connectionConfigs.getProxyPassword().get());
      }
    }
    return clientConfig;
  }

AmazonS3Client createS3Client() throws StageException {

    AmazonS3ClientBuilder builder = createAmazonS3ClientBuilder().withClientConfiguration(createClientConfiguration())
                                                                 .withChunkedEncodingDisabled(connectionConfigs
                                                                     .isChunkedEncodingEnabled())
                                                                 .withPathStyleAccessEnabled(true);
    AWSCredentialsProvider awsCredentialsProvider = getCredentialsProvider();
    // If we don't call build.withCredentials(...) then we will not overwrite the default credentials provider
    // already set in the builder when doing AmazonS3ClientBuilder.standard() so only calling build.withCredentials(...)
    // if our own provider exists
    if (awsCredentialsProvider != null) {
      builder.withCredentials(awsCredentialsProvider);
    }

    String region = (connectionConfigs.getRegion() == null || connectionConfigs.getRegion().isEmpty())
                    ? null
                    : connectionConfigs.getRegion();

    if (connectionConfigs.isUseEndpoint()) {
      builder.withEndpointConfiguration(new AwsClientBuilder.EndpointConfiguration(connectionConfigs.getEndpoint(),
          region
      ));
    } else if (region != null) {
      builder.withRegion(connectionConfigs.getRegion());
    } else {
      builder.withRegion(AwsRegion.US_WEST_1.getId());
      builder.withForceGlobalBucketAccessEnabled(true);
    }
    return (AmazonS3Client) builder.build();
  }

TransferManager createTransferManager(AmazonS3 s3Client) throws StageException {
    return createTransferManagerBuilder().withS3Client(s3Client)
                                         .withExecutorFactory(
                                             createExecutorFactory(transferManagerConfigs.getThreads())
                                         )
                                         .withShutDownThreadPools(true)
                                         .withMinimumUploadPartSize(transferManagerConfigs.getMinimumUploadPartSize())
                                         .withMultipartUploadThreshold(transferManagerConfigs
                                             .getMultipartUploadThreshold())
                                         .build();
  }

static String calculateUserId(String csId) {
    try {
      // Try to hash based on default interface
      InetAddress ip = InetAddress.getLocalHost();
      NetworkInterface netIf = NetworkInterface.getByInetAddress(ip);
      byte[] mac = netIf.getHardwareAddress();

      if (mac == null) {
        // In some cases the default interface may be a tap/tun device which has no MAC
        // instead pick the first available interface.
        Enumeration<NetworkInterface> netIfs = NetworkInterface.getNetworkInterfaces();
        while (netIfs.hasMoreElements() && mac == null) {
          netIf = netIfs.nextElement();
          mac = netIf.getHardwareAddress();
        }
      }

      if (mac == null) {
        throw new IllegalStateException("Could not find network interface with MAC address.");
      }

      Hasher hasher = HASH_FUNCTION.newHasher(6); // MAC is 6 bytes.
      return hasher.putBytes(mac).hash().toString();
    } catch (IOException e) {
      LOG.error("CredentialStore '{}' Vault, could not compute Vault user-id: '{}'", csId, e);
      throw new VaultRuntimeException("Could not compute Vault user-id: " + e.toString());
    }
  }

public String read(String path, String key, long delay) {
    if (!secrets.containsKey(path)) {
      VaultClient vault = new VaultClient(getConfig());
      Secret secret;

      try {
        secret = vault.logical().read(path);
      } catch (VaultException e) {
        LOG.error(e.toString(), e);
        throw new VaultRuntimeException(e.toString());
      }

      // Record the expiration date of this lease
      String leaseId;
      if (secret.isRenewable()) {
        // Only renewable secrets seem to have a leaseId
        leaseId = secret.getLeaseId();
      } else {
        // So for non-renewable secrets we'll store the path with an extra / so that we can purge them correctly.
        leaseId = path + "/";
      }
      leases.put(leaseId, System.currentTimeMillis() + (secret.getLeaseDuration() * 1000));

      secrets.put(path, secret);

      try {
        Thread.sleep(delay);
      } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
      }
    }

    Map<String, Object> data = secrets.get(path).getData();
    String value = getSecretValue(data, key).orElseThrow(() -> new VaultRuntimeException("Value not found for key"));
    LOG.trace("CredentialStore '{}' Vault, retrieved value for key '{}'", csId, key);
    return value;
  }

private WriteOperationType getOperationFromHeader(Record record, String key) {

    String op = record.getHeader().getAttribute(OperationType.SDC_OPERATION_TYPE);
    if (op == null || op.isEmpty()) {
      return config.defaultWriteOperation;
    }

    int opCode;

    try {
      opCode = Integer.parseInt(op);
    } catch(NumberFormatException e) {
        LOG.debug("Unparsable CDC operation. Sending record to error.");
        handleError(record, Errors.COUCHBASE_08, e);
        return null;
      }

    switch (opCode) {
      case OperationType.INSERT_CODE:
        return WriteOperationType.INSERT;
      case OperationType.UPDATE_CODE:
        return WriteOperationType.REPLACE;
      case OperationType.UPSERT_CODE:
        return WriteOperationType.UPSERT;
      case OperationType.DELETE_CODE:
        return WriteOperationType.DELETE;
      default:
        switch (config.unsupportedOperation) {
          case DISCARD:
            LOG.debug("Unsupported CDC operation for key: {}. Discarding record per configuration.", key);
            return null;
          case TOERROR:
            LOG.debug("Unsupported CDC operation for key: {}. Sending record to error configuration.", key);
            handleError(record, Errors.COUCHBASE_09, new RuntimeException());
            return null;
          default:
            LOG.debug("Unsupported CDC operation for key: {}. Using default write operation per configuration.", key);
            return config.defaultWriteOperation;
        }
    }
  }

private Observable<AbstractDocument> writeDoc(String key, int ttl, long cas, ByteArrayOutputStream baos, Record record) {

    WriteOperationType opType = getOperationFromHeader(record, key);

    if(opType == null) {
      return Observable.empty();
    }

    AbstractDocument doc;

    if(config.dataFormat == DataFormat.JSON) {
      try {
         doc = JsonDocument.create(key, ttl, JsonObject.fromJson(baos.toString(config.dataFormatConfig.charset)), cas);
      } catch(Exception e) {
        return handleError(record, Errors.COUCHBASE_10, e);
      }
    } else {
       doc = ByteArrayDocument.create(key, ttl, baos.toByteArray(), cas);
    }

    switch (opType) {
      case DELETE: {
          LOG.debug("DELETE key: {}, TTL: {}, CAS: {}", key, ttl, cas);
          return connector.bucket().remove(doc, config.persistTo, config.replicateTo)
              .timeout(config.couchbase.kvTimeout, TimeUnit.MILLISECONDS);
      }
      case INSERT: {
          LOG.debug("INSERT key: {}, TTL: {}, CAS: {}", key, ttl, cas);
          return connector.bucket().insert(doc, config.persistTo, config.replicateTo)
              .timeout(config.couchbase.kvTimeout, TimeUnit.MILLISECONDS);
      }
      case REPLACE: {
          LOG.debug("REPLACE key: {}, TTL: {}, CAS: {}", key, ttl, cas);
          return connector.bucket().replace(doc, config.persistTo, config.replicateTo)
              .timeout(config.couchbase.kvTimeout, TimeUnit.MILLISECONDS);
      }
      case UPSERT: {
          LOG.debug("UPSERT key: {}, TTL: {}, CAS: {}", key, ttl, cas);
          return connector.bucket().upsert(doc, config.persistTo, config.replicateTo)
              .timeout(config.couchbase.kvTimeout, TimeUnit.MILLISECONDS);
      }
      default:
        return Observable.empty();
    }
  }

private Observable<DocumentFragment<Mutation>> writeSubdoc(String key, int ttl, long cas, ByteArrayOutputStream baos,
      String subdocPath, Record record) {

    JsonObject frag;

    try {
      frag = JsonObject.fromJson(baos.toString(config.dataFormatConfig.charset));
    }
    catch (IOException e) {
      return handleError(record, Errors.COUCHBASE_12, e);
    }

    AsyncMutateInBuilder mutation = connector.bucket().mutateIn(key);
    SubdocOptionsBuilder options = new SubdocOptionsBuilder().createPath(true);
    String subdocOpType;

    try {
      subdocOpType = subdocOperationELEval.eval(elVars, config.subdocOperationEL, String.class);
    } catch (ELEvalException e) {
      return handleError(record, Errors.COUCHBASE_13, e);
    }

    if(config.allowSubdoc && !subdocOpType.isEmpty()) {
      switch (subdocOpType.toUpperCase()) {
        case "DELETE":
          LOG.debug("Sub-document DELETE key: {}, sub-document path: {}, TTL: {}, CAS: {}", key, subdocPath, ttl, cas);
          return buildSubdocMutation(mutation.remove(subdocPath, options), ttl, cas, false);

        case "INSERT":
          LOG.debug("Sub-document INSERT key: {}, sub-document path: {}, TTL: {}, CAS: {}", key, subdocPath, ttl, cas);
          return buildSubdocMutation(mutation.insert(subdocPath, frag, options), ttl, cas, true);

        case "REPLACE":
          LOG.debug("Sub-document REPLACE key: {}, sub-document path: {}, TTL: {}, CAS: {}", key, subdocPath, ttl, cas);
          return buildSubdocMutation(mutation.replace(subdocPath, frag), ttl, cas,false);

        case "UPSERT":
          LOG.debug("Sub-document UPSERT key: {}, sub-document path: {}, TTL: {}, CAS: {}", key, subdocPath, ttl, cas);
          return buildSubdocMutation(mutation.upsert(subdocPath, frag, options), ttl, cas,true);

        case "ARRAY_PREPEND":
          LOG.debug("Sub-document ARRAY_PREPEND key: {}, sub-document path: {}, TTL: {}, CAS: {}", key, subdocPath, ttl, cas);
          return buildSubdocMutation(mutation.arrayPrepend(subdocPath, frag, options), ttl, cas,true);

        case "ARRAY_APPEND":
          LOG.debug("Sub-document ARRAY_APPEND key: {}, sub-document path: {}, TTL: {}, CAS: {}", key, subdocPath, ttl, cas);
          return buildSubdocMutation(mutation.arrayAppend(subdocPath, frag, options), ttl, cas, true);

        case "ARRAY_ADD_UNIQUE":
          LOG.debug("Sub-document ARRAY_ADD_UNIQUE key: {}, sub-document path: {}, TTL: {}, CAS: {}", key, subdocPath, ttl, cas);
          return buildSubdocMutation(mutation.arrayAddUnique(subdocPath, frag, options), ttl, cas, true);

        default:
          switch (config.unsupportedOperation) {
            case DISCARD:
              LOG.debug("Unsupported sub-document operation: {} for key: {}. Discarding record per configuration.", subdocOpType, key);
              return Observable.empty();
            case TOERROR:
              LOG.debug("Unsupported sub-document operation: {} for key: {}. Sending record to error per configuration.", subdocOpType, key);
              return handleError(record, Errors.COUCHBASE_14, new RuntimeException());
            default:
              LOG.debug("Unsupported sub-document operation: {} for key: {}. Using default write operation per configuration.", subdocOpType, key);
              // Fall through
              // Inherit the CDC or default operation
          }
      }
    }

    WriteOperationType opType = getOperationFromHeader(record, key);

    if(opType == null) {
      return Observable.empty();
    }

    switch (opType) {
      case DELETE:
        LOG.debug("Sub-document DELETE key: {}, sub-document path: {}, TTL: {}, CAS: {}", key, subdocPath, ttl, cas);
        return buildSubdocMutation(mutation.remove(subdocPath, options), ttl, cas,false);

      case INSERT:
        LOG.debug("Sub-document INSERT key: {}, sub-document path: {}, TTL: {}, CAS: {}", key, subdocPath, ttl, cas);
        return buildSubdocMutation(mutation.insert(subdocPath, frag, options), ttl, cas, true);

      case REPLACE:
        LOG.debug("Sub-document REPLACE key: {}, sub-document path: {}, TTL: {}, CAS: {}", key, subdocPath, ttl, cas);
        return buildSubdocMutation(mutation.replace(subdocPath, frag), ttl, cas, false);

      case UPSERT:
        LOG.debug("Sub-document UPSERT key: {}, sub-document path: {}, TTL: {}, CAS: {}", key, subdocPath, ttl, cas);
        return buildSubdocMutation(mutation.upsert(subdocPath, frag, options), ttl, cas, true);

      default:
        return Observable.empty();
    }
  }

private Observable<DocumentFragment<Mutation>> buildSubdocMutation(AsyncMutateInBuilder mutation, int ttl, long cas,
      boolean upsertDoc) {

    return mutation
        .upsertDocument(upsertDoc)
        .withExpiry(ttl)
        .withCas(cas)
        .withDurability(config.persistTo, config.replicateTo)
        .execute()
        .timeout(config.couchbase.kvTimeout, TimeUnit.MILLISECONDS);
  }

