public static boolean compareFiles(WrappedFileSystem fs, WrappedFile f1, WrappedFile f2) {
    if (!fs.exists(f2)) {
      return true;
    }

    try {
      long mtime1 = fs.getLastModifiedTime(f1);
      long mtime2 = fs.getLastModifiedTime(f2);

      long ctime1 = fs.getChangedTime(f1);
      long ctime2 = fs.getChangedTime(f2);

      long time1 = Math.max(mtime1, ctime1);
      long time2 = Math.max(mtime2, ctime2);

      int compares = Long.compare(time1, time2);

      if (compares != 0) {
        return compares > 0;
      }
    } catch (IOException ex) {
      LOG.error("Failed to get ctime: '{}'", f1.getFileName(), ex);
      return false;
    }

    return f1.getAbsolutePath().compareTo(f2.getAbsolutePath()) > 0;
  }

public static DataParser getParser(
      WrappedFileSystem fs,
      WrappedFile file,
      DataFormat dataFormat,
      DataParserFactory parserFactory,
      String offset,
      int wholeFileMaxObjectLen,
      ELEval rateLimitElEval,
      ELVars rateLimitElVars,
      String rateLimit
  ) throws DataParserException, ELEvalException, IOException {
    DataParser parser;

    switch (dataFormat) {
      case WHOLE_FILE:
        FileRef fileRef = fs.getFileRefBuilder()
            .filePath(file.getAbsolutePath())
            .bufferSize(wholeFileMaxObjectLen)
            .rateLimit(FileRefUtil.evaluateAndGetRateLimit(rateLimitElEval, rateLimitElVars, rateLimit))
            .createMetrics(true)
            .totalSizeInBytes(file.getSize())
            .build();
        parser = parserFactory.getParser(file.getFileName(), file.getFileMetadata(), fileRef);
        break;
      default:
        parser = parserFactory.getParser(file.getFileName(), file.getInputStream(), offset);
    }

    return parser;
  }

public static String truncateGlobPatternDirectory(String directory) {
    String[] absolutePath = directory.split(ESCAPED_ASTERISK);
    String truncatedString = absolutePath[0];

    if (lastCharacterIsAsterisk(truncatedString) != SLASH.toCharArray()[0]) {
      List<String> subDirectories = Arrays.asList(truncatedString.split(SLASH));
      StringBuffer stringBuffer = new StringBuffer();
      stringBuffer.append(String.join(SLASH, subDirectories.subList(0, subDirectories.size() - 1))).append(SLASH);
      truncatedString = stringBuffer.toString();
    }

    LOG.debug(String.format("Checking existence of path: %s", truncatedString));
    return truncatedString;
  }

private static int retrievePidIfFeasible(Process process) {
    if(unixProcessClass == null) {
      return UNDETERMINED_PID;
    }

    if(!unixProcessClass.isInstance(process)) {
      LOG.debug("Do not support retrieving PID from {}", process.getClass().getName());
      return UNDETERMINED_PID;
    }

    try {
      return (int)pidField.get(process);
    } catch (IllegalAccessException e) {
      LOG.debug("Can't retrieve PID value from the field", e);
      return UNDETERMINED_PID;
    }

  }

private Set<String> validateAndExtractFieldsToHash(
      Record record,
      Set<String> fieldsDontExist,
      Set<String> fieldsWithListOrMapType,
      Set<String> fieldsWithNull,
      Collection<String> matchingFieldsPath
  ) {
    Set<String> validFieldsToHashForThisConfig = new HashSet<String>();
    for (String matchingFieldPath : matchingFieldsPath) {
      if (record.has(matchingFieldPath)) {
        Field field = record.get(matchingFieldPath);
        if (UNSUPPORTED_FIELD_TYPES.contains(field.getType())) {
          fieldsWithListOrMapType.add(matchingFieldPath);
        } else if (field.getValue() == null) {
          fieldsWithNull.add(matchingFieldPath);
        } else {
          validFieldsToHashForThisConfig.add(matchingFieldPath);
        }
      } else {
        fieldsDontExist.add(matchingFieldPath);
      }
    }
    return validFieldsToHashForThisConfig;
  }

public static UserGroupInformation getProxyUser(
    String user,                    // Hadoop user (HDFS User, HBase user, generally the to-be-impersonated user in component's configuration)
    Stage.Context context,          // Stage context object
    UserGroupInformation loginUser, // Login UGI (sdc user)
    List<Stage.ConfigIssue> issues, // Reports errors
    String configGroup,             // Group where "HDFS User" is present
    String configName               // Config name of "HDFS User"
  ) {
    // Should we always impersonate current user?
    boolean alwaysImpersonate = context.getConfiguration().get(
      HadoopConfigConstants.IMPERSONATION_ALWAYS_CURRENT_USER,
      false
    );

    // If so, propagate current user to "user" (the one to be impersonated)
    if(alwaysImpersonate) {
      if(!StringUtils.isEmpty(user)) {
        issues.add(context.createConfigIssue(configGroup, configName, Errors.HADOOP_00001));
      }
      user = context.getUserContext().getAliasName();
    }

    // If impersonated user is empty, simply return login UGI (no impersonation performed)
    if(StringUtils.isEmpty(user)) {
      return loginUser;
    }

    // Optionally lower case the user name
    boolean lowerCase = context.getConfiguration().get(
      HadoopConfigConstants.LOWERCASE_USER,
      false
    );
    if(lowerCase) {
      user = user.toLowerCase();
    }
    return UserGroupInformation.createProxyUser(user, loginUser);
  }

public ActiveStats roll() {
    long now = System.currentTimeMillis();
    setEndTime(now);
    ActiveStats statsBean = new ActiveStats().setStartTime(now)
                                             .setDataCollectorVersion(getDataCollectorVersion())
                                             .setDpmEnabled(isDpmEnabled())
                                             .setUpTime(getUpTime().roll());
    statsBean.setPipelines(getPipelines().stream().map(UsageTimer::roll).collect(Collectors.toList()));
    statsBean.setStages(getStages().stream()
                                   .filter(timer -> timer.getMultiplier() > 0)
                                   .map(UsageTimer::roll)
                                   .collect(Collectors.toList()));
    return statsBean;
  }

