public int queueReport() throws IOException, InterruptedException, ExecutionException, TimeoutException, StageException {
    final AsyncInvoker asyncInvoker = queueResource.request()
        .header(WSSE_HEADER, OmnitureAuthUtil.getHeader(username.get(), sharedSecret.get()))
        .async();
    LOG.debug("Queueing report using URL {} with description {}",
        queueResource.getUri().toURL().toString(), reportDescription);
    final Future<Response> responseFuture = asyncInvoker.post(Entity.json(reportDescription));
    Response response = responseFuture.get(responseTimeoutMillis, TimeUnit.MILLISECONDS);
    if (response == null) {
      LOG.error("Failed to get response using URL {}", queueResource.getUri().toURL().toString());
      throw new StageException(Errors.OMNITURE_01, "HTTP response was null");
    }
    LOG.debug("Received response: status {}", response.getStatus());

    ObjectMapper mapper = new ObjectMapper();
    String json = response.readEntity(String.class);
    LOG.trace("Response JSON: {}", json);
    JsonNode root = mapper.readTree(json);

    if (root == null) {
      LOG.error("Invalid JSON in response: {}", json);
      throw new StageException(Errors.OMNITURE_01, json);
    }

    if (root.has("error")) {
      throw new StageException(Errors.OMNITURE_01, root.get("error_description").asText());
    }

    LOG.info("Omniture report queued");
    return root.get("reportID").asInt();
  }

public void getReport(int reportId)
      throws InterruptedException, ExecutionException, TimeoutException, IOException, StageException {
    int waitTime = 1000;
    Response response = null;
    while (!stop) {
      final AsyncInvoker asyncInvoker = getResource.request()
          .header(WSSE_HEADER, OmnitureAuthUtil.getHeader(username.get(), sharedSecret.get()))
          .async();

      LOG.debug("Getting report using URL {} with report ID {}", getResource.getUri().toURL().toString(), reportId);
      final Future<Response> responseFuture = asyncInvoker.post(Entity.json("{ \"reportID\": " + reportId + " }"));
      response = responseFuture.get(responseTimeoutMillis, TimeUnit.MILLISECONDS);
      String input = response.readEntity(String.class);

      ObjectMapper mapper = new ObjectMapper();
      JsonNode root = mapper.readTree(input);

      // If the report has an error field, it means the report has not finished generating
      if (!root.has("error")) {
        boolean accepted = entityQueue.offer(input, responseTimeoutMillis, TimeUnit.MILLISECONDS);
        if (!accepted) {
          LOG.warn("Response buffer full, dropped record.");
        }
        break;
      } else {
        // Exponential backoff while making subsequent Report.Get requests
        if (root.get("error").textValue().equals("report_not_ready")) {
          waitTime *= 2;
          LOG.info("Report not available. Sleeping for {} seconds", waitTime / 1000);
          Thread.sleep(waitTime);
        } else {
          throw new StageException(Errors.OMNITURE_02,
              root.get("error").get("error_description").asText());
        }
      }
    }
    response.close();
  }

public boolean isSDCCheckPointing()  {
    try {
      return fs.exists(checkPointFilePath) || fs.exists(backupCheckPointFilePath);
    } catch (IOException ex) {
      LOG.error("Error doing isSDCCheckPointing", ex);
      throw new RuntimeException(Utils.format("Error checking exists on hdfs path: {}. Reason: {}", checkPointFilePath.toString(), ex.toString()), ex);
    }
  }

private void writeOffsetsToMainOffsetFile(Map<Integer, Long> partitionToOffsetMap) throws IOException {
    LOG.info("Saving the following offset {} to {}", partitionToOffsetMap, checkPointFilePath);

    //Creating a marker file (overwriting if it already exists) to mark that we are going to write offsets out the offsets to the main offset file.
    try(OutputStream os = fs.create(checkPointMarkerFilePath, true)) {
      //NOOP
    }
    //If the both above passes and writing fails or leaves corrupted file we will have the back file
    try (OutputStream os = fs.create(checkPointFilePath, true)) {
      OBJECT_MAPPER.writeValue(os, new ClusterSourceOffsetJson(serializeKafkaPartitionOffset(partitionToOffsetMap), SDC_STREAMING_OFFSET_VERSION));
    }

    //If this fails we are still good, as we will start from the backup offset file. (Not optimal, but deterministic)
    boolean deleted = fs.delete(checkPointMarkerFilePath, false);
    LOG.warn("Status {} for Deleting Marker File {}", deleted, checkPointMarkerFilePath);

    //If the write fails we don't want to touch the timestamp and will error out so not doing this in finally
    lastOffsetStoredTime = System.currentTimeMillis();
  }

private Map<Integer, Long> readClusterOffsetFile(Path checkPointFilePath, int numberOfPartitions) throws IOException{
    if (!fs.exists(checkPointFilePath)) {
      throw new IOException(Utils.format("Checkpoint file path {} does not exist", checkPointFilePath));
    }
    ClusterSourceOffsetJson clusterSourceOffsetJson = OBJECT_MAPPER.readValue(
        (InputStream) fs.open(checkPointFilePath),
        ClusterSourceOffsetJson.class
    );
    String lastSourceOffset = clusterSourceOffsetJson.getOffset();
    if (!StringUtils.isEmpty(lastSourceOffset)) {
      return deserializeKafkaPartitionOffset(lastSourceOffset, numberOfPartitions);
    } else {
      throw new IOException("Partition Offset Cannot be empty");
    }
  }

public TableOrderProvider create() {
    switch (tableOrderStrategy) {
      case NONE:
        //Don't do any ordering, just add tables as per the incoming order.
        return new DefaultTableOrderProvider(new LinkedHashSet<>());
      case ALPHABETICAL:
        //Alphabetical sorting based on table qualified names.
        return new DefaultTableOrderProvider(new TreeSet<>());
      case REFERENTIAL_CONSTRAINTS:
        return new ReferentialTblOrderProvider(connection);
      default:
        throw new IllegalArgumentException(Utils.format("Unknown table order strategy: {}", tableOrderStrategy));
    }
  }

private void delete(BlobId blobId) {
    LOG.debug("Deleting object '{}'", String.format(BLOB_PATH_TEMPLATE, blobId.getBucket(), blobId.getName()));
    boolean deleted = storage.delete(blobId);
    if (!deleted) {
      LOG.error("Cannot delete object '{}'", String.format(BLOB_PATH_TEMPLATE, blobId.getBucket(), blobId.getName()));
    }
  }

private void copy(BlobId sourceBlobId, String destinationBucket, String destinationPath, boolean deleteSource) {
    LOG.debug(
        "Copying object '{}' to Object '{}'",
        String.format(BLOB_PATH_TEMPLATE, sourceBlobId.getBucket(), sourceBlobId.getName()),
        String.format(BLOB_PATH_TEMPLATE, destinationBucket, destinationPath)
    );

    Storage.CopyRequest copyRequest = new Storage.CopyRequest.Builder()
        .setSource(sourceBlobId)
        .setTarget(BlobId.of(destinationBucket, destinationPath))
        .build();
    Blob destinationBlob = storage.copy(copyRequest).getResult();
    LOG.debug(
        "Copied object '{}' to Object '{}'",
        String.format(BLOB_PATH_TEMPLATE, sourceBlobId.getBucket(), sourceBlobId.getName()),
        String.format(BLOB_PATH_TEMPLATE, destinationBlob.getBlobId().getBucket(), destinationBlob.getBlobId().getName())
    );
    if (deleteSource) {
      delete(sourceBlobId);
    }
  }

void handleError(BlobId blobId) {
    switch (gcsOriginErrorConfig.errorHandlingOption) {
      case NONE:
        break;
      case ARCHIVE:
        handleArchive(blobId);
        break;
      case DELETE:
        delete(blobId);
        break;
    }
  }

private void handleArchive(BlobId blobId) {
    String destinationPath = getDestinationPath(blobId, gcsOriginErrorConfig.errorPrefix);
    switch (gcsOriginErrorConfig.archivingOption) {
