@Override
  public void initialize(InitializationInput initializationInput) {
    shardId = initializationInput.getShardId();
    if (LOG.isDebugEnabled()) {
      LOG.debug("Initializing record processor at: {}", initializationInput.getExtendedSequenceNumber().toString());
      LOG.debug("Initializing record processor for shard: {}", shardId);
    }
  }

@Override
  public void processRecords(ProcessRecordsInput processRecordsInput) {
    LOG.debug("RecordProcessor processRecords called");

    try {
      IRecordProcessorCheckpointer checkpointer = processRecordsInput.getCheckpointer();
      startBatch();
      Optional<Record> lastProcessedRecord = Optional.empty();
      int recordCount = 0;
      for (Record kRecord : processRecordsInput.getRecords()) {
        try {
          KinesisUtil.processKinesisRecord(shardId, kRecord, parserFactory).forEach(batchMaker::addRecord);
          lastProcessedRecord = Optional.of(kRecord);
          if (++recordCount == maxBatchSize) {
            recordCount = 0;
            finishBatch(checkpointer, kRecord);
            startBatch();
          }
        } catch (DataParserException | IOException e) {
          com.streamsets.pipeline.api.Record record = context.createRecord(kRecord.getSequenceNumber());
          record.set(Field.create(kRecord.getData().array()));
          try {
            errorRecordHandler.onError(new OnRecordErrorException(
                record,
                Errors.KINESIS_03,
                kRecord.getSequenceNumber(),
                e.toString(),
                e
            ));
            // move the lastProcessedRecord forward if not set to stop pipeline
            lastProcessedRecord = Optional.of(kRecord);
          } catch (StageException ex) {
            // KCL skips over the data records that were passed prior to the exception
            // that is, these records are not re-sent to this record processor
            // or to any other record processor in the consumer.
            lastProcessedRecord.ifPresent(r -> finishBatch(checkpointer, r));
            try {
              error.put(ex);
            } catch (InterruptedException ie) {
              Thread.currentThread().interrupt();
            }
            return;
          }
        }
      }
      lastProcessedRecord.ifPresent(r -> finishBatch(checkpointer, r));
    } catch (Exception e) {
      LOG.error("Unknown error while processing records: {}", e.toString(), e);
      context.reportError(Errors.KINESIS_17, e.toString());
    }
  }

@Override
  public void shutdown(ShutdownInput shutdownInput) {
    LOG.info("Shutting down record processor for shard: {}", shardId);

    if (ShutdownReason.TERMINATE.equals(shutdownInput.getShutdownReason())) {
      // Shard is closed / finished processing. Checkpoint all processing up to here.
      try {
        shutdownInput.getCheckpointer().checkpoint();
        LOG.debug("Checkpointed due to record processor shutdown request.");
      } catch (InvalidStateException | ShutdownException e) {
        LOG.error("Error checkpointing batch: {}", e.toString(), e);
      }
    }
  }

@Override
  public void process(final HttpRequest request, final HttpContext context)
      throws HttpException, IOException {
    URIBuilder uriBuilder;
    try {
      uriBuilder = new URIBuilder(request.getRequestLine().getUri());
    } catch (URISyntaxException e) {
      throw new IOException("Invalid URI" , e);
    }

    // Copy Apache HttpRequest to AWS DefaultRequest
    DefaultRequest<?> signableRequest = new DefaultRequest<>(service);

    HttpHost host = (HttpHost) context.getAttribute(HttpCoreContext.HTTP_TARGET_HOST);
    if (host != null) {
      signableRequest.setEndpoint(URI.create(host.toURI()));
    }
    final HttpMethodName httpMethod =
        HttpMethodName.fromValue(request.getRequestLine().getMethod());
    signableRequest.setHttpMethod(httpMethod);
    try {
      signableRequest.setResourcePath(uriBuilder.build().getRawPath());
    } catch (URISyntaxException e) {
      throw new IOException("Invalid URI" , e);
    }

    if (request instanceof HttpEntityEnclosingRequest) {
      HttpEntityEnclosingRequest httpEntityEnclosingRequest =
          (HttpEntityEnclosingRequest) request;
      if (httpEntityEnclosingRequest.getEntity() != null) {
        signableRequest.setContent(httpEntityEnclosingRequest.getEntity().getContent());
      }
    }
    signableRequest.setParameters(nvpToMapParams(uriBuilder.getQueryParams()));
    signableRequest.setHeaders(headerArrayToMap(request.getAllHeaders()));

    // Sign it
    signer.sign(signableRequest, awsCredentialsProvider.getCredentials());

    // Now copy everything back
    request.setHeaders(mapToHeaderArray(signableRequest.getHeaders()));
    if (request instanceof HttpEntityEnclosingRequest) {
      HttpEntityEnclosingRequest httpEntityEnclosingRequest =
          (HttpEntityEnclosingRequest) request;
      if (httpEntityEnclosingRequest.getEntity() != null) {
        BasicHttpEntity basicHttpEntity = new BasicHttpEntity();
        basicHttpEntity.setContent(signableRequest.getContent());
        httpEntityEnclosingRequest.setEntity(basicHttpEntity);
      }
    }
  }

private boolean checkFieldOrderByList(SOQLParser.FieldOrderByListContext fieldOrderByList, String fieldName) {
    return fieldOrderByList.fieldOrderByElement(0).fieldElement().getText().equalsIgnoreCase(fieldName);
  }

private boolean checkConditionExpressions(
      SOQLParser.ConditionExpressionsContext conditionExpressions,
      String fieldName
  ) {
    for (SOQLParser.ConditionExpressionContext ce : conditionExpressions.conditionExpression()) {
      if ((ce.conditionExpressions() != null && checkConditionExpressions(ce.conditionExpressions(), fieldName))
          || (ce.fieldExpression() != null && ce.fieldExpression().fieldElement().getText().equalsIgnoreCase(fieldName))) {
        return true;
      }
    }

    return false;
  }

@Override
  public void destroy() {
    // SDC-6258 - destroy() is called from a different thread, so we
    // need to signal produce() to terminate early
    destroyed.set(true);

    if (job != null) {
      try {
        try {
          bulkConnection.abortJob(job.getId());
        } catch (AsyncApiException e) {
          ForceUtils.renewSession(bulkConnection, e);
          bulkConnection.abortJob(job.getId());
        }
        job = null;
      } catch (AsyncApiException e) {
        LOG.error("Exception while aborting job", e);
      }
    }

    job = null;

    if (forceConsumer != null) {
      try {
        forceConsumer.stop();
        forceConsumer = null;
      } catch (Exception e) {
        LOG.error("Exception while stopping ForceStreamConsumer.", e);
      }

      if (!messageQueue.isEmpty()) {
        LOG.error("Queue still had {} entities at shutdown.", messageQueue.size());
      } else {
        LOG.info("Queue was empty at shutdown. No data lost.");
      }
    }

    if (recordCreator != null) {
      recordCreator.destroy();
    }

    // Clean up any open resources.
    super.destroy();
  }

@Override
  public String produce(String lastSourceOffset, int maxBatchSize, BatchMaker batchMaker) throws StageException {
    String nextSourceOffset = null;

    LOG.debug("lastSourceOffset: {}", lastSourceOffset);

    // send event only once for each time we run out of data.
    if(shouldSendNoMoreDataEvent) {
      CommonEvents.NO_MORE_DATA.create(getContext()).createAndSend();
      shouldSendNoMoreDataEvent = false;
      return lastSourceOffset;
    }

    int batchSize = Math.min(conf.basicConfig.maxBatchSize, maxBatchSize);

    if (!conf.queryExistingData ||
        (null != lastSourceOffset && lastSourceOffset.startsWith(EVENT_ID_OFFSET_PREFIX))) {
      if (conf.subscribeToStreaming) {
        nextSourceOffset = streamingProduce(lastSourceOffset, batchSize, batchMaker);
      } else {
        // We're done reading existing data, but we don't want to subscribe to Streaming API
        return null;
      }
    } else if (conf.queryExistingData) {
      if (!queryInProgress()) {
        long now = System.currentTimeMillis();
        long delay = Math.max(0, (lastQueryCompletedTime + (1000 * conf.queryInterval)) - now);

        if (delay > 0) {
          // Sleep in one second increments so we don't tie up the app.
          LOG.info("{}ms remaining until next fetch.", delay);
          ThreadUtil.sleep(Math.min(delay, 1000));

          return lastSourceOffset;
        }
      }

      if (conf.useBulkAPI) {
        nextSourceOffset = bulkProduce(lastSourceOffset, batchSize, batchMaker);
      } else {
        nextSourceOffset = soapProduce(lastSourceOffset, batchSize, batchMaker);
      }
    } else if (conf.subscribeToStreaming) {
      // No offset, and we're not querying existing data, so switch to streaming
      nextSourceOffset = READ_EVENTS_FROM_NOW;
    }

    LOG.debug("nextSourceOffset: {}", nextSourceOffset);

    return nextSourceOffset;
  }

