      }
    }
    return originParallelism;
  }

static List<URL> bringStageAndProtoLibsToFront(String stageLibName, List<URL> urls) {
    List<URL> otherJars = new ArrayList<>();
    List<URL> protolibJars = new ArrayList<>();
    List<URL> stageLibjars = new ArrayList<>();
    for (URL url : urls) {
      String str = url.toExternalForm();
      if (str.endsWith(".jar")) {
        int nameIdx = str.lastIndexOf("/");
        if (nameIdx > -1) {
          String jarName = str.substring(nameIdx + 1);
          if (jarName.contains("-protolib-")) {
            // adding only protolib jars
            protolibJars.add(url);
          } else if (jarName.contains(stageLibName)) {
            stageLibjars.add(url);
          } else {
            otherJars.add(url);
          }
        } else {
          otherJars.add(url);
        }
      } else {
        otherJars.add(url);
      }
    }
    List<URL> allJars = new ArrayList<>();
    if (stageLibjars.size() != 1) {
      throw new ExceptionInInitializerError("Expected exactly 1 stage lib jar but found " + stageLibjars.size() +
          " with name " + stageLibName);
    }
    allJars.addAll(stageLibjars);
    allJars.addAll(protolibJars);
    allJars.addAll(otherJars);
    return allJars;
  }

public TableResult runQuery(QueryJobConfiguration queryConfig, long timeout, long pageSize) throws
      StageException {
    checkArgument(timeout >= 1000, "Timeout must be at least one second.");
    Instant maxTime = Instant.now().plusMillis(timeout);

    // Create a job ID so that we can safely retry.
    JobId jobId = JobId.of(UUID.randomUUID().toString());
    JobInfo jobInfo = JobInfo.newBuilder(queryConfig).setJobId(jobId).build();
    Job queryJob = bigquery.create(jobInfo);

    // Check for errors
    if (queryJob == null) {
      LOG.error("Job no longer exists: {}", jobInfo);
      throw new RuntimeException("Job no longer exists: "+jobInfo);
    } else if (queryJob.getStatus().getError() != null) {
      BigQueryError error = queryJob.getStatus().getError();
      LOG.error("Query Job execution error: {}", error);
      throw new StageException(Errors.BIGQUERY_02, error);
    }

    //Should consider using .waitFor(RetryOption.totalTimeout())
    while(!queryJob.isDone()) {
      if (Instant.now(clock).isAfter(maxTime) || !ThreadUtil.sleep(100)) {
        if (bigquery.cancel(queryJob.getJobId())) {
          LOG.info("Job {} cancelled successfully.", queryJob.getJobId());
        } else {
          LOG.warn("Job {} not found", queryJob.getJobId());
        }
        throw new StageException(Errors.BIGQUERY_00);
      }
    }


    if (queryJob.getStatus().getError() != null) {
      String errorMsg = queryJob.getStatus().getError().toString();
      throw new StageException(Errors.BIGQUERY_02, errorMsg);
    }

    // Get the results.
    TableResult result = null;
    try {
      result = queryJob.getQueryResults(QueryResultsOption.pageSize(pageSize));
    } catch (InterruptedException e) {
      String errorMsg = e.getMessage();
      throw new StageException(Errors.BIGQUERY_02, errorMsg);
    }

    return result;
  }

public Field.Type asRecordFieldType(com.google.cloud.bigquery.Field field) {
    Field.Type type = asRecordFieldTypeFunction.apply(field);
    return checkNotNull(type, Utils.format("Unsupported type '{}'", field.getType()));
  }

public LinkedHashMap<String, Field> fieldsToMap( // NOSONAR
      List<com.google.cloud.bigquery.Field> schema,
      List<FieldValue> values
  ) {
    checkState(
        schema.size() == values.size(),
        "Schema '{}' and Values '{}' sizes do not match.",
        schema.size(),
        values.size()
    );

    LinkedHashMap<String, Field> root = new LinkedHashMap<>();
    for (int i = 0; i < values.size(); i++) {
      FieldValue value = values.get(i);
      com.google.cloud.bigquery.Field field = schema.get(i);
      if (value.getAttribute().equals(FieldValue.Attribute.PRIMITIVE)) {
        root.put(field.getName(), fromPrimitiveField(field, value));
      } else if (value.getAttribute().equals(FieldValue.Attribute.RECORD)) {
        root.put(
            field.getName(),
            Field.create(fieldsToMap(field.getSubFields(), value.getRecordValue()))
        );
      } else if (value.getAttribute().equals(FieldValue.Attribute.REPEATED)) {
        root.put(field.getName(), Field.create(fromRepeatedField(field, value.getRepeatedValue())));
      }
    }
    return root;
  }

public List<Field> fromRepeatedField(com.google.cloud.bigquery.Field schema,
      List<FieldValue> repeatedValue) {

    if (repeatedValue.isEmpty()) {
      return Collections.emptyList();
    }
    FieldValue.Attribute repeatedFieldType = repeatedValue.get(0).getAttribute();

    BiFunction<com.google.cloud.bigquery.Field, FieldValue, Field> transform =
        transforms.get(repeatedFieldType);
    return repeatedValue
        .stream()
        .map( v -> transform.apply(schema, v))
        .collect(Collectors.toList());
  }

private List<String> getTableDescription() throws GPUdbException {
    List<List<String>> descriptions = showTableResponse.getTableDescriptions();
    if (descriptions == null || descriptions.size() != 1) {
      throw new GPUdbException("Error getting description for table " + tableName);
    }
    return descriptions.get(0);
  }

private void validateTableAcceptsInserts() throws GPUdbException {
    for (String s : tableDescription) {
      if (s.equalsIgnoreCase("COLLECTION")) {
        throw new GPUdbException("Error: table " + tableName + " is a Collection");
      } else if (s.equalsIgnoreCase("VIEW")) {
        throw new GPUdbException("Error: table " + tableName + " is a View");
      } else if (s.equalsIgnoreCase("JOIN")) {
        throw new GPUdbException("Error: table " + tableName + " is a Join Table");
      } else if (s.equalsIgnoreCase("RESULT_TABLE")) {
        throw new GPUdbException("Error: table " + tableName + " is a Result Table");
      }
    }
  }

private Class<?> getColumnType(JSONObject field) throws GPUdbException {

    Class<?> columnType = null;

    // The Avro "type" element might be an array if the type is nullable
    if (field.get("type") instanceof JSONArray) {
      JSONArray columnTypes = field.getJSONArray("type");
      for (int j = 0; j < columnTypes.length(); j++) {
        String ct = (String) columnTypes.get(j);
        if (!ct.equals("null")) {
          columnType = getClassForType(ct);
          break;
        }
      }
    } else {
      columnType = getClassForType(field.getString("type"));
    }
    if (columnType == null) {
      throw new GPUdbException("Error getting column type for field: " + field.toString());
    }
    return columnType;
  }

private boolean typeIsNullable(JSONObject field) throws GPUdbException {
    if (field.get("type") instanceof JSONArray) {
      JSONArray columnTypes = field.getJSONArray("type");
      for (int j = 0; j < columnTypes.length(); j++) {
        String ct = (String) columnTypes.get(j);
        if (ct.equals("null")) {
          return true;
        }
      }
    }
    return false;
  }

private JSONObject getTableSchema(String tableName, ShowTableResponse showTableResponse) throws GPUdbException {

    List<String> schemas = showTableResponse.getTypeSchemas();

    if (schemas == null || schemas.size() != 1) {
      throw new GPUdbException("Error getting schema for table " + tableName);
    }

    return new JSONObject(schemas.get(0));
  }

private Map<String, List<String>> getColumnProperties(String tableName, ShowTableResponse showTableResponse)
      throws GPUdbException {

    List<Map<String, List<String>>> columnPropertiesList = showTableResponse.getProperties();

    if (columnPropertiesList == null || columnPropertiesList.size() != 1) {
      throw new GPUdbException("Error getting properties for table " + tableName);
    }

    return columnPropertiesList.get(0);
  }

private Class<?> getClassForType(String typeName) throws GPUdbException {

    typeName = typeName.replace(" ", "");
    if (typeName.equalsIgnoreCase(STRING_TYPE_NAME)) {
      return String.class;
    } else if (typeName.equalsIgnoreCase(LONG_TYPE_NAME)) {
      return Long.class;
    } else if (typeName.equalsIgnoreCase(INTEGER_TYPE_NAME)) {
      return Integer.class;
    } else if (typeName.equalsIgnoreCase(FLOAT_TYPE_NAME)) {
      return Float.class;
    } else if (typeName.equalsIgnoreCase(DOUBLE_TYPE_NAME)) {
      return Double.class;
    } else if (typeName.equalsIgnoreCase(BYTES_TYPE_NAME)) {
      return ByteBuffer.class;
    } else {
      throw new GPUdbException("Error: unknown type '" + typeName + "' in table schema");
    }
  }

public void init(Target.Context context, List<Target.ConfigIssue> issues) {
    List<Host> hosts = getAerospikeHosts(issues, connectionString, Groups.AEROSPIKE.getLabel(), "aerospikeBeanConfig.connectionString", context);
    ClientPolicy cp = new ClientPolicy();
    try {
      client = new AerospikeClient(cp, hosts.toArray(new Host[hosts.size()]));
      int retries = 0;
      while (!client.isConnected() && retries <= maxRetries) {
        if (retries > maxRetries) {
          issues.add(context.createConfigIssue(Groups.AEROSPIKE.getLabel(), "aerospikeBeanConfig.connectionString", AerospikeErrors.AEROSPIKE_03, connectionString));
          return;
        }
        retries++;
        try {
          Thread.sleep(100);
        } catch (InterruptedException ignored) {
        }
      }

    } catch (AerospikeException ex) {
      issues.add(context.createConfigIssue(Groups.AEROSPIKE.getLabel(), "aerospikeBeanConfig.connectionString", AerospikeErrors.AEROSPIKE_03, connectionString));
    }
  }

String getTopic(Record record) throws StageException {
    String result = publisherConf.topic;
    if (publisherConf.runtimeTopicResolution) {
      RecordEL.setRecordInContext(topicVars, record);
      try {
        result = topicEval.eval(topicVars, publisherConf.topicExpression, String.class);
        if (isEmpty(result)) {
          throw new StageException(Errors.MQTT_08, publisherConf.topicExpression, record.getHeader().getSourceId());
        }
        if (!allowedTopics.contains(result) && !allowAllTopics) {
          throw new StageException(Errors.MQTT_09, result, record.getHeader().getSourceId());
        }
      } catch (ELEvalException e) {
        throw new StageException(
            Errors.MQTT_10,
            publisherConf.topicExpression,
            record.getHeader().getSourceId(),
            e.toString()
        );
      }
    }
    return result;
  }

public String convertDateFormat( String pattern ) {
        boolean inside = false;
        boolean mark = false;
        boolean modifiedCommand = false;

        StringBuilder buf = new StringBuilder();

        for(int i = 0; i < pattern.length(); i++) {
            char c = pattern.charAt(i);

            if ( c=='%' && !mark ) {
                mark=true;
            } else {
                if ( mark ) {
                    if ( modifiedCommand ) {
                        //don't do anything--we just wanted to skip a char
                        modifiedCommand = false;
                        mark = false;
                    } else {
                        inside = translateCommand( buf, pattern, i, inside );
                        //It's a modifier code
                        if ( c=='O' || c=='E' ) {
                            modifiedCommand = true;
                        } else {
                            mark=false;
                        }
                    }
                } else {
                    if ( !inside && c != ' ' ) {
                        //We start a literal, which we need to quote
                        buf.append("'");
                        inside = true;
                    }

                    buf.append(c);
                }
            }
        }

        if ( buf.length() > 0 ) {
            char lastChar = buf.charAt( buf.length() - 1 );

            if( lastChar!='\'' && inside ) {
                buf.append('\'');
            }
        }
        return buf.toString();
    }

protected boolean translateCommand( StringBuilder buf, String pattern, int index, boolean oldInside ) {
        char firstChar = pattern.charAt( index );
        boolean newInside = oldInside;

        //O and E are modifiers, they mean to present an alternative representation of the next char
        //we just handle the next char as if the O or E wasn't there
        if ( firstChar == 'O' || firstChar == 'E' ) {
            if ( index + 1 < pattern.length() ) {
                newInside = translateCommand( buf, pattern, index + 1, oldInside );
            } else {
                buf.append( quote("%" + firstChar, oldInside ) );
            }
        } else {
            String command = translate.getProperty( String.valueOf( firstChar ) );

            //If we don't find a format, treat it as a literal--That's what apache does
            if ( command == null ) {
                buf.append( quote( "%" + firstChar, oldInside ) );
            } else {
                //If we were inside quotes, close the quotes
                if ( oldInside ) {
                    buf.append( '\'' );
                }
                buf.append( command );
                newInside = false;
            }
        }
        return newInside;
    }

