private static void upgradeV5ToV6(List<Config> configs, Context context) {
    List<Config> dataFormatConfigs = configs.stream()
      .filter(c -> c.getName().startsWith("dataFormat"))
      .collect(Collectors.toList());

    // Remove those configs
    configs.removeAll(dataFormatConfigs);

    // There is an interesting history with compression - at some point (version 2), we explicitly added it, then
    // we have hidden it. So this config might or might not exists, depending on the version in which the pipeline
    // was created. However the service is expecting it and thus we need to ensure that it's there.
    if(dataFormatConfigs.stream().noneMatch(c -> "dataFormatConfig.compression".equals(c.getName()))) {
      dataFormatConfigs.add(new Config("dataFormatConfig.compression", "NONE"));
    }

    // And finally register new service
    context.registerService(DataFormatParserService.class, dataFormatConfigs);
  }

public static List<String> evaluateMatchingFieldPaths(
      String fieldExpression,
      ELEval elEval,
      ELVars elVars,
      Record record,
      Iterable<String> recordEscapedFieldPaths
  ) throws ELEvalException {
    if (isFieldPathExpressionFast(fieldExpression)) {
      // this field path expression actually does contain an EL expression, so need to evaluate against all fields
      return evaluateMatchingFieldPathsImpl(fieldExpression, elEval, elVars, record);
    } else {
      // else it does NOT contain one, so the field regex util (which is faster) can be used
      return FieldRegexUtil.getMatchingFieldPaths(fieldExpression, recordEscapedFieldPaths);
    }
  }

private static boolean pathMatches(
      Record record,
      String fieldPath,
      String fieldExpression,
      ELEval elEval,
      ELVars elVars
  ) throws ELEvalException {
    List<PathElement> actualPathElements = PathElement.parse(fieldPath, true);
    List<PathElement> matcherPathElements = PathElement.parse(fieldExpression, false, true);

    Iterator<PathElement> currentPathIter = actualPathElements.iterator();
    Iterator<PathElement> matcherPathIter = matcherPathElements.iterator();

    PathElement currentMatcher = null;
    PathElement currentPath = null;
    Field currentField = null;
    StringBuilder currentFieldPath = new StringBuilder();

    while (matcherPathIter.hasNext()) {
      currentMatcher = matcherPathIter.next();
      switch (currentMatcher.getType()) {
        case MAP:
          if (!currentPathIter.hasNext()) {
            // we are expecting to match a MAP, but there are no more elements in the path
            return false;
          }
          currentPath = currentPathIter.next();

          // see if the name matches the pattern
          String childName = currentPath.getName();

          String patternName = currentMatcher.getName();
          if (FieldRegexUtil.hasWildCards(patternName)) {
            patternName = FieldRegexUtil.transformFieldPathRegex(patternName);
          }
          if (childName.matches(patternName)) {
            currentField = currentField.getValueAsMap().get(childName);
            currentFieldPath.append("/");
            currentFieldPath.append(childName);
          } else {
            return false;
          }

          break;
        case LIST:
          // see if the index matches the pattern

          if (!currentPathIter.hasNext()) {
            // we are expecting to match a LIST, but there are no more elements in the path
            return false;
          }
          currentPath = currentPathIter.next();

          int childIndex = currentPath.getIndex();
          final int matchInd = currentMatcher.getIndex();
          if (matchInd == PathElement.WILDCARD_INDEX_ANY_LENGTH
              || (matchInd == PathElement.WILDCARD_INDEX_SINGLE_CHAR && childIndex < 10)
              || matchInd == childIndex) {
            currentField = currentField.getValueAsList().get(childIndex);
            currentFieldPath.append("[");
            currentFieldPath.append(childIndex);
            currentFieldPath.append("]");
          } else {
            return false;
          }
          break;
        case ROOT:
          if (!currentPathIter.hasNext()) {
            // we are expecting to match the ROOT, but there are no more elements in the path
            return false;
          }
          currentPath = currentPathIter.next();
          if (currentPath.getType() != PathElement.Type.ROOT) {
            // we are expecting to match the ROOT, the root element wasn't for some reason
            return false;
          }
          currentField = record.get();
          break;
        case FIELD_EXPRESSION:
          // see if the current field matches the given expression
          FieldEL.setFieldInContext(elVars, currentFieldPath.toString(), currentPath.getName(), currentField);
          String expression = currentMatcher.getName();
          final boolean result = elEval.eval(elVars, expression, Boolean.class);
          if (LOG.isDebugEnabled()) {
            LOG.debug(
                "Result of evaluating expression {} on field {} with path {} was {}",
                expression,
                currentField,
                currentFieldPath,
                result
            );
          }
          if (!result) {
            return false;
          }
          break;
      }
    }

    return !currentPathIter.hasNext();
  }

public void release() {
    CounterLock lock;
    synchronized (DataStore.class) {
      lock = FILE_LOCKS.get(file);

      if(lock == null) {
        LOG.error("Trying to release unlocked file {}", file);
        return;
      }

      lock.dec();

      if(lock.counter == 0) {
        FILE_LOCKS.remove(file);
      }
    }

    LOG.trace("Releasing the lock {} for '{}'", lock, file);
    lock.unlock();
    LOG.trace("Released the lock {} for '{}'", lock, file);
  }

public InputStream getInputStream() throws IOException {
    acquireLock();
    try {
      isClosed = false;
      forWrite = false;
      LOG.trace("Starts read '{}'", file);
      verifyAndRecover();
      InputStream is = new ProxyInputStream(new FileInputStream(file.toFile())) {
        @Override
        public void close() throws IOException {
          if (isClosed) {
            return;
          }
          try {
            super.close();
          } finally {
            release();
            isClosed = true;
            stream = null;
          }
          LOG.trace("Finishes read '{}'", file);
        }
      };
      stream = is;
      return is;
    } catch (Exception ex) {
      release();
      throw ex;
    }
  }

public OutputStream getOutputStream() throws IOException {
    acquireLock();
    try {
      isClosed = false;
      forWrite = true;
      LOG.trace("Starts write '{}'", file);
      verifyAndRecover();
      if (Files.exists(file)) {
        Files.move(file, fileOld);
        LOG.trace("Starting write, move '{}' to '{}'", file, fileOld);
      }
      OutputStream os = new ProxyOutputStream(new FileOutputStream(fileTmp.toFile())) {
        @Override
        public void close() throws IOException {
          if (isClosed) {
            return;
          }
          try {
            super.close();
          } finally {
            isClosed = true;
            stream = null;
          }
          LOG.trace("Finishes write '{}'", file);
        }
      };
      stream = os;
      return os;
    } catch (Exception ex) {
      release();
      throw ex;
    }
  }

public void commit(OutputStream out) throws IOException {
    // close the stream in order to flush the contents into the disk
    Utils.checkNotNull(out, "Argument output stream cannot be null");
    Utils.checkState(stream == out, "The argument output stream must be the same as the output stream obtained " +
      "from this data store instance");
    out.close();
    Files.move(fileTmp, fileNew);
    LOG.trace("Committing write, move '{}' to '{}'", fileTmp, fileNew);
    Files.move(fileNew, file);
    LOG.trace("Committing write, move '{}' to '{}'", fileNew, file);
    if (Files.exists(fileOld)) {
      Files.delete(fileOld);
      LOG.trace("Committing write, deleting '{}'", fileOld);
    }
    LOG.trace("Committed");
  }

public boolean exists() throws IOException {
    acquireLock();
    try {
      verifyAndRecover();
      return Files.exists(file) && Files.size(file) > 0;
    } finally {
      release();
    }
  }

@Override
  @VisibleForTesting
  int getOperationFromRecord(
      Record record,
      int defaultOpCode,
      UnsupportedOperationAction unsupportedAction,
      List<OnRecordErrorException> errorRecords ) {

    int opCode = -1; // -1 is invalid and not used in OperationType.
    String op = null;
    try {
      // Try sdc.operation.type first
      op = record.getHeader().getAttribute(OperationType.SDC_OPERATION_TYPE);
      // If not set, look for "__$operation" in record.
      if (StringUtils.isBlank(op)) {
        if (record.has(MSOperationCode.getOpField())) {
          int intOp = record.get(MSOperationCode.getOpField()).getValueAsInteger();
          // Convert the MS specific operation code to SDC standard operation code
          opCode = MSOperationCode.convertToJDBCCode(intOp);
        }
      } else {
        opCode = JDBCOperationType.convertToIntCode(op);
      }
      if (opCode == -1) { // Both MS code and sdc code are not set. Use default.
        opCode = defaultOpCode;
      }
    } catch (NumberFormatException | UnsupportedOperationException ex) {
      LOG.debug(
          "Operation obtained from record is not supported: {}. Handle by UnsupportedOpertaionAction {}. {}",
          ex.getMessage(),
          unsupportedAction.getLabel(),
          ex
      );
      switch (unsupportedAction) {
        case DISCARD:
          LOG.debug("Discarding record with unsupported operation {}", op);
          break;
        case SEND_TO_ERROR:
          LOG.debug("Sending record to error due to unsupported operation {}", op);
          errorRecords.add(new OnRecordErrorException(record, JdbcErrors.JDBC_70, op));
          break;
        case USE_DEFAULT:
          opCode = defaultOpCode;
          break;
        default: //unknown action
          LOG.debug("Sending record to error due to unknown operation: {}", op);
      }
    }
    return opCode;
  }

public static FsPermission parseFsPermission(String permissions) throws IllegalArgumentException {
    try {
      // Octal or symbolic representation
      return new FsPermission(permissions);
    } catch (IllegalArgumentException e) {
      // FsPermission.valueOf will work with unix style permissions which is 10 characters
      // where the first character says the type of file
      if (permissions.length() == 9) {
        // This means it is a posix standard without the first character for file type
        // We will simply set it to '-' suggesting regular file
        permissions = "-" + permissions;
      }

      // Try to parse unix style format.
      return FsPermission.valueOf(permissions);
    }
  }

@VisibleForTesting void validateRequiredStageLibraries() {
    // Name of all installed libraries
    Set<String> installedLibraries = stageLibraries.stream()
      .map(StageLibraryDefinition::getName)
      .collect(Collectors.toSet());

    // Required libraries
    Set<String> requiredLibraries = new HashSet<>();
    String config = configuration.get(SdcConfiguration.REQUIRED_STAGELIBS, DEFAULT_REQUIRED_STAGELIBS);
    for(String stageLib : config.split(",")) {
      if(!stageLib.isEmpty()) {
        requiredLibraries.add(stageLib);
      }
    }

    Set<String> missingLibraries = Sets.difference(requiredLibraries, installedLibraries);
    if(!missingLibraries.isEmpty()) {
      throw new RuntimeException(Utils.format(
        "Some required stage libraries are missing: {}",
        StringUtils.join(missingLibraries, ", ")
      ));
    }
  }

private void validateAllServicesAvailable() {
    // Firstly validate that all stages have satisfied service dependencies
    List<String> missingServices = new LinkedList<>();

    for(StageDefinition stage : stageList) {
      for(ServiceDependencyDefinition service : stage.getServices()) {
        if(!serviceMap.containsKey(service.getService())) {
          missingServices.add(Utils.format("Stage {} is missing service {}", stage.getName(), service.getService().getName()));
        }
      }
    }
    if(!missingServices.isEmpty()) {
      throw new RuntimeException("Missing services: " + StringUtils.join(missingServices, ", "));
    }

    // Secondly ensure that all loaded services are compatible with what is supported by our runtime engine
    List<String> unsupportedServices = new LinkedList<>();
    for(ServiceDefinition serviceDefinition : serviceList) {
      if(!ServiceRuntime.supports(serviceDefinition.getProvides())) {
        unsupportedServices.add(serviceDefinition.getProvides().toString());
      }
    }
    if(!unsupportedServices.isEmpty()) {
      throw new RuntimeException("Unsupported services: " + StringUtils.join(unsupportedServices, ", "));
    }
  }

@SuppressWarnings("unchecked")
