    Utils.checkState(started, "Not started");
    Utils.checkState(!stopped, "Already stopped");
    return dataProvider.roll(newDataWindowEndTimeMillis);
  }

private static int resolveScaleOrPrecisionExpression(
      String type,
      Field field,
      String attributeName,
      String fieldPath
  ) throws JdbcStageCheckedException {
    String stringValue = field.getAttribute(attributeName);

    try {
      return Integer.parseInt(stringValue);
    } catch (NumberFormatException e) {
      throw new JdbcStageCheckedException(JdbcErrors.JDBC_304, type, fieldPath, attributeName, stringValue, e);
    }
  }

public static final LoginManager acquireLoginManager(LoginType loginType, Map<String, ?> configs) throws IOException, LoginException {
        synchronized (LoginManager.class) {
            LoginManager loginManager = CACHED_INSTANCES.get(loginType);
            if (loginManager == null) {
                loginManager = new LoginManager(loginType, configs);
                CACHED_INSTANCES.put(loginType, loginManager);
            }
            return loginManager.acquire();
        }
    }

public void release() {
        synchronized (LoginManager.class) {
            if (refCount == 0)
                throw new IllegalStateException("release called on LoginManager with refCount == 0");
            else if (refCount == 1) {
                CACHED_INSTANCES.remove(loginType);
                login.shutdown();
            }
            --refCount;
        }
    }

public static void closeAll() {
        synchronized (LoginManager.class) {
            for (LoginType loginType : new ArrayList<>(CACHED_INSTANCES.keySet())) {
                LoginManager loginManager = CACHED_INSTANCES.remove(loginType);
                loginManager.login.shutdown();
            }
        }
    }

private static String globToRegex(String glob) {
    if (glob.charAt(0) == '.' || glob.contains("/") || glob.contains("~")) {
      throw new IllegalArgumentException("Invalid character in file glob");
    }

    // treat dot as a literal.
    glob = glob.replace(".", "\\.");
    glob = glob.replace("*", ".+");
    glob = glob.replace("?", ".{1}+");

    return glob;
  }

public void decodeStandaloneBuffer(
      ByteBuf buf,
      List<BaseNetflowMessage> resultMessages,
      InetSocketAddress sender,
      InetSocketAddress recipient
  ) throws OnRecordErrorException {
    final List<Object> results = new LinkedList<>();
    try {
      decode(null, buf, results, sender, recipient, true);
      for (Object result : results) {
        if (result == null) {
          LOG.warn("null result found from decoding standalone Netflow buffer; skipping");
          continue;
        }
        if (result instanceof BaseNetflowMessage) {
          resultMessages.add((BaseNetflowMessage) result);
        } else {
          throw new IllegalStateException(String.format(
              "Found unexpected object type in results: %s",
              result.getClass().getName())
          );
        }
      }
    } finally {
      resetStateVariables();
    }
  }

static List<S3ObjectSummary> listObjectsLexicographically(
      AmazonS3 s3Client,
      S3ConfigBean s3ConfigBean,
      AntPathMatcher pathMatcher,
      S3Offset s3Offset,
      int fetchSize
  ) {
    // Incrementally scan objects after the marker (s3Offset).
    List<S3ObjectSummary> list = new ArrayList<>(fetchSize);

    ListObjectsRequest listObjectsRequest = new ListObjectsRequest();
    listObjectsRequest.setBucketName(s3ConfigBean.s3Config.bucket);
    listObjectsRequest.setPrefix(s3ConfigBean.s3Config.commonPrefix);
    listObjectsRequest.setMaxKeys(BATCH_SIZE);
    if (s3Offset.getKey() != null) {
      listObjectsRequest.setMarker(s3Offset.getKey());
    }

    ObjectListing objectListing = s3Client.listObjects(listObjectsRequest);

    while (true) {
      for (S3ObjectSummary s : objectListing.getObjectSummaries()) {
        String fullPrefix = s.getKey();
        String remainingPrefix = fullPrefix.substring(s3ConfigBean.s3Config.commonPrefix.length(), fullPrefix.length());
        if (!remainingPrefix.isEmpty()) {
          if (pathMatcher.match(s3ConfigBean.s3FileConfig.prefixPattern, remainingPrefix)) {
            list.add(s);
          }
          // We've got enough objects.
          if (list.size() == fetchSize) {
            return list;
          }
        }
      }
      // Listing is complete. No more objects to be listed.
      if (!objectListing.isTruncated()) {
        break;
      }
      objectListing = s3Client.listNextBatchOfObjects(objectListing);
    }

    return list;
  }

static List<S3ObjectSummary> listObjectsChronologically(
      AmazonS3 s3Client,
      S3ConfigBean s3ConfigBean,
      AntPathMatcher pathMatcher,
      S3Offset s3Offset,
      int fetchSize
  ) {

    //Algorithm:
    // - Full scan all objects that match the file name pattern and which are later than the file in the offset
    // - Select the oldest "fetchSize" number of files and return them.
    TreeSet<S3ObjectSummary> treeSet = new TreeSet<>((o1, o2) -> {
      int result = o1.getLastModified().compareTo(o2.getLastModified());
      if(result != 0) {
        //same modified time. Use name to sort
        return result;
      }
      return o1.getKey().compareTo(o2.getKey());
    });

    S3Objects s3ObjectSummaries = S3Objects
      .withPrefix(s3Client, s3ConfigBean.s3Config.bucket, s3ConfigBean.s3Config.commonPrefix);

    // SDC-9413: since the s3ObjectSummaries is in lexical order, we should get all list of files in one api call
    for (S3ObjectSummary s : s3ObjectSummaries) {
      String fullPrefix = s.getKey();
      String remainingPrefix = fullPrefix.substring(s3ConfigBean.s3Config.commonPrefix.length(), fullPrefix.length());
      if (!remainingPrefix.isEmpty()) {
        // remainingPrefix can be empty.
        // If the user manually creates a prefix "myFolder/mySubFolder" in bucket "myBucket" and uploads "myObject",
        // then the first objects returned here are:
        // myFolder/mySubFolder
        // myFolder/mySubFolder/myObject
        //
        // All is good when pipeline is run but preview returns with no data. So we should ignore the empty file as it
        // has no data
        if (pathMatcher.match(s3ConfigBean.s3FileConfig.prefixPattern, remainingPrefix) && isEligible(s, s3Offset)) {
          treeSet.add(s);
        }
        if (treeSet.size() > fetchSize) {
          treeSet.pollLast();
        }
      }
    }

    return new ArrayList<>(treeSet);
  }

