@Override
  protected void process(Record record, SingleLaneProcessor.SingleLaneBatchMaker batchMaker) throws StageException {
    RecordEL.setRecordInContext(tableNameVars, record);
    String tableName = tableNameEval.eval(tableNameVars, conf.kuduTableTemplate, String.class);
    if (!conf.caseSensitive) {
      tableName = tableName.toLowerCase();
    }
    LOG.trace("Processing record:{}  TableName={}", record.toString(), tableName);

    try {
      try {
        KuduLookupKey key = generateLookupKey(record, tableName);
        List<Map<String, Field>> values = cache.get(key);
        if (values.isEmpty()) {
          // No record found
          if (conf.missingLookupBehavior == MissingValuesBehavior.SEND_TO_ERROR) {
            errorRecordHandler.onError(new OnRecordErrorException(record, Errors.KUDU_31));
          } else {
            // Configured to 'Send to next stage' and 'pass as it is'
            batchMaker.addRecord(record);
          }
        } else {
          switch (conf.multipleValuesBehavior) {
            case FIRST_ONLY:
              setFieldsInRecord(record, values.get(0));
              batchMaker.addRecord(record);
              break;
            case SPLIT_INTO_MULTIPLE_RECORDS:
              for(Map<String, Field> lookupItem : values) {
                Record newRecord = getContext().cloneRecord(record);
                setFieldsInRecord(newRecord, lookupItem);
                batchMaker.addRecord(newRecord);
              }
              break;
            default:
              throw new IllegalStateException("Unknown multiple value behavior: " + conf.multipleValuesBehavior);
          }
        }
      } catch (ExecutionException e) {
        Throwables.propagateIfPossible(e.getCause(), StageException.class);
        Throwables.propagateIfPossible(e.getCause(), OnRecordErrorException.class);
        throw new IllegalStateException(e); // The cache loader shouldn't throw anything that isn't a StageException.
      }
    } catch (OnRecordErrorException error) { // NOSONAR
      errorRecordHandler.onError(new OnRecordErrorException(record, error.getErrorCode(), error.getParams()));
    }
  }

private KuduLookupKey generateLookupKey(final Record record, final String tableName) throws OnRecordErrorException{
    Map<String, Field> keyList = new HashMap<>();
    for (Map.Entry<String, String> key : columnToField.entrySet()){
      String fieldName = key.getValue();
      if (!record.has(fieldName)) {
        throw new OnRecordErrorException(record, Errors.KUDU_32, fieldName);
      }
      keyList.put(key.getKey(), record.get(fieldName));
    }
    return new KuduLookupKey(tableName, keyList);
  }

private Properties getKafkaProperties(Stage.Context context) {
    Properties props = new Properties();
    props.putAll(conf.kafkaOptions);

    props.setProperty("bootstrap.servers", conf.brokerURI);
    props.setProperty("group.id", conf.consumerGroup);
    props.setProperty("max.poll.records", String.valueOf(batchSize));
    props.setProperty(KafkaConstants.KEY_DESERIALIZER_CLASS_CONFIG, conf.keyDeserializer.getKeyClass());
    props.setProperty(KafkaConstants.VALUE_DESERIALIZER_CLASS_CONFIG, conf.valueDeserializer.getValueClass());
    props.setProperty(KafkaConstants.CONFLUENT_SCHEMA_REGISTRY_URL_CONFIG, StringUtils.join(conf.dataFormatConfig.schemaRegistryUrls, ","));
    props.setProperty(KafkaConstants.AUTO_COMMIT_OFFEST, "false");

    if(context.isPreview()) {
      props.setProperty(KafkaConstants.AUTO_OFFSET_RESET_CONFIG, KafkaConstants.AUTO_OFFSET_RESET_PREVIEW_VALUE);
    }

    return props;
  }

private void handlePartitioningTurnedOffOrOn(
      SortedSetMultimap<TableContext, TableRuntimeContext> reconstructedPartitions
  ) {

    for (TableContext tableContext : reconstructedPartitions.keySet()) {
      final SortedSet<TableRuntimeContext> partitions = reconstructedPartitions.get(tableContext);
      final TableRuntimeContext lastPartition = partitions.last();
      final TableContext sourceTableContext = lastPartition.getSourceTableContext();
      Utils.checkState(
          sourceTableContext.equals(tableContext),
          String.format(
              "Source table context for %s should match TableContext map key of %s",
              lastPartition.getDescription(),
              tableContext.getQualifiedName()
          )
      );

      final boolean partitioningTurnedOff = lastPartition.isPartitioned()
          && sourceTableContext.getPartitioningMode() == PartitioningMode.DISABLED;
      final boolean partitioningTurnedOn = !lastPartition.isPartitioned()
          && sourceTableContext.isPartitionable()
          && sourceTableContext.getPartitioningMode() != PartitioningMode.DISABLED;

      if (!partitioningTurnedOff && !partitioningTurnedOn) {
        continue;
      }

      final Map<String, String> nextStartingOffsets = new HashMap<>();
      final Map<String, String> nextMaxOffsets = new HashMap<>();

      final int newPartitionSequence = lastPartition.getPartitionSequence() > 0 ? lastPartition.getPartitionSequence() + 1 : 1;
      if (partitioningTurnedOff) {
        LOG.info(
            "Table {} has switched from partitioned to non-partitioned; partition sequence {} will be the last (with" +
                " no max offsets)",
            sourceTableContext.getQualifiedName(),
            newPartitionSequence
        );

        lastPartition.getStartingPartitionOffsets().forEach(
            (col, off) -> {
              String basedOnStartOffset = lastPartition.generateNextPartitionOffset(col, off);
              nextStartingOffsets.put(col, basedOnStartOffset);
            }
        );

      } else if (partitioningTurnedOn) {

        lastPartition.getStartingPartitionOffsets().forEach(
            (col, off) -> {
              String basedOnStoredOffset = lastPartition.getInitialStoredOffsets().get(col);
              nextStartingOffsets.put(col, basedOnStoredOffset);
            }
        );

        nextStartingOffsets.forEach(
            (col, off) -> nextMaxOffsets.put(col, lastPartition.generateNextPartitionOffset(col, off))
        );

        if (!reconstructedPartitions.remove(sourceTableContext, lastPartition)) {
          throw new IllegalStateException(String.format(
              "Failed to remove partition %s for table %s in switching partitioning from off to on",
              lastPartition.getDescription(),
              sourceTableContext.getQualifiedName()
          ));
        }

        LOG.info(
            "Table {} has switched from non-partitioned to partitioned; using last stored offsets as the starting" +
                " offsets for the new partition {}",
            sourceTableContext.getQualifiedName(),
            newPartitionSequence
        );
      }

      final TableRuntimeContext nextPartition = new TableRuntimeContext(
          sourceTableContext,
          lastPartition.isUsingNonIncrementalLoad(),
          (lastPartition.isPartitioned() && !partitioningTurnedOff) || partitioningTurnedOn,
          newPartitionSequence,
          nextStartingOffsets,
          nextMaxOffsets
      );

      reconstructedPartitions.put(sourceTableContext, nextPartition);
    }
  }

@VisibleForTesting
  void acquireTableAsNeeded(int threadNumber) throws InterruptedException {
    if (!getOwnedTablesQueue().isEmpty() && batchTableStrategy == BatchTableStrategy.SWITCH_TABLES) {
      final TableRuntimeContext lastOwnedPartition = getOwnedTablesQueue().pollLast();


      if (getTableContextMap().containsValue(lastOwnedPartition.getSourceTableContext())) {
        sharedAvailableTablesQueue.offer(lastOwnedPartition);
      }

      TableContext lastOwnedTable = lastOwnedPartition.getSourceTableContext();
      // need to cycle off all partitions from the same table to the end of the queue
      TableRuntimeContext first = sharedAvailableTablesQueue.peek();
      while (first != null && first.getSourceTableContext().equals(lastOwnedTable)
          && !first.equals(lastOwnedPartition)) {
        if (LOG.isDebugEnabled()) {
          LOG.debug(
              "Moving partition {} to end of shared queue to comply with BatchTableStrategy of {}",
              first.getDescription(),
              batchTableStrategy.getLabel()
          );
        }

        // poll() should never return null since it is actually returning 'first' as we want to move it from the head
        // of the queue, that's why we are calling offer, to basically remove it from the head but keep it in the queue
        TableRuntimeContext toMove = sharedAvailableTablesQueue.poll();
        sharedAvailableTablesQueue.offer(toMove);
        // Get the new head of the queue
        first = sharedAvailableTablesQueue.peek();
      }
    }

    if (getOwnedTablesQueue().isEmpty()) {
      TableRuntimeContext head = sharedAvailableTablesQueue.poll();
      if (head != null) {
        offerToOwnedTablesQueue(head, threadNumber);
      }
    }

    partitionFirstSharedQueueItemIfNeeded();
  }

@VisibleForTesting
  void partitionFirstSharedQueueItemIfNeeded() {
    final TableRuntimeContext headPartition = getOwnedTablesQueue().peek();
    if (headPartition != null) {
      synchronized (partitionStateLock) {
        keepPartitioningIfNeeded(headPartition);
      }
    } else if (LOG.isTraceEnabled()) {
      LOG.trace("No item at head of shared partition queue");
    }
  }

public TableRuntimeContext nextTable(int threadNumber) throws InterruptedException {
    synchronized (partitionStateLock) {
      acquireTableAsNeeded(threadNumber);

      final TableRuntimeContext partition = getOwnedTablesQueue().pollFirst();
      if (partition != null) {
        offerToOwnedTablesQueue(partition, threadNumber);
      }
      return partition;
    }
  }

public void reportDataOrNoMoreData(
      TableRuntimeContext tableRuntimeContext,
      int recordCount,
      int batchSize,
      boolean resultSetEndReached,
      AtomicBoolean tableFinished,
      AtomicBoolean schemaFinished,
      List<String> schemaFinishedTables
  ) {
    final TableContext sourceContext = tableRuntimeContext.getSourceTableContext();

    // When we see a table with data, we mark isNoMoreDataEventGeneratedAlready to false
    // so we can generate event again if we don't see data from all tables.
    if(recordCount > 0) {
      isNoMoreDataEventGeneratedAlready = false;
      tablesWithNoMoreData.remove(tableRuntimeContext.getSourceTableContext());
      remainingSchemasToTableContexts.put(sourceContext.getSchema(), sourceContext);
      completedSchemasToTableContexts.remove(sourceContext.getSchema(), sourceContext);
    }

    // we need to account for the activeRuntimeContexts here
    // if there are still other active contexts in process, then this should do "nothing"
    // if there are not other contexts, we need to figure out what the highest offset completed by the last batch was

    final boolean noMoreData = recordCount == 0 || resultSetEndReached;

    if (noMoreData) {
      tableRuntimeContext.setMarkedNoMoreData(true);
    }

    if (recordCount > 0) {
      maxPartitionWithDataPerTable.put(sourceContext, tableRuntimeContext.getPartitionSequence());
    }

    boolean tableExhausted = removePartitionIfNeeded(tableRuntimeContext);

    if (noMoreData) {
      if (tableExhausted) {
        synchronized (this) {
          if (LOG.isDebugEnabled()) {
            LOG.debug(
                "Table {} exhausted",
                sourceContext.getQualifiedName()
            );
          }

          final boolean newlyFinished = tablesWithNoMoreData.add(sourceContext);

          if (newlyFinished && tableFinished != null) {
            tableFinished.set(true);
          }

          final boolean remainingSchemaChanged = remainingSchemasToTableContexts.remove(sourceContext.getSchema(), sourceContext);
          completedSchemasToTableContexts.put(sourceContext.getSchema(), sourceContext);

          if (remainingSchemaChanged && remainingSchemasToTableContexts.get(sourceContext.getSchema()).isEmpty() && schemaFinished != null) {
            schemaFinished.set(true);
            if (schemaFinishedTables != null) {
              completedSchemasToTableContexts.get(sourceContext.getSchema()).forEach(
                  t -> schemaFinishedTables.add(t.getTableName())
              );
            }
          }
        }
      }
    }

    if (LOG.isTraceEnabled()) {
      LOG.trace(
          "Just released table {}; Number of Tables With No More Data {}",
          tableRuntimeContext.getDescription(),
          tablesWithNoMoreData.size()
      );
    }
  }

public synchronized boolean shouldGenerateNoMoreDataEvent() {
    boolean noMoreData = (
        !isNoMoreDataEventGeneratedAlready &&
            tablesWithNoMoreData.size() == tableContextMap.size());
    if (noMoreData) {
      isNoMoreDataEventGeneratedAlready = true;
    }
    return noMoreData;
  }

private int readAhead(Map<String, Field> fieldsFromLogLine, StringBuilder stackTrace)
    throws DataParserException, IOException {
    StringBuilder multilineLog = new StringBuilder();
    int read = readLine(multilineLog);
    int numberOfLinesRead = 0;
    while (read > -1) {
      try {
        Map<String, Field> stringFieldMap = parseLogLine(multilineLog);
        fieldsFromLogLine.putAll(stringFieldMap);
        currentLine.append(multilineLog);
        //If the line can be parsed successfully, do not read further
        //This line will be used in the current record if this is the first line being read
        //or stored for the next round if there is a line from the previous round.
        break;
      } catch (DataParserException e) {
        //is this the first line being read? Yes -> throw exception
        if (previousLine.length() == 0 || maxStackTraceLines == -1) {
          throw e;
        }
        //otherwise read until we get a line that matches pattern
        if(numberOfLinesRead < maxStackTraceLines) {
          if(numberOfLinesRead != 0) {
            stackTrace.append("\n");
          }
          stackTrace.append(multilineLog.toString());
        }
        numberOfLinesRead++;
        multilineLog.setLength(0);
        read = readLine(multilineLog);
      }
    }
    return read;
  }

int readLine(StringBuilder sb) throws IOException {
    int c = reader.read();
    int count = (c == -1) ? -1 : 0;
    while (c > -1 && !isOverMaxObjectLen(count) && !checkEolAndAdjust(c)) {
      count++;
      sb.append((char) c);
      c = reader.read();
    }
    if (isOverMaxObjectLen(count)) {
      sb.setLength(sb.length() - 1);
      while (c > -1 && c != '\n' && c != '\r') {
        count++;
        c = reader.read();
      }
      checkEolAndAdjust(c);
    }
    return count;
  }

public UsageTimer roll() {
    int multiplier;
    synchronized (this) {
      multiplier = getMultiplier();
      changeMultiplier(-multiplier); //stopAll;
    }
    return new UsageTimer().setName(getName()).changeMultiplier(multiplier);
  }

public static void enableDPM(DPMInfoJson dpmInfo, Context context) throws IOException {
    Utils.checkNotNull(dpmInfo, "DPMInfo");

    String dpmBaseURL = normalizeDpmBaseURL(dpmInfo.getBaseURL());

    // Since we support enabling/Disabling DPM, first check if token already exists for the given DPM URL.
    // If token exists skip first 3 steps
    String currentDPMBaseURL = context.configuration.get(RemoteSSOService.DPM_BASE_URL_CONFIG, "");
    String currentAppAuthToken = context.configuration.get(RemoteSSOService.SECURITY_SERVICE_APP_AUTH_TOKEN_CONFIG, "").trim();
    if (!currentDPMBaseURL.equals(dpmBaseURL) ||  currentAppAuthToken.length() == 0) {
      // 1. Login to DPM to get user auth token
      String userAuthToken = retrieveUserToken(dpmBaseURL, dpmInfo.getUserID(), dpmInfo.getUserPassword());
      String appAuthToken = null;

      // 2. Create Data Collector application token
      Response response = null;
      try {
        Map<String, Object> newComponentJson = new HashMap<>();
        newComponentJson.put("organization", dpmInfo.getOrganization());
        newComponentJson.put("componentType", "dc");
        newComponentJson.put("numberOfComponents", 1);
        newComponentJson.put("active", true);
        response = ClientBuilder.newClient()
            .target(dpmBaseURL + "/security/rest/v1/organization/" + dpmInfo.getOrganization() + "/components")
            .register(new CsrfProtectionFilter("CSRF"))
            .request()
            .header(SSOConstants.X_USER_AUTH_TOKEN, userAuthToken)
            .put(Entity.json(newComponentJson));
        if (response.getStatus() != Response.Status.CREATED.getStatusCode()) {
          throw new RuntimeException(Utils.format("DPM Create Application Token failed, status code '{}': {}",
              response.getStatus(),
              response.readEntity(String.class)
          ));
        }

        List<Map<String, Object>> newComponent = response.readEntity(new GenericType<List<Map<String,Object>>>() {});
        if (newComponent.size() > 0) {
          appAuthToken = (String) newComponent.get(0).get("fullAuthToken");
        } else {
          throw new RuntimeException("DPM Create Application Token failed: No token data from DPM Server.");
        }

      } finally {
        if (response != null) {
          response.close();
        }
        // Logout from DPM
        logout(dpmBaseURL, userAuthToken);
      }

      // 3. Update App Token file
      updateTokenFile(context, appAuthToken);
    }

    // 4. Update dpm.properties file
    updateDpmProperties(context, dpmBaseURL, dpmInfo.getLabels(), true);
  }

public static void disableDPM(String username, String password, String organizationId, Context context) throws IOException {
    String dpmBaseURL = normalizeDpmBaseURL(context.configuration.get(RemoteSSOService.DPM_BASE_URL_CONFIG, ""));
    String userToken = retrieveUserToken(dpmBaseURL, username, password);
    try {
      disableDPM(userToken, organizationId, context);
    } finally {
      logout(dpmBaseURL, userToken);
    }
  }

public static void disableDPM(String userAuthToken, String organizationId, Context context) throws IOException {
    // check if DPM enabled
    if (!context.runtimeInfo.isDPMEnabled()) {
      throw new RuntimeException("disableDPM is supported only when DPM is enabled");
    }

    String dpmBaseURL = normalizeDpmBaseURL(context.configuration.get(RemoteSSOService.DPM_BASE_URL_CONFIG, ""));
    String componentId = context.runtimeInfo.getId();

    // 2. Deactivate Data Collector System Component
    Response response = null;
    try {
      response = ClientBuilder.newClient()
          .target(dpmBaseURL + "/security/rest/v1/organization/" + organizationId + "/components/deactivate")
          .register(new CsrfProtectionFilter("CSRF"))
          .request()
          .header(SSOConstants.X_USER_AUTH_TOKEN, userAuthToken)
          .header(SSOConstants.X_REST_CALL, true)
          .post(Entity.json(ImmutableList.of(componentId)));
      if (response.getStatus() != Response.Status.OK.getStatusCode()) {
        throw new RuntimeException(Utils.format(
            " Deactivate Data Collector System Component from DPM failed, status code '{}': {}",
            response.getStatus(),
            response.readEntity(String.class)
        ));
      }
    } finally {
      if (response != null) {
        response.close();
      }
    }

    // 3. Delete Data Collector System Component
    try {
      response = ClientBuilder.newClient()
          .target(dpmBaseURL + "/security/rest/v1/organization/" + organizationId + "/components/delete")
          .register(new CsrfProtectionFilter("CSRF"))
          .request()
          .header(SSOConstants.X_USER_AUTH_TOKEN, userAuthToken)
          .header(SSOConstants.X_REST_CALL, true)
          .post(Entity.json(ImmutableList.of(componentId)));
      if (response.getStatus() != Response.Status.OK.getStatusCode()) {
        throw new RuntimeException(Utils.format(
            " Deactivate Data Collector System Component from DPM failed, status code '{}': {}",
            response.getStatus(),
            response.readEntity(String.class)
        ));
      }
    } finally {
      if (response != null) {
        response.close();
      }
    }

    // 4. Delete from Job Runner SDC list
    try {
      response = ClientBuilder.newClient()
          .target(dpmBaseURL + "/jobrunner/rest/v1/sdc/" + componentId)
          .register(new CsrfProtectionFilter("CSRF"))
          .request()
          .header(SSOConstants.X_USER_AUTH_TOKEN, userAuthToken)
          .header(SSOConstants.X_REST_CALL, true)
          .delete();
      if (response.getStatus() != Response.Status.OK.getStatusCode()) {
        throw new RuntimeException(Utils.format(
            "Delete from DPM Job Runner SDC list failed, status code '{}': {}",
            response.getStatus(),
            response.readEntity(String.class)
        ));
      }
    } finally {
      if (response != null) {
        response.close();
      }
    }

    // 5. Update App Token file
    updateTokenFile(context, "");

    // 4. Update dpm.properties file
    updateDpmProperties(context, dpmBaseURL, null, false);
  }

private static String normalizeDpmBaseURL(String url) {
    if (url.endsWith("/")) {
      url = url.substring(0, url.length() - 1);
    }

    return url;
  }

private static String retrieveUserToken(String url, String username, String password) {
    Response response = null;
    try {
      Map<String, String> loginJson = new HashMap<>();
      loginJson.put("userName", username);
      loginJson.put("password", password);
      response = ClientBuilder.newClient()
          .target(url + "/security/public-rest/v1/authentication/login")
          .register(new CsrfProtectionFilter("CSRF"))
          .request()
          .post(Entity.json(loginJson));
      if (response.getStatus() != Response.Status.OK.getStatusCode()) {
        throw new RuntimeException(Utils.format("DPM Login failed, status code '{}': {}",
            response.getStatus(),
            response.readEntity(String.class)
        ));
      }
    } finally {
      if (response != null) {
        response.close();
      }
    }

   return response.getHeaderString(SSOConstants.X_USER_AUTH_TOKEN);
  }

private static void logout(String dpmBaseURL, String userAuthToken) {
    Response response = null;
    try {
      response = ClientBuilder.newClient()
          .target(dpmBaseURL + "/security/_logout")
          .register(new CsrfProtectionFilter("CSRF"))
          .request()
          .header(SSOConstants.X_USER_AUTH_TOKEN, userAuthToken)
          .cookie(SSOConstants.AUTHENTICATION_COOKIE_PREFIX + "LOGIN", userAuthToken)
          .get();
    } finally {
      if (response != null) {
        response.close();
      }
    }
  }

private static void updateTokenFile(Context context, String appAuthToken) throws IOException {
    File tokenFile = context.tokenFilePath == null ? new File(context.runtimeInfo.getConfigDir(), APP_TOKEN_FILE) : new File(context.tokenFilePath);
    DataStore dataStore = new DataStore(tokenFile);
    try (OutputStream os = dataStore.getOutputStream()) {
      IOUtils.write(appAuthToken, os);
      dataStore.commit(os);
    } finally {
      dataStore.release();
    }
  }

private static void updateDpmProperties(Context context, String dpmBaseURL, List<String> labels, boolean enableSch) {
    if(context.skipUpdatingDpmProperties) {
      return;
    }

    try {
      FileBasedConfigurationBuilder<PropertiesConfiguration> builder =
          new FileBasedConfigurationBuilder<>(PropertiesConfiguration.class)
              .configure(new Parameters().properties()
                  .setFileName(context.runtimeInfo.getConfigDir() + "/dpm.properties")
                  .setThrowExceptionOnMissing(true)
                  .setListDelimiterHandler(new DefaultListDelimiterHandler(';'))
                  .setIncludesAllowed(false));
      PropertiesConfiguration config = null;
      config = builder.getConfiguration();
      config.setProperty(RemoteSSOService.DPM_ENABLED, Boolean.toString(enableSch));
      config.setProperty(RemoteSSOService.DPM_BASE_URL_CONFIG, dpmBaseURL);
      config.setProperty(RemoteSSOService.SECURITY_SERVICE_APP_AUTH_TOKEN_CONFIG, APP_TOKEN_FILE_PROP_VAL);
      if (labels != null && labels.size() > 0) {
        config.setProperty(RemoteEventHandlerTask.REMOTE_JOB_LABELS, StringUtils.join(labels, ','));
      } else {
        config.setProperty(RemoteEventHandlerTask.REMOTE_JOB_LABELS, "");
      }
      builder.save();
    } catch (ConfigurationException e) {
      throw new RuntimeException(Utils.format("Updating dpm.properties file failed: {}", e.getMessage()), e);
    }
  }

@Override
  public void createAndAddRecord(
      ResultSet rs,
      TableRuntimeContext tableRuntimeContext,
      BatchContext batchContext
  ) throws SQLException, StageException {
    ResultSetMetaData md = rs.getMetaData();

    LinkedHashMap<String, Field> fields = jdbcUtil.resultSetToFields(
        rs,
        commonSourceConfigBean,
        errorRecordHandler,
        tableJdbcConfigBean.unknownTypeAction,
        recordHeader,
        DatabaseVendor.SQL_SERVER
    );

    Map<String, String> columnOffsets = new HashMap<>();


    // Generate Offset includes primary keys, sys_change_version, and sys_change_operation
    for (String key : tableRuntimeContext.getSourceTableContext().getOffsetColumns()) {
      String value = rs.getString(key);
      if (Strings.isNullOrEmpty(value)) {
        value = fields.get(key) != null ? fields.get(key).getValueAsString() : "";
      }
      columnOffsets.put(key, value);
    }


    columnOffsets.put(SYS_CHANGE_OPERATION, rs.getString(SYS_CHANGE_OPERATION));

    String offsetFormat = OffsetQueryUtil.getOffsetFormat(columnOffsets);

    Record record = context.createRecord(tableRuntimeContext.getQualifiedName() + "::" + offsetFormat);
    record.set(Field.createListMap(fields));

    //Set Column Headers
    jdbcUtil.setColumnSpecificHeaders(
        record,
        Collections.singleton(tableRuntimeContext.getSourceTableContext().getTableName()),
        md,
        JDBC_NAMESPACE_HEADER
    );

    //Set Operation Headers
    int op = MSOperationCode.convertToJDBCCode(rs.getString(SYS_CHANGE_OPERATION));
    record.getHeader().setAttribute(OperationType.SDC_OPERATION_TYPE, String.valueOf(op));

    for (String fieldName : recordHeader) {
      record.getHeader().setAttribute(JDBC_NAMESPACE_HEADER + fieldName, rs.getString(fieldName) != null ? rs.getString(fieldName) : "NULL" );
    }

    int columns = rs.getMetaData().getColumnCount();
    if (fields.size() != columns) {
      errorRecordHandler.onError(JdbcErrors.JDBC_35, fields.size(), columns);
      return; // Don't output this record.
    } else {
      batchContext.getBatchMaker().addRecord(record);
    }

    offsets.put(tableRuntimeContext.getOffsetKey(), offsetFormat);
  }

private Field pullMap(XMLEventReader reader) throws StageException, XMLStreamException {
    LinkedHashMap<String, Field> map = new LinkedHashMap<>();
    String type = null;
    String fieldValue = null;

    while (reader.hasNext()) {
      XMLEvent event = reader.nextEvent();
      if (event.isStartElement()) {
        if (event.asStartElement().getName().getLocalPart().equals(TYPE)) {
          // Move to content
          event = reader.nextEvent();
          type = event.asCharacters().getData().toLowerCase();
          // Consume closing tag
          reader.nextEvent();
        } else {
          String fieldName = event.asStartElement().getName().getLocalPart();
          Attribute attr = event.asStartElement().getAttributeByName(XSI_TYPE);
          if (attr != null && attr.getValue().equals(S_OBJECT)) {
            // Element is a nested record
            map.put(fieldName, pullMap(reader));
          } else {
            event = reader.nextEvent();
            fieldValue = null;
            switch (event.getEventType()) {
              case XMLEvent.START_ELEMENT:
                // Element is a nested list of records
                // Advance over <done>, <queryLocator> to record list
                while (!(event.isStartElement() && event.asStartElement().getName().getLocalPart().equals(RECORDS))) {
                  event = reader.nextEvent();
                }

                // Read record list
                List<Field> recordList = new ArrayList<>();
                while (event.isStartElement() && event.asStartElement().getName().getLocalPart().equals(RECORDS)) {
                  recordList.add(pullMap(reader));
                  event = reader.nextEvent();
                }
                map.put(fieldName, Field.create(recordList));
                break;
              case XMLEvent.CHARACTERS:
                // Element is a field value
                fieldValue = event.asCharacters().getData();
                // Consume closing tag
                reader.nextEvent();
                // Intentional fall through to next case!
              case XMLEvent.END_ELEMENT:
                // Create the SDC field
                if (type == null) {
                  throw new StageException(Errors.FORCE_38);
                }
                // Is this a relationship to another object?
                com.sforce.soap.partner.Field sfdcField = metadataCache.get(type).getFieldFromRelationship(fieldName);
                if (sfdcField != null) {
                  // See if we already added fields from the related record
                  if (map.get(fieldName) != null) {
                    // We already created this node - don't overwrite it!
                    sfdcField = null;
                  }
                } else {
                  sfdcField = getFieldMetadata(type, fieldName);
                }

                if (sfdcField != null) {
                  Field field = createField(fieldValue, sfdcField);
                  if (conf.createSalesforceNsHeaders) {
                    setHeadersOnField(field, getFieldMetadata(type, fieldName));
                  }

                  map.put(fieldName, field);
                }
                break;
              default:
                throw new StageException(Errors.FORCE_41, event.getEventType());
            }
          }
        }
      } else if (event.isEndElement()) {
        // Done with record
        return Field.createListMap(map);
      }
    }

    throw new StageException(Errors.FORCE_39);
  }

protected Authentication returnUnauthorized(
      HttpServletRequest httpReq, HttpServletResponse httpRes, String principalId, String logMessageTemplate
  ) throws ServerAuthException {
    return returnUnauthorized(httpReq, httpRes, UNAUTHORIZED_JSON, principalId, logMessageTemplate);
  }

private Schema.Field schemaFieldForType(
      String fieldPath,
      Record record,
      String fieldName,
      Field field
  ) throws OnRecordErrorException {
    Schema simpleSchema = simpleSchemaForType(fieldPath, record, field);
    Schema finalSchema = simpleSchema;

    // If Nullable check box was selected, wrap the whole schema in union with null
    if(getConfig().avroNullableFields) {
      finalSchema = Schema.createUnion(ImmutableList.of(
        Schema.create(Schema.Type.NULL),
        simpleSchema
      ));
    }

    return new Schema.Field(
      fieldName,
      finalSchema,
      null,
      getDefaultValue(simpleSchema)
    );
  }

private Schema complexSchemaForType(
      String fieldPath,
      Record record,
      Field field
  ) throws OnRecordErrorException {
    Schema simpleSchema = simpleSchemaForType(fieldPath, record, field);
    Schema finalSchema = simpleSchema;

    if(getConfig().avroNullableFields) {
      finalSchema = Schema.createUnion(ImmutableList.of(
        Schema.create(Schema.Type.NULL),
        simpleSchema
      ));
    }

    JsonNode defaultValue = getDefaultValue(simpleSchema);
    if(defaultValue != null) {
      finalSchema.addProp("defaultValue", defaultValue);
    }

    return finalSchema;
  }

private Schema simpleSchemaForType(String fieldPath, Record record, Field field) throws OnRecordErrorException {
    switch (field.getType()) {
      // Primitive types
      case BOOLEAN:
        return Schema.create(Schema.Type.BOOLEAN);
      case INTEGER:
        return Schema.create(Schema.Type.INT);
      case LONG:
        return Schema.create(Schema.Type.LONG);
      case FLOAT:
        return Schema.create(Schema.Type.FLOAT);
      case DOUBLE:
        return Schema.create(Schema.Type.DOUBLE);
      case STRING:
        return Schema.create(Schema.Type.STRING);
      case BYTE_ARRAY:
        return Schema.create(Schema.Type.BYTES);

      // Logical types
      case DECIMAL:
        int precision = getDecimalScaleOrPrecision(record, field, getConfig().precisionAttribute, getConfig().defaultPrecision, 1);
        int scale = getDecimalScaleOrPrecision(record, field, getConfig().scaleAttribute, getConfig().defaultScale, 0);
        Schema decimalSchema = Schema.create(Schema.Type.BYTES);
        decimalSchema.addProp(AvroTypeUtil.LOGICAL_TYPE, AvroTypeUtil.LOGICAL_TYPE_DECIMAL);
        decimalSchema.addProp(AvroTypeUtil.LOGICAL_TYPE_ATTR_PRECISION, new IntNode(precision));
        decimalSchema.addProp(AvroTypeUtil.LOGICAL_TYPE_ATTR_SCALE, new IntNode(scale));
        return decimalSchema;
      case DATE:
        Schema dateSchema = Schema.create(Schema.Type.INT);
        dateSchema.addProp(AvroTypeUtil.LOGICAL_TYPE, AvroTypeUtil.LOGICAL_TYPE_DATE);
        return dateSchema;
      case TIME:
        Schema timeSchema = Schema.create(Schema.Type.INT);
        timeSchema.addProp(AvroTypeUtil.LOGICAL_TYPE, AvroTypeUtil.LOGICAL_TYPE_TIME_MILLIS);
        return timeSchema;
      case DATETIME:
        Schema dateTimeSchema = Schema.create(Schema.Type.LONG);
        dateTimeSchema.addProp(AvroTypeUtil.LOGICAL_TYPE, AvroTypeUtil.LOGICAL_TYPE_TIMESTAMP_MILLIS);
        return dateTimeSchema;

      // Complex types
      case LIST:
        // In avro list must be of the same type - which is not true with our records

        // We can't generate the list type from empty list
        if(field.getValueAsList().isEmpty()) {
          throw new OnRecordErrorException(record, Errors.SCHEMA_GEN_0006, fieldPath);
        }

        // And all items in the list must have the same schema
        Schema itemSchema = null;
        int index = 0;
        for(Field listItem : field.getValueAsList()) {
          Schema currentListItemSchema = complexSchemaForType(fieldPath + "[" + index + "]", record, listItem);
          if(itemSchema == null) {
            itemSchema = currentListItemSchema;
          } else if (!itemSchema.equals(currentListItemSchema)) {
            throw new OnRecordErrorException(record, Errors.SCHEMA_GEN_0005, fieldPath, itemSchema, currentListItemSchema);
          }
          index++;
        }
        return Schema.createArray(itemSchema);
      case MAP:
      case LIST_MAP:
        // In avro maps must have key of string (same as us) and value must be the same for all items - which
        // is different then our records.

        // We can't generate the map value type from null or empty map
        if(field.getValueAsMap() == null || field.getValueAsMap().isEmpty()) {
          throw new OnRecordErrorException(record, Errors.SCHEMA_GEN_0008, fieldPath);
        }

        // And all values in the map must be the same
        Schema mapSchema = null;
        for(Map.Entry<String, Field> item : field.getValueAsMap().entrySet()) {
          Schema currentListItemSchema = complexSchemaForType(fieldPath + "/" + item.getKey(), record, item.getValue());
          if(mapSchema == null) {
            mapSchema = currentListItemSchema;
          } else if (!mapSchema.equals(currentListItemSchema)) {
            throw new OnRecordErrorException(record, Errors.SCHEMA_GEN_0007, fieldPath, mapSchema, currentListItemSchema);
          }
        }
        return Schema.createMap(mapSchema);

      // Types that does not have direct equivalent in Avro
      case SHORT:
        if(getConfig().avroExpandTypes) {
          return Schema.create(Schema.Type.INT);
        }
        // fall through
      case CHAR:
        if(getConfig().avroExpandTypes) {
          return Schema.create(Schema.Type.STRING);
        }
        // fall through

      // Not supported data types:
      case BYTE:
      case FILE_REF:
      default:
        throw new OnRecordErrorException(record, Errors.SCHEMA_GEN_0002, field.getType());
    }
  }

private int getDecimalScaleOrPrecision(
      Record record,
      Field field,
      String attributeName,
      int defaultValue,
      int minAllowed
  ) throws OnRecordErrorException {
    int finalValue = -1; // Invalid value

    // Firstly try the field attribute
    String stringValue = field.getAttribute(attributeName);
    if(!StringUtils.isEmpty(stringValue)) {
      finalValue = Integer.valueOf(stringValue);
    }

    // If it's invalid, then use the default value
    if(finalValue < minAllowed) {
      finalValue = defaultValue;
    }

    // If even the default value is invalid, then send the record to error
    if(finalValue < minAllowed) {
      throw new OnRecordErrorException(record, Errors.SCHEMA_GEN_0004, finalValue, field);
    }

    return finalValue;
  }

