private int parsePart(int startOffset, ByteBuf buf, Map<String, Field> fields) throws OnRecordErrorException {
    int offset = startOffset;
    int type = buf.getUnsignedShort(offset); // 0-1
    offset += 2;
    final int length = buf.getUnsignedShort(offset); // 2-3
    offset += 2;

    switch (type) {
      case HOST:
      case PLUGIN:
      case PLUGIN_INSTANCE:
      case TYPE:
      case TYPE_INSTANCE:
      case MESSAGE:
        pruneFields(type);
        fields.put(PART_TYPES.get(type), Field.create(parseString(offset, length, buf)));
        offset += length - 4;
        break;
      case TIME_HIRES:
      case INTERVAL_HIRES:
        if (type != INTERVAL_HIRES || !excludeInterval) {
          long value = parseNumeric(offset, buf);
          if (convertTime) {
            value *= (Math.pow(2, -30) * 1000);
            type = type == TIME_HIRES ? TIME : INTERVAL;
          }
          fields.put(PART_TYPES.get(type), Field.create(value));
        }
        offset += 8;
        break;
      case TIME:
      case INTERVAL:
      case SEVERITY:
        if (type != INTERVAL || !excludeInterval) {
          fields.put(PART_TYPES.get(type), Field.create(parseNumeric(offset, buf)));
        }
        offset += 8;
        break;
      case VALUES:
        offset = parseValues(offset, buf);
        startNewRecord();
        break;
      case SIGNATURE:
        if (!verifySignature(offset, length, buf)) {
          throw new OnRecordErrorException(Errors.COLLECTD_02);
        }
        offset += length - 4;
        break;
      case ENCRYPTION:
        String user = parseUser(offset, buf);
        offset += (2 + user.length());
        byte[] iv = parseIv(offset, buf);
        offset += 16;
        decrypt(offset, length, buf, user, iv);
        // Skip the checksum and continue processing.
        offset += 20;
        break;
      default:
        // Don't recognize this part type, so skip it
        LOG.warn("Unrecognized part type: {}", type);
        offset += length - 4;
        break;
    }

    return offset;
  }

private int parseValues(int startOffset, ByteBuf buf) throws OnRecordErrorException {
    int offset = startOffset;
    // N Values
    // For each Value:
    // 1 byte data type code
    int numValues = buf.getUnsignedShort(offset); // 4-5
    offset += 2;

    List<Byte> types = new ArrayList<>(numValues);

    while (numValues-- > 0) {
      types.add(buf.getByte(offset));
      offset += 1;
    }

    for (int i = 0; i < types.size(); i++) {
      Byte type = types.get(i);
      String label = getValueLabel(i, type);
      switch (type) {
        case COUNTER:
          fields.put(label, Field.create(buf.getUnsignedInt(offset)));
          offset += 8;
          break;
        case GAUGE:
          fields.put(
              label,
              Field.create(buf.order(ByteOrder.LITTLE_ENDIAN).getDouble(offset))
          );
          offset += 8;
          break;
        case DERIVE:
          fields.put(label, Field.create(buf.getLong(offset)));
          offset += 8;
          break;
        case ABSOLUTE:
          fields.put(label, Field.create(buf.getUnsignedInt(offset)));
          offset += 8;
          break;
        default:
          // error
          throw new OnRecordErrorException(Errors.COLLECTD_01, type);
      }
    }
    return offset;
  }

public static Field getUnsignedShortField(byte[] bytes) {
    Utils.checkState(bytes.length == 2, "2 bytes required to parse an unsigned short");
    final short shortVal = Shorts.fromByteArray(bytes);
    int intVal = shortVal >= 0 ? shortVal : 0x10000 + shortVal;
    return Field.create(intVal);
  }

@Override
  public String inferSchema(Map<String, HiveTypeInfo> record)
      throws StageException
  {
    Map<String, Schema> fields = new LinkedHashMap<>();
    for(Map.Entry<String, HiveTypeInfo> pair:  record.entrySet()) {
      if(!HiveMetastoreUtil.validateObjectName(pair.getKey())) {
        throw new HiveStageCheckedException(Errors.HIVE_30, pair.getKey());
      }
      Schema columnSchema = Schema.createUnion(ImmutableList.of(Schema.create(Schema.Type.NULL), traverse(pair)));
      // We always set default value to null
      columnSchema.addProp("default", NullNode.getInstance());
      fields.put(pair.getKey(), columnSchema);
    }
    Schema schema =  buildSchema(fields);
    return schema.toString();
  }

public static String nameForType(DatabaseVendor vendor, int jdbcType) {
    for( JDBCType sqlType : JDBCType.class.getEnumConstants()) {
      if(jdbcType == sqlType.getVendorTypeNumber())
        return sqlType.name();
    }

    switch (vendor) {
      case ORACLE:
        switch (jdbcType) {
          case -101: return "TIMESTAMP WITH TIME ZONE";
          case -102: return "TIMESTAMP WITH LOCAL TIME ZONE";
        }
        break;
    }

    return "Unknown";
  }

