public void executeBatch(
      String offsetKey,
      String offsetValue,
      long batchStartTime,
      ThrowingConsumer<Pipe> consumer
  ) throws PipelineRuntimeException, StageException {
    MDC.put(LogConstants.RUNNER, String.valueOf(runnerId));
    // Persist static information for the batch (this won't change as the batch progresses)
    this.runtimeMetricGauge.put(METRIC_BATCH_START_TIME, batchStartTime);
    this.runtimeMetricGauge.put(METRIC_OFFSET_KEY, Optional.ofNullable(offsetKey).orElse(""));
    this.runtimeMetricGauge.put(METRIC_OFFSET_VALUE, Optional.ofNullable(offsetValue).orElse(""));
    this.runtimeMetricGauge.put(METRIC_STAGE_START_TIME, System.currentTimeMillis());
    try {
      // Run one pipe at a time
      for(Pipe p : pipes) {
        String instanceName = p.getStage().getInfo().getInstanceName();
        this.runtimeMetricGauge.put(METRIC_CURRENT_STAGE, instanceName);
        MDC.put(LogConstants.STAGE, instanceName);
        if (p instanceof StagePipe) {
          this.runtimeMetricGauge.put(METRIC_STAGE_START_TIME, System.currentTimeMillis());
        }

        acceptConsumer(consumer, p);
      }


      // We've successfully finished batch
      this.runtimeMetricGauge.computeIfPresent(METRIC_BATCH_COUNT, (key, value) -> ((long)value) + 1);
    } finally {
      resetBatchSpecificMetrics();
      MDC.put(LogConstants.RUNNER, "");
      MDC.put(LogConstants.STAGE, "");
    }
  }

public void forEach(ThrowingConsumer<Pipe> consumer) {
    try {
      MDC.put(LogConstants.RUNNER, String.valueOf(runnerId));
      try {
        for(Pipe p : pipes) {
          MDC.put(LogConstants.STAGE, p.getStage().getInfo().getInstanceName());
          acceptConsumer(consumer, p);
        }
      } finally {
        MDC.put(LogConstants.RUNNER, "");
        MDC.put(LogConstants.STAGE, "");
      }
    } catch (PipelineException|StageException e) {
      throw new RuntimeException(e);
    }
  }

public OffsetCommitTrigger getOffsetCommitTrigger() {
    for (Pipe pipe : pipes) {
      Stage stage = pipe.getStage().getStage();
      if (stage instanceof Target && stage instanceof OffsetCommitTrigger) {
        return (OffsetCommitTrigger) stage;
      }
    }
    return null;
  }

public boolean onRecordErrorStopPipeline() {
    for(Pipe pipe : pipes) {
      StageContext stageContext = pipe.getStage().getContext();
      if(stageContext.getOnErrorRecord() == OnRecordError.STOP_PIPELINE) {
        return true;
      }
    }

    return false;
  }

private void acceptConsumer(ThrowingConsumer<Pipe> consumer, Pipe p) throws PipelineRuntimeException, StageException {
    try {
      // Process pipe
      consumer.accept(p);
    } catch (Throwable t) {
      String instanceName = p.getStage().getInfo().getInstanceName();
      LOG.error("Failed executing stage '{}': {}", instanceName, t.toString(), t);
      Throwables.propagateIfInstanceOf(t, PipelineRuntimeException.class);
      Throwables.propagateIfInstanceOf(t, StageException.class);
      Throwables.propagate(t);
    }
  }

private String getInsertIdForRecord(ELVars elVars, Record record) throws OnRecordErrorException {
    String recordId = null;
    RecordEL.setRecordInContext(elVars, record);
    try {
      if (!(StringUtils.isEmpty(conf.rowIdExpression))) {
        recordId = rowIdELEval.eval(elVars, conf.rowIdExpression, String.class);
        if (StringUtils.isEmpty(recordId)) {
          throw new OnRecordErrorException(record, Errors.BIGQUERY_15);
        }
      }
    } catch (ELEvalException e) {
      LOG.error("Error evaluating Row Expression EL", e);
      throw new OnRecordErrorException(record, Errors.BIGQUERY_10,e);
    }
    return recordId;
  }

private Map<String, Object> convertToRowObjectFromRecord(Record record) throws OnRecordErrorException {
    Field rootField = record.get();
    Map<String, Object> rowObject = new LinkedHashMap<>();
    if (rootField.getType().isOneOf(Field.Type.MAP, Field.Type.LIST_MAP)) {
      Map<String, Field> fieldMap = rootField.getValueAsMap();
      for (Map.Entry<String, Field> fieldEntry : fieldMap.entrySet()) {
        Field field = fieldEntry.getValue();
        //Skip null value fields
        if (field.getValue() != null){
          try {
            rowObject.put(fieldEntry.getKey(), getValueFromField("/" + fieldEntry.getKey(), field));
          } catch (IllegalArgumentException e) {
            throw new OnRecordErrorException(record, Errors.BIGQUERY_13, e.getMessage());
          }
        }
      }
    } else {
      throw new OnRecordErrorException(record,  Errors.BIGQUERY_16);
    }
    return rowObject;
  }

private Object getValueFromField(String fieldPath, Field field) {
    LOG.trace("Visiting Field Path '{}' of type '{}'", fieldPath, field.getType());
    switch (field.getType()) {
      case LIST:
        //REPEATED
        List<Field> listField = field.getValueAsList();
        //Convert the list to map with indices as key and Field as value (Map<Integer, Field>)
        Map<Integer, Field> fields =
            IntStream.range(0, listField.size()).boxed()
                .collect(Collectors.toMap(Function.identity(), listField::get));
        //filter map to remove fields with null value
        fields = fields.entrySet().stream()
            .filter(e -> e.getValue().getValue() != null)
            .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
        //now use the map index to generate field path and generate object for big query write
        return fields.entrySet().stream()
            .map(e -> getValueFromField(fieldPath + "[" + e.getKey() + "]", e.getValue()))
            .collect(Collectors.toList());
      case MAP:
      case LIST_MAP:
        //RECORD
        return field.getValueAsMap().entrySet().stream()
            .filter(me -> me.getValue().getValue() != null)
            .collect(
                Collectors.toMap(
                    Map.Entry::getKey,
                    e -> getValueFromField(fieldPath + "/" + e.getKey(), e.getValue())
                )
            );
      case DATE:
        return dateFormat.format(field.getValueAsDate());
      case TIME:
        return timeFormat.format(field.getValueAsTime());
      case DATETIME:
        return dateTimeFormat.format(field.getValueAsDatetime());
      case BYTE_ARRAY:
        return Base64.getEncoder().encodeToString(field.getValueAsByteArray());
      case DECIMAL:
      case BYTE:
      case CHAR:
      case FILE_REF:
        throw new IllegalArgumentException(Utils.format(Errors.BIGQUERY_12.getMessage(), fieldPath, field.getType()));
      default:
        //Boolean -> Map to Boolean in big query
        //Float, Double -> Map to Float in big query
        //String -> maps to String in big query
        //Short, Integer, Long -> Map to integer in big query
        return field.getValue();
    }
  }

private void checkValidPorts() {
