public static <T, E1 extends Exception> T withClassLoader(
      ClassLoader classLoader,
      Class<E1> e1,
      ExceptionSupplier<T> supplier
   ) throws E1 {
     try {
       return withClassLoaderInternal(classLoader, supplier);
     } catch (Exception e) {
