      try {
        synchronized (this) {
          if (System.currentTimeMillis() > getExpireTime()) {
            accessToken = fetchAccessToken();
            if (accessToken != null && !accessToken.isEmpty()) {
              expires = (System.currentTimeMillis() + expires);
