public void writeException(OutputStream out, Throwable e) {
        int len = excepWriters.length;
        for (int i = 0; i < len; i++) {
            if (excepWriters[i].getExceptionClass().isInstance(e)) {
                excepWriters[i].write(out, e);
                return;
