      clusters = DEFAULT_CLUSTER_NAME;

    for (String cluster : clusters) {
      final List<String> serverList = getClusterConfiguration(cluster).field(SERVERS);
      if (serverList != null) {
        if (!serverList.contains(server))
          return false;
      }
    }
    return true;
  }

