    public BraintreeError errorFor(String field) {
        BraintreeError returnError;
        if (mFieldErrors != null) {
            for (BraintreeError error : mFieldErrors) {
                if (error.getField().equals(field)) {
                    return error;
                } else if (error.getFieldErrors() != null) {
