public void decodeFrame(byte[] frame, SampleBuffer buffer) throws AACException {
        if (frame != null)
            _in.setData(frame);
        Logger.debug("bits left " + _in.getBitsLeft());
        try {
            decode(buffer);
        } catch (AACException e) {
            if (!e.isEndOfStream())
                throw e;
            else
                Logger.warn("unexpected end of frame");
        }
    }

public void setBigEndian(boolean bigEndian) {
		if(bigEndian!=this.bigEndian) {
			byte tmp;
			for(int i = 0; i<data.length; i += 2) {
				tmp = data[i];
				data[i] = data[i+1];
				data[i+1] = tmp;
			}
			this.bigEndian = bigEndian;
		}
	}

public void deblockMBGeneric(EncodedMB curMB, EncodedMB leftMB, EncodedMB topMB, int[][] vertStrength,
            int horizStrength[][]) {
        Picture curPix = curMB.getPixels();
        if (leftMB != null) {
            Picture leftPix = leftMB.getPixels();
            int avgQp = MathUtil.clip((leftMB.getQp() + curMB.getQp() + 1) >> 1, 0, 51);
            deblockBorder(vertStrength[0], avgQp, leftPix.getPlaneData(0), 3, curPix.getPlaneData(0), 0, P_POS_V,
                    Q_POS_V, false);
            deblockBorderChroma(vertStrength[0], avgQp, leftPix.getPlaneData(1), 3, curPix.getPlaneData(1), 0,
                    P_POS_V_CHR, Q_POS_V_CHR, false);
            deblockBorderChroma(vertStrength[0], avgQp, leftPix.getPlaneData(2), 3, curPix.getPlaneData(2), 0,
                    P_POS_V_CHR, Q_POS_V_CHR, false);
        }
        for (int i = 0; i < 3; i++) {
            deblockBorder(vertStrength[i + 1], curMB.getQp(), curPix.getPlaneData(0), i, curPix.getPlaneData(0), i + 1,
                    P_POS_V, Q_POS_V, false);
            deblockBorderChroma(vertStrength[i + 1], curMB.getQp(), curPix.getPlaneData(1), i, curPix.getPlaneData(1),
                    i + 1, P_POS_V_CHR, Q_POS_V_CHR, false);
            deblockBorderChroma(vertStrength[i + 1], curMB.getQp(), curPix.getPlaneData(2), i, curPix.getPlaneData(2),
                    i + 1, P_POS_V_CHR, Q_POS_V_CHR, false);
        }

        if (topMB != null) {
            Picture topPix = topMB.getPixels();
            int avgQp = MathUtil.clip((topMB.getQp() + curMB.getQp() + 1) >> 1, 0, 51);
            deblockBorder(horizStrength[0], avgQp, topPix.getPlaneData(0), 3, curPix.getPlaneData(0), 0, P_POS_H,
                    Q_POS_H, true);
            deblockBorderChroma(horizStrength[0], avgQp, topPix.getPlaneData(1), 3, curPix.getPlaneData(1), 0,
                    P_POS_H_CHR, Q_POS_H_CHR, true);
            deblockBorderChroma(horizStrength[0], avgQp, topPix.getPlaneData(2), 3, curPix.getPlaneData(2), 0,
                    P_POS_H_CHR, Q_POS_H_CHR, true);
        }
        for (int i = 0; i < 3; i++) {
            deblockBorder(horizStrength[i + 1], curMB.getQp(), curPix.getPlaneData(0), i, curPix.getPlaneData(0),
                    i + 1, P_POS_H, Q_POS_H, true);
            deblockBorderChroma(horizStrength[i + 1], curMB.getQp(), curPix.getPlaneData(1), i, curPix.getPlaneData(1),
                    i + 1, P_POS_H_CHR, Q_POS_H_CHR, true);
            deblockBorderChroma(horizStrength[i + 1], curMB.getQp(), curPix.getPlaneData(2), i, curPix.getPlaneData(2),
                    i + 1, P_POS_H_CHR, Q_POS_H_CHR, true);
        }
    }

public void deblockMBP(EncodedMB cur, EncodedMB left, EncodedMB top) {
        int[][] vertStrength = new int[4][4];
        int[][] horizStrength = new int[4][4];

        calcStrengthForBlocks(cur, left, vertStrength, LOOKUP_IDX_P_V, LOOKUP_IDX_Q_V);
        calcStrengthForBlocks(cur, top, horizStrength, LOOKUP_IDX_P_H, LOOKUP_IDX_Q_H);

        deblockMBGeneric(cur, left, top, vertStrength, horizStrength);
    }

public void encodeNativeFrame(Picture pic) throws IOException {
		if (pic.getColor() != ColorSpace.RGB)
			throw new IllegalArgumentException("The input images is expected in RGB color.");

		ColorSpace sinkColor = sink.getInputColor();
		LoanerPicture toEncode;
		if (sinkColor != null) {
			toEncode = pixelStore.getPicture(pic.getWidth(), pic.getHeight(), sinkColor);
			transform.transform(pic, toEncode.getPicture());
		} else {
			toEncode = new LoanerPicture(pic, 0);
		}

		Packet pkt = Packet.createPacket(null, timestamp, fps.getNum(), fps.getDen(), frameNo, FrameType.KEY, null);
		sink.outputVideoFrame(new VideoFrameWithPacket(pkt, toEncode));

		if (sinkColor != null)
			pixelStore.putBack(toEncode);

		timestamp += fps.getDen();
		frameNo++;
	}

public static byte[] ebmlEncodeLen(long value, int length) {
        byte[] b = new byte[length];
        for (int idx = 0; idx < length; idx++) {
            // Rightmost bytes should go to end of array to preserve big-endian notation
            b[length - idx - 1] = (byte) ((value >>> (8 * idx)) & 0xFFL);
        }

        b[0] |= 0x80 >>> (length - 1);
        return b;
    }

static public int computeLength(byte b) {
        if (b == 0x00)
            throw new RuntimeException("Invalid head element for ebml sequence");

        int i = 1;
        while ((b & lengthOptions[i]) == 0)
            i++;

        return i;
    }

public static int ebmlLength(long v) {
        if (v == 0)
            return 1;

        int length = 8;

        while (length > 0 && (v & ebmlLengthMasks[length]) == 0)
            length--;

        return length;
    }

static void oneLong(float[] src, float[] dst) {
        for (int i = 17; i > 0; i--)
            src[i] += src[i - 1];

        for (int i = 17; i > 2; i -= 2)
            src[i] += src[i - 2];

        for (int i = 0, k = 0; i < 2; i++, k += 8) {
            float tmp0 = src[i] + src[i];
            float tmp1 = tmp0 + src[12 + i];
            float tmp2 = src[6 + i] * factor36pt3;

            tmp[k + 0] = tmp1 + src[4 + i] * factor36pt2 + src[8 + i] * factor36pt1 + src[16 + i] * factor36pt0;
            tmp[k + 1] = tmp0 + src[4 + i] - src[8 + i] - src[12 + i] - src[12 + i] - src[16 + i];
            tmp[k + 2] = tmp1 - src[4 + i] * factor36pt0 - src[8 + i] * factor36pt2 + src[16 + i] * factor36pt1;
            tmp[k + 3] = tmp1 - src[4 + i] * factor36pt1 + src[8 + i] * factor36pt0 - src[16 + i] * factor36pt2;

            tmp[k + 4] = src[2 + i] * factor36pt4 + tmp2 + src[10 + i] * factor36pt5 + src[14 + i] * factor36pt6;
            tmp[k + 5] = (src[2 + i] - src[10 + i] - src[14 + i]) * factor36pt3;
            tmp[k + 6] = src[2 + i] * factor36pt5 - tmp2 - src[10 + i] * factor36pt6 + src[14 + i] * factor36pt4;
            tmp[k + 7] = src[2 + i] * factor36pt6 - tmp2 + src[10 + i] * factor36pt4 - src[14 + i] * factor36pt5;
        }

        for (int i = 0, j = 4, k = 8, l = 12; i < 4; i++, j++, k++, l++) {
            float q1 = tmp[i];
            float q2 = tmp[k];
            tmp[i] += tmp[j];
            tmp[j] = q1 - tmp[j];
            tmp[k] = (tmp[k] + tmp[l]) * factor36[i];
            tmp[l] = (q2 - tmp[l]) * factor36[7 - i];
        }

        for (int i = 0; i < 4; i++) {
            dst[26 - i] = tmp[i] + tmp[8 + i];
            dst[8 - i] = tmp[8 + i] - tmp[i];
            dst[27 + i] = dst[26 - i];
            dst[9 + i] = -dst[8 - i];
        }

        for (int i = 0; i < 4; i++) {
            dst[21 - i] = tmp[7 - i] + tmp[15 - i];
            dst[3 - i] = tmp[15 - i] - tmp[7 - i];
            dst[32 + i] = dst[21 - i];
            dst[14 + i] = -dst[3 - i];
        }

        float tmp0 = src[0] - src[4] + src[8] - src[12] + src[16];
        float tmp1 = (src[1] - src[5] + src[9] - src[13] + src[17]) * cos450;
        dst[4] = tmp1 - tmp0;
        dst[13] = -dst[4];
        dst[31] = dst[22] = tmp0 + tmp1;
    }

static void threeShort(float[] src, float[] dst) {
        Arrays.fill(dst, 0.0f);

        for (int i = 0, outOff = 0; i < 3; i++, outOff += 6) {
            imdct12(src, dst, outOff, i);
        }
    }

private static void imdct12(float[] src, float[] dst, int outOff, int wndIdx) {

        for (int j = 15 + wndIdx, k = 12 + wndIdx; j >= 3 + wndIdx; j -= 3, k -= 3)
            src[j] += src[k];

        src[15 + wndIdx] += src[9 + wndIdx];
        src[9 + wndIdx] += src[3 + wndIdx];

        float pp2 = src[12 + wndIdx] * cos600;
        float pp1 = src[6 + wndIdx] * cos300;
        float sum = src[0 + wndIdx] + pp2;
        tmp[1] = src[wndIdx] - src[12 + wndIdx];
        tmp[0] = sum + pp1;
        tmp[2] = sum - pp1;

        pp2 = src[15 + wndIdx] * cos600;
        pp1 = src[9 + wndIdx] * cos300;
        sum = src[3 + wndIdx] + pp2;
        tmp[4] = src[3 + wndIdx] - src[15 + wndIdx];
        tmp[5] = sum + pp1;
        tmp[3] = sum - pp1;

        tmp[3] *= factor12pt0;
        tmp[4] *= cos450;
        tmp[5] *= factor12pt1;

        float t  = tmp[0];
        tmp[0]  += tmp[5];
        tmp[5]   = t - tmp[5];

        t        = tmp[1];
        tmp[1]  += tmp[4];
        tmp[4]   = t - tmp[4];

        t        = tmp[2];
        tmp[2]  += tmp[3];
        tmp[3]   = t - tmp[3];

        for (int j = 0; j < 6; j++)
            tmp[j] *= factor12[j];

        tmp[8]  = -tmp[0] * cos375;
        tmp[9]  = -tmp[0] * cos525;
        tmp[7]  = -tmp[1] * cos225;
        tmp[10] = -tmp[1] * cos675;
        tmp[6]  = -tmp[2] * cos075;
        tmp[11] = -tmp[2] * cos825;

        tmp[0]  = tmp[3];
        tmp[1]  = tmp[4]  * cos675;
        tmp[2]  = tmp[5]  * cos525;

        tmp[3]  = -tmp[5] * cos375;
        tmp[4]  = -tmp[4] * cos225;
        tmp[5]  = -tmp[0] * cos075;

        tmp[0] *= cos825;

        for (int i = 0, j = outOff + 6; i < 12; i++, j++) {
            dst[j] += tmp[i];
        }
    }

public int decode(IBitStream ld, int cnt) throws AACException {
		int result = 0;
		int num_align_bits = 0;
		long num_sbr_bits1 = ld.getPosition();
		int num_sbr_bits2;

		int saved_start_freq, saved_samplerate_mode;
		int saved_stop_freq, saved_freq_scale;
		int saved_xover_band;
		boolean saved_alter_scale;

		int bs_extension_type = ld.readBits(4);

		if(bs_extension_type==EXT_SBR_DATA_CRC) {
			this.bs_sbr_crc_bits = ld.readBits(10);
		}

		/* save old header values, in case the new ones are corrupted */
		saved_start_freq = this.bs_start_freq;
		saved_samplerate_mode = this.bs_samplerate_mode;
		saved_stop_freq = this.bs_stop_freq;
		saved_freq_scale = this.bs_freq_scale;
		saved_alter_scale = this.bs_alter_scale;
		saved_xover_band = this.bs_xover_band;

		this.bs_header_flag = ld.readBool();

		if(this.bs_header_flag)
			sbr_header(ld);

		/* Reset? */
		sbr_reset();

		/* first frame should have a header */
		//if (!(sbr.frame == 0 && sbr.bs_header_flag == 0))
		if(this.header_count!=0) {
			if(this.Reset||(this.bs_header_flag&&this.just_seeked)) {
				int rt = calc_sbr_tables(this.bs_start_freq, this.bs_stop_freq,
					this.bs_samplerate_mode, this.bs_freq_scale,
					this.bs_alter_scale, this.bs_xover_band);

				/* if an error occured with the new header values revert to the old ones */
				if(rt>0) {
					calc_sbr_tables(saved_start_freq, saved_stop_freq,
						saved_samplerate_mode, saved_freq_scale,
						saved_alter_scale, saved_xover_band);
				}
			}

			if(result==0) {
				result = sbr_data(ld);

				/* sbr_data() returning an error means that there was an error in
				 envelope_time_border_vector().
				 In this case the old time border vector is saved and all the previous
				 data normally read after sbr_grid() is saved.
				 */
				/* to be on the safe side, calculate old sbr tables in case of error */
				if((result>0)
					&&(this.Reset||(this.bs_header_flag&&this.just_seeked))) {
					calc_sbr_tables(saved_start_freq, saved_stop_freq,
						saved_samplerate_mode, saved_freq_scale,
						saved_alter_scale, saved_xover_band);
				}

				/* we should be able to safely set result to 0 now, */
				/* but practise indicates this doesn't work well */
			}
		}
		else {
			result = 1;
		}

		num_sbr_bits2 = (int) (ld.getPosition()-num_sbr_bits1);

		/* check if we read more bits then were available for sbr */
		if(8*cnt<num_sbr_bits2) {
			throw new AACException("frame overread");
			//faad_resetbits(ld, num_sbr_bits1+8*cnt);
			//num_sbr_bits2 = 8*cnt;

			/* turn off PS for the unfortunate case that we randomly read some
			 * PS data that looks correct */
			//this.ps_used = 0;

			/* Make sure it doesn't decode SBR in this frame, or we'll get glitches */
			//return 1;
		}

		{
			/* -4 does not apply, bs_extension_type is re-read in this function */
			num_align_bits = 8*cnt /*- 4*/-num_sbr_bits2;

			while(num_align_bits>7) {
				ld.readBits(8);
				num_align_bits -= 8;
			}
			ld.readBits(num_align_bits);
		}

		return result;
	}

private void sbr_header(IBitStream ld) throws AACException {
		boolean bs_header_extra_1, bs_header_extra_2;

		this.header_count++;

		this.bs_amp_res = ld.readBool();

		/* bs_start_freq and bs_stop_freq must define a fequency band that does
		 not exceed 48 channels */
		this.bs_start_freq = ld.readBits(4);
		this.bs_stop_freq = ld.readBits(4);
		this.bs_xover_band = ld.readBits(3);
		ld.readBits(2); //reserved
		bs_header_extra_1 = ld.readBool();
		bs_header_extra_2 = ld.readBool();

		if(bs_header_extra_1) {
			this.bs_freq_scale = ld.readBits(2);
			this.bs_alter_scale = ld.readBool();
			this.bs_noise_bands = ld.readBits(2);
		}
		else {
			/* Default values */
			this.bs_freq_scale = 2;
			this.bs_alter_scale = true;
			this.bs_noise_bands = 2;
		}

		if(bs_header_extra_2) {
			this.bs_limiter_bands = ld.readBits(2);
			this.bs_limiter_gains = ld.readBits(2);
			this.bs_interpol_freq = ld.readBool();
			this.bs_smoothing_mode = ld.readBool();
		}
		else {
			/* Default values */
			this.bs_limiter_bands = 2;
			this.bs_limiter_gains = 2;
			this.bs_interpol_freq = true;
			this.bs_smoothing_mode = true;
		}

	}

private int sbr_data(IBitStream ld) throws AACException {
		int result;

		this.rate = (this.bs_samplerate_mode!=0) ? 2 : 1;

		if(stereo) {
			if((result = sbr_channel_pair_element(ld))>0)
				return result;
		}
		else {
			if((result = sbr_single_channel_element(ld))>0)
				return result;
		}

		return 0;
	}

private int sbr_single_channel_element(IBitStream ld) throws AACException {
		int result;

		if(ld.readBool()) {
			ld.readBits(4); //reserved
		}

		if((result = sbr_grid(ld, 0))>0)
			return result;

		sbr_dtdf(ld, 0);
		invf_mode(ld, 0);
		sbr_envelope(ld, 0);
		sbr_noise(ld, 0);

		NoiseEnvelope.dequantChannel(this, 0);

		Arrays.fill(bs_add_harmonic[0], 0, 64, 0);
		Arrays.fill(bs_add_harmonic[1], 0, 64, 0);

		this.bs_add_harmonic_flag[0] = ld.readBool();
		if(this.bs_add_harmonic_flag[0])
			sinusoidal_coding(ld, 0);

		this.bs_extended_data = ld.readBool();

		if(this.bs_extended_data) {
			int nr_bits_left;
			int ps_ext_read = 0;
			int cnt = ld.readBits(4);
			if(cnt==15) {
				cnt += ld.readBits(8);
			}

			nr_bits_left = 8*cnt;
			while(nr_bits_left>7) {
				int tmp_nr_bits = 0;

				this.bs_extension_id = ld.readBits(2);
				tmp_nr_bits += 2;

				/* allow only 1 PS extension element per extension data */
				if(this.bs_extension_id==EXTENSION_ID_PS) {
					if(ps_ext_read==0) {
						ps_ext_read = 1;
					}
					else {
						/* to be safe make it 3, will switch to "default"
						 * in sbr_extension() */
						this.bs_extension_id = 3;
					}
				}

				tmp_nr_bits += sbr_extension(ld, this.bs_extension_id, nr_bits_left);

				/* check if the data read is bigger than the number of available bits */
				if(tmp_nr_bits>nr_bits_left)
					return 1;

				nr_bits_left -= tmp_nr_bits;
			}

			/* Corrigendum */
			if(nr_bits_left>0) {
				ld.readBits(nr_bits_left);
			}
		}

		return 0;
	}

private int sbr_channel_pair_element(IBitStream ld) throws AACException {
		int n, result;

		if(ld.readBool()) {
			//reserved
			ld.readBits(4);
			ld.readBits(4);
		}

		this.bs_coupling = ld.readBool();

		if(this.bs_coupling) {
			if((result = sbr_grid(ld, 0))>0)
				return result;

			/* need to copy some data from left to right */
			this.bs_frame_class[1] = this.bs_frame_class[0];
			this.L_E[1] = this.L_E[0];
			this.L_Q[1] = this.L_Q[0];
			this.bs_pointer[1] = this.bs_pointer[0];

			for(n = 0; n<=this.L_E[0]; n++) {
				this.t_E[1][n] = this.t_E[0][n];
				this.f[1][n] = this.f[0][n];
			}
			for(n = 0; n<=this.L_Q[0]; n++) {
				this.t_Q[1][n] = this.t_Q[0][n];
			}

			sbr_dtdf(ld, 0);
			sbr_dtdf(ld, 1);
			invf_mode(ld, 0);

			/* more copying */
			for(n = 0; n<this.N_Q; n++) {
				this.bs_invf_mode[1][n] = this.bs_invf_mode[0][n];
			}

			sbr_envelope(ld, 0);
			sbr_noise(ld, 0);
			sbr_envelope(ld, 1);
			sbr_noise(ld, 1);

			Arrays.fill(bs_add_harmonic[0], 0, 64, 0);
			Arrays.fill(bs_add_harmonic[1], 0, 64, 0);

			this.bs_add_harmonic_flag[0] = ld.readBool();
			if(this.bs_add_harmonic_flag[0])
				sinusoidal_coding(ld, 0);

			this.bs_add_harmonic_flag[1] = ld.readBool();
			if(this.bs_add_harmonic_flag[1])
				sinusoidal_coding(ld, 1);
		}
		else {
			int[] saved_t_E = new int[6], saved_t_Q = new int[3];
			int saved_L_E = this.L_E[0];
			int saved_L_Q = this.L_Q[0];
			int saved_frame_class = this.bs_frame_class[0];

			for(n = 0; n<saved_L_E; n++) {
				saved_t_E[n] = this.t_E[0][n];
			}
			for(n = 0; n<saved_L_Q; n++) {
				saved_t_Q[n] = this.t_Q[0][n];
			}

			if((result = sbr_grid(ld, 0))>0)
				return result;
			if((result = sbr_grid(ld, 1))>0) {
				/* restore first channel data as well */
				this.bs_frame_class[0] = saved_frame_class;
				this.L_E[0] = saved_L_E;
				this.L_Q[0] = saved_L_Q;
				for(n = 0; n<6; n++) {
					this.t_E[0][n] = saved_t_E[n];
				}
				for(n = 0; n<3; n++) {
					this.t_Q[0][n] = saved_t_Q[n];
				}

				return result;
			}
			sbr_dtdf(ld, 0);
			sbr_dtdf(ld, 1);
			invf_mode(ld, 0);
			invf_mode(ld, 1);
			sbr_envelope(ld, 0);
			sbr_envelope(ld, 1);
			sbr_noise(ld, 0);
			sbr_noise(ld, 1);

			Arrays.fill(bs_add_harmonic[0], 0, 64, 0);
			Arrays.fill(bs_add_harmonic[1], 0, 64, 0);

			this.bs_add_harmonic_flag[0] = ld.readBool();
			if(this.bs_add_harmonic_flag[0])
				sinusoidal_coding(ld, 0);

			this.bs_add_harmonic_flag[1] = ld.readBool();
			if(this.bs_add_harmonic_flag[1])
				sinusoidal_coding(ld, 1);
		}
		NoiseEnvelope.dequantChannel(this, 0);
		NoiseEnvelope.dequantChannel(this, 1);

		if(this.bs_coupling)
			NoiseEnvelope.unmap(this);

		this.bs_extended_data = ld.readBool();
		if(this.bs_extended_data) {
			int nr_bits_left;
			int cnt = ld.readBits(4);
			if(cnt==15) {
				cnt += ld.readBits(8);
			}

			nr_bits_left = 8*cnt;
			while(nr_bits_left>7) {
				int tmp_nr_bits = 0;

				this.bs_extension_id = ld.readBits(2);
				tmp_nr_bits += 2;
				tmp_nr_bits += sbr_extension(ld, this.bs_extension_id, nr_bits_left);

				/* check if the data read is bigger than the number of available bits */
				if(tmp_nr_bits>nr_bits_left)
					return 1;

				nr_bits_left -= tmp_nr_bits;
			}

			/* Corrigendum */
			if(nr_bits_left>0) {
				ld.readBits(nr_bits_left);
			}
		}

		return 0;
	}

private int sbr_grid(IBitStream ld, int ch) throws AACException {
		int i, env, rel, result;
		int bs_abs_bord, bs_abs_bord_1;
		int bs_num_env = 0;
		int saved_L_E = this.L_E[ch];
		int saved_L_Q = this.L_Q[ch];
		int saved_frame_class = this.bs_frame_class[ch];

		this.bs_frame_class[ch] = ld.readBits(2);

		switch(this.bs_frame_class[ch]) {
			case FIXFIX:
				i = ld.readBits(2);

				bs_num_env = Math.min(1<<i, 5);

				i = ld.readBit();
				for(env = 0; env<bs_num_env; env++) {
					this.f[ch][env] = i;
				}

				this.abs_bord_lead[ch] = 0;
				this.abs_bord_trail[ch] = this.numTimeSlots;
				this.n_rel_lead[ch] = bs_num_env-1;
				this.n_rel_trail[ch] = 0;
				break;

			case FIXVAR:
				bs_abs_bord = ld.readBits(2)+this.numTimeSlots;
				bs_num_env = ld.readBits(2)+1;

				for(rel = 0; rel<bs_num_env-1; rel++) {
					this.bs_rel_bord[ch][rel] = 2*ld.readBits(2)+2;
				}
				i = sbr_log2(bs_num_env+1);
				this.bs_pointer[ch] = ld.readBits(i);

				for(env = 0; env<bs_num_env; env++) {
					this.f[ch][bs_num_env-env-1] = ld.readBit();
				}

				this.abs_bord_lead[ch] = 0;
				this.abs_bord_trail[ch] = bs_abs_bord;
				this.n_rel_lead[ch] = 0;
				this.n_rel_trail[ch] = bs_num_env-1;
				break;

			case VARFIX:
				bs_abs_bord = ld.readBits(2);
				bs_num_env = ld.readBits(2)+1;

				for(rel = 0; rel<bs_num_env-1; rel++) {
					this.bs_rel_bord[ch][rel] = 2*ld.readBits(2)+2;
				}
				i = sbr_log2(bs_num_env+1);
				this.bs_pointer[ch] = ld.readBits(i);

				for(env = 0; env<bs_num_env; env++) {
					this.f[ch][env] = ld.readBit();
				}

				this.abs_bord_lead[ch] = bs_abs_bord;
				this.abs_bord_trail[ch] = this.numTimeSlots;
				this.n_rel_lead[ch] = bs_num_env-1;
				this.n_rel_trail[ch] = 0;
				break;

			case VARVAR:
				bs_abs_bord = ld.readBits(2);
				bs_abs_bord_1 = ld.readBits(2)+this.numTimeSlots;
				this.bs_num_rel_0[ch] = ld.readBits(2);
				this.bs_num_rel_1[ch] = ld.readBits(2);

				bs_num_env = Math.min(5, this.bs_num_rel_0[ch]+this.bs_num_rel_1[ch]+1);

				for(rel = 0; rel<this.bs_num_rel_0[ch]; rel++) {
					this.bs_rel_bord_0[ch][rel] = 2*ld.readBits(2)+2;
				}
				for(rel = 0; rel<this.bs_num_rel_1[ch]; rel++) {
					this.bs_rel_bord_1[ch][rel] = 2*ld.readBits(2)+2;
				}
				i = sbr_log2(this.bs_num_rel_0[ch]+this.bs_num_rel_1[ch]+2);
				this.bs_pointer[ch] = ld.readBits(i);

				for(env = 0; env<bs_num_env; env++) {
					this.f[ch][env] = ld.readBit();
				}

				this.abs_bord_lead[ch] = bs_abs_bord;
				this.abs_bord_trail[ch] = bs_abs_bord_1;
				this.n_rel_lead[ch] = this.bs_num_rel_0[ch];
				this.n_rel_trail[ch] = this.bs_num_rel_1[ch];
				break;
		}

		if(this.bs_frame_class[ch]==VARVAR)
			this.L_E[ch] = Math.min(bs_num_env, 5);
		else
			this.L_E[ch] = Math.min(bs_num_env, 4);

		if(this.L_E[ch]<=0)
			return 1;

		if(this.L_E[ch]>1)
			this.L_Q[ch] = 2;
		else
			this.L_Q[ch] = 1;

		/* TODO: this code can probably be integrated into the code above! */
		if((result = TFGrid.envelope_time_border_vector(this, ch))>0) {
			this.bs_frame_class[ch] = saved_frame_class;
			this.L_E[ch] = saved_L_E;
			this.L_Q[ch] = saved_L_Q;
			return result;
		}
		TFGrid.noise_floor_time_border_vector(this, ch);

		return 0;
	}

private void sbr_dtdf(IBitStream ld, int ch) throws AACException {
		int i;

		for(i = 0; i<this.L_E[ch]; i++) {
			this.bs_df_env[ch][i] = ld.readBit();
		}

		for(i = 0; i<this.L_Q[ch]; i++) {
			this.bs_df_noise[ch][i] = ld.readBit();
		}
	}

private void invf_mode(IBitStream ld, int ch) throws AACException {
		int n;

		for(n = 0; n<this.N_Q; n++) {
			this.bs_invf_mode[ch][n] = ld.readBits(2);
		}
	}

private void sinusoidal_coding(IBitStream ld, int ch) throws AACException {
		int n;

		for(n = 0; n<this.N_high; n++) {
			this.bs_add_harmonic[ch][n] = ld.readBit();
		}
	}

private void sbr_envelope(IBitStream ld, int ch) throws AACException {
		int env, band;
		int delta = 0;
		int[][] t_huff, f_huff;

		if((this.L_E[ch]==1)&&(this.bs_frame_class[ch]==FIXFIX))
			this.amp_res[ch] = false;
		else
			this.amp_res[ch] = this.bs_amp_res;

		if((this.bs_coupling)&&(ch==1)) {
			delta = 1;
			if(this.amp_res[ch]) {
				t_huff = T_HUFFMAN_ENV_BAL_3_0DB;
				f_huff = F_HUFFMAN_ENV_BAL_3_0DB;
			}
			else {
				t_huff = T_HUFFMAN_ENV_BAL_1_5DB;
				f_huff = F_HUFFMAN_ENV_BAL_1_5DB;
			}
		}
		else {
			delta = 0;
			if(this.amp_res[ch]) {
				t_huff = T_HUFFMAN_ENV_3_0DB;
				f_huff = F_HUFFMAN_ENV_3_0DB;
			}
			else {
				t_huff = T_HUFFMAN_ENV_1_5DB;
				f_huff = F_HUFFMAN_ENV_1_5DB;
			}
		}

		for(env = 0; env<this.L_E[ch]; env++) {
			if(this.bs_df_env[ch][env]==0) {
				if(this.bs_coupling&&(ch==1)) {
					if(this.amp_res[ch]) {
						this.E[ch][0][env] = ld.readBits(5)<<delta;
					}
					else {
						this.E[ch][0][env] = ld.readBits(6)<<delta;
					}
				}
				else {
					if(this.amp_res[ch]) {
						this.E[ch][0][env] = ld.readBits(6)<<delta;
					}
					else {
						this.E[ch][0][env] = ld.readBits(7)<<delta;
					}
				}

				for(band = 1; band<this.n[this.f[ch][env]]; band++) {
					this.E[ch][band][env] = (decodeHuffman(ld, f_huff)<<delta);
				}

			}
			else {
				for(band = 0; band<this.n[this.f[ch][env]]; band++) {
					this.E[ch][band][env] = (decodeHuffman(ld, t_huff)<<delta);
				}
			}
		}

		NoiseEnvelope.extract_envelope_data(this, ch);
	}

private void sbr_noise(IBitStream ld, int ch) throws AACException {
		int noise, band;
		int delta = 0;
		int[][] t_huff, f_huff;

		if(this.bs_coupling&&(ch==1)) {
			delta = 1;
			t_huff = T_HUFFMAN_NOISE_BAL_3_0DB;
			f_huff = F_HUFFMAN_ENV_BAL_3_0DB;
		}
		else {
			delta = 0;
			t_huff = T_HUFFMAN_NOISE_3_0DB;
			f_huff = F_HUFFMAN_ENV_3_0DB;
		}

		for(noise = 0; noise<this.L_Q[ch]; noise++) {
			if(this.bs_df_noise[ch][noise]==0) {
				if(this.bs_coupling&&(ch==1)) {
					this.Q[ch][0][noise] = ld.readBits(5)<<delta;
				}
				else {
					this.Q[ch][0][noise] = ld.readBits(5)<<delta;
				}
				for(band = 1; band<this.N_Q; band++) {
					this.Q[ch][band][noise] = (decodeHuffman(ld, f_huff)<<delta);
				}
			}
			else {
				for(band = 0; band<this.N_Q; band++) {
					this.Q[ch][band][noise] = (decodeHuffman(ld, t_huff)<<delta);
				}
			}
		}

		NoiseEnvelope.extract_noise_floor_data(this, ch);
	}

@Deprecated
    public static int parsePAT(ByteBuffer data) {
        PATSection pat = PATSection.parsePAT(data);
        if (pat.getPrograms().size() > 0)
            return pat.getPrograms().values()[0];
        else
            return -1;
    }

public void addPacket(FLVTag pkt) throws IOException {
        if (!writePacket(writeBuf, pkt)) {
            writeBuf.flip();
            startOfLastPacket -= out.write(writeBuf);
            writeBuf.clear();
            if (!writePacket(writeBuf, pkt))
                throw new RuntimeException("Unexpected");
        }
    }

static public byte[] readEbmlId(SeekableByteChannel source) throws IOException {
        if (source.position() == source.size())
            return null;

        ByteBuffer buffer = ByteBuffer.allocate(8);
        buffer.limit(1);
        source.read(buffer);
        buffer.flip();

        byte firstByte = buffer.get();
        int numBytes = EbmlUtil.computeLength(firstByte);

        if (numBytes == 0)
            return null;

        if (numBytes > 1) {
            buffer.limit(numBytes);
            source.read(buffer);
        }

        buffer.flip();
        ByteBuffer val = ByteBuffer.allocate(buffer.remaining());
        val.put(buffer);
        return val.array();
    }

public boolean repositionFile() throws IOException {
        int payloadSize = 0;
        for (int i = 0; i < REPOSITION_BUFFER_READS; i++) {
            while (readBuf.hasRemaining()) {
                payloadSize = ((payloadSize & 0xffff) << 8) | (readBuf.get() & 0xff);
                int pointerPos = readBuf.position() + 7 + payloadSize;
                if (readBuf.position() >= 8 && pointerPos < readBuf.limit() - 4
                        && readBuf.getInt(pointerPos) - payloadSize == 11) {
                    readBuf.position(readBuf.position() - 8);
                    return true;
                }
            }
            initialRead(ch);
            if (!readBuf.hasRemaining())
                break;
        }
        return false;
    }

private final static void pass1(ShortBuffer data) {
        int z1;
        int tmp2;
        int tmp3;
        int tmp0;
        int tmp1;
        int tmp10;
        int tmp13;
        int tmp11;
        int tmp12;
        int z2;
        int z3;
        int z4;
        int z5;

        ShortBuffer dataptr = data.duplicate();

        for (int rowctr = DCTSIZE - 1; rowctr >= 0; rowctr--) {
            /*
             * Due to quantization, we will usually find that many of the input
             * coefficients are zero, especially the AC terms. We can exploit
             * this by short-circuiting the IDCT calculation for any row in
             * which all the AC terms are zero. In that case each output is
             * equal to the DC coefficient (with scale factor as needed). With
             * typical images and quantization tables, half or more of the row
             * DCT calculations can be simplified this way.
             */

            // register int *idataptr = (int*)dataptr;
            /*
             * WARNING: we do the same permutation as MMX idct to simplify the
             * video core
             */
            int d0 = dataptr.get(0);
            int d2 = dataptr.get(1);
            int d4 = dataptr.get(2);
            int d6 = dataptr.get(3);
            int d1 = dataptr.get(4);
            int d3 = dataptr.get(5);
            int d5 = dataptr.get(6);
            int d7 = dataptr.get(7);

            if ((d1 | d2 | d3 | d4 | d5 | d6 | d7) == 0) {
                /* AC terms all zero */
                if (d0 != 0) {
                    /* Compute a 32 bit value to assign. */
                    int dcval = (int) (d0 << PASS1_BITS);
                    for (int i = 0; i < 8; i++) {
                        dataptr.put(i, (short) dcval);
                    }
                }
                /*
                 * advance pointer to next row
                 */
                dataptr = advance(dataptr, DCTSIZE);
                continue;
            }

            /* Even part: reverse the even part of the forward DCT. */
            /* The rotator is sqrt(2)c(-6). */
            if (d6 != 0) {
                if (d2 != 0) {
                    /* d0 != 0, d2 != 0, d4 != 0, d6 != 0 */
                    z1 = MULTIPLY(d2 + d6, FIX_0_541196100);
                    tmp2 = z1 + MULTIPLY(-d6, FIX_1_847759065);
                    tmp3 = z1 + MULTIPLY(d2, FIX_0_765366865);

                    tmp0 = (d0 + d4) << CONST_BITS;
                    tmp1 = (d0 - d4) << CONST_BITS;

                    tmp10 = tmp0 + tmp3;
                    tmp13 = tmp0 - tmp3;
                    tmp11 = tmp1 + tmp2;
                    tmp12 = tmp1 - tmp2;
                } else {
                    /* d0 != 0, d2 == 0, d4 != 0, d6 != 0 */
                    tmp2 = MULTIPLY(-d6, FIX_1_306562965);
                    tmp3 = MULTIPLY(d6, FIX_0_541196100);

                    tmp0 = (d0 + d4) << CONST_BITS;
                    tmp1 = (d0 - d4) << CONST_BITS;

                    tmp10 = tmp0 + tmp3;
                    tmp13 = tmp0 - tmp3;
                    tmp11 = tmp1 + tmp2;
                    tmp12 = tmp1 - tmp2;
                }
            } else {
                if (d2 != 0) {
                    /* d0 != 0, d2 != 0, d4 != 0, d6 == 0 */
                    tmp2 = MULTIPLY(d2, FIX_0_541196100);
                    tmp3 = MULTIPLY(d2, FIX_1_306562965);

                    tmp0 = (d0 + d4) << CONST_BITS;
                    tmp1 = (d0 - d4) << CONST_BITS;

                    tmp10 = tmp0 + tmp3;
                    tmp13 = tmp0 - tmp3;
                    tmp11 = tmp1 + tmp2;
                    tmp12 = tmp1 - tmp2;
                } else {
                    /* d0 != 0, d2 == 0, d4 != 0, d6 == 0 */
                    tmp10 = tmp13 = (d0 + d4) << CONST_BITS;
                    tmp11 = tmp12 = (d0 - d4) << CONST_BITS;
                }
            }

            /*
             * Odd part per figure 8; the matrix is unitary and hence its
             * transpose is its inverse. i0..i3 are y7,y5,y3,y1 respectively.
             */

            if (d7 != 0) {
                if (d5 != 0) {
                    if (d3 != 0) {
                        if (d1 != 0) {
                            /* d1 != 0, d3 != 0, d5 != 0, d7 != 0 */
                            z1 = d7 + d1;
                            z2 = d5 + d3;
                            z3 = d7 + d3;
                            z4 = d5 + d1;
                            z5 = MULTIPLY(z3 + z4, FIX_1_175875602);

                            tmp0 = MULTIPLY(d7, FIX_0_298631336);
                            tmp1 = MULTIPLY(d5, FIX_2_053119869);
                            tmp2 = MULTIPLY(d3, FIX_3_072711026);
                            tmp3 = MULTIPLY(d1, FIX_1_501321110);
                            z1 = MULTIPLY(-z1, FIX_0_899976223);
                            z2 = MULTIPLY(-z2, FIX_2_562915447);
