public static MediaPictureConverter createConverter(
    String converterDescriptor,
    PixelFormat.Type pictureType, 
    int pictureWidth, int pictureHeight,
    int imageWidth, int imageHeight)
  {
    MediaPictureConverter converter = null;

    // establish the converter type

    Type converterType = findRegisteredConverter(converterDescriptor);
    if (null == converterType)
      throw new UnsupportedOperationException(
        "No converter \"" + converterDescriptor + "\" found.");

    // create the converter

    try
    {
      // establish the constructor 

      Constructor<? extends MediaPictureConverter> converterConstructor = 
        converterType.getConverterClass().getConstructor(PixelFormat.Type.class,
          int.class, int.class, int.class, int.class);

      // create the converter

      converter = converterConstructor.newInstance(
        pictureType, pictureWidth, pictureHeight, imageWidth, imageHeight);
    }
    catch (NoSuchMethodException e)
    {
      throw new UnsupportedOperationException(
        "Converter " + converterType.getConverterClass() + 
        " requries a constructor of the form "  +
        "(PixelFormat.Type, int, int, int, int)");
    }
    catch (InvocationTargetException e)
    {
      Throwable cause = e.getCause();
      if (cause != null && cause instanceof OutOfMemoryError)
      {
        throw (OutOfMemoryError)cause;
      }
      else
      {
        throw new UnsupportedOperationException(
            "Converter " + converterType.getConverterClass() + 
            " constructor failed with: " + e.getCause());
      }
    }
    catch (IllegalAccessException e)
    {
      Throwable cause = e.getCause();
      if (cause != null && cause instanceof OutOfMemoryError)
      {
        throw (OutOfMemoryError)cause;
      }
      else
      {
        throw new UnsupportedOperationException(
            "Converter " + converterType.getConverterClass() + 
            " constructor failed with: " + e.getCause());
      }
    }
    catch (InstantiationException e)
    {
      Throwable cause = e.getCause();
      if (cause != null && cause instanceof OutOfMemoryError)
      {
        throw (OutOfMemoryError)cause;
      }
      else
      {
        throw new UnsupportedOperationException(
            "Converter " + converterType.getConverterClass() + 
            " constructor failed with: " + e.getCause());
      }
    }

    // return the newly created converter

    return converter;
  }

public static BufferedImage convertToType(BufferedImage sourceImage, 
    int targetType)
  {
    BufferedImage image;

    // if the source image is already the target type, return the source image

    if (sourceImage.getType() == targetType)
      image = sourceImage;

    // otherwise create a new image of the target type and draw the new
    // image 

    else
    {
      image = new BufferedImage(sourceImage.getWidth(), sourceImage.getHeight(),
        targetType);
      image.getGraphics().drawImage(sourceImage, 0, 0, null);
    }

    return image;
  }

boolean packChute() throws OutOfMemoryError
  {
    if (mPayload != null)
      return true;

    // otherwise the payload is null
    synchronized(this)
    {
      if (mPayload != null)
        return true;
      try {
        //System.out.println("Packing the parachute! this=" + this);
        mPayload = new byte[PAYLOAD_BYTES];
        mPayload[0] = 'P';
        mPayload[1] = 'A';
        mPayload[2] = 'R';
        mPayload[3] = 'A';
        mPayload[4] = 'C';
        mPayload[5] = 'H';
        mPayload[6] = 'U';
        mPayload[7] = 'T';
        mPayload[8] = 'E';
        mPayload[9] = '!';
        return true;
      } catch (OutOfMemoryError e) {
        // we failed to create the parachute.  Also known as bad.
        // forward it on.
        throw e;
      }
    }
  }

public int close()
  {
    int retval = 0;
    try
    {
      if (mOpenStream != null && mCloseStreamOnClose)
      {
        mOpenStream.close();
      }
    }
    catch (IOException e)
    {
      log.error("could not close stream {}: {}", mOpenStream, e);
      retval = -1;
    }
    mOpenStream = null;
    return retval;
  }

public int open(String url, int flags)
  {
    if (mOpenStream != null)
    {
      log.debug("attempting to open already open handler: {}",
          mOpenStream);
      return -1;
    }
    switch (flags)
    {
      case URL_RDWR:
        log.debug("do not support read/write mode for Java IO Handlers");
        return -1;
      case URL_WRONLY_MODE:
        mOpenStream = mWriteChannel;
        if (mOpenStream == null)
        {
          log.error("No OutputStream specified for writing: {}",url);
          return -1;
        }
        break;
      case URL_RDONLY_MODE:
        mOpenStream = mReadChannel;
        if (mOpenStream == null)
        {
          log.error("No InputStream specified for reading: {}", url);
          return -1;
        }
        break;
      default:
        log.error("Invalid flag passed to open: {}", url);
        return -1;
    }

    return 0;
  }

public int read(byte[] buf, int size)
  {
    int ret = -1;
    if (mOpenStream == null || !(mOpenStream instanceof ReadableByteChannel))
      return -1;

    try
    {
      ReadableByteChannel channel = (ReadableByteChannel) mOpenStream;
      ByteBuffer buffer = ByteBuffer.allocate(size);
      ret = channel.read(buffer);
      if (ret > 0) {
        buffer.flip();
        buffer.get(buf, 0, ret);
      }
      return ret;
    }
    catch (IOException e)
    {
      log.error("Got IO exception reading from channel: {}; {}",
          mOpenStream, e);
      return -1;
    }
  }

public int write(byte[] buf, int size)
  {
    if (mOpenStream == null ||
        !(mOpenStream instanceof WritableByteChannel))
      return -1;

    try
    {
      WritableByteChannel channel = (WritableByteChannel) mOpenStream;
      ByteBuffer buffer = ByteBuffer.allocate(size);
      buffer.put(buf, 0, size);
      buffer.flip();
      return channel.write(buffer);
    }
    catch (IOException e)
    {
      log.error("Got error writing to file: {}; {}", mOpenStream, e);
      return -1;
    }
  }

