            this.t = t;
        } finally {
            lock.writeLock().unlock();
        }
    }

public void setIfFirst(Throwable t) {
        try {
            lock.writeLock().lock();

            if (this.t == null)
                this.t = t;
        } finally {
            lock.writeLock().unlock();
        }
    }

public static double normalize(double val, double min, double max) {
        if (max < min)
