public static String msg(Path path, String msg) {
		StringBuilder bld = new StringBuilder();
		bld.append("\t.");
		bld.append(path.toPathString());
		
		if (bld.length() < PATH_PADDING)
			while (bld.length() < PATH_PADDING)
				bld.append(' ');
		else
			bld.append('\t');

		bld.append(msg);
		
		return bld.toString();
	}

