        }

        int sectionIndex = 0;

        Enumeration e = sectionNames.elements();

        boolean done = false;
        while(!done && e.hasMoreElements()) {
            String thisName = (String) e.nextElement();
            if(sectionName.equalsIgnoreCase(thisName))
                done = true;
            else
                sectionIndex++;
        }

        if(!done)
