    /* if (name != null) {
      sbuff.append(" names= ");
      for (int ii = 0; ii < rank; ii++) {
        sbuff.append(name[ii]);
        sbuff.append(" ");
      }
    } */

    sbuff.append(" offset= ").append(offset);
    sbuff.append(" rank= ").append(rank);
