    hasNext()
    {
        if(this.current >= odomset.size())
            return false;
        Odometer ocurrent = odomset.get(this.current);
        if(ocurrent.hasNext())
            return true;
        // Try to move to next odometer
        this.current++;
        return hasNext();
    }

