static DataType setDataType(short type, Variable v) {
    DataType dt;
    switch (type) {
      case 3:
        dt = DataType.UBYTE;
        break;
      case 4:
        dt =  DataType.CHAR;
        break;
      case 5:
        dt =  DataType.FLOAT;
        break;
      case 6:
        dt =  DataType.DOUBLE;
        break;
      case 20:
        dt =  DataType.BYTE;
        break;
      case 21:
        dt =  DataType.UBYTE;
        break;
      case 22:
        dt =  DataType.SHORT;
        break;
      case 23:
        dt =  DataType.USHORT;
        break;
      case 24:
        dt =  DataType.INT;
        break;
      case 25:
        dt =  DataType.UINT;
        break;
      case 26:
        dt =  DataType.LONG;
        break;
      case 27:
        dt =  DataType.ULONG;
        break;
      default:
        throw new IllegalStateException("unknown type= " + type);
    }

    if (v != null) {
      v.setDataType(dt);
    }

    return dt;
  }

