            for(int i = 0; i < n; i++) {
                ReqState rs = (ReqState) prArr.get(i);
                RequestDebug reqD = (RequestDebug) rs.getUserObject();
                if(!reqD.done) {
                    preqs.append("<pre>-----------------------\n");
                    preqs.append("Request[");
