public String getProjName(int type) {
    String projName;
    switch (type) {

      case PSEUDO_MERCATOR:
      case PSEUDO_MERCATOR_GENERAL:
        projName = "MERC";
        break;

      case PS_OR_LAMBERT_CONIC:
        projName = (vals[38] == vals[39])
                ? "PS"
                : "CONF";
        break;

      case EQUIDISTANT:
        projName = "EQUI";
        break;

      case LAMBERT_CONFORMAL_TANGENT:
        projName = "CONF";
        break;

      default:
        projName = "NAV" + type;
    }
    return projName;

  }

