        return new MultipleQueryEmulator(this.getRawIndexName()) {
            @Override
            protected JSONObject singleQuery(@NonNull Query query) throws AlgoliaException {
                return _searchOffline(query);
            }
        }.multipleQueries(queries, strategy);
    }

