        final Enumeration enum1 = contexts.keys();
        final Enumeration enum2 = proxyServerUrls.keys();

        Enumeration e = new Enumeration() {
            public boolean hasMoreElements() {
                return enum1.hasMoreElements() || enum2.hasMoreElements();
