public IContext createContext() {
        IContext context = WebDAVFactory.contextFactory.newContext();
        // Need to make sure the USER-AGENT header is present for Guvnor
        context.put("USER-AGENT", "guvnor"); //$NON-NLS-1$ //$NON-NLS-2$
