private int pruneToDo() {
		int size = 0;
		Iterator<IndexedClassEntity> itr = toDoEntities_.iterator();
		while (itr.hasNext()) {
			IndexedClassEntity next = itr.next();
			if (!next.occurs()) {
				itr.remove();
				continue;
			}
			// else
			Context context = saturationState_.getContext(next);
			if (context != null && context.isSaturated()) {
				itr.remove();
			} else {
				size++;
			}
		}
		return size;
	}

public Proof<? extends EntailmentInference> getEvidence(
			final boolean atMostOne) {

		return new Proof<EntailmentInference>() {

			@SuppressWarnings("unchecked")
			@Override
			public Collection<OntologyInconsistencyEntailmentInference> getInferences(
					final Object conclusion) {

				if (!OntologyInconsistencyImpl.INSTANCE.equals(conclusion)) {
					return Collections.emptyList();
				}
				// else

				final Collection<? extends IndexedIndividual> inconsistentIndividuals = getInconsistentIndividuals();
				Iterable<OntologyInconsistencyEntailmentInference> result = Operations
						.map(inconsistentIndividuals,
								INDIVIDUAL_TO_ENTAILMENT_INFERENCE);
				int size = inconsistentIndividuals.size();

				if (isTopObjectPropertyInBottom_) {
					result = Operations.concat(Operations
							.<OntologyInconsistencyEntailmentInference> singleton(
									new TopObjectPropertyInBottomEntailsOntologyInconsistencyImpl(
											conclusionFactory_
													.getSubPropertyChain(
															topProperty_,
															bottomProperty_))),
							result);
					size++;
				}

				if (isOwlThingInconsistent_) {
					result = Operations.concat(Operations
							.<OntologyInconsistencyEntailmentInference> singleton(
									new OwlThingInconsistencyEntailsOntologyInconsistencyImpl(
											conclusionFactory_.getContradiction(
													owlThing_))),
							result);
					size++;
				}

				if (atMostOne) {
					final Iterator<OntologyInconsistencyEntailmentInference> iter = result
							.iterator();
					if (!iter.hasNext()) {
						return Collections.emptyList();
					}
					// else
					return Collections.singleton(iter.next());
				}
				// else

				return Operations.getCollection(result, size);
			}

		};

	}

void registerQueries(final Iterable<? extends ElkAxiom> axioms) {

		lastQueries_.clear();
		for (final ElkAxiom axiom : axioms) {

			LOGGER_.trace("entailment query registered {}", axiom);

			lastQueries_.add(axiom);

			QueryState state = queried_.get(axiom);
			if (state != null) {
				queriedEvictor_.add(state);
				continue;
			}
			// Create query state.
			state = new QueryState(axiom);
			queried_.put(axiom, state);
			queriedEvictor_.add(state);
			toLoad_.offer(axiom);

		}

	}

Map<ElkAxiom, EntailmentQueryResult> isEntailed(
			final Iterable<? extends ElkAxiom> axioms)
			throws ElkQueryException {

		final Map<ElkAxiom, EntailmentQueryResult> results = new ArrayHashMap<ElkAxiom, EntailmentQueryResult>();

		for (final ElkAxiom axiom : axioms) {
			if (!EntailmentQueryConverter
					.isEntailmentCheckingSupported(axiom.getClass())) {
				results.put(axiom,
						new UnsupportedQueryTypeEntailmentQueryResultImpl(
								axiom));
				continue;
			}
			// else
			final QueryState state = queried_.get(axiom);
			if (state == null) {
				throw new ElkQueryException(
						"Query was not registered: " + axiom);
			}
			// else
			if (state.indexed == null) {
				results.put(axiom,
						new UnsupportedIndexingEntailmentQueryResultImpl(
								axiom));
				continue;
			}
			// else
			state.lock();
			results.put(axiom, state);
		}

		return results;
	}

@Override
	public boolean preExecute() {
		if (isInitialized_)
			return false;
		LOGGER_.trace("{}: initialized", this);
		this.workerNo = reasoner.getNumberOfWorkers();
		return isInitialized_ = true;
	}

@Override
	public boolean postExecute() {
		if (!isInitialized_)
			return false;
		LOGGER_.trace("{}: done", this);
		this.isCompleted_ = true;
		this.workerNo = 0;
		this.isInitialized_ = false;		
		return true;
	}

boolean invalidate() {
		if (!isCompleted_ && !isInitialized_) {
			return false;
		}
		LOGGER_.trace("{}: invalidated", this);
		isCompleted_ = false;
		isInitialized_ = false;
		return true;
	}

public void invalidateRecursive() {
		Queue<AbstractReasonerStage> toInvalidate_ = new LinkedList<AbstractReasonerStage>();
		toInvalidate_.add(this);
		AbstractReasonerStage next;
		while ((next = toInvalidate_.poll()) != null) {
			if (next.invalidate()) {
				for (AbstractReasonerStage postStage : next.postStages_) {
					toInvalidate_.add(postStage);
				}
			}
		}
	}

@Override
	public int hash(Node<? extends ElkEntity> node) {
		if (node.size() >= cacheNodeMemberNo) {
			if (hashCache.containsKey(node)) {
				return hashCache.get(node);
			}
			// else
			int hash = HashGenerator.combineMultisetHash(true, node,
					elkEntityHasher);
			hashCache.put(node, hash);
			return hash;
		}
		// else
		return HashGenerator.combineMultisetHash(true, node, elkEntityHasher);
	}

private int pruneToAdd() {
		final Iterator<IndexedIndividual> iter = toAdd_.iterator();
		int size = 0;
		while (iter.hasNext()) {
			final IndexedIndividual ind = iter.next();
			/* @formatter:off
			 * 
			 * Should be pruned when:
			 * it is not in ontology, or
			 * it has types in taxonomy.
			 * 
			 * @formatter:on
			 */
			if (!ind.occurs()) {
				iter.remove();
				continue;
			}
			// else
			final Context context = saturationState_.getContext(ind);
			if (context == null || !context.isInitialized()
					|| !context.isSaturated()) {
				// it is not saturated.
				size++;
				continue;
			}
			// else
			final InstanceNode<ElkClass, ElkNamedIndividual> node = taxonomy_
					.getInstanceNode(ind.getElkEntity());
			if (node == null) {
				// it is not in taxonomy
				size++;
				continue;
			}
			// else
			if (!node.getDirectTypeNodes().isEmpty()) {
				iter.remove();
				continue;
			}
			// else
			size++;
		}
		return size;
	}

Collection<IndexedIndividual> getToAdd() {
		if (taxonomy_ == null) {
			// No individual can be pruned.
			return toAdd_;
		}
		// else
		final int size = pruneToAdd();
		/*
		 * since getting the size of the queue is a linear operation, use the
		 * computed size
		 */
		return Operations.getCollection(toAdd_, size);
	}

private int pruneToRemove() {
		final Iterator<IndexedIndividual> iter = toRemove_.iterator();
		int size = 0;
		while (iter.hasNext()) {
			final IndexedIndividual cls = iter.next();
			/* @formatter:off
			 * 
			 * Should be pruned when
			 * it is not in taxonomy.
			 * 
			 * @formatter:on
			 */
			final InstanceNode<ElkClass, ElkNamedIndividual> node = taxonomy_
					.getInstanceNode(cls.getElkEntity());
			if (node == null) {
				iter.remove();
				continue;
			}
			// else
			size++;
		}
		return size;
	}

Collection<IndexedIndividual> getToRemove() {
		if (taxonomy_ == null) {// TODO: Never set taxonomy_ to null !!!
			// no individuals are in taxonomy
			toRemove_.clear();
			return Collections.emptyList();
		}
		// else
		final int size = pruneToRemove();
		/*
		 * since getting the size of the queue is a linear operation, use the
		 * computed size
		 */
		return Operations.getCollection(toRemove_, size);
	}

