static ProofNode<OWLAxiom> canConvertStep(ProofStep<OWLAxiom> step) {
		if (step.getName() != ElkClassInclusionExistentialComposition.NAME) {
			return null;
		}
		List<? extends ProofNode<OWLAxiom>> premises = step.getPremises();
		ProofNode<OWLAxiom> lastPremise = premises.get(premises.size() - 1);
		Collection<? extends ProofStep<OWLAxiom>> lastPremiseSteps = lastPremise
				.getInferences();
		if (lastPremiseSteps.size() != 1) {
			return null;
		}
		// else
		for (ProofStep<OWLAxiom> lastPremiseStep : lastPremiseSteps) {
			if (lastPremiseStep
					.getName() == ElkPropertyInclusionOfTransitiveObjectProperty.NAME) {
				return lastPremiseStep.getPremises().get(0);
			}
		}
		// else
		return null;
	}

private int pruneToAdd() {
		final Iterator<IndexedClass> iter = toAdd_.iterator();
		int size = 0;
		while (iter.hasNext()) {
			final IndexedClass cls = iter.next();
			/* @formatter:off
			 * 
			 * Should be pruned when:
			 * it is not in ontology, or
			 * it is in the top node, or
			 * it has super-nodes in taxonomy.
			 * 
			 * @formatter:on
			 */
			if (!cls.occurs()) {
				iter.remove();
				continue;
			}
			// else
			final Context context = saturationState_.getContext(cls);
			if (context == null || !context.isInitialized()
					|| !context.isSaturated()) {
				// it is not saturated.
				size++;
				continue;
			}
			// else
			final TaxonomyNode<ElkClass> node = taxonomy_
					.getNode(cls.getElkEntity());
			if (node == null) {
				// it is not in taxonomy
				size++;
				continue;
			}
			// else
			if (node.equals(taxonomy_.getTopNode())) {
				iter.remove();
				continue;
			}
			// else
			if (!node.getDirectSuperNodes().isEmpty()) {
				iter.remove();
				continue;
			}
			// else
			size++;
		}
		return size;
	}

private int pruneToRemove() {
		final Iterator<IndexedClass> iter = toRemove_.iterator();
		int size = 0;
		while (iter.hasNext()) {
			final IndexedClass cls = iter.next();
			/* @formatter:off
			 * 
			 * Should be pruned when
			 * it is not in taxonomy, or
			 * it is in the bottom class.
			 * 
			 * @formatter:on
			 */
			final TaxonomyNode<ElkClass> node = taxonomy_
					.getNode(cls.getElkEntity());
			if (node == null) {
				iter.remove();
				continue;
			}
			// else
			if (cls == ontologyIndex_.getOwlNothing()) {
				iter.remove();
				continue;
			}
			size++;
		}
		return size;
	}

