		try {
			ArrayList<ServiceID> retval = new ArrayList<ServiceID>();
			for (ServiceID serviceID : componentRepositoryImpl.getServiceIDs()) {
				ServiceComponent service = componentRepositoryImpl
						.getComponentByID(serviceID);
				if (service == null) {
