		if (alarmIDs == null) {
			throw new NullPointerException("AlarmID[] must not be null");
		}

		Set<Alarm> alarms = new HashSet<Alarm>();

		try {
			for (String id : alarmIDs) {
				Alarm a = getDescriptor(id);
				if (a != null)
					alarms.add(a);
