private StatementHolder getCachedStatement(Method method, Object[] args) throws SQLException {
        if (statementCache != null) {
            return statementCache.take(new StatementMethod(getTarget(), this, method, args));
        }

        return getUncachedStatement(method, args, (String) args[0]);
    }

@Override
    public PreparedStatement newStatement(Method method, Object[] args) throws SQLException {
        String methodName = method.getName();
        if (methodName != "prepareStatement" && methodName != "prepareCall") {
            throw new ViburDBCPException("Unexpected method passed to newStatement() " + method);
        }
        return (PreparedStatement) targetInvoke(method, args);
    }

@Override
    public Object on(Statement proxy, Method method, Object[] args, String sqlQuery, List<Object[]> sqlQueryParams,
                     StatementProceedingPoint proceed) throws SQLException {

        if (++hookIdx < executionHooks.length) { // invoke the next statement execution hook, if any
            return executionHooks[hookIdx].on(proxy, method, args, sqlQuery, sqlQueryParams, this);
        }

        return doProcessExecute(proxy, method, args);
    }

Object unrestrictedInvoke(T proxy, Method method, Object[] args) throws SQLException {
        String methodName = method.getName();

        if (methodName == "equals") { // comparing with == as the Method names are interned Strings
            return proxy == args[0];
        }
        if (methodName == "hashCode") {
            return System.identityHashCode(proxy);
        }
        if (methodName == "toString") {
            return "Vibur proxy for: " + target;
        }
        // getClass(), notify(), notifyAll(), and wait() method calls are not intercepted by the dynamic proxies

        if (methodName == "unwrap") {
            @SuppressWarnings("unchecked")
            Class<T> iface = (Class<T>) args[0];
            return unwrap(iface);
        }
        if (methodName == "isWrapperFor") {
            return isWrapperFor((Class<?>) args[0]);
        }

        return NO_RESULT;
    }

Object restrictedInvoke(T proxy, Method method, Object[] args) throws SQLException {
        return targetInvoke(method, args);
    }

