private String evaluateRedirectUri(ActionRequest req) {

        // Default response -- specify a relative URI, allowing the protocol to be inferred
        String rslt = req.getContextPath() + SUCCESS_PATH;

        final PortletPreferences prefs = req.getPreferences();
        final String protocol = prefs.getValue(INVOKE_REDIRECT_PROTOCOL_PREFERENCE, null);
        if (protocol != null) {
            // Specify an absolute URI.  Apparently we need to insist on a protoco (usually HTTPS)
            String portPart = "";  // default
            final String port = prefs.getValue(INVOKE_REDIRECT_PORT_PREFERENCE, null);
            if (port != null) {
                portPart = ":" + port;
            }
            rslt = protocol.toLowerCase() + "://"
                    + req.getServerName()   // Server hostname
                    + portPart              // Server port (blank, with any luck)
                    + rslt;                 // Remainder of the URI (as above)
        }

        return rslt;

    }

@Override
    public void invoke(final ActionRequest req, final ActionResponse res) throws IOException {
        final NotificationEntry entry = getTarget();
        final String notificationId = entry.getId();
        final Set<String> readNotices = this.getReadNotices(req);
        if (readNotices.contains(notificationId)) {
            readNotices.remove(notificationId);
        } else {
            readNotices.add(notificationId);
        }
        setReadNotices(req, readNotices);
    }

Set<String> getReadNotices(final PortletRequest req) {
        final HashSet<String> rslt = new HashSet<>();
        final PortletPreferences prefs = req.getPreferences();
        final String[] ids = prefs.getValues(READ_NOTIFICATION_IDS_PREFERENCE, new String[0]);
        for (int i=0; i < ids.length; i++) {
            rslt.add(ids[i]);
        }
        return rslt;
    }

@Override
    public void invoke(final ActionRequest req, final ActionResponse res) throws IOException {
        JpaNotificationService jpaService = (JpaNotificationService) SpringContext.getApplicationContext().getBean("jpaNotificationService");

        final NotificationEntry entry = getTarget();
        Map<NotificationState, Date> stateMap = entry.getStates();
        if (stateMap != null && !stateMap.containsKey(NotificationState.COMPLETED)) {
            jpaService.addEntryState(req, entry.getId(), NotificationState.COMPLETED);
        }

        res.sendRedirect(entry.getUrl());
    }

private NotificationResponse fetchFromClasspath(List<String> locations) {

        if (locations.isEmpty()) {
            return NotificationResponse.EMPTY_RESPONSE;
        }

        NotificationResponse rslt;

        final Element m = cache.get(locations);
        if (m != null) {
            // ## CACHE HIT ##
            rslt = (NotificationResponse) m.getObjectValue();
            logger.debug("Locations cache HIT for collection {};  size={}", locations, rslt.size());
        } else {
            // ## CACHE MISS ##
            rslt = new NotificationResponse();
            for (String loc : locations) {
                final NotificationResponse response = readFromFile(loc);
                rslt = rslt.combine(response);
            }
            logger.debug("Locations cache MISS for collection {};  size={}", locations, rslt.size());
            cache.put(new Element(locations, rslt));
        }

        return rslt;

    }

private NotificationResponse readFromFile(String filename) {

        NotificationResponse rslt;

        logger.debug("Preparing to read from file:  {}", filename);

        URL location = getClass().getClassLoader().getResource(filename);
        if (location != null) {
            try {
                File f = new File(location.toURI());
                rslt =  mapper.readValue(f, NotificationResponse.class);
            } catch (Exception e) {
                String msg = "Failed to read the data file:  " + location;
                logger.error(msg, e);
                rslt = prepareErrorResponse(getName(), msg);
            }
        } else {
            String msg = "Data file not found:  " + filename;
            rslt = prepareErrorResponse(getName(), msg);
        }

        return rslt;

    }

private NotificationResponse getResponseFromService(PortletRequest req, INotificationService service) {
        NotificationResponse rslt;
        try {
            rslt = service.fetch(req);
        } catch (Exception e) {
            final String msg = "Failed to invoke the specified service:  " + service.getName();
            logger.error(msg, e);
            rslt = prepareErrorResponse(getName(), msg);
        }
        return rslt;
    }

@Override
    public String lookupPersonId(PortletRequest request) {
        String studentId = getSchoolId(request);
        if (StringUtils.isBlank(studentId)) {
            return null;
        }

        Element element = cache.get(studentId);
        if (element != null) {
            return (String)element.getObjectValue();
        }

        String url = getPersonSearchURL();
        SSPApiRequest sspReq = new SSPApiRequest(url, String.class)
                .addUriParameter("schoolId", studentId);

        try {
            ResponseEntity<String> response = sspApi.doRequest(sspReq);
            String userId = extractUserId(studentId, response);

            Element cacheElement = new Element(studentId, userId);
            cache.put(cacheElement);

            return userId;

        } catch (Exception e) {
            log.error(e.getMessage(), e);
            return null;
        }
    }

private String getSchoolId(PortletRequest request) {
        PortletPreferences prefs = request.getPreferences();
        String schoolIdAttributeName = prefs.getValue("SSPTaskNotificationService.schoolIdAttribute", "schoolId");

        Map<String, String> userInfo = (Map<String, String>)request.getAttribute(PortletRequest.USER_INFO);
        String studentId = userInfo.get(schoolIdAttributeName);
        if (!StringUtils.isEmpty(studentId)) {
            return studentId;
        }

        // if not found, fall back to username.
        studentId = userInfo.get(USERNAME_ATTRIBUTE);

        return studentId;
    }

private String extractUserId(String studentId, ResponseEntity<String> response) {
        Configuration config = Configuration.builder().options(
                Option.DEFAULT_PATH_LEAF_TO_NULL
        ).build();
        ReadContext readContext = JsonPath
                .using(config)
                .parse(response.getBody());

        String success = readContext.read(SUCCESS_QUERY);
        // SSP passes this as a string...
        if (!"true".equalsIgnoreCase(success)) {
            return null;
        }

        int count = readContext.read(RESULTS_QUERY, Integer.class);
        if (count != 1) {
            // couldn't find a single unique result.  Bail now...
            log.warn("Expected a single unique result for " + studentId + ".  Found " + count);
            return null;
        }

        String id = readContext.read(STUDENT_ID_QUERY);
        return id;
    }

