@Path("refresh")
    @GET
    @UnitOfWork
    public Response refreshServices(@RobeAuth Credentials credentials) {


        GuiceConfiguration configuration = GuiceBundle.getConfiguration();

        Reflections reflections = new Reflections(configuration.getScanPackages(), this.getClass().getClassLoader());
        Set<Class<?>> services = reflections.getTypesAnnotatedWith(Path.class);
        int count = 0;
        for (Class service : services) {
            String parentPath = "/" + ((Path) service.getAnnotation(Path.class)).value();
            for (Method method : service.getMethods()) {
                String httpMethod = ifServiceGetHttpMethod(method);
                if (httpMethod == null) {
                    continue;
                }
                String path = parentPath;
                path = extractPath(method, path);

                io.robe.admin.hibernate.entity.Service entity = serviceDao.findByPathAndMethod(path, ServiceEntry.Method.valueOf(httpMethod));
                RobeService robeService = (RobeService) method.getAnnotation(RobeService.class);

                if (entity != null) {
                    if (robeService != null) {
                        entity.setDescription(robeService.description());
                        entity.setGroup(robeService.group());
                        serviceDao.update(entity);
                    }
                    continue;
                }
                entity = new io.robe.admin.hibernate.entity.Service();
                entity.setPath(path);
                entity.setMethod(io.robe.admin.hibernate.entity.Service.Method.valueOf(httpMethod));
                if (robeService != null) {
                    entity.setDescription(robeService.description());
                    entity.setGroup(robeService.group());
                } else {
                    entity.setGroup("UNGROUPED");
                    entity.setDescription("");

                }
                entity.setDescription(entity.getDescription() + " (" + entity.getMethod() + " " + entity.getPath() + ")");
                serviceDao.create(entity);
                count++;

            }
        }
        return Response.ok(count).build();
    }

@Override
    public Response toResponse(Exception e) {

        String id = System.nanoTime() + "";
        LOGGER.error(id, e);

        if (e instanceof RobeRuntimeException) {
            return ((RobeRuntimeException) e).getResponse(id);
        } else if (e instanceof ConstraintViolationException) {
            ConstraintViolationException exception = (ConstraintViolationException) e;
            RobeMessage[] errors = new RobeMessage[exception.getConstraintViolations().size()];
            int i = 0;
            for (ConstraintViolation error : exception.getConstraintViolations()) {
                errors[i++] = new RobeMessage.Builder().message(error.getMessage()).status(422).id(id).build();
            }
            return Response.status(422).entity(errors).type(MediaType.APPLICATION_JSON).build();
        } else if (e instanceof WebApplicationException) {
            WebApplicationException we = (WebApplicationException) e;
            RobeMessage error = new RobeMessage.Builder().id(id).message(we.getMessage()).status(we.getResponse().getStatus()).build();
            return Response.fromResponse(we.getResponse()).entity(error).type(MediaType.APPLICATION_JSON).build();
        } else {
            if (e.getClass().getName().equals("org.hibernate.exception.ConstraintViolationException")) {
                if (e.getCause() != null && e.getCause().getMessage() != null) {
                    RobeMessage error = new RobeMessage.Builder().message(e.getCause().getMessage().split("for")[0]).status(Response.Status.CONFLICT.getStatusCode()).id(id).build();
                    return Response.status(Response.Status.CONFLICT).entity(error).type(MediaType.APPLICATION_JSON).build();
                }
            }
            RobeMessage error = new RobeMessage.Builder().message(e.getMessage()).id(id).build();
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity(error).type(MediaType.APPLICATION_JSON).build();
        }
    }

