        case VALUE_NUMBER_FLOAT:
        case VALUE_NUMBER_INT:
            return context.getJsonParser().getNumberValue();
        case VALUE_FALSE:
            return Boolean.FALSE;
        case VALUE_TRUE:
            return Boolean.TRUE;
        case VALUE_NULL:
            return null;
        default:
            throw new RuntimeException("We expected a VALUE token but got: " + token);
        }
