        if ( result == null )
        {
            throw new IllegalStateException ( String.format ( "Stream '%s' not closed or was not added", fileName ) );
        }

        return result;
    }

private static void validateChannelName ( final String name, final ValidationContext ctx )
    {
        if ( name == null || name.isEmpty () )
        {
            return;
