private void insertMetricsInBatch(Collection<IMetric> metrics) throws IOException {

        BatchStatement batch = new BatchStatement(BatchStatement.Type.UNLOGGED);

        for (IMetric metric : metrics) {
            BoundStatement bound = simpleNumberIO.getBoundStatementForMetric(metric);
            batch.add(bound);
            Instrumentation.markFullResMetricWritten();

            Locator locator = metric.getLocator();
            if( !LocatorCache.getInstance().isLocatorCurrentInBatchLayer(locator) ) {
                LocatorCache.getInstance().setLocatorCurrentInBatchLayer(locator);
                batch.add(locatorIO.getBoundStatementForLocator( locator ));
            }

            // if we are recording delayed metrics, we may need to do an
            // extra insert
            if ( isRecordingDelayedMetrics ) {
                BoundStatement bs = getBoundStatementForMetricIfDelayed(metric);
                if ( bs != null ) {
                    batch.add(bs);
                }
            }
        }
        LOG.trace(String.format("insert batch statement size=%d", batch.size()));

        try {
            DatastaxIO.getSession().execute(batch);
        } catch ( Exception ex ) {
            Instrumentation.markWriteError();
            LOG.error(String.format("error writing batch of %d metrics", batch.size()), ex );
        }
    }

public Emitter on(String event, Listener fn) {
        ConcurrentLinkedQueue<Listener> callbacks = this.callbacks.get(event);
        if (callbacks == null) {
            callbacks = new ConcurrentLinkedQueue<Listener>();
            ConcurrentLinkedQueue<Listener> _callbacks = this.callbacks.putIfAbsent(event, callbacks);
            if (_callbacks != null) {
                callbacks = _callbacks;
            }
        }
        callbacks.add(fn);
        return this;
    }

public Emitter once(final String event, final Listener<T> fn) {
        Listener on = new Listener<T>() {
            @Override
            public void call(T... args) {
                Emitter.this.off(event, this);
                fn.call(args);
            }
        };

        this.onceCallbacks.put(fn, on);
        this.on(event, on);
        return this;
    }

public Emitter off(String event) {
        ConcurrentLinkedQueue<Listener> callbacks = this.callbacks.remove(event);
        if (callbacks != null) {
            for (Listener fn : callbacks) {
                this.onceCallbacks.remove(fn);
            }
        }
        return this;
    }

public Future emit(String event, T... args) {
        ConcurrentLinkedQueue<Listener> callbacks = this.callbacks.get(event);
        if (callbacks != null) {
            callbacks = new ConcurrentLinkedQueue<Listener>(callbacks);
            for (Listener fn : callbacks) {
                fn.call(args);
            }
        }
        return null;
    }

public List<Listener> listeners(String event) {
        ConcurrentLinkedQueue<Listener> callbacks = this.callbacks.get(event);
        return callbacks != null ?
                new ArrayList<Listener>(callbacks) : new ArrayList<Listener>();
    }

