        if (args.length < 1) {
            try {
                mapping = new FilemakerResultDocument(buildExampleDocument()).toMapping();
            } catch (Exception ex) {
                LOGGER.error("Can't create mapping!");
                LOGGER.error("> " + ex.getLocalizedMessage(), ex);
                System.exit(1);
