                LOGGER.error("Can't create mapping from file '" + args[0] + "'!");
                LOGGER.error("> " + ex.getLocalizedMessage(), ex);
                System.exit(1);
            }
        }

        if (mapping == null) {
            LOGGER.error("No mapping was created!");
            System.exit(1);
        }

