        if (layout.getPRODUCT() != null) {
            LOGGER.info("> product name    : " + layout.getPRODUCT().getNAME());
            LOGGER.info("> product version : " + layout.getPRODUCT().getVERSION());
            LOGGER.info("> product build   : " + layout.getPRODUCT().getBUILD());
