public void sinkQuad(Node g, Node s, Node p, Node o) {
        if (writeBuffer != null) {
            writeBuffer.add(g, s, p, o);
        } else {
            Graph graph = GraphFactory.createDefaultGraph();
            graph.add(Triple.create(s,p,o));
            mergeGraph(g.getURI(), graph);
            return;
        }
    }

