static @Nullable String[] createKeysFromCollection(
            @Nullable final Collection<String> collection,
            @Nullable final String... keys) {
        if (isNullOrEmpty(keys)) {
            return collection == null ? null : collection.toArray(new String[collection.size()]);
        }
        if (isNullOrEmpty(collection)) {
            return keys;
        }
        final String[] combined = new String[collection.size() + keys.length];
        for (int i = 0; i < keys.length; ++i) {
            combined[i] = keys[i];
        }
        int i = 0;
        for (final String item : collection) {
            combined[keys.length + i++] = item;
        }
        return combined;
    }

static @Nullable Object[] createValuesFromCollection(
            @Nullable final Collection<Object> collection,
            @Nullable final Object... values) {
        if (isNullOrEmpty(values)) {
            return collection == null ? null : collection.toArray(new Object[collection.size()]);
        }
        if (isNullOrEmpty(collection)) {
            return values;
        }
        final Object[] combined = new Object[collection.size() + values.length];
        for (int i = 0; i < values.length; ++i) {
            combined[i] = values[i];
        }
        int i = 0;
        for (final Object item : collection) {
            combined[values.length + i++] = item;
        }
        return combined;
    }

static @Nullable  String[] createKeysFromArray(
            @Nullable final String[] array, 
            @Nullable final String... keys) {
        if (isNullOrEmpty(keys)) {
            return array;
        }
        if (isNullOrEmpty(array)) {
            return keys;
        }
        final String[] combined = Arrays.copyOf(keys, array.length + keys.length);
        for (int i = 0; i < array.length; ++i) {
            combined[keys.length + i] = array[i];
        }

        return combined;
    }

static @Nullable Object[] createValuesFromArray(
            @Nullable final Object[] array, 
            @Nullable final Object... values) {
        if (isNullOrEmpty(values)) {
            return array;
        }
        if (isNullOrEmpty(array)) {
            return values;
        }
        final Object[] combined = Arrays.copyOf(values, array.length + values.length);
        for (int i = 0; i < array.length; ++i) {
            combined[values.length + i] = array[i];
        }
        return combined;
    }

static @Nullable Throwable extractThrowable(
            @Nullable final String[] keys, 
            @Nullable final Object[] values) {
        final int keyLength = keys == null ? 0 : keys.length;
        if (values != null && values.length == keyLength + 1) {
            final int throwableIndex = values.length - 1;
            if (values[throwableIndex] instanceof Throwable) {
                return (Throwable) values[throwableIndex];
            }
        }
        return null;
    }

static @Nullable Object[] chompArray(@Nullable final Object[] in, final int count) {
        if (count == 0 || in == null) {
            return in;
        }
        return Arrays.copyOf(in, in.length - count);
    }

public String serialize(
            final ILoggingEvent event,
            final String eventName,
            @Nullable final Map<String, ? extends Object> map)
            throws Exception {
        final StringWriter jsonWriter = new StringWriter();
        final JsonGenerator jsonGenerator = _jsonFactory.createGenerator(jsonWriter);

        // Start wrapper
        StenoSerializationHelper.startStenoWrapper(event, eventName, jsonGenerator, _objectMapper);

        // Write event data
        jsonGenerator.writeObjectFieldStart("data");
        if (map != null) {
            for (final Map.Entry<String, ? extends Object> entry : map.entrySet()) {
                if (StenoSerializationHelper.isSimpleType(entry.getValue())) {
                    jsonGenerator.writeObjectField(entry.getKey(), entry.getValue());
                } else {
                    jsonGenerator.writeFieldName(entry.getKey());
                    _objectMapper.writeValue(
                            jsonGenerator,
                            entry.getValue());
                }
            }
        }
        jsonGenerator.writeEndObject(); // End 'data' field

        // Output throwable
        StenoSerializationHelper.writeThrowable(event.getThrowableProxy(), jsonGenerator, _objectMapper);

        // End wrapper
        StenoSerializationHelper.endStenoWrapper(event, eventName, jsonGenerator, _objectMapper, _encoder);

        return jsonWriter.toString();
    }

public String serialize(
        final ILoggingEvent event,
        final String eventName) throws Exception {

        final StringWriter jsonWriter = new StringWriter();
        final JsonGenerator jsonGenerator = _jsonFactory.createGenerator(jsonWriter);

        // Start wrapper
        StenoSerializationHelper.startStenoWrapper(event, eventName, jsonGenerator, _objectMapper);

        // Write event data
        jsonGenerator.writeObjectFieldStart("data");
        jsonGenerator.writeObjectField("message", event.getFormattedMessage());
        jsonGenerator.writeEndObject(); // End 'data' field

        // Output throwable
        StenoSerializationHelper.writeThrowable(event.getThrowableProxy(), jsonGenerator, _objectMapper);

        // End wrapper
        StenoSerializationHelper.endStenoWrapper(event, eventName, jsonGenerator, _objectMapper, _encoder);

        return jsonWriter.toString();
    }

