public static String getMd5(final String text)  {
    try {

      final MessageDigest md = MessageDigest.getInstance("MD5");
      final byte[] utf8Bytes = text.getBytes(UTF_8_NAME);
      md.update(utf8Bytes, 0, utf8Bytes.length);
      final byte[] md5hash = md.digest();
      final int radix = 16;
      final int length = 32;

      final StringBuilder result = new StringBuilder(length).append(new BigInteger(1, md5hash).toString(radix));

      final int zeroBeginLen = length - result.length();
      if (zeroBeginLen > 0) {
        final char [] zeroBegin = new char[zeroBeginLen];
        Arrays.fill(zeroBegin, Character.forDigit(0, radix));
        result.insert(0, zeroBegin);
      }

      return result.toString();

    } catch (final NoSuchAlgorithmException|UnsupportedEncodingException e) {
      throw new AssertionError(e);
    }
  }

public boolean checkSharingIntent(final Activity activity) {
    final Intent activityIntent = activity.getIntent();
    if (activityIntent.hasExtra(SharingHelper.EXTRA_SHARING)) {
      processSharingIntent(activityIntent.<Intent>getParcelableExtra(SharingHelper.EXTRA_SHARING));
      activityIntent.removeExtra(SharingHelper.EXTRA_SHARING);
      return true;
    }
    return false;
  }

private static byte[] generateMultipartBoundary() {
    final Random rand = new Random();
    final int c11 = 11, c30 = 30;
    final byte[] bytes = new byte[rand.nextInt(c11) + c30]; // a random size from 30 to 40
    final byte[] chars = getMultipartChars();
    for (int i = 0; i < bytes.length; i++) {
      bytes[i] = chars[rand.nextInt(chars.length)];
    }
    return bytes;
  }

