public static String charsToPrologList(String chars) {
		StringBuilder sb = new StringBuilder(chars.length()*2+1);
		charsToPrologList(chars, sb);
		return sb.toString();
	}

public static void charsToPrologList(String chars, StringBuilder sb) {

		sb.append('[');
		for (int i = 0; i < chars.length(); i++) {
			if (i > 0)
				sb.append(',');

			//FIXME - ne īstā vieta kristīnes marķējuma loģikai
			//FIXME - aizvākt visas anaforas prom. /Lauma
			if ((chars.startsWith("p") && i == 7) // elements, kurš ir kā saraksts no viena elem jādod
					|| (chars.startsWith("s") && i == 4)
					|| (chars.startsWith("m") && i == 6)  )
				sb.append("[" + chars.charAt(i) + "]");  
			else sb.append(chars.charAt(i));
		}
		if ((chars.startsWith("p") && chars.length() < 8) ) // tagi tagad saīsināti, compatibility ar veco čunkeri
			sb.append(",[0]"); 
		sb.append(']');
	}

public static String wordToChunkerFormat(Word word, boolean toolgenerated) {
		if (!word.isRecognized())
			return ("[]");

		StringBuilder sb = new StringBuilder();
		sb.append('[');

		if (word.getCorrectWordform() != null) {
			wordformToChunkerFormat(word.getToken(), toolgenerated, sb, word.getCorrectWordform());
		} else
			for (Wordform vf : word.wordforms) {
				if (sb.length() > 1)
					sb.append(',');
				wordformToChunkerFormat(word.getToken(), toolgenerated, sb, vf);
			}

		sb.append(']');

		return sb.toString();
	}

public List<MetricData> get() throws RequestException, UnauthorizedException {
        HttpResponse<String> response;
        try {
            response = Unirest.get(
                    this.appdURL + "/controller/rest/applications/" + appName + "/metric-data")
                    .header("accept", "application/json")
                    .basicAuth(this.appdUsername, this.appdPassword)
                    .queryString(getQueryString())
                    .queryString("output", "json")
                    .asString();
        } catch (UnirestException e) {
            throw new RequestException("Something was wrong with sending request.", e);
        }
        if (response == null) {
            throw new RequestException("Response is empty.");
        }
        switch (response.getStatus()) {
        case 200: {
            return process(new JsonNode(response.getBody()));
        }
        case 401: {
            throw new UnauthorizedException("Authentication failed");
        }
        default: {
            throw new RequestException("Unhandled response code " + response.getStatus());
        }
        }
    }

protected Map<String, Object> getQueryString() {
        Map<String, Object> qs = new HashMap<>();
        if (timeParams != null) {
            qs.put("time-range-type", timeParams.type);
            if (timeParams.duration > 0) {
                qs.put("duration-in-mins", timeParams.duration);
            }
            if (timeParams.startTime > 0) {
                qs.put("start-time", timeParams.startTime);
            }
            if (timeParams.endTime > 0) {
                qs.put("end-time", timeParams.endTime);
            }
        }
        qs.put("rollup", false);
        if (metricPath != null) {
            qs.put("metric-path", metricPath);
        }
        return qs;
    }

protected List<MetricData> process(JsonNode node) {
        JSONArray dataArray = node.getArray();
        List<MetricData> list = new LinkedList<>();
        for (int i = 0; i < dataArray.length(); i++) {
            JSONObject data = dataArray.getJSONObject(i);
            MetricData metricData =
                    new MetricData(data.getString("frequency"), data.getLong("metricId"),
                            data.getString("metricName"), data.getString("metricPath"));
            list.add(metricData);
            JSONArray valueArray = data.getJSONArray("metricValues");
            for (int j = 0; j < valueArray.length(); j++) {
                JSONObject value = valueArray.getJSONObject(j);
                metricData.metricValues.add(
                        new MetricValue(value.getLong("count"), value.getLong("value"),
                                value.getLong("max"), value.getLong("min"), value.getLong("sum"),
                                value.getLong("startTimeInMillis")));
            }
        }
        return list;
    }

public static List<AppInfo> parseInfo(String jsonString) throws IOException {
        ObjectMapper mapper = new ObjectMapper();
        return mapper.readValue(jsonString, new TypeReference<List<AppInfo>>() {});
    }

public List<SignalFxProtocolBuffers.DataPoint> process(MetricTimeSeries mts,
                                                           List<MetricValue> metricValues) {
        Long lastTimestamp = mtsToLastTimestamp.get(mts);
        Long latestTimestamp = lastTimestamp;
        List<SignalFxProtocolBuffers.DataPoint> dataPoints = new LinkedList<>();
        SignalFxProtocolBuffers.DataPoint.Builder dataPointBuilder = SignalFxProtocolBuffers.DataPoint
                .newBuilder()
                .setMetric(mts.metricName);

        if (mts.dimensions != null) {
            for (Map.Entry<String, String> entry : mts.dimensions.entrySet()) {
                dataPointBuilder.addDimensions(SignalFxProtocolBuffers.Dimension.newBuilder()
                        .setKey(entry.getKey())
                        .setValue(entry.getValue()));
            }
        }

        for (MetricValue metricValue : metricValues) {
            if (lastTimestamp == null || metricValue.startTimeInMillis > lastTimestamp) {
                SignalFxProtocolBuffers.DataPoint dataPoint = dataPointBuilder
                        .setTimestamp(metricValue.startTimeInMillis)
                        .setValue(SignalFxProtocolBuffers.Datum.newBuilder()
                                .setIntValue(metricValue.value)).build();
                dataPoints.add(dataPoint);

                latestTimestamp = lastTimestamp == null ?
                        metricValue.startTimeInMillis :
                        Math.max(metricValue.startTimeInMillis, latestTimestamp);
            }
        }
        if (lastTimestamp == null || latestTimestamp > lastTimestamp) {
            mtsToLastTimestamp.put(mts, latestTimestamp);
        }
        return dataPoints;
    }

public static ConnectionConfig getConnectionConfig() {
        boolean isValid = true;
        String appdUsername = getPropertyOrEnv("com.signalfx.appd.username", "APPD_USERNAME");
        if (StringUtils.isEmpty(appdUsername)) {
            log.error("AppDynamics username not specified.");
            isValid = false;
        }
        String appdPassword = getPropertyOrEnv("com.signalfx.appd.password", "APPD_PASSWORD");
        if (StringUtils.isEmpty(appdPassword)) {
            log.error("AppDynamics password not specified.");
            isValid = false;
        }
        String appdURL = getPropertyOrEnv("com.signalfx.appd.host", "APPD_HOST");
        if (StringUtils.isEmpty(appdURL)) {
            log.error("AppDynamics host not specified.");
            isValid = false;
        }
        String fxToken = getPropertyOrEnv("com.signalfx.api.token", "SIGNALFX_TOKEN");
        if (StringUtils.isEmpty(fxToken)) {
            log.error("SignalFx token not specified.");
            isValid = false;
        }
        if (isValid) {
            return new ConnectionConfig(appdUsername, appdPassword, appdURL, fxToken);
        } else {
            return null;
        }
    }

public void perform(List<AppInfo> apps, MetricDataRequest.TimeParams timeParams) {
        List<SignalFxProtocolBuffers.DataPoint> dataPoints = new LinkedList<>();
        for (AppInfo app : apps) {
            dataRequest.setAppName(app.name);
            for (MetricInfo metricInfo : app.metrics) {
                dataRequest.setTimeParams(timeParams);
                dataRequest.setMetricPath(metricInfo.metricPathQuery);

                List<MetricData> metricDataList;
                try {
                    metricDataList = dataRequest.get();
                } catch (RequestException e) {
                    // too bad
                    log.error("Metric query failure for \"{}\"", metricInfo.metricPathQuery);
                    counterAppDRequestFailure.inc();
                    continue;
                } catch (UnauthorizedException e) {
                    log.error("AppDynamics authentication failed");
                    return;
                }
                if (metricDataList != null && metricDataList.size() > 0) {
                    for (MetricData metricData : metricDataList) {
                        MetricTimeSeries mts =
                                metricInfo.getMetricTimeSeries(metricData.metricPath);
                        List<SignalFxProtocolBuffers.DataPoint> mtsDataPoints = processor
                                .process(mts, metricData.metricValues);
                        dataPoints.addAll(mtsDataPoints);
                        if (!mtsDataPoints.isEmpty()) {
                            counterMtsReported.inc();
                        } else {
                            counterMtsEmpty.inc();
                        }
                    }
                } else {
                    // no metrics found, something is wrong with selection
                    log.warn("No metric found for query \"{}\"", metricInfo.metricPathQuery);
                }
            }
        }
        if (!dataPoints.isEmpty()) {
            try {
                reporter.report(dataPoints);
                counterDataPointsReported.inc(dataPoints.size());
            } catch (Reporter.ReportException e) {
                log.error("There were errors reporting metric");
            }
        }
    }

public MetricTimeSeries getMetricTimeSeries(String actualMetricPath) {
        Map<String, String> actualDimensions = new HashMap<>();

        actualDimensions.putAll(dimensions);

        String[] path = actualMetricPath.split("\\|");
        for (int i = 0; i < dimensionsPath.length; i++) {
            if ("-".equals(dimensionsPath[i])) {
                continue;
            }
            actualDimensions.put(dimensionsPath[i], path[i]);
        }
        return new MetricTimeSeries(path[path.length - 1], actualDimensions);
    }

