  {
    m_fFn = m_fFnp1;
    m_fFpn = m_aFunction.derivativeAt (m_fXn);

    // Compute the value of x[n+1].
    m_fPrevXnp1 = m_fXnp1;
    m_fXnp1 = m_fXn - m_fFn / m_fFpn;

    m_fFnp1 = m_aFunction.at (m_fXnp1);
  }

