public GeocodeRequestBuilder componenets(Map<String, String> components) {
		StringBuffer filters = new StringBuffer();
		for (Iterator<Map.Entry<String, String>> iterator = components
				.entrySet().iterator(); iterator.hasNext();) {
			Map.Entry<String, String> entry = iterator.next();
			filters.append(entry.getKey() + ":" + entry.getValue() != null ? entry
					.getValue().replace(' ', '+') : entry.getValue());
			if (iterator.hasNext())
				filters.append("|");
		}
		parameters.put("components", filters.toString());
		return this;
	}

public static ServiceInstance<BarCuratorService> convert(BarCuratorService bar) throws Exception {
        ServiceInstanceBuilder<BarCuratorService> builder = ServiceInstance.builder();
        // these values are for the most part nonsensical.
        return builder.payload(bar)
            .uriSpec(new UriSpec("http://"))
            .sslPort(2400)
            .serviceType(ServiceType.STATIC)
            .port(2300)
            .address("127.0.0.1")
            .id(String.format("bar-%s-%d-%s", bar.a, bar.b, bar.c))
            .name(bar.name)
