        else if(objectAtIndex instanceof String)
        {
            Date validDate = null;
            for(SimpleDateFormat format : SUPPORTED_FORMATS)
            {
                try
                {
                    validDate = format.parse((String)objectAtIndex);
                    if(validDate != null)
                    {
                        break;
                    }
                }
                catch (ParseException parseExcept)
                {
                    validDate = null;
                }
            }

            return validDate;
        }

        return null;
    }

