		if ((formTypeParam == null || formTypeParam.trim().isEmpty()) ||
				(this.getFormType() == null || this.getFormType().trim().isEmpty())) {
			return false;
		}

		return formTypeParam.toLowerCase().equals(getFormType().toLowerCase());
	}

