               type, o.getClass().getName(), name);
         try {
            ((SearcherAware) o).inform(searcher);
         } catch (IOException e) {
            logger.error("Failed to inform {} ({}) of field type {} about a new searcher.",
                  type, o.getClass().getName(), name, e);
