public static String getFieldName(int agentid, int beliefset, int index)
      throws BeliefBaseException {
    if (beliefset < 0 || beliefset > beliefsets.size()) {
      throw new BeliefBaseException("belief set id " + beliefset + " is invalid");
    }
    BeliefSetField[] bsf = beliefsetsByID.get(beliefset).getFields();
    if (index < 0 || index >= bsf.length) {
      throw new BeliefBaseException("belief set field id " + index + " is invalid");
    }
    return bsf[index].getName();
  }

public static byte[] toBytes(String str) {
    if (str == null) {
      return new byte[0];
    }
    byte[] val = null;
    try {
      val = str.getBytes(CHARSET);
    } catch (UnsupportedEncodingException e) { // NOPMD - ignore empty catch
      // Can never occur since CHARSET is correct and final
    }
    return val;
  }

private void post(Stack255 stack, Goal goal) {
    synchronized (stack) {
      logger.debug("{} posting goal {}", Log.logPrefix(getId()), goal.getClass().getSimpleName());
      stack.push(goal);
      Main.setAgentIdle(getId(), false);
    }
    Main.flagMessageTo(Main.poolid(getId()));
  }

public boolean send(int id, Goal msg) {
    AObject obj = agents.get(id);
    if (obj == null) {
      logger.warn("{} attempted to send a message to unknown agent id '{}'", Log.logPrefix(getId()),
          id);
      return false;
    }
    logger.debug("{} is sending message of type {} to agent {}", Log.logPrefix(getId()),
        msg.getClass().getSimpleName(), id);
    ((Agent) obj).post(msg);
    return true;
  }

public boolean send(String name, Goal msg) {
    AObject obj = agents.find(name);
    if (obj == null) {
      logger.warn("{} attempted to send a message to unknown agent '{}'", Log.logPrefix(getId()),
          name);
      return false;
    }
    ((Agent) obj).post(msg);
    return true;
  }

