public void push(Event event) {
		if (!active.get()) {
			throw new BugError("Event stream |%s| is closed.", this);
		}
		// BlockingQueue is thread safe so we do not need to synchronize this method
		try {
			if (!eventsQueue.offer(event, EVENTS_QUEUE_PUSH_TIMEOUT, TimeUnit.MILLISECONDS)) {
				log.warn("Timeout trying to push event on events queue. Event |%s| not processed.", event);
			}
		} catch (InterruptedException unused) {
			log.warn("Thread interruption on event stream |%s| while trying to push event to queue. Event |%s| not processed.", this, event);
			Thread.currentThread().interrupt();
		}
	}

@Override
	public void close() {
		if (!active.get()) {
			return;
		}
		log.debug("Closing event stream |%s| ...", this);

		push(new ShutdownEvent());
		active.set(false);
		log.debug("Event stream |%s| was closed.", this);
	}

protected void setRemoteHost(String remoteHost) {
		if (string == null) {
			string = Strings.concat('#', STREAM_ID++, ':', remoteHost);
		}
	}

protected boolean loop() {
		Event event = null;
		try {
			event = eventsQueue.poll(keepAlivePeriod, TimeUnit.MILLISECONDS);
		} catch (InterruptedException unused) {
			if (!active.get()) {
				log.debug("Events stream |%s| thread is interrupted. Break events stream loop.", this);
				return false;
			}
			// in a perfect world, now would be the right moment to stop the events stream, returning false...
			// but i'm not sure interruption occurs only when current thread is interrupted
			// for now i play safe, allowing events stream to continue and use shutdown event to break it
			log.warn("Events stream |%s| thread is interrupted. Continue events stream loop.", this);
			return true;
		}

		if (event == null) {
			// we are here due to keep-alive period expiration
			// returns true to signal event stream should continue
			sendKeepAlive();
			log.debug("Keep-alive was sent to event stream |%s|.", this);
			return !writer.checkError();
		}

		// close method puts this event into queue; returns false to break this events stream loop
		if (event instanceof ShutdownEvent) {
			log.debug("Got shutdown event. Break event stream loop.");
			return false;
		}

		sendEvent(event);
		onSent(event);
		log.debug("Event |%s| was sent to event stream |%s|.", event, this);
		return !writer.checkError();
	}

protected <T> T getParameter(String name, Class<T> type) {
		if (parameters == null) {
			throw new BugError("Event stream |%s| parameters not configured.", this);
		}
		String value = parameters.get(name);
		if (value == null) {
			throw new BugError("Missing event stream parameter |%s| of expected type |%s|.", name, type);
		}
		return ConverterRegistry.getConverter().asObject(value, type);
	}

protected void sendEvent(Event event) {
		write("data:");

		if (secretKey == null) {
			json.serialize(writer, event);
		} else {
			try {
				Cipher cipher = Cipher.getInstance(secretKey.getAlgorithm());
				cipher.init(Cipher.ENCRYPT_MODE, secretKey);

				// this overload of doFinal from Cipher class is able to perform single step encrypting
				// excerpt from API:
				// Encrypts or decrypts data in a single-part operation, or finishes a multiple-part operation.
				byte[] encryptedMessage = cipher.doFinal(json.serialize(event));

				// encode encrypted event message with Base64 since content type should be text
				write(Base64.encode(encryptedMessage));
			} catch (InvalidKeyException | NoSuchPaddingException | BadPaddingException | IllegalBlockSizeException e) {
				// we step here only for bugs on encryption provider:
				// secret key size is incorrect or key is not properly initialized
				// single step encryption using directly Cipher#doFinal is supposed to process all input at once
				// missing JVM default padding mechanism
				// bad padding occurring on encryption
				throw new BugError(e);
			} catch (NoSuchAlgorithmException e) {
				throw new BugError("Missing support for |%s| cryptographic algorithm.", secretKey.getAlgorithm());
			}
		}

		// end data field
		crlf();

		// single end of line is the mark for event end
		crlf();
		flush();
	}

public String removePrefix(final String path, final String prefix) {
		String pathWithoutPrefix = path;

		if (pathWithoutPrefix.startsWith(prefix)) {
			pathWithoutPrefix = pathWithoutPrefix.substring(prefix.length());

			while (pathWithoutPrefix.startsWith("/") || pathWithoutPrefix.startsWith("\\")) {
				pathWithoutPrefix = pathWithoutPrefix.substring(1);
			}
		}

		return pathWithoutPrefix;
	}

public boolean isSubDir(final File subDir, final File parentDir) throws IOException {
		int parentDirLength = parentDir.getCanonicalFile().getAbsolutePath().length();

		File currentDir = subDir.getCanonicalFile().getAbsoluteFile();
		while (currentDir.getAbsolutePath().length() > parentDirLength) {
			currentDir = currentDir.getParentFile();
		}

		return currentDir.equals(parentDir.getAbsoluteFile());
	}

public File[] getParentDirs(final File fromDir, final File toDir) throws IOException {
		List<File> result = new LinkedList<>();
		final File fromDirCanonical = fromDir.getCanonicalFile();
		for (File current = toDir.getCanonicalFile().getAbsoluteFile(); !current.equals(fromDirCanonical); current = current.getParentFile()) {
			result.add(0, current);
		}

		return result.toArray(new File[result.size()]);
	}

public File getCommonDir(final File dir1, final File dir2) throws IOException {
		List<File> parts1 = getParentDirs(dir1);
		List<File> parts2 = getParentDirs(dir2);
		File matched = null;

		final int maxCommonSize = Math.min(parts1.size(), parts2.size());
		for (int i = 0; i < maxCommonSize; ++i) {
			if (parts1.get(i).equals(parts2.get(i))) {
				matched = parts1.get(i);
			} else {
				break;
			}
		}

		return matched;
	}

public String abs2rel(final String basePath, final String absPath) {
		if (!isAbsolutePath(absPath)) {
			return absPath;
		}

		if (isWindowsDrive(absPath) && isWindowsDrive(basePath) && absPath.charAt(0) != basePath.charAt(0)) {
			return absPath;
		}

		StringBuilder result = new StringBuilder();
		String[] baseParts = getParts(basePath);
		String[] absParts = getParts(absPath);

		// extract common prefix
		int start = 0;
		for (int i = 0; i < Math.min(baseParts.length, absParts.length); ++i) {
			if (baseParts[i].equals(absParts[i])) {
				start = i + 1;
			}
		}

		for (int i = start; i < baseParts.length; ++i) {
			if (result.length() > 0) {
				result.append(File.separator);
			}
			result.append("..");
		}

		for (int i = start; i < absParts.length; ++i) {
			if (result.length() > 0) {
				result.append(File.separator);
			}
			result.append(absParts[i]);
		}

		return result.toString();
	}

public File rel2abs(final String basePath, final String relPath) {
		String[] baseParts = getParts(basePath);
		String[] relParts = getParts(relPath);

		if (isAbsolutePath(relPath)) {
			return new File(relPath);
		}

		List<String> parts = new ArrayList<>();
		for (int i = 0; i < baseParts.length; ++i) {
			if (i > 0 || !isWindowsDrive(basePath)) {
				parts.add(baseParts[i]);
			}
		}

		for (String part : relParts) {
			if (part.equals("..") && parts.size() > 0) {
				parts.remove(parts.size() - 1);
			} else if (!part.equals(".") && !part.equals("..")) {
				parts.add(part);
			}
		}

		StringBuilder result = new StringBuilder();
		if (isWindowsDrive(basePath)) {
			result.append(baseParts[0]);
		}

		for (String part : parts) {
			result.append(File.separator);
			result.append(part);
		}

		return new File(result.toString());
	}

public int dirDepth(final File path) {
		final String stringPath = path.getPath();
		return stringPath.length() - stringPath.replaceAll("[/\\\\]", "").length();
	}

@Override
	public void init(ServletConfig config) throws UnavailableException {
		container = (ContainerSPI) config.getServletContext().getAttribute(TinyContainer.ATTR_INSTANCE);
		if (container == null) {
			log.fatal("Tiny container instance not properly created, probably misconfigured. Servlet |%s| permanently unvailable.", config.getServletName());
			throw new UnavailableException("Tiny container instance not properly created, probably misconfigured.");
		}

		servletName = Strings.concat(config.getServletContext().getServletContextName(), '#', config.getServletName());
		log.trace("Initialize servlet |%s|.", servletName);
	}

@Override
	protected void service(HttpServletRequest httpRequest, HttpServletResponse httpResponse) throws IOException, ServletException {
		// push context path and remote address of the requested processed by this thread to logger diagnostic context
		logContext.put(LOG_CONTEXT_APP, httpRequest.getContextPath().isEmpty() ? TinyContainer.ROOT_CONTEXT : httpRequest.getContextPath().substring(1));
		logContext.put(LOG_CONTEXT_IP, httpRequest.getRemoteHost());
		logContext.put(LOG_CONTEXT_ID, Integer.toString(requestID.getAndIncrement(), Character.MAX_RADIX));
		if (isEmptyUriRequest(httpRequest)) {
			log.debug("Empty URI request for |%s|. Please check for <img> with empty 'src' or <link>, <script> with empty 'href' in HTML source or script resulting in such condition.", httpRequest.getRequestURI());
			return;
		}
		String requestURI = httpRequest.getRequestURI();

		long start = System.currentTimeMillis();
		Factory.bind(container);

		// request context has THREAD scope and this request thread may be reused by servlet container
		// takes care to properly initialize request context for every HTTP request
		RequestContext context = container.getInstance(RequestContext.class);
		context.attach(httpRequest, httpResponse);
		log.trace("Processing request |%s|.", requestURI);

		try {
			handleRequest(context);
		} catch (IOException | ServletException | Error | RuntimeException t) {
			// last line of defense; dump request context and throwable then dispatch exception to servlet container
			// servlet container will generate response page using internal templates or <error-page>, if configured
			dumpError(context, t);
			throw t;
		} finally {
			log.trace("%s %s processed in %d msec.", httpRequest.getMethod(), context.getRequestURL(), System.currentTimeMillis() - start);
			// cleanup remote address from logger context and detach request context instance from this request
			logContext.clear();
			context.detach();
		}
	}

private static boolean isEmptyUriRequest(HttpServletRequest httpRequest) {
		if (!"GET".equals(httpRequest.getMethod())) {
			return false;
		}
		String acceptValue = httpRequest.getHeader(HttpHeader.ACCEPT);
		if (acceptValue != null && acceptValue.contains(ContentType.TEXT_HTML.getMIME())) {
			return false;
		}

		String referer = httpRequest.getHeader(HttpHeader.REFERER);
		if (referer == null) {
			return false;
		}

		StringBuilder uri = new StringBuilder(httpRequest.getRequestURI());
		String query = httpRequest.getQueryString();
		if (query != null) {
			if (query.charAt(0) != '?') {
				uri.append('?');
			}
			uri.append(query);
		}
		return referer.toLowerCase().endsWith(uri.toString().toLowerCase());
	}

protected static void sendUnauthorized(RequestContext context) {
		final ContainerSPI container = context.getContainer();
		final HttpServletResponse httpResponse = context.getResponse();

		if (httpResponse.isCommitted()) {
			log.fatal("Abort HTTP transaction. Attempt to send reponse after response already commited.");
			return;
		}
		log.error("Reject unauthorized request for private resource or service: |%s|.", context.getRequestURI());

		String loginPage = container.getLoginPage();
		if (HttpHeader.isXHR(context.getRequest()) && loginPage != null) {
			// XMLHttpRequest specs mandates that redirection codes to be performed transparently by user agent
			// this means redirect from server does not reach script counterpart
			// as workaround uses 200 OK and X-JSLIB-Location extension header
			log.trace("Send X-JSLIB-Location |%s| for rejected XHR request: |%s|", container.getLoginPage(), context.getRequestURI());
			httpResponse.setStatus(HttpServletResponse.SC_OK);
			httpResponse.setHeader(HttpHeader.X_HEADER_LOCATION, container.getLoginPage());
			return;
		}

		log.trace("Send WWW-Authenticate |Basic realm=%s| for rejected request: |%s|", container.getLoginRealm(), context.getRequestURI());
		httpResponse.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
		httpResponse.setHeader(HttpHeader.WWW_AUTHENTICATE, String.format("Basic realm=%s", container.getLoginRealm()));
	}

protected static void sendBadRequest(RequestContext context) throws IOException {
		log.error("Bad request format for resource or service: |%s|.", context.getRequestURI());
		context.dump();
		context.getResponse().sendError(HttpServletResponse.SC_BAD_REQUEST, context.getRequestURI());
	}

protected static void sendNotFound(RequestContext context, Exception exception) throws IOException {
		log.error("Request for missing resource or service: |%s|.", context.getRequestURI());
		sendJsonObject(context, new RemoteException(exception), HttpServletResponse.SC_NOT_FOUND);
	}

protected static void sendError(RequestContext context, Throwable throwable) throws IOException {
		if (throwable instanceof InvocationException && throwable.getCause() != null) {
			throwable = throwable.getCause();
		}
		if (throwable instanceof InvocationTargetException) {
			throwable = ((InvocationTargetException) throwable).getTargetException();
		}
		if (throwable instanceof BusinessException) {
			// business constrains exception is generated by user space code and sent to client using HTTP response
			// status 400 - HttpServletResponse.SC_BAD_REQUEST, as JSON serialized object
			log.debug("Send business constrain exception |%d|.", ((BusinessException) throwable).getErrorCode());
			sendJsonObject(context, throwable, HttpServletResponse.SC_BAD_REQUEST);
		} else {
			dumpError(context, throwable);
			sendJsonObject(context, new RemoteException(throwable), HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
		}
	}

protected static void dumpError(RequestContext context, Throwable throwable) {
		log.dump("Error on HTTP request:", throwable);
		context.dump();
	}

protected static void sendJsonObject(RequestContext context, Object object, int statusCode) throws IOException {
		final HttpServletResponse httpResponse = context.getResponse();
		if (httpResponse.isCommitted()) {
			log.fatal("Abort HTTP transaction. Attempt to send JSON object after reponse commited.");
			return;
		}
		log.trace("Send response object |%s|.", object.toString());

		Json json = Classes.loadService(Json.class);
		String buffer = json.stringify(object);
		byte[] bytes = buffer.getBytes("UTF-8");

		httpResponse.setStatus(statusCode);
		httpResponse.setContentType(ContentType.APPLICATION_JSON.getValue());
		httpResponse.setContentLength(bytes.length);
		httpResponse.setHeader("Content-Language", context.getLocale().toLanguageTag());

		httpResponse.getOutputStream().write(bytes);
		httpResponse.getOutputStream().flush();
	}

