                        + e.getMessage());
                e.printStackTrace();
            } finally {
                if (is != null) {
                    try {
                        is.close();
                    } catch (IOException e) {
                        // Ignored
                    }
                }
            }
        }

        QApplication.setOrganizationName("akquinet A.G.");
