  }

public static <E> List<E> valuesAt(List<E> from, int... indexes) {
    List<E> list = new ArrayList<>();
    for (int i : indexes) {
      if (0 <= i && i < from.size()) {
        list.add(from.get(i));
      } else if (-from.size() <= i && i < 0) {
        list.add(from.get(from.size() + i));
      } else {
        list.add(null);
      }
    }
    return list;
  }

public static int[] assignAt(int[] a, Integer[] indexes, int... values) {
    if (indexes.length != values.length) {
      throw new IllegalArgumentException(String.format("index.length(%d) != values.length(%d)", indexes.length, values.length));
    }
    for (int i = 0; i < indexes.length; i++) {
      int index = indexes[i];
      if (0 <= index && index < a.length) {
        a[index] = values[i];
      } else if (-a.length <= index && index < 0) {
        a[a.length + index] = values[i];
      } else {
        throw new ArrayIndexOutOfBoundsException(index);
      }
    }
    return a;
  }

public static List<String> map(Collection<?> from, String format) {
    List<String> to = new ArrayList<>(from.size());
    for (Object e : from) {
      to.add(String.format(format, e));
    }
    return to;
  }

public static List<String> partition(Collection<String> from, int n, String delimiter) {
    List<String> to = new ArrayList<>();
    List<String> buffer = new ArrayList<>(n);
    for (String e : from) {
      buffer.add(e);
      if (buffer.size() >= n) {
        to.add(join(buffer, delimiter));
        buffer.clear();
      }
    }
    return to;
  }

private static Object[] rehash(final Object[] values, final int newSize)
    {
        Object[] newArray = new Object[newSize];

        for (Object value : values)
        {
            if (value == null)
            {
                continue;
            }

            newArray[predictedPosition(newArray, value, value.hashCode())] = value;
        }

        return newArray;
    }

private static int predictedPosition(final Object[] array, final Object object, final int hash)
    {
        int arraySize = array.length;
        int i = Math.abs(hash) % arraySize;

        Object element = array[i];
        while (element != null) // the load factor guarantees that there is always at least one free slot
        {
            if (element.equals(object))
            {
                // already in the array
                return i;
            }
            // the position is taken, try the next slot
            i = (i + 1) % arraySize;
            element = array[i];
        }
        return i;
    }

private void findNextSeparator()
    {
        mLastSeparatorPos = mNextSeparatorPos;
        while (++mNextSeparatorPos < mValue.length())
        {
            char c = mValue.charAt(mNextSeparatorPos);
            if (c == mSeparator)
            {
                return;
            }
        }
    }

private void findNextSeparator()
    {
        boolean isQuoted = false;
        mLastSeparatorPos = mNextSeparatorPos;
        while (++mNextSeparatorPos < mValue.length())
        {
            char c = mValue.charAt(mNextSeparatorPos);
            if (c == mSeparator)
            {
                if (!isQuoted)
                {
                    return;
                }
                // else: ignore quoted speparator
            }
            else if (c == '"')
            {
                isQuoted = !isQuoted;
            }
        }
    }

