@Override
  public void doAction(char cha) throws ConnectionSectionException, NotationException {

    /* list of connections is empty */
    if (cha == '$') {
      if (sourcepolymerid == "" && _parser.notationContainer.getListOfConnections().size() == 0) {
        LOG.info("Connection section is empty:");
        LOG.info("Transition to group section:");
        _parser.setState(new GroupingParser(_parser));

      } else {
        LOG.error("Missing target polymer ID in connection section:");
        throw new ConnectionSectionException("Missing target polymer id in connection section. Source of connection is " + sourcepolymerid);
      }
    } /* target polymer ID is starting */ else if (cha == ',' && checkBracketsParenthesis()) {
      if (_parser.checkPolymeridConnection(sourcepolymerid)) {
        LOG.info("Target polymer ID is read:");
        _parser.notationContainer.addConnection(new ConnectionNotation(sourcepolymerid));
        _parser.setState(new ConnectionsReadSecondIDParser(_parser));
      } else {
        LOG.error("Source polymer ID is not correct in the connection section: " + sourcepolymerid);
        throw new ConnectionSectionException("Source polymer id is not correct in the connection section: "
            + sourcepolymerid);
      }

    } else {
      sourcepolymerid += cha;
      if (cha == '(') {
        parenthesisCounterOpen += 1;
      }
      if (cha == ')') {
        parenthesisCounterClose += 1;
      }

    }
  }

public String toHELM2() {
    DecimalFormat d = new DecimalFormat("#.##");
    StringBuilder notation = new StringBuilder();
    for (int i = 0; i < elements.size(); i++) {
      if (!(elements.get(i).isDefaultValue())) {
        String value = d.format(elements.get(i).getValue().get(0)).replace(',', '.');
        if (elements.get(i).getValue().size() > 1) {
          value += "-" + d.format(elements.get(i).getValue().get(1)).replace(',', '.');
        }
        notation.append(elements.get(i).getID() + ":" + value + ",");
      } else {
        notation.append(elements.get(i).getID() + ",");
      }
    }
    notation.setLength(notation.length() - 1);
    return notation.toString();
  }

@Override
  public void doAction(char cha) throws AnnotationSectionException {
    /* list of attributes is finished */
    if (cha == '$') {
      if (checkBracketsParenthesis()) {
        LOG.info("Annotation section is finished:");
        if (annotation != "") {
          _parser.notationContainer.addAnnotation(new AnnotationNotation(annotation));
        }
        LOG.info("Transition to FinalState:");
        _parser.setState(new FinalState());
      } else {
        LOG.info("Annotation section is not valid: " + annotation);
        throw new AnnotationSectionException("Annotation section is not valid: " + annotation);
      }
    } else if (cha == '|') {
      if (checkBracketsParenthesis()) {
        LOG.info(" new annotation is starting");
        if (annotation != "") {
          _parser.notationContainer.addAnnotation(new AnnotationNotation(annotation));
          _parser.setState(new AnnotationsParser(_parser));
        } else {
          LOG.info("Annotation section is not valid: ");
          throw new AnnotationSectionException("Annotation section is not valid: ");
        }
      }
    } else {
      annotation += cha;
      if (cha == '{') {
        curlyBracketCounterOpen++;
      }
      if (cha == '}') {
        curlyBracketCounterClose++;
      }
      if (cha == '[') {
        bracketCounterOpen++;
      }
      if (cha == ']') {
        bracketCounterClose++;
      }
      if (cha == '(') {
        parenthesisCounterOpen++;
      }
      if (cha == ')') {
        parenthesisCounterClose++;
      }
    }

  }

private boolean checkBracketsParenthesis() {
    LOG.debug("Check of brackets in the annotation section:");
    if (bracketCounterOpen == bracketCounterClose
        && parenthesisCounterOpen == parenthesisCounterClose
        && curlyBracketCounterOpen == curlyBracketCounterClose) {
      return true;

    }
    return false;
  }

private void addDetails(String str) throws NotationException{
    String[] parts = str.split("-");

    /* MonomerUnit */
    sourceUnit = parts[0].split(":")[0].toUpperCase();
    targetUnit = parts[1].split(":")[0].toUpperCase();

    /* R-group */
    
    rGroupSource = parts[0].split(":")[1];
    rGroupTarget = parts[1].split(":")[1];
    
    Pattern r = Pattern.compile("R\\d", Pattern.CASE_INSENSITIVE);
    Pattern pair = Pattern.compile("pair", Pattern.CASE_INSENSITIVE);
    
    Matcher mR = r.matcher(rGroupSource);
    Matcher mPair = pair.matcher(rGroupTarget);
    if(mR.matches()){
    	rGroupSource = rGroupSource.toUpperCase();
    }else{
    	rGroupSource = rGroupSource.toLowerCase();
    }
    
    if(mPair.matches()){
    	rGroupTarget = rGroupTarget.toLowerCase();
    }else{
    	rGroupTarget = rGroupTarget.toUpperCase();
    }
  }

