@Override
  public void doAction(char cha) throws SimplePolymerSectionException {

    /* repeating information is finished */
    if (cha == '\'') {
      if (_parser.checkRepeating(repeating)) {
        String[] range = repeating.split("-");
        int first = Integer.parseInt(range[0]);
        if (range.length > 1) {
          int second = Integer.parseInt(range[1]);
          /* range is wrong */
          if (second - first <= 0) {
            LOG.error("Information about repeating is wrong: " + repeating);
            throw new SimplePolymerSectionException("Information about repeating is wrong: " + repeating);
          } else {
            LOG.info("Monomer unit is repeated:");
            _parser.notationContainer.getCurrentPolymer().getPolymerElements().getCurrentMonomerNotation().setCount(repeating);
            _parser.setState(new BetweenMonomerParser(_parser));
          }

        } else {
          LOG.info("Monomer unit is repeated:");
          _parser.notationContainer.getCurrentPolymer().getPolymerElements().getCurrentMonomerNotation().setCount(repeating);
          _parser.setState(new BetweenMonomerParser(_parser));
        }

      } else {
        LOG.error("Information about repeating is wrong: " + repeating);
        throw new SimplePolymerSectionException("Information about repeating is wrong: " + repeating);
      }
    } /* add characters to repeating information */ else {
      repeating += cha;
    }
  }

public static void main(String[] args) throws ParseException,
      ExceptionState, IOException {
    /* options for the program */
    Options options = new Options();
    /* add helm string */
    options.addOption("inputHELM", true, "HELM1 or HELM2 string in a file");

    /* add output option */
    options.addOption("output", true, "output can be in JSON- or HELM2-format");

    /* add translate option */
    options.addOption("translate", false, "translate HELM1 to HELM2");

    CommandLineParser parameter = new DefaultParser();
    try {

      CommandLine cmd = parameter.parse(options, args);

      String filename = cmd.getOptionValue("inputHELM");

      ParserHELM2 parser = new ParserHELM2();

      FileReader in = new FileReader(filename);

      BufferedReader br = new BufferedReader(in);

      String line;
      String helm;
      try {
        while ((line = br.readLine()) != null) {
          helm = line;
          /* HELM1 notation has to be translated into HELM2 */
          if (cmd.hasOption("translate")) {

            ConverterHELM1ToHELM2 converter = new ConverterHELM1ToHELM2();
            helm = converter.doConvert(helm);
            LOG.info("HELM1 is translated to HELM2");
          }

          parser.parse(helm);

          /* There are two different output options */
          String output = "";
          if (cmd.getOptionValue("output").equals("HELM2")) {
            output = parser.getHELM2Notation().toHELM2();
          } else if (cmd.getOptionValue("output").equals("JSON")) {

            output = parser.getJSON();
          }
          System.out.println(output);
        }
      } finally {
        br.close();
      }
    } catch (NullPointerException e) {
      System.out.println("Please call the program with the following arguments: "
          + "\n"
          + "-inputHELM  <"
          + options.getOption("inputHELM").getDescription()
          + ">\n"
          + "-output <"
          + options.getOption("output").getDescription()
          + ">\n-translate(optional) <"
          + options.getOption("translate").getDescription()
          + ">");
    } catch (ParseException exp) {
      System.out.println("Unexpected exception: " + exp.getMessage());
    }

  }

@Override
  public void doAction(char cha) throws SimplePolymerSectionException, NotationException{
    /* simple polymer notation is finished; can also be empty */
    if (cha == '}' && checkBracketsParenthesis()) {
      // initialize object - normal monomer type
      if (!(monomer.equals(""))) {
        LOG.info("Monomer unit is read:");
        _parser.notationContainer.getCurrentPolymer().getPolymerElements().addMonomerNotation(monomer);
        _parser.setState(new BetweenParser(_parser));
      } else {
        throw new SimplePolymerSectionException("Monomer unit is missing: ");
      }
    } else if (cha == '.' && checkBracketsParenthesis()) {
      /*
       * a new monomer unit is starting. This is only valid for peptide and rna
       * not for chem and blob
       */
      if (monomer != "") {
        if (_parser.isPeptideOrRna()) {
          LOG.info("Monomer unit is read: " + monomer);
          LOG.info("New monomer unit is starting:");
          _parser.notationContainer.getCurrentPolymer().getPolymerElements().addMonomerNotation(monomer);
          _parser.setState(new SimplePolymersNotationParser(_parser));
        } else {
          LOG.error("Only one monomer unit is allowed: " + monomer);
          throw new SimplePolymerSectionException("Only one monomer unit is allowed: " + monomer);
        }
      } else {
        LOG.error("Monomer unit is missing: " + monomer);
        throw new SimplePolymerSectionException("Monomer unit is missing: " + monomer);
      }

    } /* an additional annotation is given */ else if (cha == '"' && checkBracketsParenthesis()) {
      if (monomer != "") {
        LOG.info("Monomer unit is read: " + monomer);
        LOG.info("Annotation for monomer unit is starting:");
        _parser.notationContainer.getCurrentPolymer().getPolymerElements().addMonomerNotation(monomer);
        _parser.setState(new InlineAnnotationsParser(_parser, 11));
      } else {
        LOG.error("Monomer unit is missing:");
        throw new SimplePolymerSectionException("Monomer unit is missing:");
      }
    } else if (cha == '\'' && checkBracketsParenthesis()) {
      /*
       * the monomer unit is being repeated. This is only valid for peptide and
       * rna not for chem and blob
       */
      if (monomer != "") {
        if (_parser.isPeptideOrRna()) {
          LOG.info("Monomer unit is read: " + monomer);
          _parser.notationContainer.getCurrentPolymer().getPolymerElements().addMonomerNotation(monomer);
          _parser.setState(new RepeatingMonomerParser(_parser));
        } else {
          LOG.error("Monomer unit shall be not repeated: ");
          throw new SimplePolymerSectionException("Monomer unit shall be not repeated: ");
        }
      } else {
        LOG.error("Monomer unit is missing");
        throw new SimplePolymerSectionException("Monomer unit is missing");
      }

    } /* check all brackets */ else if (cha == '[' || cha == ']' || cha == '(' || cha == ')') {
      monomer += cha;
      if (cha == '[') {
        bracketCounterOpen += 1;
      } else if (cha == ']') {
        bracketCounterClose += 1;
      } else if (cha == '(') {
        parenthesisCounterOpen += 1;

      } else {
        parenthesisCounterClose += 1;

      }
    } /* add characters */ else {
      monomer += cha;
    }

  }

public boolean checkPolymerId(String polymerId) {
    LOG.debug("Validation of polymerID: " + polymerId);
    String pattern = "PEPTIDE[1-9][0-9]*|RNA[1-9][0-9]*|CHEM[1-9][0-9]*|BLOB[1-9][0-9]*";

    Pattern p = Pattern.compile(pattern, Pattern.CASE_INSENSITIVE);
    Matcher m = p.matcher(polymerId);
    if (m.matches()) {
      LOG.debug("PolymerID is valid: " + polymerId);
      return true;
    }

    LOG.debug("PolymerID is not valid: " + polymerId);
    return false;
  }

public boolean checkPolymeridConnection(String polymerId) {
    LOG.debug("Validation of polymerID in the connection section:");
    String ratio = "(:[1-9][0-9]*(\\.[0-9]+)?)?";
    String id = "(PEPTIDE[1-9][0-9]*|RNA[1-9][0-9]*|CHEM[1-9][0-9]*|BLOB[1-9][0-9]*|G[1-9][0-9]*)";
    String pattern = "(\\(" + id + ratio + "(," + id + ratio + ")+\\)" + ratio + "|" + id + ratio + ")";
    Pattern p = Pattern.compile(pattern,Pattern.CASE_INSENSITIVE);
    Matcher m  = p.matcher(polymerId);
    if (m.matches()) {
      LOG.debug("PolymerID in the connection section is valid:");
      return true;
    }

    LOG.debug("PolymerID in the connection section is not valid: " + polymerId);
    return false;
  }

public boolean checkDetailsConnections(String d) {
    LOG.debug("Validation of connection's details:");
    String group = "\\((\\D|\\d)((,|\\+)(\\D|\\d))+\\)";
    String partOne = "([1-9][0-9]*|\\D|\\?|" + group + ")";
    String partTwo = "(R[1-9][0-9]*+|\\?)";
    String element = partOne + ":" + partTwo;
    String patternConnection = element + "-" + element;
    String hydrogenBondPartner = partOne + ":pair";
    String hydrogenBondPattern = hydrogenBondPartner + "-" + hydrogenBondPartner;
    Pattern pConnection = Pattern.compile(patternConnection , Pattern.CASE_INSENSITIVE);
    Matcher mConnection = pConnection.matcher(d);
    Pattern pHydrogen = Pattern.compile(hydrogenBondPattern, Pattern.CASE_INSENSITIVE);
    Matcher mHydrogen = pHydrogen.matcher(d);
    if (mConnection.matches() || mHydrogen.matches()) {
      LOG.debug("Connection's details are valid:");
      return true;
    }
    LOG.debug("Connection's details are not valid: " + d);
    return false;
  }

