public static MonomerNotation decideWhichMonomerNotation(String str, String type)
			throws NotationException {
		MonomerNotation mon;
		/* group ? */
		if (str.startsWith("(") && str.endsWith(")")) {
			String str2 = str.substring(1, str.length() - 1);

			Pattern patternAND = Pattern.compile("\\+");
			Pattern patternOR = Pattern.compile(",");
			/* Mixture of elements */
			if (patternAND.matcher(str).find()) {
				mon = new MonomerNotationGroupMixture(str2, type);
			} /* or - groups */ else if (patternOR.matcher(str).find()) {
				mon = new MonomerNotationGroupOr(str2, type);
			} else {
				if (str.contains(".")) {
					mon = new MonomerNotationList(str2, type);
				} else {
					/* monomer unit is just in brackets */
					if (type == "RNA") {
						mon = new MonomerNotationUnitRNA(str2, type);
					} else {
						if (str2.length() > 1) {
							if (!(str2.startsWith("[") && str2.endsWith("]"))) {
								throw new NotationException("Monomers have to be in brackets: " + str);
							}
						}
						mon = new MonomerNotationUnit(str2, type);
					}
				}

			}
		} else {
			if (type == "RNA") {
				// if (str.startsWith("[") && str.endsWith("]")) {
				// mon = new MonomerNotationUnitRNA(str, type);
				// }
				mon = new MonomerNotationUnitRNA(str, type);
			} else if (type != "BLOB") {
				if (str.length() > 1) {
					if (!(str.startsWith("[") && str.endsWith("]"))) {
						throw new NotationException("Monomers have to be in brackets: " + str);
					}
				}
				mon = new MonomerNotationUnit(str, type);
			}
			else{
				mon = new MonomerNotationUnit(str, type);
			}

		}
		return mon;
	}

public static MonomerNotationGroupElement decideWhichMonomerNotationInGroup(String str, String type, double one,
			double two, boolean interval, boolean isDefault) throws NotationException{
		MonomerNotation element;

		element = decideWhichMonomerNotation(str, type);

		if (interval) {
			return new MonomerNotationGroupElement(element, one, two);
		} else {
			return new MonomerNotationGroupElement(element, one, isDefault);
		}
	}

public static HELMEntity decideWhichEntity(String str) throws NotationException {

		HELMEntity item;

		if (str.toUpperCase().matches("PEPTIDE[1-9][0-9]*")) {
			item = new PeptideEntity(str.toUpperCase());
		} else if (str.toUpperCase().matches("RNA[1-9][0-9]*")) {
			item = new RNAEntity(str.toUpperCase());
		} else if (str.toUpperCase().matches("BLOB[1-9][0-9]*")) {
			item = new BlobEntity(str.toUpperCase());
		} else if (str.toUpperCase().matches("CHEM[1-9][0-9]*")) {
			item = new ChemEntity(str.toUpperCase());
		} else if (str.toUpperCase().matches("G[1-9][0-9]*")) {
			item = new GroupEntity(str.toUpperCase());
		} else {
			throw new NotationException("ID is wrong: " + str);
		}

		return item;

	}

@Override
  public void doAction(char cha) throws ConnectionSectionException,
      NotationException{
    /* a new connection is starting */
    if (cha == '|') {
      if (_parser.checkDetailsConnections(details)) {
        LOG.info("A new connection is starting:");
        ConnectionNotation current =
            _parser.notationContainer.getCurrentConnection();
        _parser.notationContainer.changeConnectionNotation(new ConnectionNotation(
            current.getSourceId(),
            current.getTargetId(), details));

        _parser.setState(new ConnectionsParser(_parser));
      } else {
        LOG.error("Details about the connection are not corret: " + details);
        throw new ConnectionSectionException("Details about the connection are not correct: " + details);
      }

    } /* connection section is finished */ else if (cha == '$') {
      if (_parser.checkDetailsConnections(details)) {
        LOG.info("Connection section is finished:");
        ConnectionNotation current =
            _parser.notationContainer.getCurrentConnection();
        _parser.notationContainer.changeConnectionNotation(new ConnectionNotation(
            current.getSourceId(),
            current.getTargetId(), details));

        LOG.info("Transition to group section");
        _parser.setState(new GroupingParser(_parser));

      } else {
        throw new ConnectionSectionException("Details about the connection are not correct: " + details);
      }
    } /* start of an annotation */ else if (cha == '\"') {
      if (_parser.checkDetailsConnections(details)) {
        LOG.info("Add annotation to connection:");
        ConnectionNotation current =
            _parser.notationContainer.getCurrentConnection();
        _parser.notationContainer.changeConnectionNotation(new ConnectionNotation(
            current.getSourceId(),
            current.getTargetId(), details));

        _parser.setState(new InlineAnnotationsParser(_parser, 2));
      } else {
        LOG.error("Details about the connection are not corret: " + details);
        throw new ConnectionSectionException("Details about the connection are not correct: " + details);
      }

    } /* add characters to connection description */ else {
      details += cha;
    }
  }

@Override
  public void doAction(char cha) throws GroupingSectionException, NotationException {
    /*
     * group section is finished: section was empty: annotation section starts
     */
    if (cha == '$') {
      /* no details */
      if (groupId == "" && _parser.notationContainer.getListOfGroupings().size() == 0) {
        LOG.info("Group section is empty:");
        LOG.info("Transition to annotation section:");
        _parser.setState(new AnnotationsParser(_parser));
      } else {
        throw new GroupingSectionException("Missing details about the group: " + groupId);
      }

    } /* detailed information about the group is starting */ else if (cha == '(') {
      if (_parser.checkGroupId(groupId)) {
        LOG.info("Group ID is read:");
        _parser.notationContainer.addGrouping(new GroupingNotation(groupId));
        _parser.setState(new GroupingDetailedInformationParser(_parser));
      } else {
        LOG.error("Invalid group ID: " + groupId);
        throw new GroupingSectionException("Invalid group Id: " + groupId);
      }
    } /* add characters to the group id */ else {
      groupId += cha;
    }

  }

