            case 'L':
                this.errorCorrectionLevel = ErrorCorrectionLevel.L;
                break;
            case 'M':
                this.errorCorrectionLevel = ErrorCorrectionLevel.M;
                break;
            case 'Q':
                this.errorCorrectionLevel = ErrorCorrectionLevel.Q;
                break;
            case 'H':
                this.errorCorrectionLevel = ErrorCorrectionLevel.H;
                break;
            default:
                this.errorCorrectionLevel = ErrorCorrectionLevel.M;
        }

        return this;
    }

