public int compareTo(MoneyKit other) {
        assertSameCurrencyAs(other);

        if (cent < other.cent) {
            return -1;
        } else if (cent == other.cent) {
            return 0;
        } else {
            return 1;
        }
    }

public MoneyKit add(MoneyKit other) {
        assertSameCurrencyAs(other);

        return newMoneyWithSameCurrency(cent + other.cent);
    }

public MoneyKit subtract(MoneyKit other) {
        assertSameCurrencyAs(other);

        return newMoneyWithSameCurrency(cent - other.cent);
    }

public MoneyKit multiply(BigDecimal val, int roundingMode) {
        BigDecimal newCent = BigDecimal.valueOf(cent).multiply(val);

        return newMoneyWithSameCurrency(rounding(newCent, roundingMode));
    }

public MoneyKit divide(BigDecimal val, int roundingMode) {
        BigDecimal newCent = BigDecimal.valueOf(cent).divide(val, roundingMode);

        return newMoneyWithSameCurrency(newCent.longValue());
    }

public MoneyKit[] allocate(int targets) {
        MoneyKit[] results = new MoneyKit[targets];

        MoneyKit lowResult = newMoneyWithSameCurrency(cent / targets);
        MoneyKit highResult = newMoneyWithSameCurrency(lowResult.cent + 1);

        int remainder = (int) cent % targets;

        for (int i = 0; i < remainder; i++) {
            results[i] = highResult;
        }

        for (int i = remainder; i < targets; i++) {
            results[i] = lowResult;
        }

        return results;
    }

public MoneyKit[] allocate(long[] ratios) {
        MoneyKit[] results = new MoneyKit[ratios.length];

        long total = 0;

        for (long ratio : ratios) {
            total += ratio;
        }

        long remainder = cent;

        for (int i = 0; i < results.length; i++) {
            results[i] = newMoneyWithSameCurrency((cent * ratios[i]) / total);
            remainder -= results[i].cent;
        }

        for (int i = 0; i < remainder; i++) {
            results[i].cent++;
        }

        return results;
    }

protected MoneyKit newMoneyWithSameCurrency(long cent) {
        MoneyKit money = new MoneyKit(0, currency);

        money.cent = cent;

        return money;
    }

public static SecurityHandler newSecurityHandler(List<SimpleServiceUser> users) {
    final HashLoginService loginService = new HashLoginService();
    final Set<String> roles = new HashSet<>();
    for (final SimpleServiceUser user : users) {
      final List<String> authorities = user.getAuthorities();
      loginService.putUser(user.getUsername(), Credential.getCredential(user.getPassword()),
          authorities.toArray(new String[authorities.size()]));
      roles.addAll(authorities);

    }
    loginService.setName(DEFAULT_REALM);

    final Constraint constraint = new Constraint();
    constraint.setName(Constraint.__BASIC_AUTH);
    constraint.setRoles(roles.toArray(new String[roles.size()]));
    constraint.setAuthenticate(true);

    final ConstraintMapping constraintMapping = new ConstraintMapping();
    constraintMapping.setConstraint(constraint);
    constraintMapping.setPathSpec("/*");

    final ConstraintSecurityHandler csh = new ConstraintSecurityHandler();
    csh.setAuthenticator(new BasicAuthenticator());
    csh.setRealmName(DEFAULT_REALM_NAME);
    csh.addConstraintMapping(constraintMapping);
    csh.setLoginService(loginService);

    return csh;
  }

public static List<SimpleServiceUser> loadUsers(PropertySource<?> propertySource, String authPropertiesPrefix) {
    if (propertySource instanceof EnumerablePropertySource) {
      final EnumerablePropertySource<?> enumPropSource = (EnumerablePropertySource) propertySource;
      final String[] propertyNames = enumPropSource.getPropertyNames();

      final PropertyEntrySink sink = new PropertyEntrySink(authPropertiesPrefix);

      for (final String propertyName : propertyNames) {
        final Object value = propertySource.getProperty(propertyName);
        if (value instanceof String) {
          sink.putEntry(propertyName, value.toString());
        }
      }

      return sink.getUserList();
    }

    LoggerFactory.getLogger(SimpleAuthenticatorUtil.class)
        .warn("propertySource={} is not of type EnumerablePropertySource", propertySource);

    return Collections.emptyList();
  }

public static String serialize(Document document) {
        StringWriter writer = new StringWriter();
        try {
            TransformerFactory factory = TransformerFactory.newInstance();
            Transformer transformer = factory.newTransformer();
            DOMSource domSource = new DOMSource(document);
            StreamResult streamResult = new StreamResult(writer);
            transformer.transform(domSource, streamResult);
        } catch (TransformerException e) {
            throw new RuntimeException(
                    "Error when serializing XML document.", e);
        }
        return writer.toString();
    }

