public static <A> A readArguments(Class<A> interfaceClass, String[] args) {
        A result = null;
        try {
            final ArgumentHandler argumentHandler = new ArgumentHandler(args);
            result = argumentHandler.getInstance(interfaceClass);
            argumentHandler.processArguments(new ArgumentProcessor() {

                @Override
                public void process(List<String> remaining) throws InvalidArgumentsException {
                    if (remaining.size() > 0) {
                        throw new InvalidArgumentsException("The following arguments could not be understood: " + remaining);
                    }
                }
            });
        } catch (InvalidArgumentsException e) {
            System.out.println(e.getMessage());
            showUsage(interfaceClass);
            result = null;
        }
        if (result instanceof ArgumentsWithHelp) {
            if (((ArgumentsWithHelp)result).getHelp()) {
                showUsage(interfaceClass);
                result = null;
            }
        }
        return result;
    }

public int read() throws IOException {
		if (currentReader == null) {
			try {
				getNextReader();
			} catch (StreamFinishedException e) {
				return -1;
			}
		}
		int result = currentReader.read();
		while (result == -1) {
			try {
				getNextReader();
			} catch (StreamFinishedException e) {
				return -1;
			}
			result = currentReader.read();
		}
		return result;
	}

public V put(K key, V value) {
		//remove possible existing with same value

		if (backward.containsKey(value)) {
			K oldKey = backward.get(value);
			forward.remove(oldKey);
		}
		if (forward.containsKey(key)) {
			V oldValue = forward.get(key);
			backward.remove(oldValue);
		}
		backward.put(value, key);
		return forward.put(key, value);
	}

public V remove(Object key) {
		V value = forward.remove(key);
		backward.remove(value);
		return value;
	}

public static final Class<? extends Object> getProtobufClass(Object value, Class<? extends Object> protobufClass)
  {
    if (value instanceof Integer)
    {
      return Integer.TYPE;
    }
    if (value instanceof Boolean)
    {
      return Boolean.TYPE;
    }
    if (value instanceof Double)
    {
      return Double.TYPE;
    }
    if (value instanceof Long || value instanceof Date)
    {
      return Long.TYPE;
    }
    if (value instanceof List)
    {
      return Iterable.class;
    }
    return protobufClass;
  }

