public static <T> T toBean(JsonParser jsonParser, Class<T> clazz) {
		if (clazz == null || jsonParser == null)
			return null;

		T obj = null;
		try {
			obj = getMapper().readValue(jsonParser, clazz);
		} catch (JsonParseException e) {
			log.error("{}", e.getMessage(), e);
		} catch (JsonMappingException e) {
			log.error("{}", e.getMessage(), e);
		} catch (IOException e) {
			log.error("{}", e.getMessage(), e);
		} finally {
			try {
				jsonParser.close();
			} catch (IOException e) {
			}
		}
		return obj;

	}

public static <T> String toJson(T obj) {
		StringWriter writer = new StringWriter();
		String jsonStr = "";
		JsonGenerator gen = null;
		try {
			gen = getJsonFactory().createGenerator(writer);
			getMapper().writeValue(gen, obj);
			writer.flush();
			jsonStr = writer.toString();

		} catch (IOException e) {
			log.error("{}", e.getMessage(), e);
		} finally {
			if (gen != null) {
				try {
					gen.close();
				} catch (IOException e) {
				}
			}

		}
		return jsonStr;
	}

public static void close(final Connection conn) {
        if (conn != null) {
            try {
                conn.close();
            } catch (SQLException e) {
                final String error = "Error closing JDBC connection. This may indicate a resource leak.";
                LOG.warn(error, e);
            }
        }
