@Override
    public void registerController(Class<?> clazz) {
        Controller controller = clazz.getAnnotation(Controller.class);
        Validate.notNull(controller);

        String ctrlPath = ValueConstants.trimToEmpty(controller.value());
        ControllerInfo ctrlInfo = new ControllerInfo(clazz, controller);

        ResultHandlerResolver resultHandlerResolver = WebConfig.getInstance().getResultHandlerResolver();
        KlassInfo klass = KlassInfo.create(clazz);
        for (MethodInfo actionMethod : klass.getMethods()) {
            if (!klass.isPublic() || actionMethod.isStatic()) {
                continue;
            }
            Action action = actionMethod.getAnnotation(Action.class);
            if (action == null) {
                continue;
            }
            String actionPath = ValueConstants.defaultValue(action.value(), actionMethod.getName());
            String url = StringUtils.removeEnd(ctrlPath, "/") + StringUtils.prefix(actionPath, "/");

            // validate the action result type
            Class<?> returnClass = actionMethod.getRawReturnType(clazz);
            if (!resultHandlerResolver.validate(returnClass)) {
                throw new IllegalStateException("Unsupported result class: " + returnClass.getName() + " of " + actionMethod);
            }

            HttpMethod[] httpMethods = action.method();
            Validate.isTrue(httpMethods.length > 0);

            if (log.isDebugEnabled()) {
                log.debug("found action: {} {}", ArrayUtils.toString(httpMethods), url);
            }
            ActionInfo actionInfo = new ActionInfo(ctrlInfo, actionMethod, url);
            for (HttpMethod method : httpMethods) {
                RestfulMatcher matcher = matchers[method.getIndex()];
                if (matcher == null) {
                    matcher = new RestfulMatcher();
                    matchers[method.getIndex()] = matcher;
                }
                matcher.register(actionInfo, url);
            }
        }
    }

public static Date parse(String date) {
        Date d = parseUsingPatterns(date, STD_PATTERNS);
        if (d == null) {
            d = parseRFC822Date(date);
        }
        if (d == null) {
            d = parseW3CDateTime(date);
        }
        if (d == null) {
            try {
                d = DateFormat.getInstance().parse(date);
            } catch (ParseException e) {
                d = null;
            }
        }
        return d;
    }

public static Date parseUsingPattern(String date, String pattern) {
        SimpleDateFormat df = new SimpleDateFormat(pattern);
        df.setLenient(false);

        try {
            ParsePosition pp = new ParsePosition(0);
            Date d = df.parse(date, pp);
            if (d != null && pp.getIndex() != date.length()) {
                return d;
            }
        } catch (Exception e) {
        }
        return null;
    }

public void copyOutAttributes(Object target, List<Attribute> jmxAttributeValues,
                                  Map<String, Method> attributeSetters, ObjectName objectName) {

        this.copyOutAttributes(target, jmxAttributeValues, attributeSetters, "oname", objectName);
    }

protected void copyOutAttributes(Object target, List<Attribute> jmxAttributeValues,
                                     Map<String, Method> attributeSetters, String identifierKey, Object identifier) {

        for (Attribute oneAttribute : jmxAttributeValues) {
            String attributeName = oneAttribute.getName();

            Method setter = attributeSetters.get(attributeName);
            Object value = oneAttribute.getValue();

            try {
                //
                // Automatically down-convert longs to integers as-needed.
                //
                if ((setter.getParameterTypes()[0].isAssignableFrom(Integer.class)) ||
                    (setter.getParameterTypes()[0].isAssignableFrom(int.class))) {
                    if (value instanceof Long) {
                        value = ((Long) value).intValue();
                    }
                }
                setter.invoke(target, value);
            } catch (InvocationTargetException invocationExc) {
                this.log.info("invocation exception storing mbean results: {}={}; attributeName={}", identifierKey,
                        identifier, attributeName, invocationExc);
            } catch (IllegalAccessException illegalAccessExc) {
                this.log.info("illegal access exception storing mbean results: {}={}; attributeName={}", identifierKey,
                        identifier, attributeName, illegalAccessExc);
            } catch (IllegalArgumentException illegalArgumentExc) {
                this.log.info("illegal argument exception storing mbean results: {}={}; attributeName={}",
                        identifierKey, identifier, attributeName, illegalArgumentExc);
            }
        }
    }

public static void browse(String url) throws Exception {
        if (OS_NAME.startsWith("Mac OS")) {
            Method openURL = ClassUtil.getDeclaredMethod(
                    Class.forName("com.apple.eio.FileManager"), true,
                    "openURL", String.class);
            openURL.invoke(null, url);

        } else if (OS_NAME.startsWith("Windows")) {

            Runtime.getRuntime().exec(
                    "rundll32 url.dll,FileProtocolHandler " + url);
        } else {
            // assume Unix or Linux
            String[] browsers = {"firefox", "opera", "konqueror", "epiphany",
                    "mozilla", "netscape"};
            String browser = null;
            for (int count = 0; count < browsers.length && browser == null; count++)
                if (Runtime.getRuntime()
                        .exec(new String[]{"which", browsers[count]})
                        .waitFor() == 0)
                    browser = browsers[count];
            if (browser == null)
                throw new NoSuchMethodException("Could not find web browser");
            else
                Runtime.getRuntime().exec(new String[]{browser, url});
        }
    }

public void visitTypeDeclaration(TypeDeclaration d) {
		d.accept(pre);

		SortedSet<Declaration> decls = new
				TreeSet<Declaration>(SourceOrderDeclScanner.comparator);

		for (TypeParameterDeclaration tpDecl : d.getFormalTypeParameters()) {
			decls.add(tpDecl);
		}

		for (FieldDeclaration fieldDecl : d.getFields()) {
			decls.add(fieldDecl);
		}

		for (MethodDeclaration methodDecl : d.getMethods()) {
			decls.add(methodDecl);
		}

		for (TypeDeclaration typeDecl : d.getNestedTypes()) {
			decls.add(typeDecl);
		}

		for (Declaration decl : decls)
			decl.accept(this);

		d.accept(post);
	}

