public static Collection<URL> getClasspathURLs(final ClassLoader classLoader) {
        Collection<URL> urls = new LinkedHashSet<URL>(32);
        ClassLoader loader = classLoader;
        while (loader != null) {
            String className = loader.getClass().getName();
            if (EXT_CLASS_LOADER_NAME.equals(className)) {
                break;
            }
            if (loader instanceof URLClassLoader) {
                for (URL url : ((URLClassLoader) loader).getURLs()) {
                    urls.add(url);
                }
            } else if (className.startsWith("weblogic.utils.classloaders.")) {
                // 该死的 WebLogic，只能特殊处理
                // GenericClassLoader, FilteringClassLoader, ChangeAwareClassLoader
                try {
                    Method method = loader.getClass().getMethod("getClassPath");
                    Object result = method.invoke(loader);
                    if (result != null) {
                        String[] paths = StringUtils.split(result.toString(), File.pathSeparatorChar);
                        for (String path : paths) {
                            urls.add(URLUtils.fromFile(path));
                        }
                    }
                } catch (NoSuchMethodException e) {
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            } else if (className.startsWith("org.jboss.modules.ModuleClassLoader")) {
                // 该死的 Jboss/Wildfly 8，只能特殊处理
                try {
                    Set<URL> urlSet = JBossModuleUtils.getClasspathURLs(loader, false);
                    urls.addAll(urlSet);
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }
            loader = loader.getParent();
        }

        // moved jsp classpath from ServletContext.attributes to System.properties
        String jsp_classpath = System.getProperty("org.apache.catalina.jsp_classpath");
        String classpath = System.getProperty("java.class.path");
        classpath = StringUtils.trimToEmpty(classpath) + File.pathSeparatorChar + StringUtils.trimToEmpty(jsp_classpath);
        if (classpath.length() > 1) {
            String[] paths = StringUtils.split(classpath, File.pathSeparatorChar);
            for (String path : paths) {
                path = path.trim();
                if (path.length() > 0) {
                    URL url = URLUtils.fromFile(path);
                    urls.add(url);
                }
            }
        }

        // 添加包含所有的 META-INF/MANIFEST.MF 的 jar 文件
        try {
            Enumeration<URL> paths = classLoader.getResources("META-INF/MANIFEST.MF");
            while (paths.hasMoreElements()) {
                URL url = paths.nextElement();
                File file = URLUtils.toFileObject(url);
                urls.add(file.toURI().toURL());
            }
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        // 删除 jdk 自带的 jar
        Iterator<URL> it = urls.iterator();
        while (it.hasNext()) {
            String path = it.next().getPath();
            if (path.contains("/jre/lib/")) {
                it.remove();
            }
        }

        return urls;
    }

public static Collection<URL> getClasspathURLs(ClassLoader classLoader, String packageName) {
        if (packageName == null) {
            throw new IllegalArgumentException("PackageName must be not null.");
        }
        Collection<URL> urls = new ArrayList<URL>();
        String dirname = packageName.replace('.', '/');
        try {
            Enumeration<URL> dirs = classLoader.getResources(dirname);
            while (dirs.hasMoreElements()) {
                urls.add(dirs.nextElement());
            }
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
        return urls;
    }

@SuppressWarnings("PMD.NonThreadSafeSingleton")
    public static PasswordAuthenticator getSingleton(final String className, final CommonProperties properties)
            throws FactoryException {

        Validate.notBlank(className, "The validated character sequence 'className' is null or empty");
        Validate.notNull(properties, "The validated object 'properties' is null");

        if (passwordAuthenticatorInstance == null) {
            synchronized (PasswordAuthenticatorFactory.class) {
                if (passwordAuthenticatorInstance == null) {

                    passwordAuthenticatorInstance = getInstance(className, properties);
                }
            }
        }

        return passwordAuthenticatorInstance;
    }

public static ClassLoader getDefault() {
        ClassLoader loader = null;
        try {
            loader = Thread.currentThread().getContextClassLoader();
        } catch (Exception e) {
        }
        if (loader == null) {
            loader = ClassLoaderUtils.class.getClassLoader();
            if (loader == null) {
                loader = ClassLoader.getSystemClassLoader();
            }
        }
        return loader;
    }

public static Class<?> loadClass(final String qualifiedClassName, ClassLoader loader) {
        try {
            return loadClassEx(qualifiedClassName, loader);
        } catch (ClassNotFoundException e) {
            return null;
        }
    }

public static Class<?> loadClassEx(final String qualifiedClassName, final ClassLoader classLoader) throws ClassNotFoundException {
        Validate.notNull(qualifiedClassName, "qualifiedClassName must be not null");

        ClassLoader loader = (classLoader == null) ? getDefault() : classLoader;

        // 尝试基本类型
        if (abbreviationMap.containsKey(qualifiedClassName)) {
            String className = '[' + abbreviationMap.get(qualifiedClassName);
            return Class.forName(className, false, loader).getComponentType();
        }

        // 尝试用 Class.forName()
        try {
            String className = getCanonicalClassName(qualifiedClassName);
            return Class.forName(className, false, loader);
        } catch (ClassNotFoundException e) {
        }

        // 尝试当做一个内部类去识别
        if (qualifiedClassName.indexOf('$') == -1) {
            int ipos = qualifiedClassName.lastIndexOf('.');
            if (ipos > 0) {
                try {
                    String className = qualifiedClassName.substring(0, ipos) + '$' + qualifiedClassName.substring(ipos + 1);
                    className = getCanonicalClassName(className);
                    return Class.forName(className, false, loader);
                } catch (ClassNotFoundException e) {
                }
            }
        }

        throw new ClassNotFoundException(qualifiedClassName);
    }

public static String getCanonicalClassName(String qualifiedClassName) {
        Validate.notNull(qualifiedClassName, "qualifiedClassName must be not null");

        String name = StringUtils.deleteWhitespace(qualifiedClassName);
        if (name.endsWith("[]")) {
            StringBuilder sb = new StringBuilder();

            while (name.endsWith("[]")) {
                name = name.substring(0, name.length() - 2);
                sb.append('[');
            }

            String abbreviation = abbreviationMap.get(name);
            if (abbreviation != null) {
                sb.append(abbreviation);
            } else {
                sb.append('L').append(name).append(';');
            }

            name = sb.toString();
        }
        return name;
    }

public static URL getResource(String name, ClassLoader classLoader) {
        Validate.notNull(name, "resourceName must be not null");

        if (name.startsWith("/")) {
            name = name.substring(1);
        }
        if (classLoader != null) {
            URL url = classLoader.getResource(name);
            if (url != null) {
                return url;
            }
        }
        ClassLoader loader = Thread.currentThread().getContextClassLoader();
        if (loader != null && loader != classLoader) {
            URL url = loader.getResource(name);
            if (url != null) {
                return url;
            }
        }

        return ClassLoader.getSystemResource(name);
    }

public static InputStream getResourceAsStream(String name, ClassLoader classLoader) throws IOException {
        URL url = getResource(name, classLoader);
        if (url != null) {
            return url.openStream();
        }
        return null;
    }

public static InputStream getClassAsStream(Class<?> clazz) throws IOException {
        return getResourceAsStream(getClassFileName(clazz), clazz.getClassLoader());
    }

public static String getClassFileName(Class<?> clazz) {
        if (clazz.isArray()) {
            clazz = clazz.getComponentType();
        }
        return getClassFileName(clazz.getName());
    }

private void initialize(URI p_other) {
		m_scheme = p_other.getScheme();
		m_userinfo = p_other.getUserinfo();
		m_host = p_other.getHost();
		m_port = p_other.m_port;
		n_port = p_other.n_port;
		m_path = p_other.getPath();
		m_queryString = p_other.getQueryString();
		m_fragment = p_other.getFragment();
	}

private void initialize(URI p_base, String p_uriSpec)
		throws MalformedURIException {
		if (p_base == null && (p_uriSpec == null || p_uriSpec.length() == 0)) {
			throw new RelativeURIException("Cannot initialize URI with empty parameters.");
		}

		// just make a copy of the base if spec is empty
		if (p_uriSpec == null || p_uriSpec.length() == 0) {
			initialize(p_base);
			return;
		}

		String uriSpec = p_uriSpec;
		int uriSpecLen = uriSpec.length();
		int index = 0;

		// Check for scheme, which must be before '/', '?' or '#'. Also handle
		// names with DOS drive letters ('D:'), so 1-character schemes are not
		// allowed.
		int colonIdx = uriSpec.indexOf(':');
		int slashIdx = uriSpec.indexOf('/');
		int queryIdx = uriSpec.indexOf('?');
		int fragmentIdx = uriSpec.indexOf('#');

		if ((colonIdx < 2)
			|| (colonIdx > slashIdx && slashIdx != -1)
			|| (colonIdx > queryIdx && queryIdx != -1)
			|| (colonIdx > fragmentIdx && fragmentIdx != -1)) {
			// We need to do the relative URI algorithm:

			// jjc: the spec says:
			// 'URI-reference = [ absoluteURI | relativeURI ] [ "#" fragment ]'
			// My understanding is that if there is only the fragment
			// then this is a relative URI.
			if (p_base == null // del jjc: && fragmentIdx != 0
			) {
				// Nothing to be relative against.
				throw new RelativeURIException("No scheme found in URI." + p_uriSpec );
			} else {
				if ((!p_base.isGenericURI()) && fragmentIdx != 0)
					// Can't be relative against opaque URI (except using the #frag).
					throw new MalformedURIException("Cannot apply relative URI to an opaque URI");
			}
		} else {
			initializeScheme(uriSpec);
			index = m_scheme.length() + 1;
		}

		// two slashes means generic URI syntax, so we get the authority
		if (((index + 1) < uriSpecLen)
			&& (uriSpec.substring(index).startsWith("//"))) {
			index += 2;
			int startPos = index;

			// get authority - everything up to path, query or fragment
			char testChar = '\0';
			while (index < uriSpecLen) {
				testChar = uriSpec.charAt(index);
				if (testChar == '/' || testChar == '?' || testChar == '#') {
					break;
				}
				index++;
			}

			// if we found authority, parse it out, otherwise we set the
			// host to empty string
			if (index > startPos) {
				initializeAuthority(uriSpec.substring(startPos, index));
			} else {
				m_host = "";
			}
		}

		initializePath(uriSpec.substring(index));

		// Resolve relative URI to base URI - see RFC 2396 Section 5.2
		// In some cases, it might make more sense to throw an exception
		// (when scheme is specified is the string spec and the base URI
		// is also specified, for example), but we're just following the
		// RFC specifications
		if (p_base != null) {

			// check to see if this is the current doc - RFC 2396 5.2 #2
			// note that this is slightly different from the RFC spec in that
			// we don't include the check for query string being null
			// - this handles cases where the urispec is just a query
			// string or a fragment (e.g. "?y" or "#s") -
			// see <http://www.ics.uci.edu/~fielding/url/test1.html> which
			// identified this as a bug in the RFC
			if (m_path.length() == 0 && m_scheme == null && m_host == null) {
				m_scheme = p_base.getScheme();
				m_userinfo = p_base.getUserinfo();
				m_host = p_base.getHost();
				m_port = p_base.m_port;
				n_port = p_base.getPort();
				m_path = p_base.getPath();

				if (m_queryString == null) {
					m_queryString = p_base.getQueryString();
				}
				return;
			}

			// check for scheme - RFC 2396 5.2 #3
			// if we found a scheme, it means absolute URI, so we're done
			if (m_scheme == null) {
				m_scheme = p_base.getScheme();
			} else {
				return;
			}

			// check for authority - RFC 2396 5.2 #4
			// if we found a host, then we've got a network path, so we're done
			if (m_host == null) {
				m_userinfo = p_base.getUserinfo();
				m_host = p_base.getHost();
				m_port = p_base.m_port;
				n_port = p_base.getPort();
			} else {
				return;
			}

			// check for absolute path - RFC 2396 5.2 #5
			if (m_path.length() > 0 && m_path.startsWith("/")) {
				return;
			}

			// if we get to this point, we need to resolve relative path
			// RFC 2396 5.2 #6
				String path = // jjc new String();
	"/"; // jjc ins
			String basePath = p_base.getPath();

			// 6a - get all but the last segment of the base URI path
			if (basePath != null) {
				int lastSlash = basePath.lastIndexOf('/');
				if (lastSlash != -1) {
					path = basePath.substring(0, lastSlash + 1);
				}
			}

			// 6b - append the relative URI path
			path = path.concat(m_path);

			// 6c - remove all "./" where "." is a complete path segment
			index = -1;
			while ((index = path.indexOf("/./")) != -1) {
				path =
					path.substring(0, index + 1).concat(
						path.substring(index + 3));
			}

			// 6d - remove "." if path ends with "." as a complete path segment
			if (path.endsWith("/.")) {
				path = path.substring(0, path.length() - 1);
			}

			// 6e - remove all "<segment>/../" where "<segment>" is a complete
			// path segment not equal to ".."
			index = 1;
			int segIndex = -1;

			while ((index = path.indexOf("/../", index)) > 0) {
				segIndex = path.lastIndexOf('/', index - 1);
				if (segIndex != -1
					&& !path.substring(segIndex + 1, index).equals("..")) {
					path =
						path.substring(0, segIndex).concat(
							path.substring(index + 3));
					index = segIndex;
				} else {
					index += 4;
				}
			}

			// 6f - remove ending "<segment>/.." where "<segment>" is a
			// complete path segment
			if (path.endsWith("/..")) {
				index = path.length() - 3;
				segIndex = path.lastIndexOf('/', index - 1);
				if (segIndex != -1
					&& !path.substring(segIndex + 1, index).equals("..")) {
					path = path.substring(0, segIndex + 1);
				}
			}

			m_path = path;
		}
	}

private void initializeScheme(String p_uriSpec)
		throws MalformedURIException {
		int uriSpecLen = p_uriSpec.length();
		int index = p_uriSpec.indexOf(':');

		if (index < 1)
			throw new MalformedURIException("No scheme found in URI.");

		if (index == uriSpecLen - 1)
			throw new MalformedURIException("A bare scheme name is not a URI.");

		setScheme(p_uriSpec.substring(0, index));
	}

private void initializeAuthority(String p_uriSpec)
		throws MalformedURIException {
		int index = 0;
		int start = 0;
		int end = p_uriSpec.length();
		char testChar = '\0';
		String userinfo = null;

		// userinfo is everything up @
		if (p_uriSpec.indexOf('@', start) != -1) {
			while (index < end) {
				testChar = p_uriSpec.charAt(index);
				if (testChar == '@') {
					break;
				}
				index++;
			}
			userinfo = p_uriSpec.substring(start, index);
			index++;
		}

		// host is everything up to ':'
		String host = null;
		start = index;
		while (index < end) {
			testChar = p_uriSpec.charAt(index);
			if (testChar == ':') {
				break;
			}
			index++;
		}
		host = p_uriSpec.substring(start, index);
		int port = -1;
		if (host.length() > 0) {
			// port
			if (testChar == ':') {
				index++;
				start = index;
				while (index < end) {
					index++;
				}
				String portStr = p_uriSpec.substring(start, index);
				if (portStr.length() > 0) {
					for (int i = 0; i < portStr.length(); i++) {
						if (!isDigit(portStr.charAt(i))) {
							throw new MalformedURIException(
								portStr
									+ " is invalid. Port should only contain digits!");
						}
					}
					try {
						port = Integer.parseInt(portStr);
						m_port = portStr;
					} catch (NumberFormatException nfe) {
						// can't happen
					}
				}
			}
		}
		setHost(host);
		setPort(port);
		setUserinfo(userinfo);
	}

private void initializePath(String p_uriSpec)
		throws MalformedURIException {
		if (p_uriSpec == null) {
			throw new MalformedURIException("Cannot initialize path from null string!");
		}

		int index = 0;
		int start = 0;
		int end = p_uriSpec.length();
		char testChar = '\0';

		// path - everything up to query string or fragment
		while (index < end) {
			testChar = p_uriSpec.charAt(index);
			if (testChar == '?' || testChar == '#') {
				break;
			}
			// check for valid escape sequence
			if (testChar == '%') {
				if (index + 2 >= end
					|| !isHex(p_uriSpec.charAt(index + 1))
					|| !isHex(p_uriSpec.charAt(index + 2))) {
					throw new MalformedURIException("Path contains invalid escape sequence!");
				}
			} else if (
				!isReservedCharacter(testChar)
					&& !isUnreservedCharacter(testChar)) {
				throw new MalformedURIException(
					"Path contains invalid character: " + testChar);
			}
			index++;
		}
		m_path = p_uriSpec.substring(start, index);

		// query - starts with ? and up to fragment or end
		if (testChar == '?') {
			index++;
			start = index;
			while (index < end) {
				testChar = p_uriSpec.charAt(index);
				if (testChar == '#') {
					break;
				}
				if (testChar == '%') {
					if (index + 2 >= end
						|| !isHex(p_uriSpec.charAt(index + 1))
						|| !isHex(p_uriSpec.charAt(index + 2))) {
						throw new MalformedURIException("Query string contains invalid escape sequence!");
					}
				} else if (
					!isReservedCharacter(testChar)
						&& !isUnreservedCharacter(testChar)) {
					throw new MalformedURIException(
						"Query string contains invalid character:" + testChar);
				}
				index++;
			}
			m_queryString = p_uriSpec.substring(start, index);
		}

		// fragment - starts with #
		if (testChar == '#') {
			index++;
			start = index;
			while (index < end) {
				testChar = p_uriSpec.charAt(index);

				if (testChar == '%') {
					if (index + 2 >= end
						|| !isHex(p_uriSpec.charAt(index + 1))
						|| !isHex(p_uriSpec.charAt(index + 2))) {
						throw new MalformedURIException("Fragment contains invalid escape sequence!");
					}
				} else if (
					!isReservedCharacter(testChar)
						&& !isUnreservedCharacter(testChar)) {
					throw new MalformedURIException(
						"Fragment contains invalid character:" + testChar);
				}
				index++;
			}
			m_fragment = p_uriSpec.substring(start, index);
		}
	}

public String getSchemeSpecificPart() {
		StringBuffer schemespec = new StringBuffer();

		if (m_userinfo != null || m_host != null || m_port != null) {
			schemespec.append("//");
		}

		if (m_userinfo != null) {
			schemespec.append(m_userinfo);
			schemespec.append('@');
		}

		if (m_host != null) {
			schemespec.append(m_host);
		}

		if (m_port != null) {
			schemespec.append(':');
			schemespec.append(m_port);
		}

		if (m_path != null) {
			schemespec.append((m_path));
		}

		if (m_queryString != null) {
			schemespec.append('?');
			schemespec.append(m_queryString);
		}

		if (m_fragment != null) {
			schemespec.append('#');
			schemespec.append(m_fragment);
		}

		return schemespec.toString();
	}

private void setScheme(String p_scheme) throws MalformedURIException {
		if (p_scheme == null) {
			throw new MalformedURIException("Cannot set scheme from null string!");
		}
		if (!isConformantSchemeName(p_scheme)) {
			throw new MalformedURIException("The scheme is not conformant.");
		}

		m_scheme = p_scheme; //.toLowerCase();
	}

private void setUserinfo(String p_userinfo) throws MalformedURIException {
		if (p_userinfo == null) {
			m_userinfo = null;
		} else {
			if (m_host == null) {
				throw new MalformedURIException("Userinfo cannot be set when host is null!");
			}

			// userinfo can contain alphanumerics, mark characters, escaped
			// and ';',':','&','=','+','$',','
			int index = 0;
			int end = p_userinfo.length();
			char testChar = '\0';
			while (index < end) {
				testChar = p_userinfo.charAt(index);
				if (testChar == '%') {
					if (index + 2 >= end
						|| !isHex(p_userinfo.charAt(index + 1))
						|| !isHex(p_userinfo.charAt(index + 2))) {
						throw new MalformedURIException("Userinfo contains invalid escape sequence!");
					}
				} else if (
					!isUnreservedCharacter(testChar)
						&& USERINFO_CHARACTERS.indexOf(testChar) == -1) {
					throw new MalformedURIException(
						"Userinfo contains invalid character:" + testChar);
				}
				index++;
			}
		}
		m_userinfo = p_userinfo;
	}

private void setHost(String p_host) throws MalformedURIException {
		if (p_host == null || p_host.length() == 0) {
			m_host = p_host;
			m_userinfo = null;
			m_port = null;
			n_port = -1;
		} else if (!isWellFormedAddress(p_host)) {
			throw new MalformedURIException("Host is not a well formed address!");
		}
		m_host = p_host;
	}

private void setPort(int p_port) throws MalformedURIException {
		if (p_port >= 0 && p_port <= 65535) {
			if (m_host == null) {
				throw new MalformedURIException("Port cannot be set when host is null!");
			}
		} else if (p_port != -1) {
			throw new MalformedURIException("Invalid port number!");
		}
		n_port = p_port;

	}

private void setPath(String p_path) throws MalformedURIException {
		if (p_path == null) {
			m_path = null;
			m_queryString = null;
			m_fragment = null;
		} else {
			initializePath(p_path);
		}
	}

private void appendPath(String p_addToPath) throws MalformedURIException {
		if (p_addToPath == null || p_addToPath.length() == 0) {
			return;
		}

		if (!isURIString(p_addToPath)) {
			throw new MalformedURIException("Path contains invalid character!");
		}

		if (m_path == null || m_path.length() == 0) {
			if (p_addToPath.startsWith("/")) {
				m_path = p_addToPath;
			} else {
				m_path = "/" + p_addToPath;
			}
		} else if (m_path.endsWith("/")) {
			if (p_addToPath.startsWith("/")) {
				m_path = m_path.concat(p_addToPath.substring(1));
			} else {
				m_path = m_path.concat(p_addToPath);
			}
		} else {
			if (p_addToPath.startsWith("/")) {
				m_path = m_path.concat(p_addToPath);
			} else {
				m_path = m_path.concat("/" + p_addToPath);
			}
		}
	}

private void setQueryString(String p_queryString)
		throws MalformedURIException {
		if (p_queryString == null) {
			m_queryString = null;
		} else if (!isGenericURI()) {
			throw new MalformedURIException("Query string can only be set for a generic URI!");
		} else if (getPath() == null) {
			throw new MalformedURIException("Query string cannot be set when path is null!");
		} else if (!isURIString(p_queryString)) {
			throw new MalformedURIException("Query string contains invalid character!");
		} else {
			m_queryString = p_queryString;
		}
	}

public void setFragment(String p_fragment) throws MalformedURIException {
		if (p_fragment == null) {
			m_fragment = null;
		} else if (!isGenericURI()) {
			throw new MalformedURIException("Fragment can only be set for a generic URI!");
		} else if (getPath() == null) {
			throw new MalformedURIException("Fragment cannot be set when path is null!");
		} else if (!isURIString(p_fragment)) {
			throw new MalformedURIException("Fragment contains invalid character!");
		} else {
			m_fragment = p_fragment;
		}
	}

public String getURIString() {
		StringBuffer uriSpecString = new StringBuffer();

		if (m_scheme != null) {
			uriSpecString.append(m_scheme);
			uriSpecString.append(':');
		}
		uriSpecString.append(getSchemeSpecificPart());
		return uriSpecString.toString();
	}

public static boolean isWellFormedAddress(String p_address) {
		if (p_address == null) {
			return false;
		}

		String address = p_address;
		int addrLength = address.length();
		if (addrLength == 0 || addrLength > 255) {
			return false;
		}

		if (address.startsWith(".") || address.startsWith("-")) {
			return false;
		}

		// rightmost domain label starting with digit indicates IP address
		// since top level domain label can only start with an alpha
		// see RFC 2396 Section 3.2.2
		int index = address.lastIndexOf('.');
		if (address.endsWith(".")) {
			index = address.substring(0, index).lastIndexOf('.');
		}

		if (index + 1 < addrLength && isDigit(p_address.charAt(index + 1))) {
			char testChar;
			int numDots = 0;

			// make sure that 1) we see only digits and dot separators, 2) that
			// any dot separator is preceded and followed by a digit and
			// 3) that we find 3 dots
			for (int i = 0; i < addrLength; i++) {
				testChar = address.charAt(i);
				if (testChar == '.') {
					if (!isDigit(address.charAt(i - 1))
						|| (i + 1 < addrLength
							&& !isDigit(address.charAt(i + 1)))) {
						return false;
					}
					numDots++;
				} else if (!isDigit(testChar)) {
					return false;
				}
			}
			if (numDots != 3) {
				return false;
			}
		} else {
			// domain labels can contain alphanumerics and '-"
			// but must start and end with an alphanumeric
			char testChar;

			for (int i = 0; i < addrLength; i++) {
				testChar = address.charAt(i);
				if (testChar == '.') {
					if (!isAlphanum(address.charAt(i - 1))) {
						return false;
					}
					if (i + 1 < addrLength
						&& !isAlphanum(address.charAt(i + 1))) {
						return false;
					}
				} else if (!isAlphanum(testChar) && testChar != '-') {
					return false;
				}
			}
		}
		return true;
	}

public static byte[] encodeToByte(String s) {
        try {
            return encodeToByte(s.getBytes(ENCODING), false);
        } catch (UnsupportedEncodingException ignore) {
            return null;
        }
    }

public static String encodeToString(String s) {
        try {
            return new String(encodeToChar(s.getBytes(ENCODING), false));
        } catch (UnsupportedEncodingException ignore) {
            return null;
        }
    }

@Override
  public final void write(final Map<String, Object> pAddParam,
    final Object pField, final String pFieldName,
      final Writer pWriter) throws Exception {
    String fieldValue;
    if (pField == null) {
      fieldValue = "NULL";
    } else if (Enum.class.isAssignableFrom(pField.getClass())) {
      fieldValue = String.valueOf(((Enum) pField).ordinal());
    } else if (pField.getClass() == Date.class) {
      fieldValue = String.valueOf(((Date) pField).getTime());
    } else {
      fieldValue = pField.toString();
      if (pField instanceof String) {
        fieldValue = getUtilXml().escapeXml(fieldValue);
      }
    }
    pWriter.write(" " + pFieldName + "=\"" + fieldValue
      + "\"\n");
  }

protected static PreparedStatement createByIterator(Connection conn, String sql, Iterator<?> parameters) throws SQLException {
        PreparedStatement ps = conn.prepareStatement(sql);
        if (parameters != null) {
            int index = 1;
            while (parameters.hasNext()) {
                Object parameter = parameters.next();
                if (parameter == null) {
                    ps.setObject(index, null);
                } else {
                    ps.setObject(index, parameter);
                }
                index++;
            }
        }
        return ps;
    }

protected static PreparedStatement createByMap(Connection conn, String sql, Map<String, ?> parameters) throws SQLException {
        StringBuffer sb = new StringBuffer();
        List<Object> params = new ArrayList<Object>();

        Matcher m = namedParameterPattern.matcher(sql);
        while (m.find()) {
            String key = m.group(1);
            Object value = parameters.get(key);
            if (value == null) {
                params.add(null);
                m.appendReplacement(sb, "?");
            } else if (value instanceof Object[]) {
                Object[] array = (Object[]) value;
                if (array.length == 0) {
                    params.add(null);
                    m.appendReplacement(sb, "?");
                } else {
                    for (Object one : array) {
                        params.add(one);
                    }
                    m.appendReplacement(sb, StringUtils.repeat("?", ",", array.length));
                }
            } else if (value instanceof Collection) {
                Collection<?> collection = (Collection<?>) value;
                if (collection.size() == 0) {
                    params.add(null);
                    m.appendReplacement(sb, "?");
                } else {
                    for (Object one : collection) {
                        params.add(one);
                    }
                    m.appendReplacement(sb, StringUtils.repeat("?", ",", collection.size()));
                }
            } else {
                params.add(value);
                m.appendReplacement(sb, "?");
            }
        }
        m.appendTail(sb);

        return createByIterator(conn, sb.toString(), params.iterator());
    }

