public static void postMessage(final MessageQ messageQ, final String domain, final String username,
                                   final Events event, final String error)
            throws LoginException {

        // "messageQ" may be null, not validating here (see below)
        Validate.notBlank(domain, "The validated character sequence 'domain' is null or empty");
        Validate.notBlank(username, "The validated character sequence 'username' is null or empty");
        Validate.notNull(event, "The validated object 'event' is null");
        Validate.notBlank(error, "The validated character sequence 'error' is null or empty");

        // if message queues are disabled, the messageQ object will not have been initialized
        if (messageQ == null) {
            // string concatenation is only executed if log level is actually enabled
            if (LOG.isDebugEnabled()) {
                LOG.debug("Messages queues have been disabled, not creating event '"
                        + event.getValue() + "' for '" + username + "@" + domain + "'");
            }
        } else {
            try {
                messageQ.create(event, domain, username);
            } catch (MessageQException e) {
                LOG.warn(error, e);
                throw Util.newLoginException(error, e);
            }
        }
    }

@Override
    // Cannot change the interface to use varags, this interface is owned by javax.security
    @SuppressWarnings("PMD.UseVarargs")
    public final void handle(final Callback[] callbacks)
            throws IOException, UnsupportedCallbackException {

        Validate.notNull(callbacks, "The validated object 'callbacks' is null");

        for (final Callback callback : callbacks) {
            if (callback instanceof NameCallback) {
                final NameCallback nameCallback = (NameCallback) callback;
                nameCallback.setName(username);
            } else if (callback instanceof PasswordCallback) {
                final PasswordCallback passwordCallback = (PasswordCallback) callback;
                passwordCallback.setPassword(password);
            } else if (callback instanceof TextInputCallback) {
                final TextInputCallback textInputCallback = (TextInputCallback) callback;
                textInputCallback.setText(domain);
            } else {
                final String error = "Unsupported callback: "
                        + callback.getClass().getCanonicalName() + " Allowed callbacks are: "
                        + NameCallback.class.getCanonicalName() + " OR "
                        + PasswordCallback.class.getCanonicalName() + " OR "
                        + TextInputCallback.class.getCanonicalName();
                LOG.warn(error);
                throw new UnsupportedCallbackException(callback, error);
            }
        }
    }

@Override
  public final void write(final Map<String, Object> pAddParam,
    final Object pEntity, final Writer pWriter) throws Exception {
    Map<String, Map<String, String>> fieldsSettingsMap =
      getMngSettings().lazFldsSts(pEntity.getClass());
    pWriter.write("<entity class=\"" + pEntity.getClass().getCanonicalName()
      + "\"\n");
    for (Map.Entry<String, Map<String, String>> entry
      : fieldsSettingsMap.entrySet()) {
      if ("true".equals(entry.getValue().get("isEnabled"))) {
        Field field = getUtlReflection()
          .retrieveField(pEntity.getClass(), entry.getKey());
        field.setAccessible(true);
        Object fieldValue = field.get(pEntity);
        ISrvFieldWriter srvFieldWriter = getFieldsWritersMap()
          .get(entry.getValue().get("ISrvFieldWriter"));
        if (srvFieldWriter == null) {
          throw new ExceptionWithCode(ExceptionWithCode
            .CONFIGURATION_MISTAKE, "There is no ISrvFieldWriter " + entry
              .getValue().get("ISrvFieldWriter") + " for "
                + pEntity.getClass() + " / " + field.getName());
        }
        srvFieldWriter.write(pAddParam, fieldValue, field.getName(), pWriter);
      }
    }
    pWriter.write("/>\n");
  }

