public void process(List argumentList) throws InvalidArgumentsException {
		Set<Method> requiredArguments = new HashSet<Method>();
		NamedAttributeProcessor namedAttributeProcessor = new NamedAttributeProcessor();
		for (final Method m : annotated.getMethods()) {
			if (m.isAnnotationPresent(CommandLine.class)) {
				final CommandLine cl = m.getAnnotation(CommandLine.class);
				if (cl.required()) {
					requiredArguments.add(m);
				}
				for (final String longName : cl.longName()) {
					namedAttributeProcessor
							.addLongNameAttributeProcessor(new MySingleNamedAttributeProcessor(
									longName, cl, m));
				}
				for (final String shortName : cl.shortName()) {
					namedAttributeProcessor
							.addNamedAttributeProcessor(new MySingleNamedAttributeProcessor(
									shortName, cl, m));
				}
			}
		}
		Set<CommandLine> missingArguments = new HashSet<CommandLine>();
		namedAttributeProcessor.process(argumentList);
		for (Iterator<Method> iter = requiredArguments.iterator(); iter
				.hasNext();) {
			Method current = iter.next();
			if (!valueMap.containsKey(current)) {
				missingArguments.add(current.getAnnotation(CommandLine.class));
			}
		}
		if (missingArguments.size() > 0) {
			throw new MissingArgumentException(missingArguments);
		}
	}

public final Subject authenticate(final String domain, final String userName, final char[] password,
                                      final PasswordValidator passwordValidator)
            throws LoginException {

        // make sure the credentials are not null
        if (domain == null) {
            throw new LoginException("The domain cannot be null");
        }
        if (userName == null) {
            throw new LoginException("The username cannot be null");
        }
        if (password == null) {
            throw new LoginException("The password cannot be null");
        }

        // no need for defensive copies of Strings, but create a defensive copy of the password
        final char[] myPassword = password.clone();

        // convert the username string to a char array
        final char[] myCredential = userName.toCharArray();

        // perform the password validation
        if (!passwordValidator.validate(myPassword, myCredential)) {
            final String error = "Invalid password for username '" + userName + "'";
            LOG.info(error);
            throw new FailedLoginException(error);
        }

        // The authentication was successful!
        // Create the subject and clean up confidential data as far as possible.

        // clear the char representation of the credential
        Cleanser.wipe(myCredential);

        // clear the defensive copy of the password created earlier
        Cleanser.wipe(myPassword);

        // create a principal that includes the username and domain name that were used to authenticate the user
        final UserPrincipal userPrincipal = new UserPrincipal("ID:" + userName, domain, userName);

        // wrap the principal in a Subject
        final Subject subject = new Subject();
        subject.getPrincipals().add(userPrincipal);

        return subject;
    }

@Override
  public final void readAndStoreEntities(final Map<String, Object> pAddParam,
    final Reader pReader) throws Exception {
    try {
      this.srvDatabase.setIsAutocommit(false);
      this.srvDatabase.
        setTransactionIsolation(ISrvDatabase.TRANSACTION_READ_UNCOMMITTED);
      this.srvDatabase.beginTransaction();
      while (this.utilXml.readUntilStart(pReader, "entity")) {
        Object entity = this.srvEntityReader.read(pAddParam, pReader);
        String nameEntitySync = this.mngSettings.lazClsSts(entity.getClass())
          .get("ISrvEntitySync");
        ISrvEntitySync srvEntitySync = this.srvEntitySyncMap
          .get(nameEntitySync);
        if (srvEntitySync == null) {
          throw new ExceptionWithCode(ExceptionWithCode
            .CONFIGURATION_MISTAKE, "There is no ISrvEntitySync "
              + nameEntitySync + " for " + entity.getClass());
        }
        boolean isNew = srvEntitySync.sync(pAddParam, entity);
        if (isNew) {
          this.srvOrm.insertEntity(pAddParam, entity);
        } else {
          this.srvOrm.updateEntity(pAddParam, entity);
        }
      }
      this.srvDatabase.commitTransaction();
    } catch (Exception ex) {
      this.srvDatabase.rollBackTransaction();
      throw ex;
    } finally {
      this.srvDatabase.releaseResources();
    }
  }

