public static void addParam(Properties properties, String strParams, boolean bDecodeString)
    {
        int iIndex = strParams.indexOf('=');
        int iEndIndex = strParams.length();
        if (iIndex != -1)
        {
            String strParam = strParams.substring(0, iIndex);
            String strValue = strParams.substring(iIndex + 1, iEndIndex);
            if (bDecodeString)
            {
                try {
                    strParam = URLDecoder.decode(strParam, URL_ENCODING);
                    strValue = URLDecoder.decode(strValue, URL_ENCODING);
                } catch (java.io.UnsupportedEncodingException ex) {
                    ex.printStackTrace();
                }
            }
            properties.put(strParam, strValue);
        }
    }

public void register(ActionInfo action, String url) {
        if (url.indexOf('{') == -1) {
            staticUrls.put(url, new RouteInfo(action));
        } else {
            String[] urlSegments = StringUtils.split(url.substring(1), '/');
            if (urlSegments.length >= MAX_PATH_PARTS) {
                throw new IllegalStateException("exceed max url parts: " + url);
            }
            OneByOneMatcher matcher = matchers[urlSegments.length];
            if (matcher == null) {
                matcher = new OneByOneMatcher();
                matchers[urlSegments.length] = matcher;
            }
            matcher.register(action, urlSegments);
        }
    }

