public boolean proofStep(ResolutionState state)
    {
        Functor goalTerm = state.getGoalStack().poll().getFunctor();

        Term leftArg = goalTerm.getArgument(0);
        Term rightArg = goalTerm.getArgument(1);

        // This is used to record variables bound during the unification, so that they may be undone if the resolution
        // state is backtracked over.
        List<Variable> boundVariables = new LinkedList<Variable>();

        // Unify the current query goal with the possibly matching clause, creating variable bindings.
        boolean matched = state.getUnifier().unifyInternal(leftArg, rightArg, boundVariables, boundVariables);

        if (matched)
        {
            if (TRACE)
            {
                /*trace.fine(state.getTraceIndenter().generateTraceIndent() + "Unify " +
                    leftArg.toString(state.getInterner(), true, true) + " against " +
                    rightArg.toString(state.getInterner(), true, true) + ", ok.");*/
            }

            for (Variable binding : boundVariables)
            {
                state.getVariableBindings().offer(binding);
            }
        }

        return matched;
    }

public QueryParameter partialCopy(final QueryParameterKind... excludedElements) {
        List<QueryParameterKind> excludedList = Arrays.asList(excludedElements);
        QueryParameter returnValue = new QueryParameter();
        if (!excludedList.contains(QueryParameterKind.CONSTRAINTS)) {
            returnValue.rawConstraints = this.rawConstraints;
        }
        if (!excludedList.contains(QueryParameterKind.GROUPS)) {
            returnValue.groups = this.groups;
        }
        if (!excludedList.contains(QueryParameterKind.ORDERS)) {
            returnValue.orders = this.orders;
        }
        if (!excludedList.contains(QueryParameterKind.PAGE)) {
            returnValue.pageSize = this.pageSize;
            returnValue.page = this.page;
        }
        if (!excludedList.contains(QueryParameterKind.TIMEZONE)) {
            returnValue.timezoneName = this.timezoneName;
        }

        return returnValue;
    }

public void addChild(Tree<E> child)
    {
        initChildren();

        // Add the new child to the collection of children.
        children.add(child);

        // Set the type of this point in the tree to a node as it now has children.
        nodeOrLeaf = Type.Node;

        // Set the new childs parent to this.
        child.setParent(this);
    }

public void clearChildren()
    {
        // Check that their are children to clear.
        if (children != null)
        {
            // Loop over all the children setting their parent to null.
            for (Tree<E> child : children)
            {
                child.setParent(null);
            }

            // Clear out the children collection.
            children.clear();

            // Mark this as a leaf node.
            nodeOrLeaf = Type.Leaf;
        }
    }

public E next()
    {
        // Consume the next element in the sequence, if one is available.
        E result = nextInternal();

        if (exhausted)
        {
            throw new NoSuchElementException();
        }

        nextSolution = null;

        return result;
    }

private E nextInternal()
    {
        // Check if the next soluation has already been cached, because of a call to hasNext.
        if (nextSolution != null)
        {
            return nextSolution;
        }

        // Otherwise, generate the next solution, if possible.
        nextSolution = nextInSequence();

        // Check if the solution was null, which indicates that the search space is exhausted.
        if (nextSolution == null)
        {
            exhausted = true;
        }

        return nextSolution;
    }

public void addInstructions(Functor body, SizeableList<WAMInstruction> instructions)
    {
        int oldLength;

        if (this.body == null)
        {
            oldLength = 0;
            this.body = new Functor[1];
        }
        else
        {
            oldLength = this.body.length;
            this.body = Arrays.copyOf(this.body, oldLength + 1);
        }

        this.body[oldLength] = body;

        addInstructionsAndThisToParent(instructions);
    }

private void addInstructionsAndThisToParent(SizeableList<WAMInstruction> instructions)
    {
        if (!addedToParent)
        {
            parent.addInstructions(this, instructions);
            addedToParent = true;
        }
        else
        {
            parent.addInstructions(instructions);
        }
    }

protected NumericType evaluate(NumericType firstNumber, NumericType secondNumber)
    {
        // If either of the arguments is a real number, then use real number arithmetic, otherwise use integer arithmetic.
        if (firstNumber.isInteger() && secondNumber.isInteger())
        {
            return new IntLiteral(firstNumber.intValue() - secondNumber.intValue());
        }
        else
        {
            return new DoubleLiteral(firstNumber.doubleValue() - secondNumber.doubleValue());
        }
    }

