public void reset()
    {
        // Clear out the start states.
        startStates.clear();
        enqueuedOnce = false;

        // Reset the queue to a fresh empty queue.
        queue = createQueue();

        // Clear the goal predicate.
        goalPredicate = null;

        // Reset the maximum steps limit
        maxSteps = 0;

        // Reset the number of steps taken
        searchSteps = 0;

        // Reset the repeated state filter if there is one.
        if (repeatedStateFilter != null)
        {
            repeatedStateFilter.reset();
        }

        // Reset the search alogorithm if it requires resettting.
        searchAlgorithm.reset();
    }

public Queue<SearchNode<O, T>> enqueueStartStates(Collection<T> startStates)
    {
        // Check that there are some start states
        if (!startStates.isEmpty())
        {
            // Only enqueue the start states if they have not already been enqueued.
            if (!enqueuedOnce)
            {
                // Enqueue all the start states
                for (T nextStartState : startStates)
                {
                    // If the goal predicate has not been defined, try to set up the default from the initial search
                    // states.
                    if (goalPredicate == null)
                    {
                        goalPredicate = nextStartState.getDefaultGoalPredicate();
                    }

                    // Make search nodes out of the start states using the abstract search node creation method,
                    // subclasses override this to create different kinds of search node.
                    SearchNode newStartNode = createSearchNode(nextStartState);

                    // Check if a repeated state filter has been applied and attach it to the start node if so.
                    if (repeatedStateFilter != null)
                    {
                        // Attach it to the start node.
                        newStartNode.setRepeatedStateFilter(repeatedStateFilter);
                    }

                    // Insert the new start search node onto the queue.
                    queue.offer(newStartNode);
                }
            }
        }
        else
        {
            // There are no start states so raise an exception because the search cannot be run without a start state.
            throw new IllegalStateException("Cannot start the search because there are no start states defined. " +
                "Queue searches require some start states.", null);
        }

        // Check that a goal predicate is set up.
        if (goalPredicate == null)
        {
            throw new IllegalStateException("Cannot start the search because there is no goal predicate.", null);
        }

        // Set the enqueuedOnce flag to indicate that the start states have already been enqueued.
        enqueuedOnce = true;

        return queue;
    }

public SearchNode<O, T> findGoalPath() throws SearchNotExhaustiveException
    {
        // Delegate the search to the pluggable search algorithm.
        return searchAlgorithm.search(this, startStates, maxSteps, searchSteps);
    }

public T search() throws SearchNotExhaustiveException
    {
        SearchNode<O, T> path = findGoalPath();

        if (path != null)
        {
            return path.getState();
        }
        else
        {
            return null;
        }
    }

public boolean proofStep(ResolutionState state)
    {
        Functor isOp = state.getGoalStack().poll().getFunctor();

        // Evaluate the second argument as a fully instantiated numeric value.
        Term expressionValue = BuiltInUtils.evaluateAsNumeric(isOp.getArgument(1));

        // This is used to record variables bound during the unification, so that they may be undone if the resolution
        // state is backtracked over.
        List<Variable> boundVariables = new LinkedList<Variable>();

        // Unify against the LHS.
        boolean matched =
            state.getUnifier().unifyInternal(isOp.getArgument(0), expressionValue, boundVariables, boundVariables);

        for (Variable binding : boundVariables)
        {
            state.getVariableBindings().offer(binding);
        }

        return matched;
    }

public static Type createInstance(String name, int min, int max)
    {
        // Ensure that min is less than or equal to max.
        if (min > max)
        {
            throw new IllegalArgumentException("'min' must be less than or equal to 'max'.");
        }

        synchronized (INT_RANGE_TYPES)
        {
            // Add the newly created type to the map of all types.
            IntRangeType newType = new IntRangeType(name, min, max);

            // Ensure that the named type does not already exist, unless it has an identical definition already, in which
            // case the old definition can be re-used and the new one discarded.
            IntRangeType oldType = INT_RANGE_TYPES.get(name);

            if ((oldType != null) && !oldType.equals(newType))
            {
                throw new IllegalArgumentException("The type '" + name + "' already exists and cannot be redefined.");
            }
            else if ((oldType != null) && oldType.equals(newType))
            {
                return oldType;
            }
            else
            {
                INT_RANGE_TYPES.put(name, newType);

                return newType;
            }
        }
    }

public Set<Integer> getAllPossibleValuesSet() throws InfiniteValuesException
    {
        Set<Integer> results = new HashSet<Integer>();

        for (int i = minValue; i <= maxValue; i++)
        {
            results.add(i);
        }

        return results;
    }

public Iterator<Integer> getAllPossibleValuesIterator() throws InfiniteValuesException
    {
        return new Iterator<Integer>()
            {
                int current = minValue;

                /** {@inheritDoc} */
                public boolean hasNext()
                {
                    return current <= maxValue;
                }

                /** {@inheritDoc} */
                public Integer next()
                {
                    if (hasNext())
                    {
                        int result = current;
                        current++;

                        return result;
                    }
                    else
                    {
                        throw new NoSuchElementException("No more elements less than or equal to max.");
                    }
                }

                /** {@inheritDoc} */
                public void remove()
                {
                    throw new UnsupportedOperationException("This iterator does not support 'remove'.");
                }
            };
    }

protected NumericType evaluate(NumericType firstNumber, NumericType secondNumber)
    {
        // If either of the arguments is a real number, then use real number arithmetic, otherwise use integer arithmetic.
        if (firstNumber.isInteger() && secondNumber.isInteger())
        {
            int n1 = firstNumber.intValue();
            int n2 = secondNumber.intValue();

            int result = 1;

            for (int i = 0; i < n2; i++)
            {
                result *= n1;
            }

            return new IntLiteral(result);
        }
        else
        {
            return new DoubleLiteral(Math.pow(firstNumber.doubleValue(), secondNumber.doubleValue()));
        }
    }

public boolean proofStep(ResolutionState state)
    {
        // Flatten the head goal on the disjunction operator to produce a series of choice points.
        Functor goalTerm = state.getGoalStack().poll().getFunctor();

        disjuncts = TermUtils.flattenTerm(goalTerm, Functor.class, state.getInterner().internFunctorName(";", 2));

        return true;
    }

public void createContinuationStates(ResolutionState state)
    {
        for (Functor disjunct : disjuncts)
        {
            BuiltInFunctor newGoal = state.getBuiltInTransform().apply(disjunct);
            newGoal.setParentChoicePointState(state);
            state.createContinuationStatesForGoal(newGoal);
        }
    }

