public int compareTo(DateOnly o)
    {
        if (year < o.year)
        {
            return -1;
        }
        else if (year > o.year)
        {
            return 1;
        }
        else if (month < o.month)
        {
            return -1;
        }
        else if (month > o.month)
        {
            return 1;
        }
        else if (day < o.day)
        {
            return -1;
        }
        else if (day > o.day)
        {
            return 1;
        }
        else
        {
            return 0;
        }
    }

