public void accept(TermVisitor visitor)
    {
        if (visitor instanceof PredicateVisitor)
        {
            ((PredicateVisitor) visitor).visit(this);
        }
        else
        {
            super.accept(visitor);
        }
    }

public Functor apply(Functor functor)
    {
        FunctorName functorName = defaultBuiltIn.getInterner().getFunctorFunctorName(functor);

        Class<? extends BuiltInFunctor> builtInClass;

        builtInClass = builtIns.get(functorName);

        if (builtInClass != null)
        {
            return ReflectionUtils.newInstance(ReflectionUtils.getConstructor(builtInClass,
                    new Class[] { Functor.class, DefaultBuiltIn.class }), new Object[] { functor, defaultBuiltIn });
        }
        else
        {
            return functor;
        }
    }

public void setArguments(Term[] arguments)
    {
        // Check that there is at least one and at most two arguments.
        if ((arguments == null) || (arguments.length < 1) || (arguments.length > 2))
        {
            throw new IllegalArgumentException("An operator has minimum 1 and maximum 2 arguments.");
        }

        this.arguments = arguments;
        this.arity = arguments.length;
    }

public Fixity getFixity()
    {
        switch (associativity)
        {
        case FX:
        case FY:
            return Fixity.Pre;

        case XF:
        case YF:
            return Fixity.Post;

        case XFX:
        case XFY:
        case YFX:
            return Fixity.In;

        default:
            throw new IllegalStateException("Unknown associativity.");
        }
    }

public boolean isInfix()
    {
        return ((associativity == Associativity.XFY) || (associativity == Associativity.YFX) ||
            (associativity == Associativity.XFX));
    }

public int compareTo(Object o)
    {
        OpSymbol opSymbol = (OpSymbol) o;

        return (priority < opSymbol.priority) ? -1 : ((priority > opSymbol.priority) ? 1 : 0);
    }

public void propertyChange(PropertyChangeEvent event)
    {
        /*log.fine("void propertyChange(PropertyChangeEvent): called");*/

        /*log.fine("source class = " + event.getSource().getClass());*/
        /*log.fine("source object = " + event.getSource());*/
        /*log.fine("property name = " + event.getPropertyName());*/
        /*log.fine("new value = " + event.getNewValue());*/
        /*log.fine("old value = " + event.getOldValue());*/

        Object source = event.getSource();
        Object oldValue = event.getOldValue();
        String propertyName = event.getPropertyName();

        // Check if the event source is an individual screen state
        if (source instanceof WorkFlowScreenState)
        {
            WorkFlowScreenState wfsState = (WorkFlowScreenState) source;

            // Update the buttons to reflect the change in screen state
            updateButtonsForScreen(wfsState);
        }

        // Check if the event source is the whole work flow
        if (source instanceof WorkFlowState)
        {
            WorkFlowState wfState = (WorkFlowState) source;

            // Check if the event cause is a change in current screen
            if ("currentScreenState".equals(propertyName))
            {
                WorkFlowScreenState newScreenState = wfState.getCurrentScreenState();
                WorkFlowScreenState oldScreenState = (WorkFlowScreenState) oldValue;

                // De-register this as a listener for the old current screen state
                if (oldScreenState != null)
                {
                    oldScreenState.removePropertyChangeListener(this);
                }

                // Register this as a listener for the new current screen state
                if (newScreenState != null)
                {
                    newScreenState.addPropertyChangeListener(this);
                }

                // Update the buttons to reflect the current screen state
                updateButtonsForScreen(newScreenState);
            }

            // Check if the event cause is a change in the work flow state
            else if ("state".equals(propertyName))
            {
                // Update the buttons to reflect the change in state
                updateButtonsForWorkFlow(wfState);
            }
        }
    }

public void updateButtonsForScreen(WorkFlowScreenState state)
    {
        // Check if it is in the READY or NOT_SAVED state
        if (state.getState().equals(WorkFlowScreenState.READY) ||
                state.getState().equals(WorkFlowScreenState.NOT_SAVED))
        {
            backButton.setEnabled(state.isPrevAvailable());
            nextButton.setEnabled(state.isNextAvailable());
            finishButton.setEnabled(state.isFinished());
        }

        // Check if it is in the NOT_INITIALIZED state
        if (state.getState().equals(WorkFlowScreenState.NOT_INITIALIZED))
        {
            backButton.setEnabled(false);
            nextButton.setEnabled(false);
            finishButton.setEnabled(false);
        }
    }

public void updateButtonsForWorkFlow(WorkFlowState state)
    {
        // Check if it is in the NOT_INITIALIZED state
        if (state.getState().equals(WorkFlowState.NOT_INITIALIZED))
        {
            backButton.setEnabled(false);
            nextButton.setEnabled(false);
            finishButton.setEnabled(false);
            cancelButton.setEnabled(false);
        }

        // Check if it is in the READY state
        if (state.getState().equals(WorkFlowState.READY))
        {
            finishButton.setEnabled(false);
            cancelButton.setEnabled(true);

            // Update buttons for the current screen state
            updateButtonsForScreen(state.getCurrentScreenState());
        }

        // Check if it is in the NOT_SAVED state
        if (state.getState().equals(WorkFlowState.NOT_SAVED))
        {
            finishButton.setEnabled(true);
            cancelButton.setEnabled(true);
        }
    }

public void registerWorkFlowController(WorkFlowController controller)
    {
        // Set the work flow controller to listen for button events
        backButton.addActionListener(controller);
        nextButton.addActionListener(controller);
        finishButton.addActionListener(controller);
        cancelButton.addActionListener(controller);

        // Register this to listen for changes to the work flow state
        controller.getWorkFlowState().addPropertyChangeListener(this);

        // Register this to listen for changes to the state for the current screen if it is not null
        WorkFlowScreenState currentScreenState = controller.getWorkFlowState().getCurrentScreenState();

        if (currentScreenState != null)
        {
            currentScreenState.addPropertyChangeListener(this);
        }
    }

public boolean proofStep(ResolutionState state)
    {
        Functor goalTerm = state.getGoalStack().peek().getFunctor();
        Functor matchTerm = state.getCurrentClause().getHead();

        // This is used to record variables bound on the domain side of the unificiation. This information seems
        // like is does not need to be kept because usually all of these bindings are in the stack frame.
        // However, this is not always the case as unification can capture a variable on the domain side.
        // These variables need to be unbound on backtracking too.
        List<Variable> domainVariables = new LinkedList<Variable>();

        // This is used to record variables bound on the query goal side of the unification. This information
        // must be kept so that the undo operation can unbind these variables before placing the goal back
        // onto the stack when backtracking.
        List<Variable> boundVariables = new LinkedList<Variable>();

        // Unify the current query goal with the possibly matching clause, creating variable bindings.
        boolean matched = state.getUnifier().unifyInternal(goalTerm, matchTerm, boundVariables, domainVariables);

        // Even if unification fails, any partial bindings created are remembered, to ensure that they are cleaned
        // up when this proof steps state is undone.
        for (Variable binding : boundVariables)
        {
            state.getVariableBindings().offer(binding);
        }

        for (Variable binding : domainVariables)
        {
            state.getVariableBindings().offer(binding);
        }

        // If the unification succeeded, establish a new state with the unified query removed from the goal stack, the
        // body of the unified with clause added to it for resolution, and the variable binding trail extended with
        // any additional bindings resulting from the unification.
        if (matched)
        {
            if (TRACE)
            {
                /*trace.fine(state.getTraceIndenter().generateTraceIndent() + "Unify " +
                    goalTerm.toString(state.getInterner(), true, true) + " against " +
                    matchTerm.toString(state.getInterner(), true, true) + ", ok.");*/
            }

            // Consume the successfully unified goal from the goal stack.
            state.getGoalStack().poll();

            // Add all functors on the body side of the unified clause onto the goal stack for resolution.
            Functor[] body = state.getCurrentClause().getBody();

            if ((body != null) && (body.length != 0))
            {
                // The new goals are placed onto the goal stack backwards. It is a stack, hence they get
                // explored first, depth first, but their insertion order is reversed for an intuitive
                // left-to-right evaluation order.
                for (int i = body.length - 1; i >= 0; i--)
                {
                    BuiltInFunctor newGoal = state.getBuiltInTransform().apply(body[i]);
                    newGoal.setParentChoicePointState(state.getLastChoicePoint());
                    state.getGoalStack().offer(newGoal);
                }
            }

            return true;
        }
        else
        {
            if (TRACE)
            {
                /*trace.fine(state.getTraceIndenter().generateTraceIndent() + "Failed to unify " +
                    goalTerm.toString(state.getInterner(), true, true) + " against " +
                    matchTerm.toString(state.getInterner(), true, true) + ".");*/
            }

            return false;
        }
    }

