public boolean structuralEquals(Term term)
    {
        Term comparator = term.getValue();
        Term value = getValue();

        // Check if this is an unbound variable in which case the comparator must be the same variable.
        if (value == this)
        {
            return this.equals(comparator);
        }
        else
        {
            return value.structuralEquals(comparator);
        }
    }

public CharSequence subSequence(int start, int end)
    {
        return new ASCIIByteBufferString(data, offset + start, end - start);
    }

public int compareTo(ASCIIString comparator)
    {
        int n = Math.min(length, comparator.length());

        for (int i = 0; i < n; i++)
        {
            byte b1 = get(i);
            byte b2 = comparator.get(i);

            if (b1 == b2)
            {
                continue;
            }

            if (b1 < b2)
            {
                return -1;
            }

            return 1;
        }

        return length - comparator.length();
    }

private void computeStringValue()
    {
        char[] chars = new char[length];

        for (int i = 0; i < length; i++)
        {
            chars[i] = (char) data.get(i + offset);
        }

        stringValue = new String(chars);
    }

private void computeHashCode()
    {
        hashCode = 0;

        for (int i = 0; i < length; i++)
        {
            hashCode = (31 * hashCode) + data.get(i + offset);
        }
    }

