protected int swapTileToLocationCountingIllegal(char t, int x, int y)
    {
        // Used to hold the count of illegal swaps
        int illegal = 0;

        // Find out where the tile to move is
        int tileX = getXForTile(t);
        int tileY = getYForTile(t);

        // Shift the tile into the correct column by repeatedly moving it left or right.
        while (tileX != x)
        {
            if ((tileX - x) > 0)
            {
                if (swapTiles(tileX, tileY, tileX - 1, tileY))
                {
                    illegal++;
                }

                tileX--;
            }
            else
            {
                if (swapTiles(tileX, tileY, tileX + 1, tileY))
                {
                    illegal++;
                }

                tileX++;
            }
        }

        // Shift the tile into the correct row by repeatedly moving it up or down.
        while (tileY != y)
        {
            // Commented out because tiles never swap down the board during the solvability test because tiles are
            // swapped into place left to right, top to bottom. The top row is always filled first so tiles cannot be
            // swapped down into it. Then the next row is filled but ones from the row above are never swapped down
            // into it because they are alrady in place and never move again and so on.
            /* if (tileY - y > 0)
             *{*/
            if (swapTiles(tileX, tileY, tileX, tileY - 1))
            {
                illegal++;
            }

            tileY--;
            /*}
             * else { if (swapTiles(tileX, tileY, tileX, tileY + 1)) illegal++; tileY++;}*/
        }

        return illegal;
    }

protected void updateWithOperator(Operator op)
    {
        // Get the operator as a character by taking the first character of the operator string
        char opc = ((String) op.getOp()).charAt(0);

        // Move the empty tile according to the specified operation
        switch (opc)
        {
        // Swap the empty tile with the one above it.
        case 'U':
        {
            swapTiles(emptyX, emptyY, emptyX, emptyY - 1);
            break;
        }

        // Swap the empty tile with the one below it.
        case 'D':
        {
            swapTiles(emptyX, emptyY, emptyX, emptyY + 1);
            break;
        }

        // Swap the empty tile with the one to the left of it.
        case 'L':
        {
            swapTiles(emptyX, emptyY, emptyX - 1, emptyY);
            break;
        }

        // Swap the empty tile with the one to the right of it.
        case 'R':
        {
            swapTiles(emptyX, emptyY, emptyX + 1, emptyY);
            break;
        }

        default:
        {
            throw new IllegalStateException("Unkown operator: " + opc + ".");
        }
        }
    }

protected boolean swapTiles(int x1, int y1, int x2, int y2)
    {
        // Used to indicate that one of the swapped tiles was the empty tile
        boolean swappedEmpty = false;

        // Get the tile at the first position
        char tile1 = board[y1][x1];

        // Store the tile from the second position at the first position
        char tile2 = board[y2][x2];

        board[y1][x1] = tile2;

        // Store the first tile in the second position
        board[y2][x2] = tile1;

        // Check if the first tile was the empty tile and update the empty tile coordinates if so
        if (tile1 == 'E')
        {
            emptyX = x2;
            emptyY = y2;
            swappedEmpty = true;
        }

        // Else check if the second tile was the empty tile and update the empty tile coordinates if so
        else if (tile2 == 'E')
        {
            emptyX = x1;
            emptyY = y1;
            swappedEmpty = true;
        }

        return !swappedEmpty;
    }

private static List<Character> stringToCharList(String boardString)
    {
        // Turn the goal state into a list of characters
        char[] chars = new char[9];

        boardString.getChars(0, 9, chars, 0);

        List<Character> charList = new ArrayList<Character>();

        for (int l = 0; l < 9; l++)
        {
            charList.add(chars[l]);
        }

        return charList;
    }

private static EightPuzzleState charListToState(List<Character> charList)
    {
        // Create a new empty puzzle state
        EightPuzzleState newState = new EightPuzzleState();

        // Loop over the board inserting the characters into it from the character list
        Iterator<Character> k = charList.iterator();

        for (int j = 0; j < 3; j++)
        {
            for (int i = 0; i < 3; i++)
            {
                char nextChar = k.next();

                // Check if this is the empty tile and if so then take note of its position
                if (nextChar == 'E')
                {
                    newState.emptyX = i;
                    newState.emptyY = j;
                }

                newState.board[j][i] = nextChar;
            }
        }

        return newState;
    }

public void publish(LogRecord record)
    {
        org.apache.log4j.Logger log4j = getTargetLogger(record.getLoggerName());
        Priority priority = toLog4j(record.getLevel());

        if (!priority.equals(org.apache.log4j.Level.OFF))
        {
            log4j.log(priority, toLog4jMessage(record), record.getThrown());
        }
    }

private String toLog4jMessage(LogRecord record)
    {
        String message = record.getMessage();

        // Format message
        Object[] parameters = record.getParameters();

        if ((parameters != null) && (parameters.length != 0))
        {
            // Check for the first few parameters ?
            if ((message.indexOf("{0}") >= 0) || (message.indexOf("{1}") >= 0) || (message.indexOf("{2}") >= 0) ||
                    (message.indexOf("{3}") >= 0))
            {
                message = MessageFormat.format(message, parameters);
            }
        }

        return message;
    }

private org.apache.log4j.Level toLog4j(Level level)
    {
        if (Level.SEVERE == level)
        {
            return org.apache.log4j.Level.ERROR;
        }
        else if (Level.WARNING == level)
        {
            return org.apache.log4j.Level.WARN;
        }
        else if (Level.INFO == level)
        {
            return org.apache.log4j.Level.INFO;
        }
        else if (Level.FINE == level)
        {
            return org.apache.log4j.Level.DEBUG;
        }
        else if (Level.FINER == level)
        {
            return org.apache.log4j.Level.TRACE;
        }
        else if (Level.OFF == level)
        {
            return org.apache.log4j.Level.OFF;
        }

        return org.apache.log4j.Level.OFF;
    }

public boolean offer(E o)
    {
        if (transactional)
        {
            // Delegate the offer operation to the wrapped queue.
            txMethod.requestWriteOperation(new EnqueueRecord(o));

            // return success;
            return true;
        }
        else
        {
            boolean success = queue.offer(o);

            // Update the queue size if the offer was succesfull.
            if (success)
            {
                incrementSizeAndCount(o);
            }

            return success;
        }
    }

public E poll()
    {
        Object owner;

        if (transactional)
        {
            owner = TxManager.getCurrentSession();
        }
        else
        {
            owner = null;
        }

        // Attempt to acquire an available element from the queue for the current transaction.
        return pollAccept(owner);
    }

public E pollAccept(Object owner)
    {
        if (transactional)
        {
            E element = null;
            RequeueElementWrapper<E> record = null;

            // Find an element on the requeue that is free, or has already been acquired by the owner but not accepted.
            // Mark the element as acquired by the owner as necessary.
            if (!requeue.isEmpty())
            {
                for (RequeueElementWrapper<E> nextRecord : requeue)
                {
                    if (AcquireState.Free.equals(nextRecord.state))
                    {
                        record = nextRecord;
                        record.state = AcquireState.Acquired;
                        record.owner = owner;

                        element = record.element;

                        break;
                    }
                    else if (AcquireState.Acquired.equals(nextRecord.state) && owner.equals(nextRecord.owner))
                    {
                        record = nextRecord;
                        element = record.element;

                        break;
                    }
                }
            }

            // If an element cannot be found on the requeue, poll an element from the main queue, and place it onto the
            // requeue.
            if (record == null)
            {
                element = queue.poll();
            }

            // If no element at all can be found return null.
            if (element == null)
            {
                return element;
            }

            // Check that an element was actually available on the queue before creating a new acquired record for it
            // on the requeue.
            if (record == null)
            {
                record = requeue(element, owner, AcquireState.Acquired);
            }

            // Accept the element and create a transaction operation to remove it upon commit or unnaccept it upon
            // rollback.
            record.state = AcquireState.Accepted;
            txMethod.requestWriteOperation(new AcceptRecord(record));

            return record.element;
        }
        else
        {
            E element;

            // Find an element on the requeue that is free. Remove it and return it.
            if (!requeue.isEmpty())
            {
                for (RequeueElementWrapper<E> nextRecord : requeue)
                {
                    if (AcquireState.Free.equals(nextRecord.state))
                    {
                        requeue.remove(nextRecord);
                        requeuedElementMap.remove(nextRecord.element);

                        return nextRecord.element;
                    }
                }
            }

            // Or poll an element from the main queue and return it.
            element = queue.poll();

            if (element != null)
            {
                decrementSizeAndCount(element);
            }

            return element;
        }
    }

public E pollAcquire(Object owner)
    {
        E element;

        // Find an element on the requeue that is free and return it.
        if (!requeue.isEmpty())
        {
            for (RequeueElementWrapper<E> nextRecord : requeue)
            {
                if (AcquireState.Free.equals(nextRecord.state))
                {
                    nextRecord.state = AcquireState.Acquired;
                    nextRecord.owner = owner;

                    return nextRecord.element;
                }
            }
        }

        // Nothing could be found on the requeue, so attempt to poll an element off the main queue and acquire
        // it on the requeue.
        element = queue.poll();

        if (element != null)
        {
            requeue(element, owner, AcquireState.Acquired);
        }

        return element;
    }

public boolean acquire(Object owner, Object o)
    {
        // Look up the element wrapper record for the element to be accepted.
        RequeueElementWrapper<E> record = requeuedElementMap.get(o);

        // Check if the element is currently free, and acquire it if so.
        if (AcquireState.Free.equals(record.state))
        {
            record.state = AcquireState.Acquired;
            record.owner = owner;

            return true;
        }

        return false;
    }

public void release(Object owner, Object o)
    {
        // Look up the element wrapper record for the element to be released, and release it.
        RequeueElementWrapper<E> record = requeuedElementMap.get(o);

        if (record != null)
        {
            record.state = AcquireState.Free;
            record.owner = null;
        }
    }

public void accept(Object owner, Object o)
    {
        // Look up the element wrapper record for the element to be accepted.
        RequeueElementWrapper<E> record = requeuedElementMap.get(o);

        if (record != null)
        {
            // If running in a transaction, create an accept operation to accept the item only upon commit of the
            // transaction.
            if (transactional)
            {
                record.state = AcquireState.Accepted;
                txMethod.requestWriteOperation(new AcceptRecord(record));
            }
            else
            {
                requeuedElementMap.remove(o);
                requeue.remove(record);
            }
        }
    }

