public ActionForward executeWithErrorHandling(ActionMapping mapping, ActionForm form, HttpServletRequest request,
        HttpServletResponse response, ActionErrors errors) throws Exception
    {
        // Get a reference to the session.
        HttpSession session = request.getSession(false);

        // Extract the page form.
        DynaActionForm pageForm = (DynaActionForm) form;
        log.fine("pageForm = " + pageForm);

        // Get the paged list object from the session.
        String listingVarName = pageForm.getString(VAR_NAME_PARAM);
        log.fine("listingVarName = " + listingVarName);

        PagedList pagedList = (PagedList) session.getAttribute(listingVarName);

        // Set its current page.
        pagedList.setCurrentPage((Integer) pageForm.get(NUMBER_PARAM));

        // Set its index offset if one is specified.
        Integer index = (Integer) pageForm.get(INDEX_PARAM);

        if (index != null)
        {
            pagedList.setCurrentIndex(index);
        }

        // Forward to the success location.
        return mapping.findForward(SUCCESS_FORWARD);
    }

public void compile(Sentence<Clause> clauseSentence) throws SourceCodeException
    {
        Clause clause = clauseSentence.getT();
        PrologCompiledClause result = new PrologCompiledClause(clause.getHead(), clause.getBody());

        // Create stack frame slots for all variables in a program.
        if (!clause.isQuery())
        {
            StackVariableTransform stackVariableTransform = new StackVariableTransform(0, result);
            result = (PrologCompiledClause) result.acceptTransformer(stackVariableTransform);

            // Set the required stack frame size on the compiled clause.
            result.setStackSize(stackVariableTransform.offset);
        }

        // Apply the built-in transformation to map any built-ins to their implementations.
        TermTransformer builtInTransformation = new BuiltInExpressionTransform(interner);
        result = (PrologCompiledClause) result.acceptTransformer(builtInTransformation);

        // Return the compiled version of the clause.
        if (clause.isQuery())
        {
            observer.onQueryCompilation(result);
        }
        else
        {
            observer.onCompilation(result);
        }
    }

public Functor transform(Functor functor)
    {
        FunctorName functorName = interner.getFunctorFunctorName(functor);

        if (builtInExpressions.containsKey(functorName))
        {
            Class<? extends Functor> builtInExpressionClass = builtInExpressions.get(functorName);

            return ReflectionUtils.newInstance(ReflectionUtils.getConstructor(builtInExpressionClass,
                    new Class[] { Integer.TYPE, Term[].class }),
                new Object[] { functor.getName(), functor.getArguments() });
        }
        else
        {
            return functor;
        }
    }

