public void renderTable()
    {
        for (int i = 0; i < tableModel.getRowCount(); i++)
        {
            int colOffset = 0;

            for (int j = 0; j < tableModel.getColumnCount(); j++)
            {
                String valueToPrint = tableModel.get(j, i);
                valueToPrint = (valueToPrint == null) ? "" : valueToPrint;
                gridModel.insert(valueToPrint, colOffset, i);

                AttributeSet attributes = tableModel.getAttributeAt(j, i);
                int columnSize = tableModel.getMaxColumnSize(j);

                if (attributes != null)
                {
                    for (int k = 0; k < columnSize; k++)
                    {
                        gridModel.insertAttribute(attributes, colOffset + k, i);
                    }
                }

                // Pad spaces up to the column width if the contents are shorter.
                int spaces = columnSize - valueToPrint.length();

                while (spaces > 0)
                {
                    gridModel.insert(" ", colOffset + valueToPrint.length() + spaces-- - 1, i);
                }

                // Shift to the next column.
                colOffset += columnSize;
            }
        }
    }

public Iterator<Operator<Term>> getChildren(boolean reverse)
    {
        if ((traverser != null) && (traverser instanceof ClauseTraverser))
        {
            return ((ClauseTraverser) traverser).traverse(this, reverse);
        }
        else
        {
            LinkedList<Operator<Term>> resultList = null;

            if (!reverse)
            {
                resultList = new LinkedList<Operator<Term>>();
            }
            else
            {
                resultList = new StackQueue<Operator<Term>>();
            }

            if (head != null)
            {
                resultList.add(head);
            }

            if (body != null)
            {
                for (Term bodyTerm : body)
                {
                    resultList.add(bodyTerm);
                }
            }

            return resultList.iterator();
        }
    }

