public static Boolean contentEquals(Path file1, Path file2) throws IOException
  {
      if (!java.nio.file.Files.isRegularFile(file1))
	      throw new IllegalArgumentException(file1 + "is not a regular file");

	  if (!java.nio.file.Files.isRegularFile(file2))
		  throw new IllegalArgumentException(file2 + "is not a regular file");

	  FileChannel channel1 = null;
	  FileChannel channel2 = null;

	  MappedByteBuffer buffer1 = null;
	  MappedByteBuffer buffer2 = null;

	  try
	  {
		  long size1 = java.nio.file.Files.size(file1);
		  long size2 = java.nio.file.Files.size(file2);

		  if (size1 != size2) return false;

		  long position = 0;
		  long length = Math.min(Integer.MAX_VALUE, size1 - position);

		  channel1 = FileChannel.open(file1);
		  channel2 = FileChannel.open(file2);

		  // Cannot map files larger than Integer.MAX_VALUE,
		  // so we have to do it in pieces.

		  while (length > 0)
		  {
			  buffer1 = channel1.map(MapMode.READ_ONLY, position, length);
			  buffer2 = channel2.map(MapMode.READ_ONLY, position, length);
			  // if (!buffer1.equals(buffer2)) return false;
			  // The line above is much slower than the line below.
			  // It should not be, but it is, possibly because it is
			  // loading the entire buffer into memory before comparing
			  // the contents. See the corresponding unit test. EK
			  for (int i = 0; i < length; i++) if (buffer1.get() != buffer2.get()) return false;
			  position += length;
			  length = Math.min(Integer.MAX_VALUE, size1 - position);
			  cleanDirectByteBuffer(buffer1); buffer1 = null;
			  cleanDirectByteBuffer(buffer2); buffer2 = null;
		  }
	  }
	  finally
	  {
		  // Is is important to clean up so we do not hold any
		  // file locks, in case the caller wants to do something
		  // else with the files.

		  // In terms of functional programming, holding a lock after
		  // returning to the caller would be an unwelcome side-effect.

		  cleanDirectByteBuffer(buffer1);
		  cleanDirectByteBuffer(buffer2);

		  if (channel1 != null) try
		  {
			  channel1.close();
		  }
		  catch (IOException e)
		  {
			  if (channel2 != null) channel2.close();
			  throw e;
		  }

		  if (channel2 != null) channel2.close();
	  }

	  return true;
  }

public static void cleanDirectByteBuffer(final ByteBuffer byteBuffer)
  {

	if (byteBuffer == null) return;

    if (!byteBuffer.isDirect())
    	throw new IllegalArgumentException("byteBuffer isn't direct!");

    AccessController.doPrivileged(new PrivilegedAction<Void>() {
        public Void run() {
        	try
        	{
        		Method cleanerMethod = byteBuffer.getClass().getMethod("cleaner");
        	    cleanerMethod.setAccessible(true);
        	    Object cleaner = cleanerMethod.invoke(byteBuffer);
        	    Method cleanMethod = cleaner.getClass().getMethod("clean");
        	    cleanMethod.setAccessible(true);
        	    cleanMethod.invoke(cleaner);
        	}
        	catch (NoSuchMethodException | SecurityException | IllegalAccessException | IllegalArgumentException | InvocationTargetException e)
        	{
        		throw new RuntimeException("Could not clean MappedByteBuffer -- File may still be locked!");
        	}
           return null; // nothing to return
        }
    });


  }

public void rollback()
    {
        
        if (auto_commit)
            return;
        
        String id = getCurrentThreadId();
        
        Entry<K,V> tab[] = table;
        for (int i = 0; i < tab.length ; i++)
        {
            Entry<K,V> prev = table[i];
            Entry<K,V> e = prev;
            
            while (e != null)
            {
                Entry<K,V> next = e.next;
                if (e.is(Entry.ADDED, id))
                {
                    modCount++;
                    size--;
                    if (prev == e)
                        table[i] = next;
                    else
                        prev.next = next;
                }
                else if (e.is(Entry.DELETED, id))
                    e.setStatus(Entry.NO_CHANGE, null);
                
                prev = e;
                e = next;
            }
        }
    }

private boolean validEntry(final Entry<K,V> entry)
    {
        if (auto_commit || entry == null)
            return (entry != null);
        
        String id = getCurrentThreadId();
        return !((entry.is(Entry.DELETED, id)) ||
                (entry.is(Entry.ADDED, null) && entry.is(Entry.NO_CHANGE, id)));
    }

@SuppressWarnings("unchecked")
    static <T> T maskNull(T key)
    {
        return (key == null ? (T)NULL_KEY : key);
    }

static int hash(Object x)
    {
        int h = x.hashCode();
        
        h += ~(h << 9);
        h ^=  (h >>> 14);
        h +=  (h << 4);
        h ^=  (h >>> 10);
        return h;
    }

static boolean eq(Object x, Object y)
    {
        return x == y || x.equals(y);
    }

@Override
    public V get(Object key)
    {
        Object k = maskNull(key);
        int hash = hash(k);
        int i = indexFor(hash, table.length);
        Entry<K,V> e = table[i];
        while (true)
        {
            if (e == null)
                return null;
            if (e.hash == hash && validEntry(e) && eq(k, e.key))
                return e.value;
            e = e.next;
        }
    }

Entry<K,V> getEntry(Object key)
    {
        Object k = maskNull(key);
        int hash = hash(k);
        int i = indexFor(hash, table.length);
        Entry<K,V> e = table[i];
        while (e != null && !(e.hash == hash && validEntry(e) && eq(k, e.key)))
            e = e.next;
        return e;
    }

@Override
    public V put(K key, V value) throws ConcurrentModificationException
    {
        K k = maskNull(key);
        int hash = hash(k);
        int i = indexFor(hash, table.length);
        
        V oldValue = null;
        for (Entry<K,V> e = table[i]; e != null; e = e.next)
        {
            if (e.hash == hash && eq(k, e.key))
            {
                //check if someone else has a pending add for the same key
                if (e.is(Entry.ADDED, null) && !e.is(Entry.ADDED, getCurrentThreadId()))
                    throw new ConcurrentModificationException();
                
                if (validEntry(e))
                {
                    oldValue = e.value;
                    //if not transactional can reuse entries
                    if (auto_commit)
                    {
                        e.value = value;
                        return oldValue;
                    }
                    else
                        e.setStatus(Entry.DELETED, getCurrentThreadId());
                }
            }
        }
        
        modCount++;
        addEntry(hash, k, value, i);
        return oldValue;
    }

private void putForCreate(K key, V value)
    {
        K k = maskNull(key);
        int hash = hash(k);
        int i = indexFor(hash, table.length);
        
        /**
         * Look for preexisting entry for key.  This will never happen for
         * clone or deserialize.  It will only happen for construction if the
         * input Map is a sorted map whose ordering is inconsistent w/ equals.
         */
        for (Entry<K,V> e = table[i]; e != null; e = e.next)
        {
            if (e.hash == hash && eq(k, e.key))
            {
                e.value = value;
                return;
            }
        }
        
        createEntry(hash, k, value, i);
    }

@SuppressWarnings("unchecked")
    void resize(int newCapacity)
    {
        Entry<K,V>[] oldTable = table;
        int oldCapacity = oldTable.length;
        if (oldCapacity == MAXIMUM_CAPACITY)
        {
            threshold = Integer.MAX_VALUE;
            return;
        }
        
        Entry<K,V>[] newTable = new Entry[newCapacity];
        transfer(newTable);
        table = newTable;
        threshold = (int)(newCapacity * loadFactor);
    }

@Override
    public void putAll(Map<? extends K, ? extends V> m)
    {
        int numKeysToBeAdded = m.size();
        if (numKeysToBeAdded == 0)
            return;
        
        /*
         * Expand the map if the map if the number of mappings to be added
         * is greater than or equal to threshold.  This is conservative; the
         * obvious condition is (m.size() + size) >= threshold, but this
         * condition could result in a map with twice the appropriate capacity,
         * if the keys to be added overlap with the keys already in this map.
         * By using the conservative calculation, we subject ourself
         * to at most one extra resize.
         */
        if (numKeysToBeAdded > threshold)
        {
            int targetCapacity = (int)(numKeysToBeAdded / loadFactor + 1);
            if (targetCapacity > MAXIMUM_CAPACITY)
                targetCapacity = MAXIMUM_CAPACITY;
            int newCapacity = table.length;
            while (newCapacity < targetCapacity)
                newCapacity <<= 1;
            if (newCapacity > table.length)
                resize(newCapacity);
        }
        
        for (Iterator<? extends Map.Entry<? extends K, ? extends V>> i = m.entrySet().iterator(); i.hasNext(); )
        {
            Map.Entry<? extends K, ? extends V> e = i.next();
            put(e.getKey(), e.getValue());
        }
    }

@Override
    public V remove(Object key) throws ConcurrentModificationException
    {
        Entry<K,V> e = removeEntryForKey(key);
        return (e == null ? null : e.value);
    }

Entry<K,V> removeEntryForKey(Object key) throws ConcurrentModificationException
    {
        Object k = maskNull(key);
        int hash = hash(k);
        int i = indexFor(hash, table.length);
        Entry<K,V> prev = table[i];
        Entry<K,V> e = prev;
        
        while (e != null)
        {
            Entry<K,V> next = e.next;
            if (e.hash == hash && validEntry(e) && eq(k, e.key))
            {
                if (e.is(Entry.DELETED, null) && !e.is(Entry.DELETED, getCurrentThreadId()))
                    throw new ConcurrentModificationException();
                
                if (auto_commit)
                {
                    modCount++;
                    size--;
                    if (prev == e)
                        table[i] = next;
                    else
                        prev.next = next;
                    return e;
                }
                else
                    e.setStatus(Entry.DELETED, getCurrentThreadId());
            }
            prev = e;
            e = next;
        }
        
        return e;
    }

@SuppressWarnings("unchecked")
    Entry<K,V> removeMapping(Object o)
    {
        if (!(o instanceof Map.Entry))
            return null;
        
        Map.Entry<K,V> entry = (Map.Entry<K,V>)o;
        Object k = maskNull(entry.getKey());
        int hash = hash(k);
        int i = indexFor(hash, table.length);
        Entry<K,V> prev = table[i];
        Entry<K,V> e = prev;
        
        while (e != null)
        {
            Entry<K,V> next = e.next;
            if (e.hash == hash && validEntry(e) && e.equals(entry))
            {
                if (auto_commit)
                {
                    modCount++;
                    size--;
                    if (prev == e)
                        table[i] = next;
                    else
                        prev.next = next;
                }
                else
                    e.setStatus(Entry.DELETED, getCurrentThreadId());
                return e;
            }
            prev = e;
            e = next;
        }
        
        return e;
    }

@Override
    public void clear()
    {
        modCount++;
        Entry<K,V> tab[] = table;
        for (int i = 0; i < tab.length; i++)
            tab[i] = null;
        size = 0;
    }

void addEntry(int hash, K key, V value, int bucketIndex)
    {
        table[bucketIndex] = new Entry<K,V>(hash, key, value, table[bucketIndex]);
        if (!auto_commit)
            table[bucketIndex].setStatus(Entry.ADDED, getCurrentThreadId());
        if (size++ >= threshold)
            resize(2 * table.length);
    }

void createEntry(int hash, K key, V value, int bucketIndex)
    {
        table[bucketIndex] = new Entry<K,V>(hash, key, value, table[bucketIndex]);
        size++;
    }

private static <K, V> ImmutableMap<K, V> createDelegate(
        final Map<K, V> base,
        final Set<? extends K> keys,
        final Function<K, V> augmentation
    ) {
        final ImmutableMap.Builder<K, V> builder = ImmutableMap.builder();
        builder.putAll(base);
        keys.stream()
            .filter(key -> !base.containsKey(key))
            .forEach(key -> builder.put(key, augmentation.apply(key)));
        return builder.build();
    }

public static Date parseDate(String dateString) throws ParseException {
        Matcher matcher = xep0091Pattern.matcher(dateString);

        /*
         * if date is in XEP-0091 format handle ambiguous dates missing the
         * leading zero in month and day
         */
        if (matcher.matches()) {
            int length = dateString.split("T")[0].length();

            if (length < 8) {
                Date date = handleDateWithMissingLeadingZeros(dateString,
                        length);

                if (date != null)
                    return date;
            } else {
                synchronized (xep0091Formatter) {
                    return xep0091Formatter.parse(dateString);
                }
            }
        } else {
            for (PatternCouplings coupling : couplings) {
                matcher = coupling.pattern.matcher(dateString);

                if (matcher.matches()) {
                    if (coupling.needToConvertTimeZone) {
                        dateString = coupling.convertTime(dateString);
                    }

                    synchronized (coupling.formatter) {
                        return coupling.formatter.parse(dateString);
                    }
                }
            }
        }

        /*
         * We assume it is the XEP-0082 DateTime profile with no milliseconds at
         * this point. If it isn't, is is just not parseable, then we attempt to
         * parse it regardless and let it throw the ParseException.
         */
        synchronized (dateTimeNoMillisFormatter) {
            return dateTimeNoMillisFormatter.parse(dateString);
        }
    }

private static Date handleDateWithMissingLeadingZeros(String stampString,
            int dateLength) throws ParseException {
        if (dateLength == 6) {
            synchronized (xep0091Date6DigitFormatter) {
                return xep0091Date6DigitFormatter.parse(stampString);
            }
        }
        Calendar now = Calendar.getInstance();

        Calendar oneDigitMonth = parseXEP91Date(stampString,
                xep0091Date7Digit1MonthFormatter);
        Calendar twoDigitMonth = parseXEP91Date(stampString,
                xep0091Date7Digit2MonthFormatter);

        List<Calendar> dates = filterDatesBefore(now, oneDigitMonth,
                twoDigitMonth);

        if (!dates.isEmpty()) {
            return determineNearestDate(now, dates).getTime();
        }
        return null;
    }

public static String parseName(String XMPPAddress) {
        if (XMPPAddress == null) {
            return null;
        }
        int atIndex = XMPPAddress.lastIndexOf("@");
        if (atIndex <= 0) {
            return "";
        } else {
            return XMPPAddress.substring(0, atIndex);
        }
    }

public static String parseServer(String XMPPAddress) {
        if (XMPPAddress == null) {
            return null;
        }
        int atIndex = XMPPAddress.lastIndexOf("@");
        // If the String ends with '@', return the empty string.
        if (atIndex + 1 > XMPPAddress.length()) {
            return "";
        }
        int slashIndex = XMPPAddress.indexOf("/");
        if (slashIndex > 0 && slashIndex > atIndex) {
            return XMPPAddress.substring(atIndex + 1, slashIndex);
        } else {
            return XMPPAddress.substring(atIndex + 1);
        }
    }

public static String parseResource(String XMPPAddress) {
        if (XMPPAddress == null) {
            return null;
        }
        int slashIndex = XMPPAddress.indexOf("/");
        if (slashIndex + 1 > XMPPAddress.length() || slashIndex < 0) {
            return "";
        } else {
            return XMPPAddress.substring(slashIndex + 1);
        }
    }

public static String parseBareAddress(String XMPPAddress) {
        if (XMPPAddress == null) {
            return null;
        }
        int slashIndex = XMPPAddress.indexOf("/");
        if (slashIndex < 0) {
            return XMPPAddress;
        } else if (slashIndex == 0) {
            return "";
        } else {
            return XMPPAddress.substring(0, slashIndex);
        }
    }

public static boolean isFullJID(String jid) {
        if (parseName(jid).length() <= 0 || parseServer(jid).length() <= 0
                || parseResource(jid).length() <= 0) {
            return false;
        }
        return true;
    }

public static String escapeNode(String node) {
        if (node == null) {
            return null;
        }
        StringBuilder buf = new StringBuilder(node.length() + 8);
        for (int i = 0, n = node.length(); i < n; i++) {
            char c = node.charAt(i);
            switch (c) {
            case '"':
                buf.append("\\22");
                break;
            case '&':
                buf.append("\\26");
                break;
            case '\'':
                buf.append("\\27");
                break;
            case '/':
                buf.append("\\2f");
                break;
            case ':':
                buf.append("\\3a");
                break;
            case '<':
                buf.append("\\3c");
                break;
            case '>':
                buf.append("\\3e");
                break;
            case '@':
                buf.append("\\40");
                break;
            case '\\':
                buf.append("\\5c");
                break;
            default: {
                if (Character.isWhitespace(c)) {
                    buf.append("\\20");
                } else {
                    buf.append(c);
                }
            }
            }
        }
        return buf.toString();
    }

public static String unescapeNode(String node) {
        if (node == null) {
            return null;
        }
        char[] nodeChars = node.toCharArray();
        StringBuilder buf = new StringBuilder(nodeChars.length);
        for (int i = 0, n = nodeChars.length; i < n; i++) {
            compare: {
                char c = node.charAt(i);
                if (c == '\\' && i + 2 < n) {
                    char c2 = nodeChars[i + 1];
                    char c3 = nodeChars[i + 2];
                    if (c2 == '2') {
                        switch (c3) {
                        case '0':
                            buf.append(' ');
                            i += 2;
                            break compare;
                        case '2':
                            buf.append('"');
                            i += 2;
                            break compare;
                        case '6':
                            buf.append('&');
                            i += 2;
                            break compare;
                        case '7':
                            buf.append('\'');
                            i += 2;
                            break compare;
                        case 'f':
                            buf.append('/');
                            i += 2;
                            break compare;
                        }
                    } else if (c2 == '3') {
                        switch (c3) {
                        case 'a':
                            buf.append(':');
                            i += 2;
                            break compare;
                        case 'c':
                            buf.append('<');
                            i += 2;
                            break compare;
                        case 'e':
                            buf.append('>');
                            i += 2;
                            break compare;
                        }
                    } else if (c2 == '4') {
                        if (c3 == '0') {
                            buf.append("@");
                            i += 2;
                            break compare;
                        }
                    } else if (c2 == '5') {
                        if (c3 == 'c') {
                            buf.append("\\");
                            i += 2;
                            break compare;
                        }
                    }
                }
                buf.append(c);
            }
        }
        return buf.toString();
    }

private static String xmlAttribEncodeBinary(String value) {
        StringBuilder s = new StringBuilder();
        char buf[] = value.toCharArray();
        for (char c : buf) {
            switch (c) {
            case '<':
                s.append("&lt;");
                break;
            case '>':
                s.append("&gt;");
                break;
            case '&':
                s.append("&amp;");
                break;
            case '"':
                s.append("&quot;");
                break;
            case '\'':
                s.append("&apos;");
                break;
            default:
                if (c <= 0x1f || (0x7f <= c && c <= 0x9f)) { // includes \t, \n,
                                                             // \r
                    s.append("&#x");
                    s.append(String.format("%X", (int) c));
                    s.append(';');
                } else {
                    s.append(c);
                }
            }
        }
        return s.toString();
    }

public synchronized static String hash(String data) {
        if (digest == null) {
            try {
                digest = MessageDigest.getInstance("SHA-1");
            } catch (NoSuchAlgorithmException nsae) {
                log.log(Level.ERROR,
                        "Failed to load the SHA-1 MessageDigest. Smack will be unable to function normally.",
                        nsae);
            }
        }
        // Now, compute hash.
        try {
            digest.update(data.getBytes("UTF-8"));
        } catch (UnsupportedEncodingException e) {
            log.log(Level.ERROR, "Error computing hash", e);
        }
        return encodeHex(digest.digest());
    }

public static String encodeHex(byte[] bytes) {
        StringBuilder hex = new StringBuilder(bytes.length * 2);

        for (byte aByte : bytes) {
            if (((int) aByte & 0xff) < 0x10) {
                hex.append("0");
            }
            hex.append(Integer.toString((int) aByte & 0xff, 16));
        }

        return hex.toString();
    }

