private synchronized static void enableExecutorService() {
        if (periodicPingExecutorService == null) {
            periodicPingExecutorService = new ScheduledThreadPoolExecutor(1,
                    new ThreadFactory() {
                        @Override
                        public Thread newThread(Runnable runnable) {
                            Thread pingThread = new Thread(runnable,
                                    "Smack Keepalive");
                            pingThread.setDaemon(true);
                            return pingThread;
                        }
                    });
        }
    }

private synchronized static void handleDisconnect(Connection con) {
        if (periodicPingExecutorService != null) {
            instances.remove(con);

            if (instances.isEmpty()) {
                periodicPingExecutorService.shutdownNow();
                periodicPingExecutorService = null;
            }
        }
    }

private void handleConnect() {
        Connection connection = weakRefConnection.get();
        // Listen for all incoming packets and reset the scheduled ping whenever
        // one arrives.
        connection.addPacketListener(new PacketListener() {

            @Override
            public void processPacket(Packet packet) {
                // reschedule the ping based on this last server contact
                lastSuccessfulContact = System.currentTimeMillis();
                schedulePingServerTask();
            }
        }, null);
    }

public void setPingInterval(long newPingInterval) {
        if (pingInterval == newPingInterval)
            return;

        // Enable the executor service
        if (newPingInterval > 0)
            enableExecutorService();

        pingInterval = newPingInterval;

        if (pingInterval < 0) {
            stopPinging();
        } else {
            schedulePingServerTask();
        }
    }

private synchronized void schedulePingServerTask() {
        enableExecutorService();
        stopPingServerTask();

        if (pingInterval > 0) {
            periodicPingTask = periodicPingExecutorService.schedule(
                    new Runnable() {
                        @Override
                        public void run() {
                            Ping ping = new Ping();
                            PacketFilter responseFilter = new PacketIDFilter(
                                    ping.getID());
                            Connection connection = weakRefConnection.get();
                            final PacketCollector response = pingFailedListeners
                                    .isEmpty() ? null : connection
                                    .createPacketCollector(responseFilter);
                            connection.sendPacket(ping);

                            if (response != null) {
                                // Schedule a collector for the ping reply,
                                // notify listeners if none is received.
                                periodicPingExecutorService.schedule(
                                        new Runnable() {
                                            @Override
                                            public void run() {
                                                Packet result = response
                                                        .nextResult(1);

                                                // Stop queuing results
                                                response.cancel();

                                                // The actual result of the
                                                // reply can be ignored since we
                                                // only care if we actually got
                                                // one.
                                                if (result == null) {
                                                    for (PingFailedListener listener : pingFailedListeners) {
                                                        listener.pingFailed();
                                                    }
                                                }
                                            }
                                        }, SmackConfiguration
                                                .getPacketReplyTimeout(),
                                        TimeUnit.MILLISECONDS);
                            }
                        }
                    }, getPingInterval(), TimeUnit.MILLISECONDS);
        }
    }

