public boolean equalsDeep(Object obj) {
        if (this == obj)
            return true;
        if (obj == null)
            return false;
        if (getClass() != obj.getClass())
            return false;
        RosterEntry other = (RosterEntry) obj;
        if (name == null) {
            if (other.name != null)
                return false;
        } else if (!name.equals(other.name))
            return false;
        if (ask == null) {
            if (other.ask != null)
                return false;
        } else if (!ask.equals(other.ask))
            return false;
        if (subscription == null) {
            if (other.subscription != null)
                return false;
        } else if (!subscription.equals(other.subscription))
            return false;
        if (user == null) {
            if (other.user != null)
                return false;
        } else if (!user.equals(other.user))
            return false;
        return true;
    }

public V get(String key) {
    Element e = cache.get(key);
    if (e == null) {
      return stats(null);
    }
    return stats(e.getObjectValue());
  }

@SuppressWarnings("unchecked")
  public V put(String key, V payload) {
    V previous = null;
    if (cache.isKeyInCache(key)) {
      Element e = cache.get(key);
      if (e != null) {
        previous = (V) e.getObjectValue();
      }
    }
    cache.put(new Element(key, payload));
    return previous;
  }

public void removeChildren(String key) {
    cache.remove(key);
    if (!key.endsWith("/")) {
      key = key + "/";
    }
    List<?> keys = cache.getKeys();
    for (Object k : keys) {
      if (((String) k).startsWith(key)) {
        cache.remove(k);
      }
    }
  }

@SuppressWarnings("unchecked")
  public List<V> list() {
    List<String> keys = cache.getKeys();
    List<V> values = new ArrayList<V>();
    for (String k : keys) {
      Element e = cache.get(k);
      if ( e != null ) {
        values.add((V) e.getObjectValue());
      }
    }
    return values;
  }

public static void appendRSMElement(Element queryElement, RSM rsm) {
        Element setElement = queryElement.addElement("set", RSM.NAMESPACE);

        if (rsm.getFirst() != null) {
            Element firstElement = setElement.addElement("first");
            firstElement.addAttribute("index", rsm.getIndex().toString());
            firstElement.setText(rsm.getFirst());
        }

        if (rsm.getLast() != null) {
            Element lastElement = setElement.addElement("last");
            lastElement.setText(rsm.getLast());
        }

        setElement.addElement("count").setText(String.valueOf(rsm.getCount()));
    }

public static RSM parseRSM(Element queryElement) {
        RSM rsm = new RSM();

        Element setElement = queryElement.element("set");
        if (setElement == null) {
            return rsm;
        }

        Element after = setElement.element("after");
        if (after != null) {
            rsm.setAfter(after.getText());
        }

        Element before = setElement.element("before");
        if (before != null) {
            String beforeText = before.getText();
            rsm.setBefore(beforeText == null ? "" : beforeText);
        }

        Element index = setElement.element("index");
        if (index != null) {
            rsm.setIndex(Integer.parseInt(index.getText()));
        }

        Element max = setElement.element("max");
        if (max != null) {
            rsm.setMax(Integer.parseInt(max.getText()));
        }

        return rsm;
    }

public static List<Identifiable> filterRSMResponse(
            List<Identifiable> objects, RSM rsm)
            throws IllegalArgumentException {

        String after = rsm.getAfter();
        String before = rsm.getBefore();

        int initialIndex = rsm.getIndex();
        int lastIndex = objects.size();

        if (after != null || (before != null && !before.isEmpty())) {

            boolean afterItemFound = false;
            boolean beforeItemFound = false;

            int i = 0;
            for (Identifiable object : objects) {
                if (after != null && after.equals(object.getId())) {
                    initialIndex = i + 1;
                    afterItemFound = true;
                }
                if (before != null && before.equals(object.getId())) {
                    lastIndex = i;
                    beforeItemFound = true;
                }
                i++;
            }

            if (after != null && !afterItemFound) {
                throw new IllegalArgumentException();
            }

            if (before != null && !before.isEmpty() && !beforeItemFound) {
                throw new IllegalArgumentException();
            }
        }

        if (rsm.getMax() != null) {
            if (before != null) {
                initialIndex = lastIndex - rsm.getMax();
            } else {
                lastIndex = initialIndex + rsm.getMax();
            }
        }

        boolean outOfRange = initialIndex > lastIndex || initialIndex < 0
                || lastIndex > objects.size();

        List<Identifiable> filteredList = outOfRange ? new LinkedList<Identifiable>()
                : objects.subList(initialIndex, lastIndex);

        rsm.setCount(objects.size());
        rsm.setIndex(initialIndex);

        if (!filteredList.isEmpty()) {
            rsm.setFirst(filteredList.get(0).getId());
            rsm.setLast(filteredList.get(filteredList.size() - 1).getId());
        }

        return filteredList;
    }

public void handleEvent(Event event) {
		String topic = event.getTopic();
		Session session = (Session) event.getProperty(Session.class.getName());
		RepositorySession repositoryRession = null;
		Thread thisThread = Thread.currentThread();
		ClassLoader classloader = thisThread.getContextClassLoader();
		// ES might load classes so we had better set the context classloader.
		try {
			thisThread.setContextClassLoader(this.getClass().getClassLoader());
			try {
				repositoryRession = new RepositorySessionImpl(session,
						repository);
			} catch (ClientPoolException e1) {
				LOGGER.error(e1.getMessage(), e1);
				return;
			} catch (StorageClientException e1) {
				LOGGER.error(e1.getMessage(), e1);
				return;
			} catch (AccessDeniedException e1) {
				LOGGER.error(e1.getMessage(), e1);
				return;
			}

			LOGGER.debug("Got Event {} {} ", event, handlers);
			Collection<IndexingHandler> contentIndexHandler = handlers
					.get(topic);
			if (contentIndexHandler != null && contentIndexHandler.size() > 0) {
				BulkRequestBuilder bulk = client.prepareBulk();
				int added = 0;
				for (IndexingHandler indexingHandler : contentIndexHandler) {
					Collection<InputDocument> documents = indexingHandler
							.getDocuments(repositoryRession, event);
					for (InputDocument in : documents) {
						LOGGER.info("Indexing {} ", in);
						if (in.isDelete()) {
							bulk.add(client.prepareDelete(in.getIndexName(),
									in.getDocumentType(), in.getDocumentId()));
							added++;
						} else {
							try {
								IndexRequestBuilder r = client.prepareIndex(
										in.getIndexName(),
										in.getDocumentType(),
										in.getDocumentId());
								XContentBuilder d = XContentFactory
										.jsonBuilder();
								d = d.startObject();
								for (Entry<String, Object> e : in.getKeyData()) {
									d = d.field(e.getKey(), e.getValue());
								}
								r.setSource(d.endObject());
								bulk.add(r);
								added++;
							} catch (IOException e) {
								LOGGER.error(e.getMessage(), e);
							}
						}
					}
				}
				if ( added > 0 ) {
					BulkResponse resp = bulk.execute().actionGet();
					if (resp.hasFailures()) {
						for (BulkItemResponse br : Iterables.adaptTo(resp
								.iterator())) {
							if (br.failed()) {
								LOGGER.error("Failed {} {} ", br.getId(),
										br.getFailureMessage());
								// not going to retry at the moment, just log.
							}
						}
					}
				}

			}
		} finally {
			if (repositoryRession != null) {
				repositoryRession.logout();
			}
			thisThread.setContextClassLoader(classloader);
		}
	}

