        if (!eventModel.containsDescriptor(StartMusicRequest.ID))
            return false;
        if (!capabilities.handlesPlayRequestFromOutside()) {
            if (activators.stream()
                    .noneMatch(identifiable -> identifiable.isOwner(eventModel.getSource())))
                return false;
        }
        if (!PlaylistResource.getPlaylist(eventModel).map(playlist -> playlist.verify(capabilities)).orElse(true)) {
            return false;
        }
        return SelectorResource.isTarget(eventModel, player)
                .orElse(false);
    }

public static <E> Filter<E> createSameAsFilter(final E base) 
    {
        return new Filter<E>() {
            public boolean isValid(E obj)
            {
                return (base == obj);
            }
        };
    }

public static <E> Filter<E> createEqualToFilter(final Object base) 
    {
        return new Filter<E>() {
            public boolean isValid(E obj)
            {
                return obj.equals(base);
            }
        };
    }

public static <E extends Comparable<E>> Filter<E> createLessThanFilter(final E base) 
    {
        return createLessThanFilter(base, new Comparator<E>() 
        {
            public int compare(E obj1, E obj2)
            {
                return obj1.compareTo(obj2);
            }
        });
    }

public static <E> Filter<E> createLessThanFilter(final E base, final Comparator<E> comparator) 
    {
        return new Filter<E>() {
            public boolean isValid(E obj)
            {
                return comparator.compare(obj, base) < 0;
            }
        };
    }

