public static Optional<Playlist> importResource(ResourceModel resourceModel) {
        Object resource = resourceModel.getResource();
        try {
            //noinspection unchecked
            HashMap<String, Object> data = (HashMap<String, Object>) resource;
            ArrayList<TrackInfo> queue = new ArrayList<>();
            ArrayList<PlaybackMode> playbackModes = new ArrayList<>();
            final String[] name = {null};
            final int[] position = {-1};
            final String[] dataString = {null};
            data.entrySet().forEach(entry -> {
                if (entry.getKey().startsWith(QUEUE_DESCRIPTOR)) {
                    int index = Integer.parseInt(entry.getKey().replace(QUEUE_DESCRIPTOR, ""));
                    //noinspection unchecked
                    TrackInfo.importFromHashMap((HashMap<String, Object>) entry.getValue())
                            .ifPresent(trackInfo -> queue.add(index, trackInfo));
                } else if (entry.getKey().startsWith(PLAYBACK_MODE_DESCRIPTOR)) {
                    try {
                        int index = Integer.parseInt(entry.getKey().replace(PLAYBACK_MODE_DESCRIPTOR, ""));
                        //noinspection unchecked
                        playbackModes.add(index, PlaybackMode.valueOf((String) entry.getValue()));
                    } catch (IllegalArgumentException ignored) {
                        //happens when the name is not present...maybe future sdks define other playbackModes
                    }
                } else if (entry.getKey().equals(NAME_DESCRIPTOR)) {
                    name[0] = (String) entry.getValue();
                } else if (entry.getKey().equals(POSITION_DESCRIPTOR)) {
                    position[0] = (int) entry.getValue();
                } else if (entry.getKey().equals(DATA_DESCRIPTOR)) {
                    dataString[0] = (String) entry.getValue();
                }
            });
            return Optional.of(new Playlist(queue, name[0] , playbackModes, position[0], dataString[0]));
        } catch (ClassCastException | IllegalArgumentException e) {
            return Optional.empty();
        }
    }

private static int decode4to3(byte[] source, int srcOffset,
            byte[] destination, int destOffset, int options) {
        byte[] DECODABET = getDecodabet(options);

        // Example: Dk==
        if (source[srcOffset + 2] == EQUALS_SIGN) {
            // Two ways to do the same thing. Don't know which way I like best.
            // int outBuff = ( ( DECODABET[ source[ srcOffset ] ] << 24 ) >>> 6
            // )
            // | ( ( DECODABET[ source[ srcOffset + 1] ] << 24 ) >>> 12 );
            int outBuff = ((DECODABET[source[srcOffset]] & 0xFF) << 18)
                    | ((DECODABET[source[srcOffset + 1]] & 0xFF) << 12);

            destination[destOffset] = (byte) (outBuff >>> 16);
            return 1;
        }

        // Example: DkL=
        else if (source[srcOffset + 3] == EQUALS_SIGN) {
            // Two ways to do the same thing. Don't know which way I like best.
            // int outBuff = ( ( DECODABET[ source[ srcOffset ] ] << 24 ) >>> 6
            // )
            // | ( ( DECODABET[ source[ srcOffset + 1 ] ] << 24 ) >>> 12 )
            // | ( ( DECODABET[ source[ srcOffset + 2 ] ] << 24 ) >>> 18 );
            int outBuff = ((DECODABET[source[srcOffset]] & 0xFF) << 18)
                    | ((DECODABET[source[srcOffset + 1]] & 0xFF) << 12)
                    | ((DECODABET[source[srcOffset + 2]] & 0xFF) << 6);

            destination[destOffset] = (byte) (outBuff >>> 16);
            destination[destOffset + 1] = (byte) (outBuff >>> 8);
            return 2;
        }

        // Example: DkLE
        else {
            try {
                // Two ways to do the same thing. Don't know which way I like
                // best.
                // int outBuff = ( ( DECODABET[ source[ srcOffset ] ] << 24 )
                // >>> 6 )
                // | ( ( DECODABET[ source[ srcOffset + 1 ] ] << 24 ) >>> 12 )
                // | ( ( DECODABET[ source[ srcOffset + 2 ] ] << 24 ) >>> 18 )
                // | ( ( DECODABET[ source[ srcOffset + 3 ] ] << 24 ) >>> 24 );
                int outBuff = ((DECODABET[source[srcOffset]] & 0xFF) << 18)
                        | ((DECODABET[source[srcOffset + 1]] & 0xFF) << 12)
                        | ((DECODABET[source[srcOffset + 2]] & 0xFF) << 6)
                        | ((DECODABET[source[srcOffset + 3]] & 0xFF));

                destination[destOffset] = (byte) (outBuff >> 16);
                destination[destOffset + 1] = (byte) (outBuff >> 8);
                destination[destOffset + 2] = (byte) (outBuff);

                return 3;
            } catch (Exception e) {
                log.log(Level.ERROR, e.getMessage(), e);
                log.error("" + source[srcOffset] + ": "
                        + (DECODABET[source[srcOffset]]));
                log.error("" + source[srcOffset + 1] + ": "
                        + (DECODABET[source[srcOffset + 1]]));
                log.error("" + source[srcOffset + 2] + ": "
                        + (DECODABET[source[srcOffset + 2]]));
                log.error("" + source[srcOffset + 3] + ": "
                        + (DECODABET[source[srcOffset + 3]]));
                return -1;
            } // end catch
        }
    }

protected void batchRequest(HttpServletRequest request,
			HttpServletResponse response, String jsonRequest,
			boolean allowModify) throws IOException, ServletException {
		JsonParser jsonParser = new JsonParser();
		JsonElement element = jsonParser.parse(jsonRequest);
		if (!element.isJsonArray()) {
			response.sendError(HttpServletResponse.SC_BAD_REQUEST,
					"Failed to parse the requests parameter");
			return;
		}

		JsonArray arr = element.getAsJsonArray();
		response.setContentType("application/json");
		response.setCharacterEncoding("UTF-8");

		String key = null;
		try {
			MessageDigest md = MessageDigest.getInstance("SHA-1");
			key = Base64.encodeBase64URLSafeString(md.digest(jsonRequest
					.getBytes("UTF-8")));
			String cachedResult = responseCache.get(key);
			if (cachedResult != null) {
				LOGGER.debug("Using Cache");
				response.getWriter().write(cachedResult);
				return;
			}
		} catch (Exception e) {
			LOGGER.warn(e.getMessage(), e);
		}

		boolean cache = (key != null);
		CaptureResponseWriter captureResponseWriter = new CaptureResponseWriter(
				response.getWriter());
		JsonWriter write = new JsonWriter(captureResponseWriter);
		write.beginObject();
		write.name("results");
		write.beginArray();
		for (int i = 0; i < arr.size(); i++) {
			JsonObject obj = arr.get(i).getAsJsonObject();
			try {
				RequestInfo r = new RequestInfo(obj);
				if (r.isValid() && (allowModify || r.isSafe())) {
					cache = doRequest(request, response, r, write) && cache;
				} else {
					outputFailure("Bad request, ignored " + obj.toString(),
							write);
				}
			} catch (MalformedURLException e) {
				outputFailure("Bad request, ignored " + obj.toString(), write);
			}
		}
		write.endArray();
		write.endObject();
		write.flush();
		if (cache) {
			responseCache.put(key, captureResponseWriter.toString());
		}
	}

