public void setName(String name) {
        synchronized (entries) {
            for (RosterEntry entry : entries) {
                Roster packet = new Roster();
                packet.setType(IQ.Type.set);
                List<String> groupNames = new LinkedList<String>(
                        entry.getGroupNames());
                groupNames.remove(this.name);
                groupNames.add(name);
                packet.addItem(new JID(entry.getUser()), entry.getName(),
                        entry.getAsk(), entry.getSubscription(), groupNames);
                connection.sendPacket(packet);
            }
        }
    }

public RosterEntry getEntry(String user) {
        if (user == null) {
            return null;
        }
        // Roster entries never include a resource so remove the resource
        // if it's a part of the XMPP address.
        user = StringUtils.parseBareAddress(user);
        String userLowerCase = user.toLowerCase();
        synchronized (entries) {
            for (RosterEntry entry : entries) {
                if (entry.getUser().equals(userLowerCase)) {
                    return entry;
                }
            }
        }
        return null;
    }

public void addEntry(RosterEntry entry) throws XMPPException {
        PacketCollector collector = null;
        // Only add the entry if it isn't already in the list.
        synchronized (entries) {
            if (!entries.contains(entry)) {
                Roster packet = new Roster();
                packet.setType(IQ.Type.set);
                List<String> groupNames = new LinkedList<String>(
                        entry.getGroupNames());
                groupNames.add(getName());
                packet.addItem(new JID(entry.getUser()), entry.getName(),
                        entry.getAsk(), entry.getSubscription(), groupNames);
                // Wait up to a certain number of seconds for a reply from the
                // server.
                collector = connection
                        .createPacketCollector(new PacketIDFilter(packet
                                .getID()));
                connection.sendPacket(packet);
            }
        }
        if (collector != null) {
            IQ response = (IQ) collector.nextResult(SmackConfiguration
                    .getPacketReplyTimeout());
            collector.cancel();
            if (response == null) {
                throw new XMPPException("No response from the server.");
            }
            // If the server replied with an error, throw an exception.
            else if (response.getType() == IQ.Type.error) {
                throw new XMPPException(response.getError());
            }
        }
    }

public V get(Object key) {
        int hashCode = hash((key == null) ? NULL : key);
        HashEntry<K, V> entry = data[hashIndex(hashCode, data.length)]; // no
                                                                        // local
                                                                        // for
                                                                        // hash
                                                                        // index
        while (entry != null) {
            if (entry.hashCode == hashCode && isEqualKey(key, entry.key)) {
                return entry.getValue();
            }
            entry = entry.next;
        }
        return null;
    }

public boolean containsKey(Object key) {
        int hashCode = hash((key == null) ? NULL : key);
        HashEntry entry = data[hashIndex(hashCode, data.length)]; // no local
                                                                  // for hash
                                                                  // index
        while (entry != null) {
            if (entry.hashCode == hashCode && isEqualKey(key, entry.getKey())) {
                return true;
            }
            entry = entry.next;
        }
        return false;
    }

public boolean containsValue(Object value) {
        if (value == null) {
            for (int i = 0, isize = data.length; i < isize; i++) {
                HashEntry entry = data[i];
                while (entry != null) {
                    if (entry.getValue() == null) {
                        return true;
                    }
                    entry = entry.next;
                }
            }
        } else {
            for (int i = 0, isize = data.length; i < isize; i++) {
                HashEntry entry = data[i];
                while (entry != null) {
                    if (isEqualValue(value, entry.getValue())) {
                        return true;
                    }
                    entry = entry.next;
                }
            }
        }
        return false;
    }

public V put(K key, V value) {
        int hashCode = hash((key == null) ? NULL : key);
        int index = hashIndex(hashCode, data.length);
        HashEntry<K, V> entry = data[index];
        while (entry != null) {
            if (entry.hashCode == hashCode && isEqualKey(key, entry.getKey())) {
                V oldValue = entry.getValue();
                updateEntry(entry, value);
                return oldValue;
            }
            entry = entry.next;
        }
        addMapping(index, hashCode, key, value);
        return null;
    }

public void putAll(Map<? extends K, ? extends V> map) {
        int mapSize = map.size();
        if (mapSize == 0) {
            return;
        }
        int newSize = (int) ((size + mapSize) / loadFactor + 1);
        ensureCapacity(calculateNewCapacity(newSize));
        // Have to cast here because of compiler inference problems.
        for (Iterator it = map.entrySet().iterator(); it.hasNext();) {
            Map.Entry<? extends K, ? extends V> entry = (Map.Entry<? extends K, ? extends V>) it
                    .next();
            put(entry.getKey(), entry.getValue());
        }
    }

public V remove(Object key) {
        int hashCode = hash((key == null) ? NULL : key);
        int index = hashIndex(hashCode, data.length);
        HashEntry<K, V> entry = data[index];
        HashEntry<K, V> previous = null;
        while (entry != null) {
            if (entry.hashCode == hashCode && isEqualKey(key, entry.getKey())) {
                V oldValue = entry.getValue();
                removeMapping(entry, index, previous);
                return oldValue;
            }
            previous = entry;
            entry = entry.next;
        }
        return null;
    }

public void clear() {
        modCount++;
        HashEntry[] data = this.data;
        for (int i = data.length - 1; i >= 0; i--) {
            data[i] = null;
        }
        size = 0;
    }

protected int hash(Object key) {
        // same as JDK 1.4
        int h = key.hashCode();
        h += ~(h << 9);
        h ^= (h >>> 14);
        h += (h << 4);
        h ^= (h >>> 10);
        return h;
    }

protected boolean isEqualKey(Object key1, Object key2) {
        return (key1 == key2 || ((key1 != null) && key1.equals(key2)));
    }

protected boolean isEqualValue(Object value1, Object value2) {
        return (value1 == value2 || value1.equals(value2));
    }

protected HashEntry<K, V> getEntry(Object key) {
        int hashCode = hash((key == null) ? NULL : key);
        HashEntry<K, V> entry = data[hashIndex(hashCode, data.length)]; // no
                                                                        // local
                                                                        // for
                                                                        // hash
                                                                        // index
        while (entry != null) {
            if (entry.hashCode == hashCode && isEqualKey(key, entry.getKey())) {
                return entry;
            }
            entry = entry.next;
        }
        return null;
    }

protected void updateEntry(HashEntry<K, V> entry, V newValue) {
        entry.setValue(newValue);
    }

protected void reuseEntry(HashEntry<K, V> entry, int hashIndex,
            int hashCode, K key, V value) {
        entry.next = data[hashIndex];
        entry.hashCode = hashCode;
        entry.key = key;
        entry.value = value;
    }

protected void addMapping(int hashIndex, int hashCode, K key, V value) {
        modCount++;
        HashEntry<K, V> entry = createEntry(data[hashIndex], hashCode, key,
                value);
        addEntry(entry, hashIndex);
        size++;
        checkCapacity();
    }

protected void removeMapping(HashEntry<K, V> entry, int hashIndex,
            HashEntry<K, V> previous) {
        modCount++;
        removeEntry(entry, hashIndex, previous);
        size--;
        destroyEntry(entry);
    }

protected void removeEntry(HashEntry<K, V> entry, int hashIndex,
            HashEntry<K, V> previous) {
        if (previous == null) {
            data[hashIndex] = entry.next;
        } else {
            previous.next = entry.next;
        }
    }

protected void destroyEntry(HashEntry<K, V> entry) {
        entry.next = null;
        entry.key = null;
        entry.value = null;
    }

protected void checkCapacity() {
        if (size >= threshold) {
            int newCapacity = data.length * 2;
            if (newCapacity <= MAXIMUM_CAPACITY) {
                ensureCapacity(newCapacity);
            }
        }
    }

protected void ensureCapacity(int newCapacity) {
        int oldCapacity = data.length;
        if (newCapacity <= oldCapacity) {
            return;
        }
        if (size == 0) {
            threshold = calculateThreshold(newCapacity, loadFactor);
            data = new HashEntry[newCapacity];
        } else {
            HashEntry<K, V> oldEntries[] = data;
            HashEntry<K, V> newEntries[] = new HashEntry[newCapacity];

            modCount++;
            for (int i = oldCapacity - 1; i >= 0; i--) {
                HashEntry<K, V> entry = oldEntries[i];
                if (entry != null) {
                    oldEntries[i] = null; // gc
                    do {
                        HashEntry<K, V> next = entry.next;
                        int index = hashIndex(entry.hashCode, newCapacity);
                        entry.next = newEntries[index];
                        newEntries[index] = entry;
                        entry = next;
                    } while (entry != null);
                }
            }
            threshold = calculateThreshold(newCapacity, loadFactor);
            data = newEntries;
        }
    }

protected int calculateNewCapacity(int proposedCapacity) {
        int newCapacity = 1;
        if (proposedCapacity > MAXIMUM_CAPACITY) {
            newCapacity = MAXIMUM_CAPACITY;
        } else {
            while (newCapacity < proposedCapacity) {
                newCapacity <<= 1; // multiply by two
            }
            if (newCapacity > MAXIMUM_CAPACITY) {
                newCapacity = MAXIMUM_CAPACITY;
            }
        }
        return newCapacity;
    }

protected HashEntry<K, V> entryNext(HashEntry<K, V> entry) {
        return entry.next;
    }

public MapIterator<K, V> mapIterator() {
        if (size == 0) {
            return EmptyMapIterator.INSTANCE;
        }
        return new HashMapIterator<K, V>(this);
    }

protected Iterator<Map.Entry<K, V>> createEntrySetIterator() {
        if (size() == 0) {
            return EmptyIterator.INSTANCE;
        }
        return new EntrySetIterator<K, V>(this);
    }

public Set<K> keySet() {
        if (keySet == null) {
            keySet = new KeySet<K, V>(this);
        }
        return keySet;
    }

protected void doWriteObject(ObjectOutputStream out) throws IOException {
        out.writeFloat(loadFactor);
        out.writeInt(data.length);
        out.writeInt(size);
        for (MapIterator it = mapIterator(); it.hasNext();) {
            out.writeObject(it.next());
            out.writeObject(it.getValue());
        }
    }

protected void doReadObject(ObjectInputStream in) throws IOException,
            ClassNotFoundException {
        loadFactor = in.readFloat();
        int capacity = in.readInt();
        int size = in.readInt();
        init();
        data = new HashEntry[capacity];
        for (int i = 0; i < size; i++) {
            K key = (K) in.readObject();
            V value = (V) in.readObject();
            put(key, value);
        }
        threshold = calculateThreshold(data.length, loadFactor);
    }

public static void loadFromStream(String key, Map<String, Object> output, InputStream binaryStream, String type)
            throws IOException {
        DataInputStream dis = new DataInputStream(binaryStream);
        String ckey = dis.readUTF();
        if (!key.equals(ckey)) {
            throw new IOException("Body Key does not match row key, unable to read");
        }
        readMapFromStream(output, dis);
        String cftype = null;
        try {
            cftype = dis.readUTF();
        } catch (IOException e) {
            LOGGER.debug("No type specified");
        }
        if (cftype != null && !cftype.equals(type)) {
            throw new IOException(
                    "Object is not of expected column family, unable to read expected [" + type
                            + "] was [" + cftype + "]");
        }
        LOGGER.debug("Finished Reading");
        dis.close();
        binaryStream.close();
    }

public static InputStream storeMapToStream(String key, Map<String, Object> m, String type)
            throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        DataOutputStream dos = new DataOutputStream(baos);
        dos.writeUTF(key);
        writeMapToStream(m, dos);
        // add the type in
        dos.writeUTF(type);
        dos.flush();
        baos.flush();
        byte[] b = baos.toByteArray();
        baos.close();
        dos.close();
        return new ByteArrayInputStream(b);
    }

public static void writeMapToStream(Map<String, Object> m,
            DataOutputStream dos) throws IOException {
        int size = 0;
        for (Entry<String, ?> e : m.entrySet()) {
            Object o = e.getValue();
            if (o != null && !(o instanceof RemoveProperty)) {
                size++;
            }
        }

        dos.writeInt(size);
        LOGGER.debug("Write {} items", size);
        for (Entry<String, ?> e : m.entrySet()) {
            Object o = e.getValue();
            if (o != null && !(o instanceof RemoveProperty)) {
                String k = e.getKey();
                LOGGER.debug("Write {} ", k);
                dos.writeUTF(k);
                Type<?> t = getTypeOfObject(o);
                dos.writeInt(t.getTypeId());
                t.save(dos, o);
            }
        }
        LOGGER.debug("Finished Writen {} items", size);

    }

@Override
    public void register() {
        prepare();
        ContentGenerator[] contentGenerators = registerContentGenerator();
        if (contentGenerators != null) {
            for (ContentGenerator contentGenerator : contentGenerators) {
                try {
                    getContext().getContentGenerators().registerContentGenerator(contentGenerator);
                } catch (IllegalIDException e) {
                    context.getLogger().fatal("Illegal Id for Module: " + contentGenerator.getID(), e);
                }
            }
        }

        EventsControllerModel[] eventsControllerModels = registerEventController();
        if (eventsControllerModels != null) {
            for (EventsControllerModel eventsController : eventsControllerModels) {
                try {
                    getContext().getEvents().distributor().registerEventsController(eventsController);
                } catch (IllegalIDException e) {
                    context.getLogger().fatal("Illegal Id for Module: " + eventsController.getID(), e);
                }
            }
        }

        OutputPluginModel[] outputPluginModels = registerOutputPlugin();
        if (outputPluginModels != null) {
            for (OutputPluginModel outputPlugin : outputPluginModels) {
                try {
                    getContext().getOutput().addOutputPlugin(outputPlugin);
                } catch (IllegalIDException e) {
                    context.getLogger().fatal("Illegal Id for Module: " + outputPlugin.getID(), e);
                }
            }
        }

        OutputExtensionModel[] outputExtensionModels = registerOutputExtension();
        if (outputExtensionModels != null) {
            for (OutputExtensionModel outputExtension : outputExtensionModels) {
                try {
                    getContext().getOutput().addOutputExtension(outputExtension);
                } catch (IllegalIDException e) {
                    context.getLogger().fatal("Illegal Id for Module: " + outputExtension.getID(), e);
                }
            }
        }

        OutputControllerModel[] outputControllerModels = registerOutputController();
        if (outputControllerModels != null) {
            for (OutputControllerModel outputController : outputControllerModels) {
                try {
                    getContext().getOutput().addOutputController(outputController);
                } catch (IllegalIDException e) {
                    context.getLogger().fatal("Illegal Id for Module: " + outputController.getID(), e);
                }
            }
        }

        ActivatorModel[] activatorModels = registerActivator();
        getContext().getSystem().registerInitializedListener(() -> {
        if (activatorModels != null) {
            for (ActivatorModel activator : activatorModels) {
                try {
                    getContext().getActivators().addActivator(activator);
                } catch (IllegalIDException e) {
                    context.getLogger().fatal("Illegal Id for Module: " + activator.getID(), e);
                }
            }
        }
        });
    }

@Override
    public void initAddOn(org.intellimate.izou.system.Context context) {
        this.context = new Context(context);
    }

synchronized protected void reconnect() {
        if (this.isReconnectionAllowed()) {
            // Since there is no thread running, creates a new one to attempt
            // the reconnection.
            // avoid to run duplicated reconnectionThread -- fd: 16/09/2010
            if (reconnectionThread != null && reconnectionThread.isAlive())
                return;

            reconnectionThread = new Thread() {

                /**
                 * Holds the current number of reconnection attempts
                 */
                private int attempts = 0;

                /**
                 * Returns the number of seconds until the next reconnection
                 * attempt.
                 * 
                 * @return the number of seconds until the next reconnection
                 *         attempt.
                 */
                private int timeDelay() {
                    attempts++;
                    if (attempts > 13) {
                        return randomBase * 6 * 5; // between 2.5 and 7.5
                                                   // minutes (~5 minutes)
                    }
                    if (attempts > 7) {
                        return randomBase * 6; // between 30 and 90 seconds (~1
                                               // minutes)
                    }
                    return randomBase; // 10 seconds
                }

                /**
                 * The process will try the reconnection until the connection
                 * succeed or the user cancell it
                 */
                public void run() {
                    // The process will try to reconnect until the connection is
                    // established or
                    // the user cancel the reconnection process {@link
                    // Connection#disconnect()}
                    while (ReconnectionManager.this.isReconnectionAllowed()) {
                        // Find how much time we should wait until the next
                        // reconnection
                        int remainingSeconds = timeDelay();
                        // Sleep until we're ready for the next reconnection
                        // attempt. Notify
                        // listeners once per second about how much time remains
                        // before the next
                        // reconnection attempt.
                        while (ReconnectionManager.this.isReconnectionAllowed()
                                && remainingSeconds > 0) {
                            try {
                                Thread.sleep(1000);
                                remainingSeconds--;
                                ReconnectionManager.this
                                        .notifyAttemptToReconnectIn(remainingSeconds);
                            } catch (InterruptedException e1) {
                                log.warn("Sleeping thread interrupted");
                                // Notify the reconnection has failed
                                ReconnectionManager.this
                                        .notifyReconnectionFailed(e1);
                            }
                        }

                        // Makes a reconnection attempt
                        try {
                            if (ReconnectionManager.this
                                    .isReconnectionAllowed()) {
                                connection.connect();
                            }
                        } catch (XMPPException e) {
                            // Fires the failed reconnection notification
                            ReconnectionManager.this
                                    .notifyReconnectionFailed(e);
                        }
                    }
                }
            };
            reconnectionThread.setName("Smack Reconnection Manager");
            reconnectionThread.setDaemon(true);
            reconnectionThread.start();
        }
    }

protected void notifyReconnectionFailed(Exception exception) {
        if (isReconnectionAllowed()) {
            for (ConnectionListener listener : connection.connectionListeners) {
                listener.reconnectionFailed(exception);
            }
        }
    }

protected void notifyAttemptToReconnectIn(int seconds) {
        if (isReconnectionAllowed()) {
            for (ConnectionListener listener : connection.connectionListeners) {
                listener.reconnectingIn(seconds);
            }
        }
    }
